-- with needs_review=true + subtopic_mapping_review note.
--
-- Idempotency: each DO $$ block checks for the external_id and
-- early-returns (RAISE NOTICE) if it already exists. Safe to
-- re-run; previously-loaded questions skip with a notice.

-- ============================================================
-- Q21 — 2024-W-Q21 — chapter=evidence subtopic=witness_competence
-- notes: needs_review=true | note: שאלה זו נפסלה במחוון הרשמי של הבחינה, וכל ארבע התשובות זוכו כתשובות נכונות. עם זאת, בהתאם לסימוכין המקורי (סעיף 21 לחוק הליכי חקירה והעדה) ולניסוח השאלה, תשובה 'א' היא התשובה המדויקת ביותר המתארת את היקף חוות הדעת המותרת. הסימוכין שצוין במקור בשאלה ('חוק חקירת סיבת מוות') שגוי ותוקן ל'חוק הליכי חקירה והעדה'.
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q21';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q21 skipped: external_id % already exists', '2024-W-Q21';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'witness_competence';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'witness_competence';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q21', 'f75683b1-e83a-47da-ba16-b35a95c536d0', v_subtopic_id,
    'תומר הוא אדם בעל מוגבלות שכלית, אשר עתיד להעיד בהליך פלילי המתנהל נגד דורון. דורון מעוניין להגיש חוות דעת מומחה בנוגע לתומר. מה הדין?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 21}'::jsonb,
    'שאלה זו עוסקת בהוראות חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס"ו-2005, ובפרט בזכותו של צד בהליך פלילי להגיש חוות דעת מומחה בנוגע לעד עם מוגבלות. החוק נועד להתאים את מערכת המשפט לצרכים הייחודיים של אוכלוסייה זו, תוך איזון בין זכויותיהם לבין זכויות הנאשם להליך הוגן.',
    'חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס"ו-2005, נועד להסדיר את הליכי החקירה וההעדה של אנשים עם מוגבלויות שכליות או נפשיות, במטרה להנגיש את מערכת המשפט לצרכיהם המיוחדים. סעיף 21(א) לחוק קובע במפורש כי צדדים בהליך פלילי, שבו עד הוא אדם עם מוגבלות, רשאים להגיש חוות דעת מומחה כראיה. חוות דעת זו יכולה להתייחס לשלושה עניינים: (1) היותו של העד אדם עם מוגבלות; (2) סוג מוגבלותו של העד; ו-(3) השפעתה האפשרית של המוגבלות על מסירת עדותו או על העד עצמו. מטרת חוות הדעת היא לסייע לבית המשפט להבין את מצבו של העד ולהתאים את ההליך בהתאם, אך סעיף 21(ב) מבהיר כי חוות דעת זו לא תשמש סיוע, חיזוק או כל תוספת ראייתית אחרת הנדרשת לפי דין. סעיף 21(א) לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס"ו-2005תפע (שלום תל אביב-יפו) 69333-01-20 מדינת ישראל נ'' פלוני (23.05.2022)ע"פ 7440/16 פלוני נ'' מדינת ישראל (06.08.2017)נבו - המתמחה דיני ראיות (2026) | עדות אדם עם מוגבלותיניב ואקי דיני ראיות כרך ב (2020) | פרק 24 עד מוגבל בשכלו או בנפשו',
    'טעות נפוצה היא לכלול בחוות הדעת עניינים שאינם קשורים ישירות למוגבלות העד והשפעתה על העדות, כגון מידת מסוכנות, או לחשוב שחוות הדעת משמשת כסיוע או חיזוק לראיות.',
    '["חוות דעת מומחה", "עד עם מוגבלות", "הליך פלילי", "קבילות ראיות", "חוק הליכי חקירה והעדה", "סיוע וחיזוק"]'::jsonb,
    '**וריאציה 1 — היקף חוות הדעת:** מהם הנושאים שחוות דעת מומחה יכולה לכלול לגבי עד עם מוגבלות? ← היותו מוגבל, סוג מוגבלותו, והשפעתה על העדות (סעיף 21(א) לחוק הליכי חקירה והעדה). **וריאציה 2 — מטרת חוות הדעת:** מהי מטרת חוות הדעת? ← לסייע לבית המשפט להבין את מצב העד ולהתאים את ההליך (נבו - המתמחה, דיני ראיות). **וריאציה 3 — מגבלות חוות הדעת:** האם חוות הדעת יכולה לשמש כסיוע או חיזוק? ← לא, סעיף 21(ב) לחוק קובע במפורש שלא (סעיף 21(ב) לחוק הליכי חקירה והעדה).',
    'חוות דעת מומחה על עד מוגבל ← תתייחס למוגבלות והשפעתה על העדות ← לא תשמש סיוע/חיזוק.',
    '["חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס\"ו-2005, סעיף 21(א)", "חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס\"ו-2005, סעיף 21(ב)", "תפע (שלום תל אביב-יפו) 69333-01-20 מדינת ישראל נ'' פלוני (23.05.2022)", "ע\"פ 7440/16 פלוני נ'' מדינת ישראל (06.08.2017)", "נבו - המתמחה, דיני ראיות (2026), עדות אדם עם מוגבלות", "יניב ואקי, דיני ראיות כרך ב (2020), פרק 24 עד מוגבל בשכלו או בנפשו"]'::jsonb,
    'needs_review=true | note: שאלה זו נפסלה במחוון הרשמי של הבחינה, וכל ארבע התשובות זוכו כתשובות נכונות. עם זאת, בהתאם לסימוכין המקורי (סעיף 21 לחוק הליכי חקירה והעדה) ולניסוח השאלה, תשובה ''א'' היא התשובה המדויקת ביותר המתארת את היקף חוות הדעת המותרת. הסימוכין שצוין במקור בשאלה (''חוק חקירת סיבת מוות'') שגוי ותוקן ל''חוק הליכי חקירה והעדה''.',
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'דורון רשאי להגיש חוות דעת מומחה בשאלה האם תומר הוא אדם עם מוגבלות, סוג המוגבלות של תומר והשפעתה האפשרית של המוגבלות על העדות שתומר צפוי לתת.', true, 'זו התשובה הנכונה. סעיף 21(א) לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית) קובע כי צדדים בהליך פלילי רשאים להגיש חוות דעת מומחה בעניין היותו של עד אדם עם מוגבלות, סוג מוגבלותו והשפעתה האפשרית על מסירת עדותו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'דורון רשאי להגיש חוות דעת מומחה בשאלה האם תומר הוא אדם עם מוגבלות, סוג המוגבלות של תומר ומידת המסוכנות של תומר.', false, 'תשובה זו שגויה. סעיף 21 לחוק הליכי חקירה והעדה אינו מתיר הגשת חוות דעת מומחה בנוגע למידת המסוכנות של העד, אלא רק לגבי מוגבלותו והשפעתה על העדות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'דורון רשאי לבקש חוות דעת מומחה רק על סוג המוגבלות של תומר והשפעתה האפשרית של המוגבלות על העדות שתומר צפוי לתת.', false, 'תשובה זו שגויה. סעיף 21 לחוק הליכי חקירה והעדה מאפשר להגיש חוות דעת גם בשאלה האם העד הוא אדם עם מוגבלות, ולא רק על סוג המוגבלות והשפעתה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'דורון רשאי לבקש חוות דעת מומחה בשאלה האם תומר הוא אדם עם מוגבלות, סוג המוגבלות של תומר, השפעתה האפשרית של המוגבלות על העדות שתומר צפוי לתת ומידת המסוכנות של תומר.', false, 'תשובה זו שגויה. סעיף 21 לחוק הליכי חקירה והעדה אינו כולל את מידת המסוכנות של העד בין העניינים שלגביהם ניתן להגיש חוות דעת מומחה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'קבילות הודאת חשוד עם מוגבלות שנחקר שלא כדין', 1, 'ראובן, חשוד עם מוגבלות שכלית, הודה בעבירה במהלך חקירה משטרתית שלא נערכה על ידי חוקר מיוחד. מה נדרש מהתביעה כדי שהודאתו תהיה קבילה כראיה?',
    'שאלה זו עוסקת בקבילות הודאת חוץ של חשוד עם מוגבלות שכלית שנחקר שלא על ידי חוקר מיוחד. היא מדגישה את ההגנה המיוחדת שהמחוקק העניק לאוכלוסייה זו, באמצעות הטלת נטל הוכחה מוגבר על התביעה להוכיח שההודאה ניתנה מרצון חופשי.',
    'חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית) קובע הסדרים מיוחדים לחקירת אנשים עם מוגבלויות. סעיף 3(ב) לחוק קובע כי חשוד עם מוגבלות שכלית ייחקר על ידי חוקר מיוחד. עם זאת, סעיף 14 לחוק מבהיר כי אי-חקירה על ידי חוקר מיוחד אינה פוגעת בחוקיות החקירה. יחד עם זאת, סעיף 15 לחוק קובע הוראה מיוחדת לעניין קבילות הודאה במצב כזה: אם אדם עם מוגבלות שכלית הודה בעבירה במהלך חקירה שלא על ידי חוקר מיוחד, על התביעה להוכיח מעל לכל ספק סביר שההודאה הייתה חופשית ומרצון, וזאת גם אם הנאשם לא העלה טענה בעניין זה. הוראה זו נועדה להגן על זכויותיהם של חשודים עם מוגבלויות ולהבטיח את אמינות ההודאה. סעיף 15 לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס"ו-2005סעיף 14(1) לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס"ו-2005נבו - המתמחה דיני ראיות (2026) | עדות אדם עם מוגבלותע"פ 9197/18 פלוני נ'' מדינת ישראל (23.01.2020)אורנה אליגון דר יסודות בדיני ראיות (2024) | פרק 3 - העדים: הכשרות והחובה להעיד ודרך החקירה',
    'טעות נפוצה היא להניח שאי-קיום חקירה על ידי חוקר מיוחד פוסל אוטומטית את ההודאה, מבלי להבין שהחוק קובע נטל הוכחה מוגבר על התביעה במקום פסילה מוחלטת.',
    '["קבילות הודאה", "חופשית ומרצון", "נטל הוכחה", "חוקר מיוחד", "מוגבלות שכלית", "חוק הליכי חקירה והעדה"]'::jsonb,
    '**וריאציה 1 — חקירה שלא כדין:** חשוד עם מוגבלות שכלית נחקר שלא על ידי חוקר מיוחד והודה. מה נדרש? ← התביעה תוכיח מעל לכל ספק סביר שההודאה חופשית ומרצון (סעיף 15 לחוק הליכי חקירה והעדה). **וריאציה 2 — חוקיות החקירה:** האם חקירה כזו פסולה? ← לא, סעיף 14 לחוק קובע שאינה פוגעת בחוקיותה (סעיף 14 לחוק הליכי חקירה והעדה). **וריאציה 3 — תכלית ההוראה:** מהי מטרת סעיף 15? ← להגן על חשודים עם מוגבלויות ולהבטיח אמינות הודאותיהם (נבו - המתמחה, דיני ראיות).',
    'הודאת מוגבל שכלית בחקירה לא מותאמת ← התביעה תוכיח חופשית ומרצון מעל ספק סביר.',
    '["חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס\"ו-2005, סעיף 14(1)", "חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס\"ו-2005, סעיף 15", "נבו - המתמחה, דיני ראיות (2026), עדות אדם עם מוגבלות", "ע\"פ 9197/18 פלוני נ'' מדינת ישראל (23.01.2020)", "אורנה אליגון דר, יסודות בדיני ראיות (2024), פרק 3 - העדים: הכשרות והחובה להעיד ודרך החקירה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'תנאים לפטור עד ממוגבלות ממסירת עדות', 2, 'בית המשפט שוקל לפטור עד עם מוגבלות נפשית ממסירת עדות בהליך פלילי. מהם התנאים המצטברים שבית המשפט צריך להשתכנע בקיומם כדי לפטור את העד מעדות?',
    'שאלה זו בוחנת את התנאים המורכבים לפטור עד עם מוגבלות ממסירת עדות בבית המשפט, כפי שנקבעו בסעיף 20(ב)(2) לחוק הליכי חקירה והעדה. היא מדגישה את האיזון בין הצורך להגן על העד לבין זכות הנאשם להליך הוגן, ואת חשיבות חוות הדעת המקצועית ושקילת אמצעי התאמה חלופיים.',
    'סעיף 20(ב)(2) לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית) קובע את התנאים המצטברים לפטור עד עם מוגבלות ממסירת עדות. התנאים הם: (א) לפי חוות הדעת של מומחה, מתן העדות עלול לפגוע בעד, או שהעד אינו מסוגל להעיד מחמת מוגבלותו השכלית או הנפשית; ו-(ב) בית המשפט שוכנע כי אין בגביית העדות באחת או יותר מהדרכים המפורטות בסעיף 22 לחוק (אמצעי התאמה), או בדחיית מועד מתן עדותו של העד בזמן סביר, כדי למנוע את הפגיעה בעד או כדי לאפשר את העדתו על אף מוגבלותו. המחוקק לא קבע רף שכנוע ספציפי, אלא הסתפק במילה ''שוכנע''. פטור זה אינו דבר של מה בכך, ונועד למקרים חריגים בהם אין דרך אחרת להגן על העד. סעיף 20(ב)(2) לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס"ו-2005תפע (שלום תל אביב-יפו) 69333-01-20 מדינת ישראל נ'' פלוני (23.05.2022)ע"פ 7440/16 פלוני נ'' מדינת ישראל (06.08.2017)ע"פ 5382/11 פלוני נ'' מדינת ישראל (10.05.2012)אורנה אליגון דר יסודות בדיני ראיות (2024) | פרק 3 - העדים: הכשרות והחובה להעיד ודרך החקירה',
    'טעות נפוצה היא להתמקד רק בתנאי הראשון (פגיעה בעד או חוסר יכולת להעיד) מבלי לזכור את התנאי המצטבר השני, הדורש שקילת אמצעי התאמה או דחיית העדות.',
    '["פטור מעדות", "מוגבלות נפשית", "חוות דעת מומחה", "אמצעי התאמה", "הליך הוגן", "חוק הליכי חקירה והעדה"]'::jsonb,
    '**וריאציה 1 — תנאי לפטור:** מהם התנאים לפטור עד עם מוגבלות מעדות? ← חוות דעת מומחה על פגיעה/חוסר יכולת, ושכנוע בית המשפט שאין פתרון אחר (סעיף 20(ב)(2) לחוק הליכי חקירה והעדה). **וריאציה 2 — רף השכנוע:** מהו רף השכנוע הנדרש מבית המשפט? ← ''שוכנע'', ללא רף הוכחה ספציפי כמו ''מעבר לספק סביר'' (תפע 69333-01-20 מדינת ישראל נ'' פלוני). **וריאציה 3 — חשיבות הפטור:** מדוע הפטור אינו דבר של מה בכך? ← הוא מאזן בין הגנה על העד לזכות הנאשם לחקירה נגדית (ע"פ 7440/16 פלוני נ'' מדינת ישראל).',
    'פטור עד ממוגבלות ← חוות דעת מומחה + אין פתרון אחר (התאמה/דחייה).',
    '["חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס\"ו-2005, סעיף 20(ב)(2)", "תפע (שלום תל אביב-יפו) 69333-01-20 מדינת ישראל נ'' פלוני (23.05.2022)", "ע\"פ 7440/16 פלוני נ'' מדינת ישראל (06.08.2017)", "ע\"פ 5382/11 פלוני נ'' מדינת ישראל (10.05.2012)", "אורנה אליגון דר, יסודות בדיני ראיות (2024), פרק 3 - העדים: הכשרות והחובה להעיד ודרך החקירה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'איסור חקירה נגדית של נפגע עבירה עם מוגבלות שכלית', 3, 'דורון נאשם בעבירת מין נגד תומר, שהוא אדם עם מוגבלות שכלית. דורון מעוניין לחקור את תומר בחקירה נגדית. מה הדין לגבי חקירה זו?',
    'שאלה זו עוסקת בהגנה מיוחדת הניתנת לנפגעי עבירה עם מוגבלות שכלית, ובפרט באיסור על נאשם לחקור אותם בחקירה נגדית ישירה. היא מדגישה את חשיבות ההגנה על אוכלוסייה פגיעה זו, תוך הבטחת זכות הנאשם להליך הוגן באמצעות ייצוג או מתווך.',
    'סעיף 19 לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית) מבחין בין עד עם מוגבלות שכלית באופן כללי לבין נפגע עבירה עם מוגבלות שכלית. סעיף 19(א) קובע כי בית המשפט רשאי להורות שהנאשם לא יחקור עד עם מוגבלות שכלית בעצמו, לאחר ששקל שיקולים שונים. אולם, סעיף 19(ב)(1) קובע חריג משמעותי: אם העד הוא נפגע עבירה עם מוגבלות שכלית, בעבירות המפורטות בפרט (1) עד (3) בתוספת לחוק (כגון עבירות מין), הנאשם לא יחקור את אותו אדם בעצמו. במקרה כזה, אם הנאשם אינו מיוצג, בית המשפט ימנה לו סניגור בהסכמתו (סעיף 19(ב)(2)). אם הנאשם יסרב למינוי סניגור, החקירה תיעשה באמצעות מתווך (סעיף 19(ג)). סעיף 19(ב)(1) לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס"ו-2005סעיף 19(ב)(2) לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס"ו-2005סעיף 19(ג) לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס"ו-2005נבו - המתמחה דיני ראיות (2026) | עדות אדם עם מוגבלותאורנה אליגון דר יסודות בדיני ראיות (2024) | פרק 3 - העדים: הכשרות והחובה להעיד ודרך החקירה',
    'טעות נפוצה היא לבלבל בין הסמכות הכללית של בית המשפט לאסור חקירה נגדית ישירה (סעיף 19(א)) לבין האיסור המוחלט החל על נפגעי עבירה עם מוגבלות שכלית בעבירות מסוימות (סעיף 19(ב)).',
    '["חקירה נגדית", "נפגע עבירה", "מוגבלות שכלית", "ייצוג סניגורי", "מתווך", "חוק הליכי חקירה והעדה"]'::jsonb,
    '**וריאציה 1 — איסור מוחלט:** האם נאשם רשאי לחקור נגדית נפגע עבירה עם מוגבלות שכלית בעבירת מין? ← לא, חל איסור מוחלט (סעיף 19(ב)(1) לחוק הליכי חקירה והעדה). **וריאציה 2 — חלופה לנאשם לא מיוצג:** מה קורה אם הנאשם אינו מיוצג? ← בית המשפט ימנה לו סניגור, או מתווך אם יסרב (סעיף 19(ב)(2) ו-(ג) לחוק הליכי חקירה והעדה). **וריאציה 3 — תכלית האיסור:** מדוע קיים איסור מוחלט זה? ← להגן על נפגעי עבירה פגיעים במיוחד (נבו - המתמחה, דיני ראיות).',
    'נפגע עבירה עם מוגבלות שכלית ← נאשם לא יחקור בעצמו ← סניגור/מתווך.',
    '["חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס\"ו-2005, סעיף 19(ב)(1)", "חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס\"ו-2005, סעיף 19(ב)(2)", "חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס\"ו-2005, סעיף 19(ג)", "נבו - המתמחה, דיני ראיות (2026), עדות אדם עם מוגבלות", "אורנה אליגון דר, יסודות בדיני ראיות (2024), פרק 3 - העדים: הכשרות והחובה להעיד ודרך החקירה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'אמצעי התאמה לעדות בבית המשפט', 4, 'תומר, אדם עם מוגבלות שכלית, עתיד להעיד בבית המשפט בהליך פלילי. בית המשפט סבור כי מסירת עדותו בדרך הרגילה עלולה לפגוע בו. אילו אמצעי התאמה רשאי בית המשפט להורות עליהם?',
    'שאלה זו עוסקת במגוון אמצעי ההתאמה שבית המשפט רשאי להורות עליהם בעת גביית עדות מאדם עם מוגבלות שכלית או נפשית. היא מדגישה את גמישות החוק ואת שיקול הדעת הרחב הנתון לבית המשפט, במטרה לאפשר לעד למסור את עדותו באופן מיטבי תוך מזעור פגיעה בו.',
    'סעיף 22(א) לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית) קובע כי אם בית המשפט רואה שעד הוא אדם עם מוגבלות, ומסירת עדותו בדרך הרגילה עלולה לפגוע בו או לפגום בעדותו, הוא רשאי להורות, מיוזמתו או לבקשת בעל דין, על גביית העדות באחת או יותר מעשר דרכים המפורטות בסעיף. דרכים אלו כוללות, בין היתר: עדות שלא בנוכחות הנאשם (אלא בנוכחות סניגורו), עדות כשהעד מאחורי פרגוד, עדות בלשכת השופט, הסתייעות באמצעי תקשורת חלופית או תומכת, בנוכחות מלווה, או בכל דרך אחרת שקבע בית המשפט, ובלבד ששוכנע מעל לכל ספק סביר כי אין בכך כדי לגרום עיוות דין לנאשם. סעיף 22(א) לחוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס"ו-2005ע"פ 7440/16 פלוני נ'' מדינת ישראל (06.08.2017)ע"פ 10166/09 פלונית נ'' מדינת ישראל (11.10.2010)נבו - המתמחה דיני ראיות (2026) | עדות אדם עם מוגבלותאורנה אליגון דר יסודות בדיני ראיות (2024) | פרק 3 - העדים: הכשרות והחובה להעיד ודרך החקירה',
    'טעות נפוצה היא לחשוב שרשימת אמצעי ההתאמה היא מצומצמת או דורשת הסכמה של הצדדים, מבלי להכיר את מגוון האפשרויות הרחב ואת שיקול הדעת הנתון לבית המשפט.',
    '["אמצעי התאמה", "עדות בבית המשפט", "מוגבלות שכלית", "שיקול דעת שיפוטי", "הליך הוגן", "חוק הליכי חקירה והעדה"]'::jsonb,
    '**וריאציה 1 — מטרת אמצעי ההתאמה:** מתי בית המשפט יורה על אמצעי התאמה? ← כשהעדות הרגילה עלולה לפגוע בעד או לפגום בעדותו (סעיף 22(א) לחוק הליכי חקירה והעדה). **וריאציה 2 — דוגמאות לאמצעים:** אילו אמצעים ניתן להורות? ← שלא בנוכחות נאשם, מאחורי פרגוד, בלשכת השופט, תקשורת חלופית ועוד (סעיף 22(א) לחוק הליכי חקירה והעדה). **וריאציה 3 — סמכות בית המשפט:** מי יוזם את אמצעי ההתאמה? ← בית המשפט מיוזמתו או לבקשת בעל דין (סעיף 22(א) לחוק הליכי חקירה והעדה).',
    'עדות מוגבל בבית המשפט ← בית המשפט יורה על אמצעי התאמה ← מגוון רחב של אפשרויות.',
    '["חוק הליכי חקירה והעדה (התאמה לאנשים עם מוגבלות שכלית או נפשית), תשס\"ו-2005, סעיף 22(א)", "ע\"פ 7440/16 פלוני נ'' מדינת ישראל (06.08.2017)", "ע\"פ 10166/09 פלונית נ'' מדינת ישראל (11.10.2010)", "נבו - המתמחה, דיני ראיות (2026), עדות אדם עם מוגבלות", "אורנה אליגון דר, יסודות בדיני ראיות (2024), פרק 3 - העדים: הכשרות והחובה להעיד ודרך החקירה"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'התביעה צריכה להוכיח מעל לכל ספק סביר שההודאה הייתה חופשית ומרצון, גם אם הנאשם לא העלה טענה בעניין זה.', true, 'זו התשובה הנכונה. סעיף 15 לחוק הליכי חקירה והעדה קובע כי במקרה כזה, על התביעה מוטל הנטל להוכיח שההודאה הייתה חופשית ומרצון, גם ללא טענה מצד הנאשם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'הודאתו של ראובן פסולה אוטומטית, שכן חקירה שלא על ידי חוקר מיוחד פוגעת בחוקיותה.', false, 'תשובה זו שגויה. סעיף 14 לחוק הליכי חקירה והעדה קובע כי אי-חקירה על ידי חוקר מיוחד אינה פוגעת בחוקיות החקירה, אך משפיעה על נטל ההוכחה לקבילות ההודאה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'התביעה צריכה להוכיח שההודאה הייתה חופשית ומרצון, אך רק אם הנאשם העלה טענה מפורשת בעניין זה.', false, 'תשובה זו שגויה. סעיף 15 לחוק הליכי חקירה והעדה קובע כי נטל ההוכחה מוטל על התביעה גם אם הנאשם לא העלה טענה מפורשת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'הודאתו של ראובן קבילה כראיה, אך משקלה יופחת באופן משמעותי.', false, 'תשובה זו שגויה. החוק קובע תנאי קבילות מחמיר יותר (הוכחת חופשיות ומרצון מעל לכל ספק סביר) ולא רק הפחתת משקל.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'לפי חוות דעת מומחה, מתן העדות עלול לפגוע בעד או שהעד אינו מסוגל להעיד מחמת מוגבלותו, ובית המשפט שוכנע כי אין בגביית העדות באמצעי התאמה או בדחיית מועד העדות כדי למנוע את הפגיעה או לאפשר את העדתו.', true, 'זו התשובה הנכונה. סעיף 20(ב)(2) לחוק הליכי חקירה והעדה מפרט את שני התנאים המצטברים הנדרשים לפטור עד ממסירת עדות: חוות דעת מומחה וכן שכנוע בית המשפט לגבי חוסר היעילות של אמצעי התאמה או דחיית העדות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'העד אינו מסוגל להעיד מחמת מוגבלותו, וכן קיימת הסכמה של התביעה וההגנה לפטור אותו מעדות.', false, 'תשובה זו שגויה. הסכמת הצדדים אינה תנאי לפטור מעדות, אלא חוות דעת מומחה ושכנוע בית המשפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'מתן העדות עלול לפגוע בעד, וכן העד עצמו מסרב להעיד גם באמצעות אמצעי התאמה.', false, 'תשובה זו שגויה. סירוב העד אינו תנאי מספיק, ונדרשת חוות דעת מומחה ושכנוע בית המשפט לגבי חוסר היעילות של אמצעי התאמה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'לפי חוות דעת מומחה, מתן העדות עלול לפגוע בעד, וכן העד אינו מסוגל להעיד מחמת מוגבלותו.', false, 'תשובה זו שגויה. אלו הם רק חלק מהתנאים. חסר התנאי המצטבר השני, לפיו בית המשפט שוכנע כי אין בגביית העדות באמצעי התאמה או בדחיית מועד העדות כדי למנוע את הפגיעה או לאפשר את העדתו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'דורון רשאי לחקור את תומר בעצמו, אלא אם כן בית המשפט הורה אחרת לאחר ששקל את הפגיעה האפשרית בתומר מול זכותו של דורון להליך הוגן.', false, 'תשובה זו שגויה. במקרה של נפגע עבירה עם מוגבלות שכלית בעבירות מסוימות, קיים איסור מוחלט על הנאשם לחקור בעצמו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'דורון אינו רשאי לחקור את תומר בעצמו, ובית המשפט ימנה לו סניגור לצורך כך, או מתווך אם יסרב לסניגור.', true, 'זו התשובה הנכונה. סעיף 19(ב)(1) לחוק הליכי חקירה והעדה קובע איסור מוחלט על נאשם לחקור נפגע עבירה עם מוגבלות שכלית בעבירות המפורטות בתוספת, וסעיף 19(ב)(2) ו-(ג) קובעים את הליך מינוי הסניגור או המתווך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'דורון רשאי לחקור את תומר בעצמו, אך רק באמצעות אמצעי התאמה כגון פרגוד או טלוויזיה במעגל סגור.', false, 'תשובה זו שגויה. אמצעי התאמה נועדו להקל על העדות, אך אינם מבטלים את האיסור המוחלט על חקירה נגדית ישירה של נפגע עבירה עם מוגבלות שכלית על ידי הנאשם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'דורון אינו רשאי לחקור את תומר בעצמו, אך רק אם תומר הוא קטין בנוסף להיותו בעל מוגבלות שכלית.', false, 'תשובה זו שגויה. האיסור חל על נפגע עבירה עם מוגבלות שכלית, ללא קשר לגילו, בעבירות המפורטות בתוספת לחוק.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'רק אמצעים טכנולוגיים כגון טלוויזיה במעגל סגור או הסתייעות בתקשורת חלופית.', false, 'תשובה זו שגויה. סעיף 22 לחוק הליכי חקירה והעדה מפרט מגוון רחב של אמצעי התאמה, שאינם מוגבלים רק לאמצעים טכנולוגיים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'שלא בנוכחות הנאשם, מאחורי פרגוד, בלשכת השופט, או הסתייעות באמצעי תקשורת חלופית, בין היתר.', true, 'זו התשובה הנכונה. סעיף 22(א) לחוק הליכי חקירה והעדה מפרט רשימה של עשרה אמצעי התאמה שונים, ובין היתר כולל את האפשרויות המצוינות בתשובה זו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'רק אם הוגשה חוות דעת מומחה הממליצה על אמצעי התאמה ספציפיים.', false, 'תשובה זו שגויה. בית המשפט רשאי להורות על אמצעי התאמה מיוזמתו או לבקשת בעל דין, ואינו מוגבל רק להמלצות מומחה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'רק אם הנאשם הסכים לאמצעי ההתאמה המוצעים.', false, 'תשובה זו שגויה. הסכמת הנאשם אינה תנאי להוראה על אמצעי התאמה, אם כי בית המשפט ישקול את הפגיעה האפשרית בזכויותיו.', 4);

END $$;

-- ============================================================
-- Q22 — 2024-W-Q22 — chapter=execution subtopic=file_opening
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q22';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q22 skipped: external_id % already exists', '2024-W-Q22';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'file_opening';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'file_opening';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q22', 'b3904dc7-882d-48fc-9f3c-ba89fc453003', v_subtopic_id,
    'חוק הוצאה לפועל מאפשר בתנאים מסוימים להגיש ללשכת ההוצאה לפועל תביעה לסכום קצוב בלי להגיש תחילה תביעה לבית המשפט. מבין 4 האפשרויות הבאות, מהי האפשרות המציגה באופן הנכון ביותר את התנאים להגשת תביעה כזו?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 22}'::jsonb,
    'שאלה זו עוסקת בתנאים המצטברים להגשת תביעה על סכום קצוב ישירות ללשכת ההוצאה לפועל, ללא צורך בהליך מקדים בבית המשפט. היא מתמקדת בסעיף 81א1 לחוק ההוצאה לפועל, אשר נועד לייעל את הליכי הגבייה עבור חובות שאינם שנויים במחלוקת מהותית, תוך שמירה על זכויות החייב באמצעות דרישות סף מחמירות.',
    'סעיף 81א1 לחוק ההוצאה לפועל, תשכ"ז-1967, מאפשר לזוכה להגיש תביעה על סכום קצוב ישירות ללשכת ההוצאה לפועל, בדומה לביצוע שטר, מבלי להיזקק להליך משפטי מקדים. מנגנון זה נועד לחסוך זמן ומשאבים למערכת המשפט ולזוכה, במקרים בהם זכותו של הזוכה מבוססת על יסודות איתנים והחייב אינו כופר בחבותו. החוק קובע שני תנאים עיקריים להגשת תביעה כזו: ראשית, סכום התביעה אינו יכול לעלות על 75,000 שקלים חדשים ביום הגשתה (סעיף 81א1(א)). שנית, על הזוכה להמציא לחייב התראה בדואר רשום עם אישור מסירה, ורק בתום 30 ימים מיום המצאת ההתראה, ולא יאוחר משנה, ניתן להגיש את הבקשה לביצוע (סעיפים 81א1(ב1) ו-(ג)(1)). דרישת ההתראה היא מהותית ונועדה להגן על החייב ולאפשר לו להסדיר את חובו לפני נקיטת הליכים. סעיף 81א1(א) לחוק ההוצאה לפועל, תשכ"ז-1967סעיף 81א1(ג)(1) לחוק ההוצאה לפועל, תשכ"ז-1967רער"צ (שלום עכו) 42663-04-22 רצון ליברמן בע"מ נ'' מידד רוימי (23.09.2022)ת"צ (מינהליים ת"א) 42450-01-18 יהודית ויצמן נ'' עירית חולון (12.11.2023)ע"א 6181/08 שמואל וינוקור נ'' ממונה מס ערך מוסף עכו (28.08.2012)תא"מ (שלום ראשל"צ) 52489-10-17 מועצה מקומית בית דגן נ'' מוקד אמון סביון 1997 אבטחה ושמירה בע"מ (24.07.2018)',
    'טעות נפוצה היא לזכור את קיומו של סעיף 81א1, אך לבלבל בין סכום התביעה המקסימלי (75,000 ש"ח) לבין סכומים אחרים, או בין תקופת ההתראה (30 יום) לבין תקופות אחרות הקבועות בחוקים שונים.',
    '["תביעה על סכום קצוב", "חוק ההוצאה לפועל", "סעיף 81א1", "התראה", "סכום תביעה", "יעילות דיונית", "הגנת החייב"]'::jsonb,
    '**וריאציה 1 — תנאי סכום:** מהו הסכום המקסימלי לתביעה על סכום קצוב בהוצאה לפועל? ← 75,000 ש"ח ביום הגשתה (סעיף 81א1(א) לחוק ההוצאה לפועל). **וריאציה 2 — תנאי התראה:** כמה זמן לפני הגשת התביעה יש להמציא התראה? ← 30 ימים לפחות (סעיף 81א1(ג)(1) לחוק ההוצאה לפועל). **וריאציה 3 — מטרת ההליך:** מהי מטרת הגשת תביעה על סכום קצוב ישירות להוצאה לפועל? ← לחסוך זמן ומשאבים במקרים של חובות מבוססים, תוך שמירה על זכויות החייב (ע"א 6181/08 וינוקור; רער"צ (שלום עכו) 42663-04-22).',
    'תביעה על סכום קצוב בהוצאה לפועל ← עד 75,000 ש"ח + התראה של 30 יום ← ייעול הליכים והגנת החייב.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 81א1(א)", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 81א1(ג)(1)", "רער\"צ (שלום עכו) 42663-04-22 רצון ליברמן בע\"מ נ'' מידד רוימי (23.09.2022)", "ת\"צ (מינהליים ת\"א) 42450-01-18 יהודית ויצמן נ'' עירית חולון (12.11.2023)", "ע\"א 6181/08 שמואל וינוקור נ'' ממונה מס ערך מוסף עכו (28.08.2012)", "תא\"מ (שלום ראשל\"צ) 52489-10-17 מועצה מקומית בית דגן נ'' מוקד אמון סביון 1997 אבטחה ושמירה בע\"מ (24.07.2018)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'החוב לא יכול לעלות על 65,000 ש"ח ביום הגשתו, ו-30 יום לפני הגשת הבקשה על הזוכה להמציא לחייב התראה על כך שבכוונתו להגיש תביעה על סכום קצוב בהוצאה לפועל.', false, 'תשובה זו שגויה. סכום התביעה המקסימלי הקבוע בחוק הוא 75,000 ש"ח, ולא 65,000 ש"ח.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'החוב לא יכול לעלות על 75,000 ש"ח ביום הגשתו, ו-30 יום לפני הגשת הבקשה על הזוכה להמציא לחייב התראה על כך שבכוונתו להגיש תביעה על סכום קצוב בהוצאה לפועל.', true, 'זו התשובה הנכונה. סעיף 81א1(א) לחוק ההוצאה לפועל קובע כי סכום התביעה אינו יכול לעלות על 75,000 ש"ח ביום הגשתה, וסעיף 81א1(ג)(1) קובע כי הבקשה לא תוגש אלא בתום 30 ימים מיום המצאת ההתראה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'החוב לא יכול לעלות על 75,000 ש"ח ביום הגשתו, ו-21 יום לפני הגשת הבקשה על הזוכה להמציא לחייב התראה על כך שבכוונתו להגיש תביעה על סכום קצוב בהוצאה לפועל.', false, 'תשובה זו שגויה. תקופת ההתראה הנדרשת בחוק היא 30 ימים, ולא 21 ימים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'החוב לא יכול לעלות על 65,000 ש"ח ביום הגשתו, ו-21 יום לפני הגשת הבקשה על הזוכה להמציא לחייב התראה על כך שבכוונתו להגיש תביעה על סכום קצוב בהוצאה לפועל.', false, 'תשובה זו שגויה. הן סכום התביעה המקסימלי והן תקופת ההתראה המינימלית אינם נכונים לפי הוראות החוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'דרישת ''ראיה בכתב'' בתביעה על סכום קצוב', 1, 'חברה הגישה תביעה על סכום קצוב ללשכת ההוצאה לפועל בגין חוב של לקוח, בהתבסס על חשבוניות שהוציאה החברה ודף חשבון המעיד על יתרת חוב. הלקוח טוען כי לא חתם על כל מסמך התקשרות. האם המסמכים שהוגשו עומדים בדרישת ''ראיה בכתב'' לפי סעיף 81א1(א)(1) לחוק ההוצאה לפועל?',
    'שאלה זו עוסקת בפרשנות דרישת ''ראיה בכתב'' בתביעה על סכום קצוב בהוצאה לפועל, לפי סעיף 81א1(א)(1) לחוק ההוצאה לפועל. היא מדגישה את ההבדל בין דרישה זו לבין הדרישה שהייתה קיימת בתקנה 202 לתקנות סדר הדין האזרחי הישנות (סדר דין מקוצר), ואת הצורך בראיה מפורשת הקושרת את החייב לחוב.',
    'סעיף 81א1(א)(1) לחוק ההוצאה לפועל קובע כי תביעה על סכום קצוב המוגשת להוצאה לפועל צריכה להיות ''מכוח חוזה או התחייבות מפורשים, שיש עליה ראיה בכתב''. הפסיקה קבעה כי דרישה זו מחמירה יותר מזו שהייתה קבועה בתקנה 202(1)(א) לתקנות סדר הדין האזרחי, תשמ"ד-1984 (שבוטלה), אשר הסתפקה ב''חוזה או התחייבות מפורשים או מכללא''. המשמעות היא שאין די בראיות המעידות על התחייבות מכללא, אלא נדרשת התחייבות מפורשת, וכן ראיה בכתב הקושרת את החייב לחוב, ורצוי שתהיה חתומה על ידו. מסמכים שהוצאו על ידי התובע בלבד, כגון חשבוניות או דפי חשבון, ללא חתימת החייב או קישור מפורש אחר אליו, אינם מספיקים בדרך כלל כדי לעמוד בדרישה המחמירה של סעיף 81א1(א)(1). סעיף 81א1(א)(1) לחוק ההוצאה לפועל, תשכ"ז-1967רער"צ (שלום עכו) 42663-04-22 רצון ליברמן בע"מ נ'' מידד רוימי (23.09.2022)(רשם ההוצאה לפועל אילת) 512144-05-24 חייבים נ'' (27.05.2024)ת"ת (שלום ב"ש) 27973-12-13 חברת פרטנר תקשורת בע"מ נ'' אמור אבו חרמה (24.01.2014)ת"ת (שלום ת"א) 26784-11-24 טריא קהילה פיננסית בע"מ נ'' אכלס דיאב (04.06.2025)',
    'טעות נפוצה היא לבלבל בין דרישת ''ראיה בכתב'' בתביעה על סכום קצוב בהוצאה לפועל לבין הדרישה שהייתה קיימת בתביעות בסדר דין מקוצר, שהייתה פחות מחמירה וכללה גם התחייבות מכללא.',
    '["ראיה בכתב", "חוזה מפורש", "התחייבות מפורשת", "סעיף 81א1(א)(1)", "סדר דין מקוצר", "חתימת החייב", "הוצאה לפועל"]'::jsonb,
    '**וריאציה 1 — דרישת הראיה בכתב:** מהי דרישת ה''ראיה בכתב'' בתביעה על סכום קצוב בהוצאה לפועל? ← חוזה או התחייבות מפורשים, שיש עליהם ראיה בכתב, רצוי חתומה על ידי החייב (סעיף 81א1(א)(1) לחוק ההוצאה לפועל; רער"צ (שלום עכו) 42663-04-22). **וריאציה 2 — הבדל מסדר דין מקוצר:** במה שונה דרישה זו מזו שהייתה בסדר דין מקוצר? ← בסדר דין מקוצר הספיקה התחייבות מכללא, בעוד שבהוצאה לפועל נדרשת התחייבות מפורשת (רער"צ (שלום עכו) 42663-04-22). **וריאציה 3 — מסמכים שאינם מספיקים:** האם חשבוניות ודפי חשבון בלבד מספיקים? ← לרוב לא, אם אינם חתומים על ידי החייב או קושרים אותו באופן מפורש לחוב (ת"ת (שלום ב"ש) 27973-12-13).',
    'ראיה בכתב בתביעה על סכום קצוב ← חוזה/התחייבות מפורשים + ראיה בכתב (רצוי חתימת חייב) ← מחמיר יותר מסדר דין מקוצר.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 81א1(א)(1)", "רער\"צ (שלום עכו) 42663-04-22 רצון ליברמן בע\"מ נ'' מידד רוימי (23.09.2022)", "(רשם ההוצאה לפועל אילת) 512144-05-24 חייבים נ'' (27.05.2024)", "ת\"ת (שלום ב\"ש) 27973-12-13 חברת פרטנר תקשורת בע\"מ נ'' אמור אבו חרמה (24.01.2014)", "ת\"ת (שלום ת\"א) 26784-11-24 טריא קהילה פיננסית בע\"מ נ'' אכלס דיאב (04.06.2025)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'סמכות רשם ההוצאה לפועל לבדיקת כשירות תביעה', 2, 'זוכה הגיש תביעה על סכום קצוב ללשכת ההוצאה לפועל. מזכירות הלשכה סירבה לפתוח את התיק בטענה שהתביעה אינה עומדת בתנאי ''ראיה בכתב'' הקבועים בסעיף 81א1(א) לחוק ההוצאה לפועל. מה הדין?',
    'שאלה זו עוסקת בסמכות רשם ההוצאה לפועל לבדוק את כשירותה של תביעה על סכום קצוב, ובאופן ספציפי, את ההבחנה בין סמכות המזכירות לבין סמכות הרשם. היא מדגישה כי בדיקת התנאים המהותיים להגשת תביעה על סכום קצוב נתונה לרשם, וכי במקרה של אי-עמידה בתנאים, יש להעביר את התביעה לבית המשפט.',
    'חוק ההוצאה לפועל מבחין בין תפקידי מזכירות ההוצאה לפועל לבין תפקידי רשם ההוצאה לפועל. מזכירות ההוצאה לפועל מוסמכת לבדוק את התנאים הפרוצדורליים להגשת בקשה לביצוע תביעה על סכום קצוב (כגון צירוף כל המסמכים הדרושים). אולם, בדיקת התקיימות התנאים המהותיים הקבועים בסעיף 81א1(א) לחוק, כגון קיומה של ''ראיה בכתב'', נתונה לסמכותו של רשם ההוצאה לפועל בלבד. סעיף 81א1(ו) לחוק קובע במפורש כי ''נוכח רשם ההוצאה לפועל כי לא התקיימו בתביעה התנאים הקבועים בסעיף קטן (א) יעבירה לבית המשפט''. כלומר, אם הרשם מוצא שהתביעה אינה עומדת בתנאי הסף, עליו להעביר אותה לבית המשפט המוסמך, ולא לסגור את התיק. החלטה של מזכירות לסרב לפתוח תיק בטענה לאי-עמידה בתנאים מהותיים היא חסרת סמכות. סעיף 81א1(ו) לחוק ההוצאה לפועל, תשכ"ז-1967רער"צ (שלום עכו) 42663-04-22 רצון ליברמן בע"מ נ'' מידד רוימי (23.09.2022)(רשם ההוצאה לפועל נצרת) העוררת נ'' המשיבה (08.05.2014)תא"ק (שלום ת"א) 13022-05-12 מיתן בנדל נ'' מוחמד מראענה (03.06.2013)רער"צ (שלום עכו) 52593-09-22 בית חולים המשפחה הקדושה נ'' מאי זילברמן (08.11.2022)',
    'טעות נפוצה היא לייחס למזכירות ההוצאה לפועל סמכויות שיפוטיות או מעין-שיפוטיות השמורות לרשם ההוצאה לפועל, או לחשוב שאי-עמידה בתנאים מובילה לסגירת התיק במקום להעברתו לבית המשפט.',
    '["רשם ההוצאה לפועל", "מזכירות ההוצאה לפועל", "סמכות עניינית", "העברת תביעה לבית המשפט", "תביעה על סכום קצוב", "סעיף 81א1(ו)"]'::jsonb,
    '**וריאציה 1 — סמכות המזכירות:** האם מזכירות ההוצאה לפועל מוסמכת לבדוק תנאים מהותיים לתביעה על סכום קצוב? ← לא, סמכותה מוגבלת לבדיקת תנאים פרוצדורליים (תא"ק (שלום ת"א) 13022-05-12). **וריאציה 2 — סמכות הרשם:** מי מוסמך לבדוק את התנאים המהותיים? ← רשם ההוצאה לפועל (סעיף 81א1(ו) לחוק ההוצאה לפועל). **וריאציה 3 — תוצאת אי-כשירות:** מה קורה אם רשם ההוצאה לפועל מוצא שהתביעה אינה כשירה? ← הוא יעביר אותה לבית המשפט המוסמך, ולא יסגור את התיק (סעיף 81א1(ו) לחוק ההוצאה לפועל; רער"צ (שלום עכו) 42663-04-22).',
    'מזכירות ← בדיקה פרוצדורלית; רשם ← בדיקה מהותית ← אי-כשירות ← העברה לבית המשפט.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 81א1(ו)", "רער\"צ (שלום עכו) 42663-04-22 רצון ליברמן בע\"מ נ'' מידד רוימי (23.09.2022)", "(רשם ההוצאה לפועל נצרת) העוררת נ'' המשיבה (08.05.2014)", "תא\"ק (שלום ת\"א) 13022-05-12 מיתן בנדל נ'' מוחמד מראענה (03.06.2013)", "רער\"צ (שלום עכו) 52593-09-22 בית חולים המשפחה הקדושה נ'' מאי זילברמן (08.11.2022)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'תביעה על סכום קצוב בתחום דיני עבודה', 3, 'עובד לשעבר מעוניין לתבוע את מעסיקו בגין אי-תשלום שכר עבודה קצוב בסך 50,000 ש"ח, ובידיו חוזה עבודה מפורש. האם העובד רשאי להגיש תביעה זו ישירות ללשכת ההוצאה לפועל כתביעה על סכום קצוב?',
    'שאלה זו בוחנת את גבולות תחולתו של סעיף 81א1 לחוק ההוצאה לפועל, ובפרט את היחס בינו לבין סמכותו הייחודית של בית הדין לעבודה. היא מדגישה כי הוראות חוק ההוצאה לפועל אינן גוברות על סמכות עניינית ייחודית של ערכאה אחרת, גם אם התביעה עומדת בתנאים הפורמליים של סכום קצוב וראיה בכתב.',
    'סעיף 81א1 לחוק ההוצאה לפועל מאפשר הגשת תביעה על סכום קצוב ישירות להוצאה לפועל, בתנאים מסוימים. אולם, אפשרות זו אינה גוברת על הוראות חוק ספציפיות המקנות סמכות ייחודית לערכאה אחרת. סעיף 24 לחוק בית הדין לעבודה קובע כי לבית הדין לעבודה סמכות ייחודית לדון בתביעות הנובעות מיחסי עובד-מעביד, לרבות תביעות לשכר עבודה. הפסיקה קבעה כי תביעה מתחום דיני עבודה, גם אם היא עומדת בתנאי סעיף 81א1 (סכום קצוב וראיה בכתב), אינה יכולה להיות מוגשת ישירות ללשכת ההוצאה לפועל, אלא לבית הדין לעבודה. זאת, משום שפרשנות הוראות חוק המעניקות סמכות צריכה להיות דווקנית ומצמצמת, ואין לשנות את סדרי הדין הנוהגים בבית הדין לעבודה באמצעות הגשת תביעות אלו להוצאה לפועל. סעיף 81א1(א)(1) לחוק ההוצאה לפועל, תשכ"ז-1967רע"א (מחוזי ת"א) 29839-10-11 יוליה שניידרמן נ'' דה סטנלי וורקס בע"מ (15.10.2012)עק"ג (ארצי ) 60709-01-24 ירמי בר - אלטשולר שחם גמל ופנסיה בע"מ (26.05.2024)(רשם ההוצאה לפועל עכו) 501972-06-21 פלונית נ'' (31.08.2022)(רשם ההוצאה לפועל עכו) 501972-06-21 פלונית נ'' (31.08.2022)',
    'טעות נפוצה היא להתעלם מסמכות עניינית ייחודית של בתי דין או בתי משפט ספציפיים, ולחשוב שכל תביעה על סכום קצוב ניתנת להגשה ישירות להוצאה לפועל.',
    '["סמכות ייחודית", "בית הדין לעבודה", "חוק בית הדין לעבודה", "תביעה על סכום קצוב", "הוצאה לפועל", "יחסי עובד-מעביד"]'::jsonb,
    '**וריאציה 1 — סמכות עניינית:** האם תביעת שכר עבודה קצוב ניתנת להגשה ישירות להוצאה לפועל? ← לא, היא בסמכותו הייחודית של בית הדין לעבודה (רע"א (מחוזי ת"א) 29839-10-11). **וריאציה 2 — חוק בית הדין לעבודה:** איזה סעיף קובע את הסמכות הייחודית? ← סעיף 24 לחוק בית הדין לעבודה (עק"ג (ארצי ) 60709-01-24). **וריאציה 3 — תכלית ההסדר:** מדוע לא ניתן להגיש תביעות אלו להוצאה לפועל? ← חוק ההוצאה לפועל אינו גובר על סמכות ייחודית, ואין לשנות את סדרי הדין בבית הדין לעבודה (רע"א (מחוזי ת"א) 29839-10-11).',
    'תביעת שכר עבודה קצוב ← סמכות ייחודית של בית הדין לעבודה ← לא ניתן להגיש ישירות להוצאה לפועל.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 81א1(א)(1)", "רע\"א (מחוזי ת\"א) 29839-10-11 יוליה שניידרמן נ'' דה סטנלי וורקס בע\"מ (15.10.2012)", "עק\"ג (ארצי ) 60709-01-24 ירמי בר - אלטשולר שחם גמל ופנסיה בע\"מ (26.05.2024)", "(רשם ההוצאה לפועל עכו) 501972-06-21 פלונית נ'' (31.08.2022)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'השלכות אי-המצאת התראה כדין', 4, 'זוכה הגיש תביעה על סכום קצוב ללשכת ההוצאה לפועל. החייב טוען כי לא קיבל התראה כדין בדואר רשום עם אישור מסירה, וכי אישור המסירה שצורף מזויף. מהן ההשלכות של אי-המצאת התראה כדין על הליך התביעה בהוצאה לפועל?',
    'שאלה זו עוסקת בחשיבותה המהותית של המצאת התראה כדין לחייב, כתנאי להגשת תביעה על סכום קצוב בהוצאה לפועל. היא מדגישה כי מדובר בדרישה מהותית, ולא פרוצדורלית גרידא, וכי אי-עמידה בה עלולה להוביל לסגירת התיק או להעברתו לבית המשפט, תוך חיוב הזוכה בהוצאות.',
    'סעיף 81א1(ב1) לחוק ההוצאה לפועל קובע כי ''המבקש לבצע תביעה על סכום קצוב לפי הוראות סעיף זה, ימציא לנתבע, בדואר רשום עם אישור מסירה, התראה בדבר כוונתו להגיש את התביעה כאמור לביצוע בהוצאה לפועל''. סעיף 81א1(ג)(1) מוסיף כי ''לא תוגש בקשה לביצוע תביעה על סכום קצוב ללשכת ההוצאה לפועל אלא בתום שלושים ימים ולא יאוחר משנה מיום שהתובע המציא לנתבע את ההתראה''. הפסיקה קבעה כי דרישת ההתראה היא דרישה מהותית, שמטרתה להעמיד את החייב על ההליכים הננקטים נגדו ולאפשר לו לצמצם את נזקיו. אי-המצאת התראה כדין, או המצאה פגומה, מונעת את הגשת התביעה במסלול זה. במקרה כזה, רשם ההוצאה לפועל יורה על סגירת התיק או על העברתו לבית המשפט, והזוכה עשוי לחוב בהוצאות. סעיף 81א1(ב1) לחוק ההוצאה לפועל, תשכ"ז-1967סעיף 81א1(ג)(1) לחוק ההוצאה לפועל, תשכ"ז-1967ת"ת (שלום צפת) 57742-11-19 אורי אברמסון נ'' יורם סונדק (13.09.2020)ת"ת (שלום ב"ש) 9355-05-24 דן באר שבע תחבורה (2016) בע"מ נ'' שמואל חברי (18.02.2025)ת"צ (מינהליים ת"א) 4768-08-15 שלומי אבני נ'' עיריית רמת-גן (05.03.2017)ת"ק (תביעות קטנות ת"א) 54488-02-20 אלה אסתר נאומייר נ'' בנק הפועלים בע"מ- שד'' רוטשילד 50 תל אביב (01.02.2021)ת"ת (שלום אש'') 3967-01-11 יובל הררי נ'' כרטיסי אשראי לישראל בע"מ (20.06.2011)',
    'טעות נפוצה היא לראות בהמצאת ההתראה דרישה טכנית בלבד, מבלי להבין את מעמדה המהותי ואת ההשלכות החמורות של אי-קיומה על כשירות התביעה.',
    '["התראה", "המצאה כדין", "דואר רשום עם אישור מסירה", "תנאי מהותי", "סעיף 81א1(ב1)", "סגירת תיק הוצאה לפועל", "הוצאות משפט"]'::jsonb,
    '**וריאציה 1 — חשיבות ההתראה:** האם המצאת התראה היא תנאי מהותי? ← כן, היא תנאי מוקדם להגשת תביעה על סכום קצוב בהוצאה לפועל (סעיף 81א1(ב1) ו-(ג)(1) לחוק ההוצאה לפועל; ת"ק (תביעות קטנות ת"א) 54488-02-20). **וריאציה 2 — תוצאת אי-המצאה:** מה קורה אם לא הומצאה התראה כדין? ← התביעה אינה כשירה להתברר בהוצאה לפועל, והתיק ייסגר או יועבר לבית המשפט (ת"ת (שלום צפת) 57742-11-19; ת"ת (שלום אש'') 3967-01-11). **וריאציה 3 — אופן ההמצאה:** כיצד יש להמציא את ההתראה? ← בדואר רשום עם אישור מסירה, או במסירה אישית על ידי עורך דין אם הניסיון הראשון נכשל (סעיף 81א1(ב1) לחוק ההוצאה לפועל; ת"ת (שלום ב"ש) 9355-05-24).',
    'אי-המצאת התראה כדין ← פגם מהותי ← סגירת תיק/העברה לבית משפט + הוצאות.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 81א1(ב1)", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 81א1(ג)(1)", "ת\"ת (שלום צפת) 57742-11-19 אורי אברמסון נ'' יורם סונדק (13.09.2020)", "ת\"ת (שלום ב\"ש) 9355-05-24 דן באר שבע תחבורה (2016) בע\"מ נ'' שמואל חברי (18.02.2025)", "ת\"צ (מינהליים ת\"א) 4768-08-15 שלומי אבני נ'' עיריית רמת-גן (05.03.2017)", "ת\"ק (תביעות קטנות ת\"א) 54488-02-20 אלה אסתר נאומייר נ'' בנק הפועלים בע\"מ- שד'' רוטשילד 50 תל אביב (01.02.2021)", "ת\"ת (שלום אש'') 3967-01-11 יובל הררי נ'' כרטיסי אשראי לישראל בע\"מ (20.06.2011)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'כן, די בראיות בכתב המעידות על התחייבות מכללא, בדומה לדרישה שהייתה קיימת בתביעות בסדר דין מקוצר.', false, 'תשובה זו שגויה. הדרישה ל''ראיה בכתב'' בתביעה על סכום קצוב בהוצאה לפועל מחמירה יותר מזו שהייתה בסדר דין מקוצר, ואינה מסתפקת בהתחייבות מכללא.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לא, הדרישה היא לחוזה או התחייבות מפורשים שיש עליהם ראיה בכתב, ורצוי שהראיה תהיה חתומה על ידי החייב או קשורה אליו באופן מובהק.', true, 'זו התשובה הנכונה. סעיף 81א1(א)(1) לחוק ההוצאה לפועל דורש ''חוזה או התחייבות מפורשים, שיש עליה ראיה בכתב'', ופסיקת בתי המשפט מפרשת זאת באופן מחמיר יותר מתקנה 202 הישנה, תוך דרישה לראיה הקושרת את החייב לחוב, לרוב באמצעות חתימתו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, חשבוניות ודף חשבון מהווים ראיה בכתב מספקת, שכן הם מפרטים את החוב וניתנים לחישוב אריתמטי.', false, 'תשובה זו שגויה. אף שהסכום קצוב, המסמכים צריכים להעיד על ''חוזה או התחייבות מפורשים'' ולקשור את החייב לחוב, ולא רק לפרט אותו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, אלא אם כן החברה תוכיח כי הלקוח קיבל את השירותים בפועל, שאז ניתן להסתפק בראיה בכתב פחות מחמירה.', false, 'תשובה זו שגויה. קבלת השירותים בפועל אינה משנה את דרישת ה''ראיה בכתב'' המפורשת בחוק, והיא אינה תנאי חלופי.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'מזכירות ההוצאה לפועל מוסמכת לבדוק את כשירות התביעה, ואם היא מוצאת שהתנאים לא התקיימו, היא רשאית לסרב לפתוח את התיק.', false, 'תשובה זו שגויה. למזכירות ההוצאה לפועל אין סמכות לבדוק את התקיימות התנאים המהותיים של סעיף 81א1(א), אלא רק את התנאים הפרוצדורליים להגשה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'רשם ההוצאה לפועל הוא הגורם המוסמך לבדוק את התקיימות התנאים המהותיים, ואם ימצא שהתביעה אינה עומדת בהם, יעביר אותה לבית המשפט המוסמך.', true, 'זו התשובה הנכונה. סעיף 81א1(ו) לחוק ההוצאה לפועל קובע כי רשם ההוצאה לפועל הוא שמוסמך לבדוק את התקיימות התנאים, ואם לא התקיימו, עליו להעביר את התביעה לבית המשפט, ולא לסגור את התיק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'התביעה תיסגר לאלתר, שכן אי-עמידה בתנאי ''ראיה בכתב'' פוסלת אותה מלהתברר בהוצאה לפועל.', false, 'תשובה זו שגויה. אי-עמידה בתנאים אינה מובילה לסגירה אוטומטית של התיק, אלא להעברתו לבית המשפט המוסמך.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'הזוכה רשאי להגיש ערעור לבית המשפט המחוזי על החלטת המזכירות, בטענה לחוסר סמכות.', false, 'תשובה זו שגויה. ערעור על החלטת מזכירות יוגש לרשם ההוצאה לפועל, ולא ישירות לבית המשפט המחוזי.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'כן, כל עוד הסכום אינו עולה על 75,000 ש"ח וקיימת ראיה בכתב, ניתן להגיש את התביעה ישירות להוצאה לפועל.', false, 'תשובה זו שגויה. אף שהתנאים של סכום וראיה בכתב מתקיימים, יש לבחון את הסמכות העניינית הייחודית של בית הדין לעבודה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לא, שכן תביעות הנובעות מיחסי עובד-מעביד נתונות לסמכותו הייחודית של בית הדין לעבודה, ואין להגישן ישירות להוצאה לפועל.', true, 'זו התשובה הנכונה. סעיף 24 לחוק בית הדין לעבודה מקנה לבית הדין לעבודה סמכות ייחודית לדון בתביעות הנובעות מיחסי עובד-מעביד, וסמכות זו גוברת על האפשרות הכללית להגיש תביעה על סכום קצוב להוצאה לפועל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'כן, אך רק אם המעסיק לא הגיש התנגדות בתוך 30 יום, שאז התביעה הופכת לפסק דין חלוט.', false, 'תשובה זו שגויה. אי-הגשת התנגדות הופכת את התביעה לחלוטה רק אם היא הוגשה כדין לערכאה המוסמכת מלכתחילה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא, אלא אם כן מדובר בתביעה שטרית, שאז ניתן להגישה ישירות להוצאה לפועל גם אם עסקת היסוד היא מתחום דיני עבודה.', false, 'תשובה זו שגויה. אף שתביעה שטרית ניתנת לביצוע בהוצאה לפועל, השאלה מתייחסת לתביעה בגין שכר עבודה מכוח חוזה, ולא לתביעה שטרית.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'אי-המצאת התראה כדין היא פגם פרוצדורלי בלבד, ובית המשפט יורה על המצאה חוזרת של ההתראה, אך התיק לא ייסגר.', false, 'תשובה זו שגויה. המצאת התראה כדין היא תנאי מהותי להגשת התביעה, ולא רק פגם פרוצדורלי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'אי-המצאת התראה כדין מהווה פגם מהותי המונע את הגשת התביעה בהוצאה לפועל, ועל רשם ההוצאה לפועל לסגור את התיק או להעבירו לבית המשפט, והזוכה עשוי לחוב בהוצאות.', true, 'זו התשובה הנכונה. סעיפים 81א1(ב1) ו-(ג)(1) לחוק ההוצאה לפועל קובעים את חובת המצאת ההתראה כתנאי מהותי. אי-קיומו מונע את הגשת התביעה במסלול זה, ורשם ההוצאה לפועל יורה על סגירת התיק או העברתו לבית המשפט, תוך אפשרות לחייב את הזוכה בהוצאות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'החייב רשאי להגיש התנגדות לביצוע התביעה, אך עליו להוכיח כי נגרם לו נזק ממשי עקב אי-המצאת ההתראה.', false, 'תשובה זו שגויה. אי-המצאת התראה כדין היא עילה להתנגדות בפני עצמה, ואין צורך להוכיח נזק ממשי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'הזוכה יחויב בתשלום קנס כספי, אך הליכי ההוצאה לפועל יימשכו כרגיל.', false, 'תשובה זו שגויה. אי-המצאת התראה כדין פוגעת בעצם כשירות התביעה להתברר בהוצאה לפועל, ולא רק מובילה לקנס.', 4);

END $$;

-- ============================================================
-- Q23 — 2024-W-Q23 — chapter=execution subtopic=asset_seizure
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q23';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q23 skipped: external_id % already exists', '2024-W-Q23';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'asset_seizure';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'asset_seizure';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q23', 'b3904dc7-882d-48fc-9f3c-ba89fc453003', v_subtopic_id,
    'משה חייב זמן רב כסף ליוסף (הזוכה) ובמרס 2023 פתח יוסף תיק הוצאה לפועל נגדו. משה מכר ליצחק, חברו הטוב, את דירתו. יצחק ידע על הבעיות הכלכליות של משה ועל תיק ההוצאה לפועל שנפתח נגדו. ביוני 2023 ולמרות שידע על תיק הוצאה לפועל, שילם יצחק את מלוא תמורת הדירה למשה. ימים מספר לאחר מכן הגיע לידיו של יצחק צו עיקול, לפיו עליו להעביר כל סכום שהוא חייב למשה לתיק ההוצאה לפועל (עיקול צד ג''). יצחק טוען כי אין לו מה להעביר לתיק ההוצאה לפועל, משום שהוא העביר את תמורת הדירה למשה לפני שידע על צו עיקול. מה הדין?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 23}'::jsonb,
    'שאלה זו עוסקת באחריותו של צד שלישי בהליכי הוצאה לפועל, ובפרט בחיובו האישי לפי סעיף 48 לחוק ההוצאה לפועל. היא בוחנת את היסוד של ''ידיעה על צו עיקול'' בעת הוצאת נכס או תשלום חוב, ומדגישה את נטל ההוכחה המוטל על הזוכה להוכיח יסוד זה. השאלה מבחינה בין ידיעה כללית על קיומו של תיק הוצאה לפועל לבין ידיעה ספציפית על צו עיקול.',
    'סעיף 48(א) לחוק ההוצאה לפועל, תשכ"ז-1967, קובע כי רשם ההוצאה לפועל רשאי לחייב צד שלישי בתשלום החוב הפסוק אם הצד השלישי ''ללא הצדק סביר לא עשה כאמור בסעיף 47, או הוציא מידו נכס או שילם חוב שלא כדין בידעו שיש עליו צו עיקול בידי צד שלישי''. הפסיקה מפרשת יסוד זה באופן דווקני. הנטל להוכיח כי הצד השלישי ידע על צו העיקול בעת הוצאת הנכס או תשלום החוב מוטל על הזוכה. ידיעה כללית על קיומו של תיק הוצאה לפועל או על בעיותיו הכלכליות של החייב אינה מספיקה כדי להקים חיוב לפי סעיף 48(א). יש להוכיח ידיעה קונקרטית על צו העיקול עצמו. במקרה הנדון, יצחק שילם את התמורה למשה לפני שהגיע לידיו צו העיקול. אף אם יצחק ידע על תיק ההוצאה לפועל, כל עוד הזוכה לא הוכיח שיצחק ידע על צו העיקול הספציפי בעת התשלום, לא ניתן לחייבו לפי סעיף 48(א). סעיף 48(א) לחוק ההוצאה לפועל, תשכ"ז-1967ע"א 4/84 מאיר שטאל נ'' עמידר, החברה הלאומית לשכון עולים בישראל בע"מ (14.12.1986)ע"ר (שלום ביש"א) 12635-08-11 ליבנה עמוס נ'' עטאללה יוסף עלי (26.07.2012)רע"א 5211/97 חיטים מכון תערובת בע"מ נ'' טנא אגודה שיתופית מרכזית לשיווק תוצרת חקלאית בישראל (09.03.1998)דוד בר -אופיר הוצאה לפועל הליכים ‏והלכות - כרך ב (2025) | צד שלישי - חקירתו - סדרי דין בהליכי החיוב - אין עיקול זמני - נטל השכנוע - הגנות - הימצאות המעוקל בידיו - הצדק סביר - חיובו בתשלום החוב הפסוק (סעיף 48 לחוק)',
    'טעות נפוצה היא לבלבל בין ידיעה כללית על קיומו של תיק הוצאה לפועל לבין ידיעה ספציפית על צו עיקול, ולחשוב שהראשונה מספיקה כדי להקים חיוב לפי סעיף 48(א). כמו כן, יש לזכור שנטל ההוכחה לידיעה זו מוטל על הזוכה.',
    '["חיוב צד שלישי", "צו עיקול", "ידיעה על צו עיקול", "נטל הוכחה", "הצדק סביר", "סעיף 48 לחוק ההוצאה לפועל", "הוצאת נכס שלא כדין"]'::jsonb,
    '**וריאציה 1 — יסוד הידיעה:** מה נדרש כדי לחייב צד שלישי ששילם חוב? ← ידיעה על *צו העיקול* בעת התשלום, לא רק ידיעה על תיק הוצאה לפועל (סעיף 48(א) לחוק ההוצאה לפועל). **וריאציה 2 — נטל ההוכחה:** מי צריך להוכיח את הידיעה על צו העיקול? ← הזוכה (ע"א 4/84 שטאל). **וריאציה 3 — תזמון הידיעה:** האם ידיעה לאחר התשלום רלוונטית? ← לא, הידיעה צריכה להיות קיימת *בעת* הוצאת הנכס או תשלום החוב (ע"ר 12635-08-11 ליבנה עמוס).',
    'חיוב צד שלישי לפי סעיף 48(א) ← דורש ידיעה על *צו העיקול* בעת התשלום ← נטל ההוכחה על הזוכה.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 48(א)", "ע\"א 4/84 מאיר שטאל נ'' עמידר, החברה הלאומית לשכון עולים בישראל בע\"מ (14.12.1986)", "ע\"ר (שלום ביש\"א) 12635-08-11 ליבנה עמוס נ'' עטאללה יוסף עלי (26.07.2012)", "רע\"א 5211/97 חיטים מכון תערובת בע\"מ נ'' טנא אגודה שיתופית מרכזית לשיווק תוצרת חקלאית בישראל (09.03.1998)", "עש\"א (שלום קריות) 25104-08-13 טמבור הפצות בע\"מ נ'' עפיף אבו נאג''י (06.03.2014)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מאחר שיצחק ידע על תיק ההוצאה לפועל, יצחק פעל בחוסר תום לב, אינו רשאי לטעון להצדק סביר ועליו לשלם לתיק ההוצאה לפועל את הסכום שהעביר למשה או את החוב הפסוק, הנמוך מביניהם.', false, 'תשובה זו שגויה. סעיף 48(א) לחוק ההוצאה לפועל דורש ידיעה על צו העיקול בעת הוצאת הנכס או תשלום החוב, ולא רק ידיעה כללית על קיומו של תיק הוצאה לפועל או בעיות כלכליות של החייב.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מאחר שהזוכה לא הוכיח כי כאשר יצחק העביר את התשלום למשה ידע יצחק על צו העיקול, אין חובה על יצחק להעביר את הכסף לתיק ההוצאה לפועל.', true, 'זו התשובה הנכונה. סעיף 48(א) לחוק ההוצאה לפועל קובע כי צד שלישי יחויב אם הוציא נכס או שילם חוב שלא כדין בידעו שיש עליו צו עיקול. הנטל להוכיח ידיעה זו מוטל על הזוכה. ידיעה על תיק הוצאה לפועל אינה שקולה לידיעה על צו עיקול ספציפי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מאחר שיצחק ידע על תיק ההוצאה לפועל, יצחק פעל בחוסר תום לב ואינו רשאי לטעון להצדק סביר, אך רשאי לבקש שתיערך חקירת יכולת ועליו נטל ההוכחה שהוא לא ידע על צו עיקול.', false, 'תשובה זו שגויה. נטל ההוכחה כי צד שלישי ידע על צו העיקול בעת התשלום מוטל על הזוכה, ולא על הצד השלישי להוכיח שלא ידע. כמו כן, ידיעה על תיק הוצאה לפועל אינה מספיקה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בטרם יוכל רשם ההוצאה לפועל לקבוע אם יצחק פעל לפי הצדק סביר אם לאו, יש להזמינו לחקירת יכולת בפני הרשם. נטל ההוכחה על כך שלא ידע על צו עיקול, מוטל על יצחק.', false, 'תשובה זו שגויה. חקירה לפי סעיף 46 לחוק ההוצאה לפועל היא הליך לבירור קיומם של נכסים, אך היא אינה משנה את נטל ההוכחה המוטל על הזוכה להוכיח את יסודות סעיף 48(א), ובפרט את ידיעת הצד השלישי על צו העיקול בעת התשלום.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'חיוב צד שלישי שהתעלם מצו עיקול בשם שגוי', 1, 'חברה קיבלה צו עיקול על משכורתו של עובד שלה, אך בצו נרשם שם שגוי של החברה (שם של אחד ממוצריה). החברה התעלמה מהצו ולא עיקלה את המשכורת. הזוכה מבקש לחייב את החברה בחוב הפסוק. האם התעלמות החברה מהצו מהווה ''הצדק סביר'' לאי-קיום הצו?',
    'שאלה זו בוחנת את גבולות המושג ''הצדק סביר'' בסעיף 48 לחוק ההוצאה לפועל, במקרה של פגם פורמלי בצו העיקול. היא מדגישה את חובת תום הלב המוטלת על צד שלישי המקבל צו עיקול, ואת האפשרות לייחס אשם תורם לזוכה במקרים של התרשלות.',
    'סעיף 48(א) לחוק ההוצאה לפועל מאפשר לחייב צד שלישי בתשלום החוב הפסוק אם ''ללא הצדק סביר לא עשה כאמור בסעיף 47, או הוציא מידו נכס או שילם חוב שלא כדין בידעו שיש עליו צו עיקול בידי צד שלישי''. הפסיקה קבעה כי המבחן ל''הצדק סביר'' הוא מבחן אובייקטיבי של ''התנהגות תקינה ומקובלת של אדם מן היישוב''. במקרה של צו עיקול שהוטל בשם שגוי, אך כוונתו הייתה גלויה וברורה לצד השלישי, התעלמות מהצו אינה מהווה ''הצדק סביר''. על הצד השלישי לפעול בתום לב, למשל, על ידי פנייה לרשם ההוצאה לפועל בבקשה למתן הוראות. עם זאת, הפסיקה מכירה באפשרות של ''אשם יחסי'' בין הצדדים, כך שאם הזוכה התרשל (למשל, בניסוח הצו או באי-מעקב), ניתן לייחס לו אשם תורם ולהפחית את חיוב הצד השלישי. סעיף 48(א) לחוק ההוצאה לפועל, תשכ"ז-1967רע"א 1016/08 ע.א.מ. קונדוס בע"מ נ'' אגס ירוק מסחר ושירותים בע"מ (14.01.2010)רע"א 1016/08 ע.א.מ. קונדוס בע"מ נ'' אגס ירוק מסחר ושירותים בע"מ (14.01.2010)עש"א (שלום ת"א) 59404-12-12 הפניקס חברה לביטוח בע"מ נ'' ראובן סרבי בע"מ (12.03.2013)דוד בר -אופיר הוצאה לפועל הליכים ‏והלכות - כרך ב (2025) | מסירת נכסים מעוקלים ופטור מאחריות - שמירה על ערך הכספים המעוקלים - טען ביניים',
    'טעות נפוצה היא לחשוב שכל פגם פורמלי בצו העיקול פוטר אוטומטית את הצד השלישי מאחריות, מבלי לבחון את חובת תום הלב ואת בהירות כוונת הצו.',
    '["חיוב צד שלישי", "הצדק סביר", "צו עיקול", "פגם פורמלי", "תום לב", "אשם יחסי", "סעיף 48 לחוק ההוצאה לפועל"]'::jsonb,
    '**וריאציה 1 — פגם בצו:** האם שם שגוי בצו עיקול פוטר צד שלישי? ← לא, אם כוונת הצו ברורה וגלויה, אין להתעלם ממנו (רע"א 1016/08 קונדוס). **וריאציה 2 — חובת תום לב:** מה מצופה מצד שלישי במקרה כזה? ← לפעול בתום לב, למשל, לפנות לרשם ההוצאה לפועל למתן הוראות (עש"א 59404-12-12 הפניקס). **וריאציה 3 — אשם תורם:** האם הזוכה יכול לשאת באחריות? ← כן, אם התרשל, ניתן לייחס לו אשם תורם ולהפחית את חיוב הצד השלישי (רע"א 1016/08 קונדוס).',
    'צו עיקול פגום אך ברור ← אין הצדק סביר להתעלמות ← חובת תום לב על צד שלישי ← אפשרות לאשם תורם לזוכה.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 48(א)", "רע\"א 1016/08 ע.א.מ. קונדוס בע\"מ נ'' אגס ירוק מסחר ושירותים בע\"מ (14.01.2010)", "ע\"ר (שלום עכו) 28515-11-15 א.מ. עבודות גרנוליט ושיפוצים בע\"מ נ'' ג''מיל סרחאן בע\"מ (19.02.2017)", "עש\"א (שלום ת\"א) 59404-12-12 הפניקס חברה לביטוח בע\"מ נ'' ראובן סרבי בע\"מ (12.03.2013)", "דוד בר -אופיר, הוצאה לפועל הליכים ‏והלכות - כרך ב (2025), פרק כ\"ג: עיקול בידי צד שלישי"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'נטל ההוכחה ו"הצדק סביר" בחיוב צד שלישי', 2, 'מהו נטל ההוכחה בבקשה לחיוב צד שלישי לפי סעיף 48 לחוק ההוצאה לפועל, ומהו המבחן לקיומו של ''הצדק סביר''?',
    'שאלה זו מתמקדת בנטלי ההוכחה ובמבחן המשפטי ל''הצדק סביר'' בהליכי חיוב צד שלישי לפי סעיף 48 לחוק ההוצאה לפועל. היא מבהירה את חלוקת הנטלים בין הזוכה לצד השלישי ואת אופיו האובייקטיבי של מבחן ''הצדק סביר''.',
    'סעיף 48(א) לחוק ההוצאה לפועל קובע את התנאים לחיוב צד שלישי. הפסיקה מפרשת את נטל ההוכחה באופן דו-שלבי: בשלב הראשון, על הזוכה המבקש את החיוב להוכיח כי הצד השלישי החזיק בנכסים מעוקלים של החייב במועד הקובע, וכי הוא לא מילא אחר חובתו למסור אותם למוציא לפועל (סעיף 47) או הוציא אותם מידיו/שילם חוב שלא כדין בידעו שיש עליו צו עיקול. רק לאחר שהזוכה עמד בנטל זה, עובר הנטל לצד השלישי להוכיח כי עמד לו ''הצדק סביר'' למעשיו או מחדליו. המבחן ל''הצדק סביר'' הוא אובייקטיבי: ''התנהגות תקינה ומקובלת של אדם מן היישוב, כפי שהיה פועל באותן נסיבות שבהן פעל הצד השלישי'', בתוספת עקרון תום הלב. סעיף 48(א) לחוק ההוצאה לפועל, תשכ"ז-1967ע"ר (שלום ביש"א) 12635-08-11 ליבנה עמוס נ'' עטאללה יוסף עלי (26.07.2012) (רשם ההוצאה לפועל ראשון לציון) 509894-08-21 זוכה נ'' (23.03.2023) (רשם ההוצאה לפועל ירושלים) 530131-03-17 מסייע 1 נ'' חייב 1 (13.03.2022)דוד בר -אופיר הוצאה לפועל הליכים ‏והלכות - כרך ב (2025) | צד שלישי - חקירתו - סדרי דין בהליכי החיוב - אין עיקול זמני - נטל השכנוע - הגנות - הימצאות המעוקל בידיו - הצדק סביר - חיובו בתשלום החוב הפסוק (סעיף 48 לחוק)',
    'טעות נפוצה היא לבלבל בין נטל ההוכחה הראשוני המוטל על הזוכה לבין הנטל המשני המוטל על הצד השלישי, או לחשוב שמבחן ''הצדק סביר'' הוא סובייקטיבי.',
    '["נטל הוכחה", "נטל שכנוע", "הצדק סביר", "חיוב צד שלישי", "סעיף 48 לחוק ההוצאה לפועל", "מבחן אובייקטיבי"]'::jsonb,
    '**וריאציה 1 — נטל הזוכה:** מה הזוכה צריך להוכיח כדי לחייב צד שלישי? ← שהצד השלישי החזיק בנכסים ופעל בניגוד לצו העיקול בידעו עליו (סעיף 48(א) לחוק ההוצאה לפועל; ע"ר 12635-08-11 ליבנה עמוס). **וריאציה 2 — נטל הצד השלישי:** מתי עובר הנטל לצד השלישי? ← לאחר שהזוכה עמד בנטל הראשוני, עובר הנטל לצד השלישי להוכיח ''הצדק סביר'' ( (רשם ההוצאה לפועל ראשון לציון) 509894-08-21 זוכה נ''). 
**וריאציה 3 — מבחן ''הצדק סביר'':** מהו המבחן ל''הצדק סביר''? ← מבחן אובייקטיבי של התנהגות אדם מן היישוב בנסיבות דומות (דוד בר -אופיר, הוצאה לפועל הליכים ‏והלכות - כרך ב).',
    'חיוב צד שלישי ← זוכה מוכיח יסודות סעיף 48(א) ← צד שלישי מוכיח ''הצדק סביר'' (מבחן אובייקטיבי).',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 48(א)", "ע\"ר (שלום ביש\"א) 12635-08-11 ליבנה עמוס נ'' עטאללה יוסף עלי (26.07.2012)", "(רשם ההוצאה לפועל ראשון לציון) 509894-08-21 זוכה נ'' (23.03.2023)", "(רשם ההוצאה לפועל ירושלים) 530131-03-17 מסייע 1 נ'' חייב 1 (13.03.2022)", "דוד בר -אופיר, הוצאה לפועל הליכים ‏והלכות - כרך ב (2025), פרק כ\"ג: עיקול בידי צד שלישי"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'עיקול זכות עתידית וקיזוז בנקאי', 3, 'בנק קיבל צו עיקול על כלל נכסי החייב המוחזקים אצלו. לחייב חשבון עו"ש ביתרת חובה וחשבון חיסכון ביתרת זכות. הבנק טוען לזכות קיזוז. מה הדין לגבי תוקף העיקול?',
    'שאלה זו עוסקת במעמדו המיוחד של בנק כצד שלישי בהליכי עיקול, ובפרט בזכות הקיזוז הייחודית המוקנית לו. היא מדגישה את ההבחנה בין זכותו של החייב לכספים לבין זכויות הבנק כלפי החייב, ואת השפעתן על תוקף צו העיקול.',
    'סעיף 44 לחוק ההוצאה לפועל קובע כי צו עיקול בידי צד שלישי יחול על נכסי החייב הנמצאים בידי הצד השלישי ביום המצאת הצו או שיגיעו לידו תוך שלושה חודשים. עם זאת, הפסיקה הכירה בזכות קיזוז ייחודית לבנקים. כאשר לחייב מספר חשבונות בבנק, והוא מצוי ביתרת חובה כוללת (גם אם יש לו חשבון אחד ביתרת זכות), העיקול אינו תופס דבר. זאת משום שהכספים המצויים בחשבונות החייב שייכים לבנק, ו''הנכס'' המעוקל הוא רק זכותו של החייב לתבוע מהבנק לשלם לו כספים. זכות זו של החייב, העוברת למעקל, כפופה לזכויות הבנק לפי הסכמיו עם החייב, המאפשרים קיזוז בין חשבונות. סעיף 44(א) לחוק ההוצאה לפועל, תשכ"ז-1967רע"צ (שלום נצ'') 14979-10-13 סמעאן עאנק נ'' בנק לאומי בע"מ (09.06.2014)רע"צ (שלום נצ'') 14979-10-13 סמעאן עאנק נ'' בנק לאומי בע"מ (09.06.2014)ע"א (מחוזי חיפה) 2855/01 סעיד עותמאן נ'' המועצה המקומית דיר אל אסד (03.09.2002)נבו - המתמחה דיני הוצאה לפועל (2026) | הטלת עיקול אצל צד שלישי',
    'טעות נפוצה היא להתייחס לבנק כאל צד שלישי רגיל, מבלי להכיר בזכות הקיזוז הייחודית שלו, אשר יכולה לנטרל את תוקף צו העיקול במקרים מסוימים.',
    '["עיקול בידי צד שלישי", "זכות קיזוז", "בנק", "נכסים מעוקלים", "חובות", "סעיף 44 לחוק ההוצאה לפועל"]'::jsonb,
    '**וריאציה 1 — זכות קיזוז בנקאית:** האם בנק יכול לקזז חובות כנגד עיקול? ← כן, לבנק זכות קיזוז ייחודית הגוברת על העיקול אם החייב ביתרת חובה כוללת (רע"צ 14979-10-13 סמעאן עאנק). **וריאציה 2 — נכס מעוקל בבנק:** מהו ''נכס'' כשמדובר בבנק? ← רק זכותו של החייב לתבוע מהבנק לשלם לו כספים, לאחר קיזוז חובותיו לבנק (רע"צ 14979-10-13 סמעאן עאנק). **וריאציה 3 — השוואה לנושים אחרים:** האם לנושים אחרים יש זכות קיזוז דומה? ← לא, ההלכה הפסוקה אוסרת קיזוז מול עיקול למי שאינו בנק (ע"א 2855/01 סעיד עותמאן).',
    'עיקול בבנק ← בנק יכול לקזז חובות ← אם החייב ביתרת חובה כוללת, העיקול לא תופס.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 44", "רע\"צ (שלום נצ'') 14979-10-13 סמעאן עאנק נ'' בנק לאומי בע\"מ (09.06.2014)", "ע\"א (מחוזי חיפה) 2855/01 סעיד עותמאן נ'' המועצה המקומית דיר אל אסד (03.09.2002)", "נבו - המתמחה, דיני הוצאה לפועל (2026), פרק ז - הליכים נגד רכוש"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'הליכים מקדימים לחיוב צד שלישי', 4, 'זוכה הטיל צו עיקול על נכסי חייב המוחזקים בידי צד שלישי. הצד השלישי השיב לצו כי אין בידיו נכסים של החייב. הזוכה חושד כי התשובה אינה נכונה. מהם ההליכים שעל הזוכה לנקוט כדי לברר את העניין ולחייב את הצד השלישי, אם יתברר שהחזיק בנכסים?',
    'שאלה זו עוסקת בהליכים הדיוניים שעל זוכה לנקוט כאשר צד שלישי מכחיש החזקת נכסים של החייב, וזאת לפני שניתן לחייב את הצד השלישי באופן אישי. היא מדגישה את חשיבות הליך החקירה לפי סעיף 46 לחוק ההוצאה לפועל כשלב מקדים להוכחת יסודות סעיף 48.',
    'חוק ההוצאה לפועל קובע היררכיה של הליכים. סעיף 44 לחוק מטיל על צד שלישי חובה להגיש הודעה המפרטת את נכסי החייב שבידיו. אם הצד השלישי לא הגיש הודעה, או שהודעתו אינה שלמה או נכונה, רשאי רשם ההוצאה לפועל, לפי בקשת הזוכה, לזמן את הצד השלישי לחקירה לפי סעיף 46 לחוק. חקירה זו נועדה לברר את קיומם של נכסים. הפסיקה קבעה כי זוכה אינו רשאי להגיש בקשה לחיוב צד שלישי בחוב הפסוק לפי סעיף 48 לחוק, אלא לאחר שהוכיח תחילה כי אכן קיים בידי צד שלישי נכס מעוקל השייך לחייב. מכאן, שכאשר צד שלישי לא מאשר בתגובתו לצו העיקול שקיים בידיו נכס מעוקל של החייב, על הזוכה לנקוט תחילה בהליך של חקירת צד שלישי לפי סעיף 46 לחוק. רק אם עלה בידי הזוכה להוכיח קיומם של נכסים, עובר הנטל לצד השלישי להראות ''הצדק סביר'' לאי-מסירתם. סעיף 46(א) לחוק ההוצאה לפועל, תשכ"ז-1967ע"ר (שלום ביש"א) 12635-08-11 ליבנה עמוס נ'' עטאללה יוסף עלי (26.07.2012) (רשם ההוצאה לפועל פתח תקוה) 526420-11-24 חייב 1 נ'' (06.08.2025)ע"א (מחוזי ירושלים) 9293/06 רם-שן שירותים והשקעות בע"מ נ'' בנק מסד בע"מ - סניף חיפה (24.12.2006)דוד בר -אופיר הוצאה לפועל הליכים ‏והלכות - כרך ב (2025) | צד שלישי - חקירתו - סדרי דין בהליכי החיוב - אין עיקול זמני - נטל השכנוע - הגנות - הימצאות המעוקל בידיו - הצדק סביר - חיובו בתשלום החוב הפסוק (סעיף 48 לחוק)',
    'טעות נפוצה היא לחשוב שאי-מענה לצו עיקול או מענה שאינו נכון מספיק כשלעצמו לחיוב צד שלישי, מבלי להבין את הצורך בהוכחה פוזיטיבית של החזקת נכסים.',
    '["חקירת צד שלישי", "חיוב צד שלישי", "נטל הוכחה", "נכסים מעוקלים", "סעיף 46 לחוק ההוצאה לפועל", "סעיף 48 לחוק ההוצאה לפועל"]'::jsonb,
    '**וריאציה 1 — הכחשת נכסים:** צד שלישי מכחיש החזקת נכסים. מה הזוכה עושה? ← ינקוט הליך חקירה לפי סעיף 46 לחוק ההוצאה לפועל ( (רשם ההוצאה לפועל פתח תקוה) 526420-11-24 חייב 1 נ''). **וריאציה 2 — מטרת החקירה:** מה מטרת החקירה לפי סעיף 46? ← לברר את קיומם של נכסים בידי הצד השלישי (סעיף 46(א) לחוק ההוצאה לפועל). **וריאציה 3 — חיוב לפי סעיף 48:** מתי ניתן לחייב לפי סעיף 48? ← רק לאחר שהזוכה הוכיח שהצד השלישי החזיק בנכסים ופעל בניגוד לצו (ע"א 9293/06 רם-שן).',
    'צד שלישי מכחיש נכסים ← זוכה יחקור לפי סעיף 46 ← יוכיח נכסים ← רק אז יוכל לחייב לפי סעיף 48.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 46", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 48", "ע\"ר (שלום ביש\"א) 12635-08-11 ליבנה עמוס נ'' עטאללה יוסף עלי (26.07.2012)", "(רשם ההוצאה לפועל פתח תקוה) 526420-11-24 חייב 1 נ'' (06.08.2025)", "ע\"א (מחוזי ירושלים) 9293/06 רם-שן שירותים והשקעות בע\"מ נ'' בנק מסד בע\"מ - סניף חיפה (24.12.2006)", "דוד בר -אופיר, הוצאה לפועל הליכים ‏והלכות - כרך ב (2025), פרק כ\"ג: עיקול בידי צד שלישי"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'כן, שכן החברה אינה צד לסכסוך ואינה חייבת לפרש צווי עיקול שאינם מופנים אליה במדויק.', false, 'תשובה זו שגויה. הפסיקה קבעה כי אם כוונת הצו ברורה וגלויה, אין להתעלם ממנו, ואין בכך ''הצדק סביר''.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לא, אם כוונת הצו הייתה גלויה וברורה לחברה, התעלמותה אינה ''הצדק סביר'', אך ייתכן שתוטל עליה אחריות חלקית בלבד בשל אשם תורם של הזוכה.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי אם כוונת הצו ברורה, אין להתעלם ממנו. עם זאת, אם הזוכה התרשל (למשל, בניסוח הצו או באי-מעקב), ניתן לייחס לו אשם תורם ולהפחית את חיוב הצד השלישי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, אלא אם כן הזוכה הוכיח שהחברה פעלה בחוסר תום לב מובהק במטרה להבריח נכסים.', false, 'תשובה זו שגויה. גם ללא הוכחת כוונת הברחה מובהקת, התעלמות מצו שכוונתו ברורה אינה נחשבת ''הצדק סביר''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, אך החברה רשאית לדרוש מהזוכה להוציא צו עיקול חדש ומתוקן לפני שתפעל על פיו.', false, 'תשובה זו שגויה. על החברה לפעול בתום לב ולבקש הבהרות או הוראות מרשם ההוצאה לפועל, ולא להתעלם מהצו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'הזוכה צריך להוכיח כי הצד השלישי החזיק בנכסים ופעל בניגוד לצו העיקול. לאחר מכן, עובר הנטל לצד השלישי להוכיח ''הצדק סביר'' לפי מבחן אובייקטיבי של אדם מן היישוב.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי נטל השכנוע הראשוני מוטל על הזוכה להוכיח את יסודות סעיף 48(א), ורק לאחר מכן עובר הנטל לצד השלישי להוכיח ''הצדק סביר'', הנבחן במבחן אובייקטיבי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'הנטל להוכיח את כל יסודות סעיף 48, כולל היעדר ''הצדק סביר'', מוטל על הזוכה בלבד.', false, 'תשובה זו שגויה. נטל ההוכחה מתחלק בין הזוכה לצד השלישי, כאשר הנטל להוכחת ''הצדק סביר'' מוטל על הצד השלישי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'הנטל להוכיח ''הצדק סביר'' מוטל על הצד השלישי, והמבחן הוא סובייקטיבי, כלומר, האם הצד השלישי האמין בתום לב שפעל כשורה.', false, 'תשובה זו שגויה. המבחן ל''הצדק סביר'' הוא אובייקטיבי, ולא סובייקטיבי, ונטל ההוכחה עובר לצד השלישי רק לאחר שהזוכה הוכיח את יסודות סעיף 48(א).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'רשם ההוצאה לפועל רשאי לחייב את הצד השלישי גם ללא הוכחה פוזיטיבית שהחזיק בנכסים, אם הצד השלישי לא השיב לצו העיקול.', false, 'תשובה זו שגויה. הפסיקה דורשת הוכחה פוזיטיבית כי הצד השלישי החזיק בנכסים במועד הקובע, ואי-מענה לצו אינו מספיק כשלעצמו לחיוב לפי סעיף 48.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'צו העיקול חל על חשבון החיסכון ביתרת זכות, והבנק אינו רשאי לקזז חובות מחשבון העו"ש כנגד כספים אלו.', false, 'תשובה זו שגויה. לבנק זכות קיזוז ייחודית, ובחישוב כולל של היתרות, אם החייב ביתרת חובה, העיקול לא תופס.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'העיקול אינו תופס דבר, אם בחישוב כולל של היתרות בחשבונות החייב אצל הבנק, החייב מצוי ביתרת חובה, וזאת בשל זכות הקיזוז הייחודית של הבנק.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי לבנק זכות קיזוז ייחודית, וכאשר לחייב מספר חשבונות, העיקול חל רק על יתרת הזכות הכוללת לאחר קיזוז חובותיו לבנק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'העיקול חל על חשבון החיסכון, אך הבנק רשאי לפנות לרשם ההוצאה לפועל בבקשה למתן הוראות לגבי זכות הקיזוז.', false, 'תשובה זו שגויה. זכות הקיזוז של הבנק היא זכות מהותית הגוברת על העיקול במקרים מסוימים, ואינה טעונה אישור מראש מרשם ההוצאה לפועל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'העיקול חל על חשבון החיסכון, והבנק רשאי לקזז רק חובות שהתגבשו לפני הטלת צו העיקול.', false, 'תשובה זו שגויה. זכות הקיזוז של הבנק יכולה לחול גם על חובות שהתגבשו לאחר הטלת העיקול, כל עוד הם נובעים ממערכת היחסים הבנקאית הקיימת.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'הזוכה רשאי להגיש מיד בקשה לחיוב הצד השלישי לפי סעיף 48 לחוק ההוצאה לפועל, ונטל ההוכחה עובר לצד השלישי להראות שלא החזיק בנכסים.', false, 'תשובה זו שגויה. הזוכה אינו יכול להגיש מיד בקשה לחיוב לפי סעיף 48 מבלי להוכיח תחילה שהצד השלישי החזיק בנכסים, ונטל ההוכחה הראשוני מוטל על הזוכה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'הזוכה צריך לנקוט תחילה בהליך של חקירת הצד השלישי לפי סעיף 46 לחוק ההוצאה לפועל, ורק אם יוכיח בחקירה כי הצד השלישי החזיק בנכסים, יוכל להגיש בקשה לחיוב לפי סעיף 48.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי כאשר צד שלישי מכחיש החזקת נכסים, על הזוכה לנקוט תחילה בהליך חקירה לפי סעיף 46 כדי להוכיח את קיומם של הנכסים, ורק אז יוכל להגיש בקשה לחיוב לפי סעיף 48.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'הזוכה רשאי להגיש תביעה אזרחית נגד הצד השלישי בבית המשפט המוסמך, שכן רשם ההוצאה לפועל אינו מוסמך לברר מחלוקות עובדתיות.', false, 'תשובה זו שגויה. רשם ההוצאה לפועל מוסמך לברר מחלוקות עובדתיות במסגרת הליכי חקירה וחיוב לפי סעיפים 46 ו-48 לחוק ההוצאה לפועל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'הזוכה צריך להגיש בקשה לצו מימוש נגד הצד השלישי, ורק אם הצד השלישי יסרב למסור את הנכסים, ניתן יהיה לחייבו לפי סעיף 48.', false, 'תשובה זו שגויה. צו מימוש ניתן רק לאחר שהוכח קיומם של נכסים בידי הצד השלישי, והוא אינו הליך מקדים לבירור קיומם של הנכסים.', 4);

END $$;

-- ============================================================
-- Q24 — 2024-W-Q24 — chapter=execution subtopic=file_opening
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q24';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q24 skipped: external_id % already exists', '2024-W-Q24';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'file_opening';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'file_opening';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q24', 'b3904dc7-882d-48fc-9f3c-ba89fc453003', v_subtopic_id,
    'יעקב מעוניין לפתוח תיק הוצאה לפועל במסלול מקוצר נגד יצחק בגין חוב בסך 3,000 ש"ח. יעקב יודע שליצחק יש תיקים נוספים המתנהלים נגדו בהוצאה לפועל. באיזה מקרה מבין המקרים הבאים לא יהיה רשאי יעקב לפתוח תיק במסלול מקוצר?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 24}'::jsonb,
    'שאלה זו עוסקת בתנאים לפתיחת תיק הוצאה לפועל במסלול המקוצר, ובפרט בתנאי המגביל את סך חובותיו של החייב. המסלול המקוצר נועד לייעל את הליכי הגבייה עבור חובות קטנים יחסית, אך החוק מציב מגבלות כדי להגן על חייבים בעלי חובות מצטברים גבוהים, שייתכן וזקוקים להליכים מורכבים יותר כמו איחוד תיקים או חדלות פירעון.',
    'סעיף 20ב לחוק ההוצאה לפועל, תשכ"ז-1967, קובע את התנאים לביצוע חיוב במסלול המקוצר. סעיף קטן (א) קובע כי המסלול מיועד לבקשות לביצוע פסק דין כספי או חיוב כספי אחר שאינו עולה על 25,000 שקלים חדשים, למעט פסקי דין למזונות ובקשות למימוש משכון או משכנתה. סעיף קטן (ב) מוסיף תנאי מהותי נוסף, לפיו ''על אף האמור בסעיף קטן (א), לא ניתן לבצע חיוב במסלול מקוצר אם סך חובותיו של החייב בתיקי הוצאה לפועל עולה על 100,000 שקלים חדשים''. תנאי זה נועד למנוע מצב שבו חייב בעל חובות רבים וגבוהים, שייתכן וזקוק להסדר חוב כולל, יטופל באמצעות המסלול המקוצר, שאינו מתאים למורכבות מצבו. לכן, גם אם החוב הספציפי נמוך מ-25,000 ש"ח, אם סך כל חובותיו של החייב עולה על 100,000 ש"ח, לא ניתן לפתוח נגדו תיק במסלול המקוצר. סעיף 20ב(ב) לחוק ההוצאה לפועל, תשכ"ז-1967בג"ץ 6804/12 לשכת עורכי הדין בישראל נ'' שר המשפטים (25.06.2013)בג"ץ 6804/12 לשכת עורכי הדין בישראל נ'' שר המשפטים (25.06.2013)',
    'טעות נפוצה היא לבלבל בין סכום החוב היחיד המותר במסלול המקוצר (25,000 ש"ח) לבין סך החובות המצטבר של החייב (100,000 ש"ח), או להתעלם מהמגבלה של סך החובות הכולל.',
    '["מסלול מקוצר", "חוק ההוצאה לפועל", "סעיף 20ב", "סך חובות", "הגנת החייב", "פתיחת תיקים"]'::jsonb,
    '**וריאציה 1 — סכום חוב יחיד:** מהו הסכום המקסימלי לחוב יחיד במסלול המקוצר? ← 25,000 ש"ח (סעיף 20ב(א) לחוק ההוצאה לפועל). **וריאציה 2 — סך חובות החייב:** מהו סך החובות המקסימלי של החייב בכל התיקים כדי שניתן יהיה לפתוח נגדו תיק במסלול המקוצר? ← 100,000 ש"ח (סעיף 20ב(ב) לחוק ההוצאה לפועל). **וריאציה 3 — מטרת המגבלה:** מדוע קיימת מגבלה על סך חובות החייב? ← להגן על חייבים בעלי חובות מצטברים גבוהים, שייתכן וזקוקים להליכים מורכבים יותר (בג"ץ 6804/12 לשכת עורכי הדין).',
    'מסלול מקוצר ← חוב יחיד עד 25,000 ש"ח + סך חובות חייב עד 100,000 ש"ח.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 20ב(ב)", "בג\"ץ 6804/12 לשכת עורכי הדין בישראל נ'' שר המשפטים (25.06.2013)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ככלל, כאשר יש תיקים אחרים פתוחים נגד חייב פלוני, אף זוכה אינו רשאי לפנות למסלול מקוצר.', false, 'תשובה זו שגויה. קיומם של תיקים אחרים אינו מונע כשלעצמו פתיחת תיק במסלול מקוצר, אלא רק אם סך החובות עולה על סכום מסוים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'אם סך החובות בכלל התיקים עולה על 20,000 ש"ח.', false, 'תשובה זו שגויה. הסכום המצטבר המונע פתיחת תיק במסלול מקוצר הוא 100,000 ש"ח, ולא 20,000 ש"ח.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אם סך החובות בכלל התיקים עולה על 100,000 ש"ח.', true, 'זו התשובה הנכונה. סעיף 20ב(ב) לחוק ההוצאה לפועל קובע כי לא ניתן לבצע חיוב במסלול מקוצר אם סך חובותיו של החייב בתיקי הוצאה לפועל עולה על 100,000 ש"ח.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אם בין הזוכים האחרים יש גם זוכה בגין חוב מזונות.', false, 'תשובה זו שגויה. קיומו של זוכה מזונות בתיקים אחרים אינו מונע פתיחת תיק במסלול מקוצר, כל עוד החוב הספציפי אינו חוב מזונות וסך החובות אינו עולה על 100,000 ש"ח.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'תנאי סף נוספים למסלול המקוצר', 1, 'זוכה מעוניין לפתוח תיק הוצאה לפועל במסלול מקוצר בגין חוב בסך 20,000 ש"ח. איזה מהבאים מהווה תנאי סף נוסף לפתיחת תיק במסלול מקוצר, מעבר לסכום החוב?',
    'שאלה זו עוסקת בתנאי הסף המהותיים לפתיחת תיק הוצאה לפועל במסלול מקוצר, כפי שנקבעו בסעיף 20ב(א) לחוק ההוצאה לפועל. היא מדגישה את סוגי החובות שאינם ניתנים לביצוע במסלול זה, גם אם הם עומדים בתנאי הסכום.',
    'סעיף 20ב(א) לחוק ההוצאה לפועל, תשכ"ז-1967, מפרט את התנאים לפתיחת תיק במסלול המקוצר. מעבר לתנאי הסכום (שאינו עולה על 25,000 ש"ח), החוק קובע כי החיוב צריך להיות פסק דין כספי או חיוב כספי אחר שניתן לפי חוק לבצעו כמו פסק דין של בית משפט. בנוסף, החוק מוציא במפורש שני סוגי חובות מהמסלול המקוצר: פסקי דין למזונות ובקשות למימוש משכון או משכנתה. לכן, כל התנאים המפורטים באפשרויות א-ג הם תנאי סף מצטברים לפתיחת תיק במסלול המקוצר. סעיף 20ב(א) לחוק ההוצאה לפועל, תשכ"ז-1967בג"ץ 6804/12 לשכת עורכי הדין בישראל נ'' שר המשפטים (25.06.2013)ת"ת (שלום י-ם) 39858-10-23 פרפקט שירותי ניקיון ת.כ יזמות בע"מ נ'' ד"ר פלוי יבגניה (01.01.2024)',
    'טעות נפוצה היא להתמקד רק בתנאי הסכום (25,000 ש"ח) ולשכוח את ההחרגות הספציפיות של חובות מזונות ומימוש משכונות/משכנתאות, או את הדרישה לסוג החיוב.',
    '["מסלול מקוצר", "חוק ההוצאה לפועל", "סעיף 20ב(א)", "חוב מזונות", "מימוש משכון", "מימוש משכנתה", "פסק דין כספי"]'::jsonb,
    '**וריאציה 1 — סכום מקסימלי:** מהו הסכום המקסימלי לחוב יחיד במסלול המקוצר? ← 25,000 ש"ח (סעיף 20ב(א) לחוק ההוצאה לפועל). **וריאציה 2 — חובות מוחרגים:** אילו חובות מוחרגים מהמסלול המקוצר? ← מזונות ומימוש משכון/משכנתה (סעיף 20ב(א) לחוק ההוצאה לפועל). **וריאציה 3 — סוג החיוב:** מהו סוג החיוב הנדרש? ← פסק דין כספי או חיוב כספי אחר שניתן לבצעו כפסק דין (סעיף 20ב(א) לחוק ההוצאה לפועל).',
    'מסלול מקוצר ← עד 25,000 ש"ח + פסק דין כספי + לא מזונות/משכון/משכנתה.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 20ב(א)", "בג\"ץ 6804/12 לשכת עורכי הדין בישראל נ'' שר המשפטים (25.06.2013)", "ת\"ת (שלום י-ם) 39858-10-23 פרפקט שירותי ניקיון ת.כ יזמות בע\"מ נ'' ד\"ר פלוי יבגניה (01.01.2024)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'תכלית המסלול המקוצר בהוצאה לפועל', 2, 'מהי התכלית העיקרית של המסלול המקוצר בהוצאה לפועל, כפי שפורשה על ידי בית המשפט העליון?',
    'שאלה זו בוחנת את הבנת התכלית החקיקתית של המסלול המקוצר בהוצאה לפועל, כפי שפורשה על ידי בית המשפט העליון. היא מדגישה את האיזון בין יעילות הגבייה לבין הגנה על זכויות החייב, ואת ההכרה בכך שהמסלול משרת את שני הצדדים.',
    'בג"ץ 6804/12 לשכת עורכי הדין בישראל נ'' שר המשפטים דן בהרחבה בתכלית המסלול המקוצר. בית המשפט העליון קבע כי תכליתו של המסלול המקוצר היא ליצור מנגנון יעיל וקצר יותר מהליך הגבייה הרגיל על מנת להקל על גביית החוב, הן מצדו של הזוכה והן מצדו של החייב. המסלול מייתר פרוצדורות ומקצר הליכים, ובכך נחסכות הוצאות על תשלום שכר טרחה לעורכי הדין משני הצדדים. בית המשפט דחה את טענת לשכת עורכי הדין כי המסלול משרת רק תאגידים מסחריים או פוגע בשוויון, וקבע כי הוא משרת את כלל הזוכים והחייבים על ידי ייעול המערכת כולה. בג"ץ 6804/12 לשכת עורכי הדין בישראל נ'' שר המשפטים (25.06.2013)בג"ץ 6804/12 לשכת עורכי הדין בישראל נ'' שר המשפטים (25.06.2013)בג"ץ 6804/12 לשכת עורכי הדין בישראל נ'' שר המשפטים (25.06.2013)',
    'טעות נפוצה היא לאמץ את טענות לשכת עורכי הדין כנגד המסלול המקוצר, במקום את פרשנותו של בית המשפט העליון, המדגישה את יעילותו והתועלת ההדדית שלו.',
    '["מסלול מקוצר", "תכלית חקיקה", "יעילות דיונית", "חיסכון בעלויות", "הגנת החייב", "בג\"ץ 6804/12"]'::jsonb,
    '**וריאציה 1 — מטרת המסלול:** מהי המטרה העיקרית של המסלול המקוצר? ← ליצור מנגנון יעיל וקצר לגביית חובות (בג"ץ 6804/12 לשכת עורכי הדין). **וריאציה 2 — מי נהנה:** מי נהנה מהמסלול המקוצר? ← הן הזוכה והן החייב, על ידי חיסכון בהוצאות וקיצור הליכים (בג"ץ 6804/12 לשכת עורכי הדין). **וריאציה 3 — טענות נדחות:** אילו טענות נדחו לגבי המסלול המקוצר? ← הטענה שהוא משרת רק תאגידים מסחריים או פוגע בשוויון (בג"ץ 6804/12 לשכת עורכי הדין).',
    'תכלית מסלול מקוצר ← יעילות וקיצור הליכים ← תועלת לזוכה ולחייב ← דחיית טענות לשכת עו"ד.',
    '["בג\"ץ 6804/12 לשכת עורכי הדין בישראל נ'' שר המשפטים (25.06.2013)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'התנגדות לביצוע במסלול המקוצר', 3, 'חייב, נגדו נפתח תיק הוצאה לפועל במסלול מקוצר, הגיש התנגדות לביצוע. מהו הדין לגבי הצורך בקבלת רשות להתגונן לאחר תיקון מס'' 70 לחוק ההוצאה לפועל?',
    'שאלה זו עוסקת בשינוי המהותי שחל בדין בעקבות תיקון מס'' 70 לחוק ההוצאה לפועל, הנוגע לדרישת ''רשות להתגונן'' בהתנגדות לביצוע במסלול המקוצר. היא מדגישה את חשיבות הפרשנות הלשונית של החוק לאחר תיקונים, גם כאשר כוונת המחוקק המקורית הייתה שונה.',
    'עד לתיקון מס'' 70 לחוק ההוצאה לפועל, התנגדות לביצוע תביעה על סכום קצוב או שטר במסלול המקוצר נחשבה כבקשת רשות להתגונן בסדר דין מקוצר. אולם, עם כניסתן לתוקף של תקנות סדר הדין האזרחי החדשות (תשע"ט-2018) וביטול סדר הדין המקוצר, ובעיקר עם תיקון מס'' 70 לחוק ההוצאה לפועל, נמחקה ההפניה ל''סדר דין מקוצר'' ול''בקשת רשות להתגונן'' מסעיפים 81א1(ד)(2) ו-81א(ג) לחוק. כפי שנקבע בפסק הדין ת"ת (שלום י-ם) 39858-10-23, בחינת לשון החוק כשלעצמה, בהיעדר היכרות עם נוסח החוק שקדם לתיקון, איננה יכולה להביא למסקנה כי נדרש מתן רשות להתגונן. לפיכך, כיום, התנגדות לביצוע במסלול המקוצר נחשבת ככתב הגנה, ואין צורך בקבלת רשות להתגונן. ת"ת (שלום י-ם) 39858-10-23 פרפקט שירותי ניקיון ת.כ יזמות בע"מ נ'' ד"ר פלוי יבגניה (01.01.2024)ת"ת (שלום י-ם) 39858-10-23 פרפקט שירותי ניקיון ת.כ יזמות בע"מ נ'' ד"ר פלוי יבגניה (01.01.2024)ת"ת (שלום י-ם) 39858-10-23 פרפקט שירותי ניקיון ת.כ יזמות בע"מ נ'' ד"ר פלוי יבגניה (01.01.2024)סעיף 20ב(ד)(1א) לחוק ההוצאה לפועל, תשכ"ז-1967',
    'טעות נפוצה היא להמשיך וליישם את הדין הישן שדרש רשות להתגונן, או לבלבל בין התנגדות לביצוע לבין טענת פרעתי, שבה רשם ההוצאה לפועל כן דן תחילה.',
    '["התנגדות לביצוע", "מסלול מקוצר", "רשות להתגונן", "תיקון 70", "חוק ההוצאה לפועל", "תקנות סדר הדין האזרחי", "פרשנות חוק"]'::jsonb,
    '**וריאציה 1 — לפני תיקון 70:** מה היה הדין לגבי התנגדות לביצוע במסלול מקוצר לפני תיקון 70? ← ההתנגדות נחשבה כבקשת רשות להתגונן בסדר דין מקוצר (ת"ת (שלום י-ם) 39858-10-23 פרפקט שירותי ניקיון). 
**וריאציה 2 — לאחר תיקון 70:** מה השתנה לאחר תיקון 70 לחוק ההוצאה לפועל? ← ההפניה ל''סדר דין מקוצר'' ול''בקשת רשות להתגונן'' נמחקה מהחוק (ת"ת (שלום י-ם) 39858-10-23 פרפקט שירותי ניקיון). **וריאציה 3 — המצב הנוכחי:** האם נדרשת רשות להתגונן כיום? ← לא, ההתנגדות נחשבת ככתב הגנה, ואין צורך ברשות להתגונן (ת"ת (שלום י-ם) 39858-10-23 פרפקט שירותי ניקיון).',
    'התנגדות במסלול מקוצר ← תיקון 70 ביטל דרישת רשות להתגונן ← נחשבת ככתב הגנה.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 20ב(ד)(1א)", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 81א1(ד)(2)", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 81א(ג)", "ת\"ת (שלום י-ם) 39858-10-23 פרפקט שירותי ניקיון ת.כ יזמות בע\"מ נ'' ד\"ר פלוי יבגניה (01.01.2024)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'חובת תום הלב של הזוכה במסלול המקוצר', 4, 'זוכה פתח תיק הוצאה לפועל במסלול מקוצר. לאחר 10 שנים של חוסר מעש מוחלט בתיק, במהלכן החייב המשיך לעמוד בתשלומים, מבקש בא כוח הזוכה (שהוא גם בא כוח יורשי הזוכה המנוח) להמשיך בהליכים ולגבות את החוב בתוספת ריבית והצמדה. החייב מבקש לסגור את התיק עקב חוסר תום לב ושיהוי חמור מצד הזוכה. מהי ההחלטה הסבירה של רשם ההוצאה לפועל?',
    'שאלה זו עוסקת בחובת תום הלב המוטלת על זוכה בהליכי הוצאה לפועל, ובפרט בהשלכות של שיהוי וחוסר מעש ממושכים. היא בוחנת את סמכותו של רשם ההוצאה לפועל להפעיל את עקרון תום הלב, ואת האפשרות לסגור תיק ולמחוק חוב במקרים חמורים של התנהלות קלוקלת מצד הזוכה.',
    'עקרון תום הלב הוא עקרון-על החולש על כל תחומי המשפט האזרחי, ובכלל זה על ניהול הליכי הוצאה לפועל. חובת תום הלב מחייבת את הזוכה לפעול באופן סביר לקבלת סעד המימוש, ואין הוא יכול ''לישון על זכותו'' עד קץ כל הימים. תיק ההוצאה לפועל אינו יכול לשמש ''תוכנית חיסכון'' לזוכה. במקרה של חוסר מעש מוחלט ושיהוי כבד וחמור, במיוחד כאשר החייב עמד בתשלומים, רשם ההוצאה לפועל מוסמך, מכוח סמכותו הכללית למניעת עיוות דין חמור, להורות על סגירת התיק ומחיקת החוב. כך נקבע בפסק הדין (רשם ההוצאה לפועל חיפה) 02-99556-95-6/ זוכה 1 נ'', שם נסגר תיק איחוד ומחיקת חוב של מאות אלפי שקלים לאחר 27 שנות התנהלות קלוקלת וחוסר מעש מצד הזוכה. (רשם ההוצאה לפועל חיפה) 02-99556-95-6/ זוכה 1 נ'' (20.03.2022) (רשם ההוצאה לפועל חיפה) 02-99556-95-6/ זוכה 1 נ'' (20.03.2022) (רשם ההוצאה לפועל חיפה) 02-99556-95-6/ זוכה 1 נ'' (20.03.2022) (רשם ההוצאה לפועל חיפה) 02-99556-95-6/ זוכה 1 נ'' (20.03.2022)דוד בר -אופיר הוצאה לפועל הליכים ‏והלכות - כרך ב (2025) | צד שלישי - חקירתו - סדרי דין בהליכי החיוב - אין עיקול זמני - נטל השכנוע - הגנות - הימצאות המעוקל בידיו - הצדק סביר - חיובו בתשלום החוב הפסוק (סעיף 48 לחוק)',
    'טעות נפוצה היא לחשוב שחוסר התיישנות על הליכי הוצאה לפועל פוטר את הזוכה מחובת תום הלב, או שסמכות רשם ההוצאה לפועל מוגבלת רק להפחתת ריבית והצמדה במקרים של שיהוי.',
    '["תום לב", "שיהוי", "חוסר מעש", "סגירת תיק הוצאה לפועל", "טעמים מיוחדים", "סמכות רשם ההוצאה לפועל", "עקרון-על"]'::jsonb,
    '**וריאציה 1 — חובת תום הלב:** האם חובת תום הלב חלה על זוכה בהוצאה לפועל? ← כן, זהו עקרון-על החולש על ניהול הליכי הוצאה לפועל ( (רשם ההוצאה לפועל חיפה) 02-99556-95-6/ זוכה 1 נ''). **וריאציה 2 — השלכות שיהוי:** מהן ההשלכות של שיהוי וחוסר מעש חמור? ← רשם ההוצאה לפועל יכול להורות על סגירת התיק ומחיקת החוב, שכן התיק אינו ''תוכנית חיסכון'' ( (רשם ההוצאה לפועל חיפה) 02-99556-95-6/ זוכה 1 נ''). **וריאציה 3 — סמכות הרשם:** האם לרשם ההוצאה לפועל סמכות לסגור תיק עקב חוסר תום לב? ← כן, מכוח סמכותו הכללית למניעת עיוות דין חמור ( (רשם ההוצאה לפועל חיפה) 02-99556-95-6/ זוכה 1 נ'').',
    'זוכה חייב בתום לב ← שיהוי חמור ← רשם יכול לסגור תיק ולמחוק חוב.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 39", "(רשם ההוצאה לפועל חיפה) 02-99556-95-6/ זוכה 1 נ'' (20.03.2022)", "דוד בר -אופיר, הוצאה לפועל הליכים ‏והלכות - כרך ב (2025), פרק כ\"ג: עיקול בידי צד שלישי"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'החוב אינו יכול להיות חוב מזונות.', false, 'תשובה זו נכונה חלקית, אך אינה כוללת את כל התנאים. חוב מזונות אכן אינו ניתן לביצוע במסלול מקוצר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'החוב אינו יכול להיות בקשה למימוש משכון או משכנתה.', false, 'תשובה זו נכונה חלקית, אך אינה כוללת את כל התנאים. בקשה למימוש משכון או משכנתה אכן אינה ניתנת לביצוע במסלול מקוצר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'החוב חייב להיות פסק דין כספי או חיוב כספי אחר שניתן לבצעו כפסק דין.', false, 'תשובה זו נכונה חלקית, אך אינה כוללת את כל התנאים. זהו אכן תנאי מהותי לסוג החיוב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'כל התשובות נכונות.', true, 'זו התשובה הנכונה. סעיף 20ב(א) לחוק ההוצאה לפועל קובע את כל התנאים הללו במצטבר: החוב צריך להיות פסק דין כספי או חיוב כספי אחר שניתן לבצעו כפסק דין, שאינו עולה על 25,000 ש"ח, למעט פסק דין למזונות ולמעט בקשות למימוש משכון או משכנתה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'לצמצם את מעורבות עורכי הדין בהליכי הגבייה ולחסוך בהוצאות שכר טרחה.', false, 'תשובה זו נכונה חלקית, אך היא תוצאה של התכלית העיקרית ולא התכלית עצמה. בית המשפט העליון ראה בכך יתרון נלווה ולא את המטרה העיקרית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'ליצור מנגנון יעיל וקצר יותר לגביית חובות, המקל הן על הזוכה והן על החייב.', true, 'זו התשובה הנכונה. בית המשפט העליון קבע כי תכלית המסלול המקוצר היא ליצור מנגנון יעיל וקצר יותר, המשרת הן את הזוכה והן את החייב על ידי ייעול הליכים וחיסכון בהוצאות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'לאפשר לתאגידים מסחריים גדולים לגבות חובות בקלות רבה יותר מאוכלוסיות מוחלשות.', false, 'תשובה זו שגויה. בית המשפט העליון דחה טענה זו של לשכת עורכי הדין, וקבע כי תכלית החוק אינה להבחין בין סוגי זוכים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'להעניק סיוע משפטי בחינם לזוכים, במיוחד לאלה שאינם יכולים לממן עורך דין.', false, 'תשובה זו שגויה. אף שהמסלול עשוי לחסוך הוצאות, תכליתו אינה מתן סיוע משפטי בחינם, ובית המשפט העליון דחה טענות דומות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'ההתנגדות תיחשב כבקשת רשות להתגונן, ובית המשפט יחליט אם להעניק רשות כזו.', false, 'תשובה זו משקפת את המצב המשפטי שקדם לתיקון מס'' 70. לאחר התיקון, אין עוד דרישה מפורשת לרשות להתגונן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'ההתנגדות תיחשב ככתב הגנה, ואין צורך בקבלת רשות להתגונן כדי שההליך יידון לגופו בבית המשפט.', true, 'זו התשובה הנכונה. לאחר תיקון מס'' 70 לחוק ההוצאה לפועל, ההפניה ל''סדר דין מקוצר'' ול''בקשת רשות להתגונן'' נמחקה, ולכן ההתנגדות נחשבת ככתב הגנה ללא צורך ברשות להתגונן.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'רשם ההוצאה לפועל ידון בהתנגדות, ואם ידחה אותה, ההליך יימשך במסלול המקוצר.', false, 'תשובה זו שגויה. במקרה של התנגדות לביצוע, רשם ההוצאה לפועל מעכב את הביצוע ומעביר את התביעה וההתנגדות לבית המשפט, ולא דן בה לגופה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'התיק ייסגר אוטומטית, שכן המסלול המקוצר מיועד רק לחובות שאינם שנויים במחלוקת.', false, 'תשובה זו שגויה. הגשת התנגדות אינה מובילה לסגירת התיק, אלא להעברתו לבית המשפט לבירור המחלוקת.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'רשם ההוצאה לפועל יאפשר את המשך ההליכים, שכן על הליכי הוצאה לפועל לא חלה התיישנות.', false, 'תשובה זו שגויה. אף שעל הליכי הוצאה לפועל לא חלה התיישנות, חובת תום הלב עדיין חלה, ושיהוי חמור יכול להוביל לסגירת התיק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'רשם ההוצאה לפועל יורה על סגירת התיק ומחיקת החוב, עקב חוסר מעש מוחלט ושיהוי כבד וחמור מצד הזוכה, המהווים ''טעמים מיוחדים'' המצדיקים זאת.', true, 'זו התשובה הנכונה. הפסיקה קובעת כי חובת תום הלב חלה על הזוכה, ושיהוי חמור וחוסר מעש לאורך שנים, במיוחד כאשר החייב עמד בתשלומים, יכולים להוות ''טעמים מיוחדים'' לסגירת התיק ומחיקת החוב, שכן תיק הוצאה לפועל אינו ''תוכנית חיסכון''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'רשם ההוצאה לפועל יפחית את הפרשי ההצמדה והריבית לתקופת חוסר המעש, אך יאפשר את גביית קרן החוב.', false, 'תשובה זו נכונה חלקית, אך אינה משקפת את מלוא הסמכות במקרים חמורים. במקרים של שיהוי חמור במיוחד, רשם ההוצאה לפועל יכול ללכת רחוק יותר מסתם הפחתת ריבית והצמדה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'רשם ההוצאה לפועל יעביר את התיק לבית המשפט המוסמך להכרעה בשאלת תום הלב של הזוכה.', false, 'תשובה זו שגויה. לרשם ההוצאה לפועל יש סמכות לדון בטענות תום לב ולפעול בהתאם, ואין צורך להעביר את התיק לבית המשפט.', 4);

END $$;

-- ============================================================
-- Q25 — 2024-W-Q25 — chapter=civil_proc subtopic=judge_recusal
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q25';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q25 skipped: external_id % already exists', '2024-W-Q25';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'judge_recusal';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'judge_recusal';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q25', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'איזה מבין המשפטים הבאים נכון לגבי פסילת מותב?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 25}'::jsonb,
    'שאלה זו עוסקת בעילות הפסלות השונות של שופט, כפי שמעוגנות בסעיף 77א לחוק בתי המשפט. היא מבחינה בין עילת הפסלות הכללית של ''חשש ממשי למשוא פנים'' לבין עילות הפסלות הספציפיות (המכונות ''עילות חובה''), ובפרט מתמקדת בעילת הפסלות הנוגעת לעניין כספי או אישי ממשי של השופט או של בן משפחתו מדרגה ראשונה, בצדדים להליך, בבא כוחם או בעד מרכזי. השאלה מדגישה את החשיבות של דיוק במונחים המשפטיים.',
    'סעיף 77א לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע את עילות הפסלות של שופט. סעיף 77א(א) קובע את עילת הפסלות הכללית – ''חשש ממשי למשוא פנים''. סעיף 77א(א1) מפרט עילות פסלות ספציפיות, המכונות ''עילות חובה'', אשר בהתקיימותן השופט מחויב לפסול את עצמו. אחת מעילות אלו, הקבועה בסעיף 77א(א1)(2), היא כאשר ''יש לשופט ענין כספי ממשי או ענין אישי ממשי בהליך או בתוצאותיו, בצד להליך, בבא כוחו או בעד מרכזי, או שלבן משפחה מדרגה ראשונה של השופט יש ענין כספי ממשי או ענין אישי ממשי בהליך או בתוצאותיו, בצד להליך או בבא כוחו''. המונח ''עד מרכזי'' מוגדר בחוק כ''עד שנדרשת הערכת מהימנותו לצורך הכרעה בהליך''. לעומת זאת, המונח ''נעד מרכזי'' אינו מופיע בחוק בתי המשפט או בכל דין רלוונטי אחר כעילת פסלות. לכן, העובדה שלבן משפחה מדרגה ראשונה של המותב קיים עניין אישי ממשי ב''נעד מרכזי'' אינה מקימה כשלעצמה עילת פסלות חובה לפי סעיף 77א(א1)(2). סעיף 77א(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984סעיף 77א(א1)(2) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984סעיף 77א(א1) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984ע"פ 566/21 אמיר ברמלי נ'' מדינת ישראל (16.02.2021)נבו - המתמחה מערכת בתי המשפט (2026) | ד. דיני פסלות שופט',
    'טעות נפוצה היא לא לשים לב לדיוק במונחים המשפטיים המופיעים בחוק, ולבלבל בין מונחים דומים אך שונים (כמו ''נעד מרכזי'' שאינו מוגדר בחוק, לבין ''עד מרכזי'' שכן מוגדר ומהווה עילת פסלות).',
    '["פסלות שופט", "חוק בתי המשפט", "סעיף 77א", "עילות חובה", "חשש ממשי למשוא פנים", "עניין אישי ממשי", "בן משפחה מדרגה ראשונה", "עד מרכזי"]'::jsonb,
    '**וריאציה 1 — עילות חובה:** מהן עילות הפסלות המפורטות בסעיף 77א(א1) לחוק בתי המשפט? ← עילות חובה, המקימות חזקה חלוטה לפגם באובייקטיביות השיפוטית (ע"פ 566/21 ברמלי). **וריאציה 2 — ''עניין אישי ממשי'' ב''עד מרכזי'':** האם עניין אישי ממשי של בן משפחה מדרגה ראשונה ב''עד מרכזי'' מקימה עילת פסלות? ← כן, במפורש לפי סעיף 77א(א1)(2) לחוק בתי המשפט (סעיף 77א(א1)(2) לחוק בתי המשפט). **וריאציה 3 — ''נעד מרכזי'':** מה לגבי ''נעד מרכזי''? ← מונח זה אינו מופיע בחוק כעילת פסלות, ולכן עניין אישי ממשי בו אינו מקימה עילת פסלות חובה לפי סעיף 77א(א1)(2) (סעיף 77א(א1) לחוק בתי המשפט).',
    'עילות פסלות שופט ← כלליות וספציפיות ← עניין אישי ממשי של בן משפחה מדרגה ראשונה ב''עד מרכזי'' הוא עילת חובה ← ''נעד מרכזי'' אינו מונח חוקי לעניין זה.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 77א", "ע\"פ 566/21 אמיר ברמלי נ'' מדינת ישראל (16.02.2021)", "ת\"ע (משפחה אשדוד) 11746-11-20 פלוני ואח'''' נ'' האפוטרופוס הכללי במחוז דרום (24.03.2021)", "ת\"צ (מחוזי תל אביב-יפו) 62995-12-21 אבישי אילישייב נ'' לוינסקי - עופר בע\"מ (22.07.2025)", "נבו - המתמחה, מערכת בתי המשפט (2026), ד. דיני פסלות שופט"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כל היכרות בין המותב ובין מי מהצדדים או באי כוחם יש בה כשלעצמה כדי להקים עילת פסלות.', false, 'תשובה זו שגויה. לא כל היכרות מקימה עילת פסלות. נדרשת ''קרבה ממשית'' או ''חשש ממשי למשוא פנים'', תוך בחינת אופי הקשר, משכו ומידת עוצמתו, וכן הזמן שחלף מאז ההיכרות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'כל קירבה שהיא בין המותב ובין מי מהצדדים או באי כוחם יש בה כשלעצמה כדי להקים עילת פסלות.', false, 'תשובה זו שגויה. בדומה להיכרות, גם קרבה כללית אינה מקימה עילת פסלות כשלעצמה. נדרשת ''קרבה ממשית'' המבססת חשש ממשי למשוא פנים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'העובדה שלבן משפחה מדרגה ראשונה של המותב קיים עניין אישי ממשי בנעד מרכזי אין בה כשלעצמה כדי להקים עילת פסלות.', true, 'זו התשובה הנכונה. סעיף 77א(א1)(2) לחוק בתי המשפט קובע עילת פסלות אם לבן משפחה מדרגה ראשונה של השופט יש עניין אישי ממשי ב''עד מרכזי''. המונח ''נעד מרכזי'' אינו מופיע בחוק, ולכן עניין אישי ממשי ב''נעד מרכזי'' אינו מקימה עילת פסלות חובה לפי סעיף זה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'העובדה שלבן משפחה מדרגה ראשונה של המותב קיים עניין אישי ממשי בבא-כוחו של צד להליך אין בה כשלעצמה כדי להקים עילת פסלות.', false, 'תשובה זו שגויה. סעיף 77א(א1)(2) לחוק בתי המשפט קובע במפורש כי אם לבן משפחה מדרגה ראשונה של השופט יש עניין אישי ממשי בבא כוחו של צד להליך, זוהי עילת פסלות חובה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'פסלות שופט עקב איום מבעל דין', 1, 'ראובן, נאשם בפלילים, איים על בנו של השופט הדן בעניינו במטרה לגרום לפסילת השופט. האם איום זה מקימה עילת פסלות לשופט?',
    'שאלה זו עוסקת במקרים בהם בעל דין מנסה ליצור עילת פסלות באופן יזום ומניפולטיבי, ובפרט באמצעות איומים על השופט או על בני משפחתו. הפסיקה קבעה כי אין לאפשר לבעל דין לקבוע מי ישפוט בעניינו בדרך זו, וכי פעולות כאלה אינן מקימות עילת פסלות.',
    'סעיף 77א(א1)(2) לחוק בתי המשפט קובע עילת פסלות חובה אם לבן משפחה מדרגה ראשונה של השופט יש עניין אישי ממשי בהליך. אולם, הפסיקה הבהירה כי גם לאחר תיקון 38 לחוק, העובדה שבעל דין איים על המותב או על בן משפחתו, או נהג כלפיו באופן שעולה כדי עבירה פלילית, אינה מקימה כשלעצמה עילת פסילה. עיקרון יסוד בדיני הפסלות הוא שאין לאפשר לבעל דין לקבוע מי יפסוק בעניינו או להחליפו כאוות נפשו באמצעות פרובוקציות. עיקרון זה כוחו יפה גם כשמדובר באיומים על בן משפחה של השופט, וזאת כדי למנוע פתח רחב לכל בעל דין לבחור את המותב המתאים לו וליצור תמריצים מסוכנים לפגיעה בשופט ובבני משפחתו. ע"פ 566/21 אמיר ברמלי נ'' מדינת ישראל (16.02.2021)ע"פ 566/21 אמיר ברמלי נ'' מדינת ישראל (16.02.2021)ע"פ 566/21 אמיר ברמלי נ'' מדינת ישראל (16.02.2021)ת"פ (כלכלית ) 52446-06-16 מדינת ישראל נ'' אמיר ברמלי (20.01.2021)',
    'טעות נפוצה היא לחשוב שכל קשר או עניין אישי של בן משפחה מדרגה ראשונה, גם אם נוצר במכוון על ידי בעל הדין, מקימה עילת פסלות, מבלי להבין את העיקרון המונע מניפולציה דיונית.',
    '["פסלות שופט", "עילות חובה", "עניין אישי ממשי", "מניפולציה דיונית", "איומים", "חוק בתי המשפט סעיף 77א(א1)(2)"]'::jsonb,
    '**וריאציה 1 — איום על בן משפחה של שופט:** האם זה פוסל את השופט? ← לא, כדי למנוע מניפולציה מצד בעל הדין (ע"פ 566/21 ברמלי). **וריאציה 2 — עיקרון יסוד בדיני פסלות:** מהו? ← אין לאפשר לבעל דין לבחור את המותב באמצעות פרובוקציות (ע"פ 566/21 ברמלי). **וריאציה 3 — תמריצים מסוכנים:** מה עלול לקרות אם איומים יקימו עילת פסלות? ← ייפתח פתח רחב לכל בעל דין לבחור את המותב המתאים לו וייווצרו תמריצים מסוכנים לפגיעה בשופט ובבני משפחתו (ע"פ 566/21 ברמלי).',
    'איום מבעל דין על בן משפחת שופט ← לא עילת פסלות ← מניעת מניפולציה.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 77א(א1)(2)", "ע\"פ 566/21 אמיר ברמלי נ'' מדינת ישראל (16.02.2021)", "ת\"פ (כלכלית ) 52446-06-16 מדינת ישראל נ'' אמיר ברמלי (20.01.2021)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'מבחן "חשש ממשי למשוא פנים"', 2, 'מהו המבחן לקיומו של "חשש ממשי למשוא פנים" המצדיק פסילת שופט, וכיצד הוא מתייחס לתחושות סובייקטיביות של בעלי הדין?',
    'שאלה זו בוחנת את אמת המידה המרכזית לפסלות שופט – ''חשש ממשי למשוא פנים'' – ואת אופיו האובייקטיבי של מבחן זה. היא מדגישה כי אין די בתחושה סובייקטיבית של בעל דין כדי להקים עילת פסלות, וכי הבחינה נעשית מנקודת מבטו של השופט הסביר.',
    'סעיף 77א(א) לחוק בתי המשפט קובע את עילת הפסלות הכללית: ''שופט לא ישב בדין אם מצא... כי קיימות נסיבות שיש בהן כדי ליצור חשש ממשי למשוא פנים בניהול המשפט''. הפסיקה קבעה כי המבחן לקיומו של חשש ממשי למשוא פנים הוא אובייקטיבי במהותו. אין די בחשש סובייקטיבי של בעל דין או בא כוחו. הבחינה היא אם מן הנסיבות החיצוניות עולה אפשרות ממשית שאכן נבצר מהשופט לשפוט באובייקטיביות הדרושה. נקודת המבט לבחינה זו היא של ''השופט הסביר'', ולא של ''האדם הסביר'' או של בעלי הדין. חובה על השופט לשבת בדין כל עוד לא קמה עילת פסלות אובייקטיבית. סעיף 77א(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984ת"ת (שלום ת"א) 4124-01-25 בנק לאומי לישראל בעמ נ'' דן ראיגרודסקי (30.11.2025)ת"פ (מחוזי ת"א) 50380-11-17 רונן משה נ'' מדינת ישראל (02.06.2019)שלמה יעקובוביץ סדרי הדין בבית הדין לעבודה (2024) | פרק טו פסלות שופט או גורם שיפוטי אחר בבית הדין לעבודהנבו - המתמחה מערכת בתי המשפט (2026) | ד. דיני פסלות שופט',
    'טעות נפוצה היא לבלבל בין המבחן האובייקטיבי למבחן הסובייקטיבי, או לחשוב שדי בתחושה אישית של בעל דין כדי לפסול שופט.',
    '["חשש ממשי למשוא פנים", "מבחן אובייקטיבי", "מבחן סובייקטיבי", "שופט סביר", "סעיף 77א(א) לחוק בתי המשפט", "חובת שופט לשבת בדין"]'::jsonb,
    '**וריאציה 1 — מבחן הפסלות:** מהו המבחן העיקרי לפסלות שופט? ← חשש ממשי למשוא פנים, במבחן אובייקטיבי (סעיף 77א(א) לחוק בתי המשפט). **וריאציה 2 — נקודת המבט:** מנקודת מבטו של מי נבחן החשש? ← מנקודת מבטו של השופט הסביר, ולא של האדם הסביר או בעל הדין (ת"ת 4124-01-25 בנק לאומי). **וריאציה 3 — תחושה סובייקטיבית:** האם תחושה סובייקטיבית של בעל דין מספיקה? ← לא, אין די בחשד מצד בעל דין, נדרשת אפשרות ממשית של משוא פנים (שלמה יעקובוביץ, סדרי הדין בבית הדין לעבודה).',
    'מבחן פסלות ← חשש ממשי למשוא פנים ← אובייקטיבי ← מנקודת מבט של שופט סביר.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 77א(א)", "ת\"ת (שלום ת\"א) 4124-01-25 בנק לאומי לישראל בעמ נ'' דן ראיגרודסקי (30.11.2025)", "ת\"פ (מחוזי ת\"א) 50380-11-17 רונן משה נ'' מדינת ישראל (02.06.2019)", "שלמה יעקובוביץ, סדרי הדין בבית הדין לעבודה (2024), פרק טו פסלות שופט או גורם שיפוטי אחר בבית הדין לעבודה", "נבו - המתמחה, מערכת בתי המשפט (2026), ד. דיני פסלות שופט"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'פסלות שופט עקב היכרות עם עורך דין', 3, 'שופט דן בתיק בו מופיע עורך דין שהיה חברו לספסל הלימודים בפקולטה למשפטים לפני 20 שנה, ומאז לא שמרו על קשר הדוק. האם היכרות זו מקימה עילת פסלות?',
    'שאלה זו בוחנת את גבולות עילת הפסלות הנובעת מקרבה או היכרות בין שופט לבין בא כוח של צד. היא מדגישה כי לא כל היכרות מקימה עילת פסלות, וכי יש לבחון את אופי הקשר, משכו, עוצמתו והזמן שחלף מאז, על מנת לקבוע אם קיים חשש ממשי למשוא פנים.',
    'הלכה פסוקה היא כי אין די בעצם ההיכרות או הקרבה של שופט לבא כוח של בעל דין כדי להביא לפסילתו, ונדרשת ''קרבה ממשית''. ''קרבה ממשית'' זו אינה אלא אותה קרבה שממשותה היא המבססת חשש ממשי למשוא פנים. יש לבחון את כלל נסיבות המקרה, בשים לב לאופי ההיכרות, למסגרתה, למשכה ולמשך הזמן שעבר מאז ההיכרות. שופטים מתמנים לרוב מקרב ציבור עורכי הדין, ולאחר לימודים ועבודה קודמת. בנסיבות אלה, טבעי כי לשופט תהא היכרות מוגבלת בטיבה, ובעיקרה מקצועית, עם חלק מעורכי הדין שיופיעו בפניו. היכרות לימודית מלפני 20 שנה, שאינה הדוקה, אינה מקימה כשלעצמה חשש ממשי למשוא פנים. ת"א (מחוזי ב"ש) 54331-06-22 איתמר כהן נ'' אופק רפאל שביט (19.09.2022)יעקב שקד סדר הדין האזרחי (2026) | 17.2.2 אמות המידה לדיון בטענת פסלותיעקב שקד סדר הדין האזרחי (2026) | 17.2.2 אמות המידה לדיון בטענת פסלותע"א 7444/23 עו"ד יואב נדב נ'' קובי ישורון (30.10.2023)',
    'טעות נפוצה היא להניח שכל היכרות קודמת, גם אם רחוקה ובלתי משמעותית, מקימה עילת פסלות, מבלי לבחון את אופי הקשר ואת מבחן החשש הממשי למשוא פנים.',
    '["פסלות שופט", "קרבה ממשית", "היכרות מקצועית", "חשש ממשי למשוא פנים", "אופי הקשר", "חלוף זמן"]'::jsonb,
    '**וריאציה 1 — היכרות עם עו"ד:** האם היכרות עם עו"ד פוסלת שופט? ← לא כל היכרות, נדרשת קרבה ממשית המבססת חשש ממשי למשוא פנים (יעקב שקד, סדר הדין האזרחי). **וריאציה 2 — גורמים לבחינה:** מהם הגורמים הנבחנים? ← אופי ההיכרות, מסגרתה, משכה ומשך הזמן שחלף מאז (יעקב שקד, סדר הדין האזרחי). **וריאציה 3 — היכרות לימודית רחוקה:** האם היכרות לימודית מלפני 20 שנה פוסלת? ← לא, שכן שופטים מגיעים מהמקצוע וזה טבעי, ואין בכך חשש ממשי למשוא פנים (ת"א 54331-06-22 איתמר כהן).',
    'היכרות שופט-עו"ד ← לא פוסלת אוטומטית ← בחינת אופי הקשר וזמן שחלף ← נדרש חשש ממשי למשוא פנים.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 77א(א)", "ת\"א (מחוזי ב\"ש) 54331-06-22 איתמר כהן נ'' אופק רפאל שביט (19.09.2022)", "ע\"א 7444/23 עו\"ד יואב נדב נ'' קובי ישורון (30.10.2023)", "יעקב שקד, סדר הדין האזרחי (2026), פרק יז נושאים כלליים בפרק זה אעמוד על נושאים שונים הכרוכים בהליך האזרחי, חלקם מופיעים בתקנות וחלקם בחיקוקים אחרים."]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'מועד העלאת טענת פסלות ושיהוי', 4, 'בעל דין מעוניין להגיש בקשת פסלות נגד שופט, אך עילת הפסלות נודעה לו לפני מספר חודשים, והוא לא הגיש את הבקשה מיד. מה הדין לגבי בקשת הפסלות?',
    'שאלה זו עוסקת בכללים הפרוצדורליים להגשת בקשת פסלות שופט, ובפרט בחשיבות מועד ההגשה. היא מדגישה את הדרישה להגיש את הבקשה מיד עם היוודע עילת הפסלות, ואת ההשלכות של שיהוי בהגשה, אשר עלול להוביל לדחיית הבקשה על הסף.',
    'הכלל בדבר מועד הגשת בקשת פסלות שופט קבוע בתקנה 173(א) לתקנות סדר הדין האזרחי (ובסעיף 146(ג) לחוק סדר הדין הפלילי), לפיו יש להגיש את הבקשה ''מיד לאחר שנודע לו על עילת הפסלות ולפני כל טענה אחרת''. הפסיקה מדגישה כי על בעל דין להגיש בקשת פסלות מיד לאחר שנודע לו על עילת הפסלות, וכי שיהוי ניכר בהגשה, ללא הסבר מספק, מהווה כשלעצמו עילה לדחיית הבקשה. זאת, מתוך רצון למנוע שימוש ציני בטענת הפסלות ולשמור על יעילות ההליך השיפוטי. ע"א 667/24 פלוני נ'' פלונית (05.02.2024)ע"א 2369/24 גיל עם מזרחי נ'' עו"ד שושנה לונדנר (14.07.2024)סעיף 146(ג) לחוק סדר הדין הפלילינבו - המתמחה מערכת בתי המשפט (2026) | ד. דיני פסלות שופטטל חבקין, יגאל נמרודי התביעה הקטנה (2017) | פרק שלישי: סדרי הדין',
    'טעות נפוצה היא להתעלם מדרישת המיידיות בהגשת בקשת פסלות, או לחשוב שניתן להעלות טענת פסלות בכל שלב של ההליך, ללא קשר למועד היוודע העילה.',
    '["בקשת פסלות", "שיהוי", "מועד הגשה", "תקנות סדר הדין האזרחי", "חוק סדר הדין הפלילי", "יעילות דיונית"]'::jsonb,
    '**וריאציה 1 — מועד הגשה:** מתי יש להגיש בקשת פסלות? ← מיד לאחר שנודע על עילת הפסלות ולפני כל טענה אחרת (ע"א 2369/24 גיל עם מזרחי). **וריאציה 2 — השלכות שיהוי:** מה קורה אם יש שיהוי בהגשה? ← הבקשה תידחה על הסף בשל השיהוי, ללא הסבר מספק (ע"א 667/24 פלוני). **וריאציה 3 — חריג לשיהוי:** מתי שיהוי יתקבל? ← אם בעל הדין יוכיח שבשקידה סבירה לא היה יכול לגלות את העילה מוקדם יותר, ופעל מיד לאחר שנודעה לו העילה (סעיף 146(ג) לחוק סדר הדין הפלילי).',
    'בקשת פסלות ← יש להגיש מיד ← שיהוי ללא הסבר ← דחייה.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 77א", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 146(ג)", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 173(א)", "ע\"א 667/24 פלוני נ'' פלונית (05.02.2024)", "ע\"א 2369/24 גיל עם מזרחי נ'' עו\"ד שושנה לונדנר (14.07.2024)", "נבו - המתמחה, מערכת בתי המשפט (2026), ד. דיני פסלות שופט"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'כן, שכן לבן משפחה מדרגה ראשונה של השופט יש עניין אישי ממשי בהליך, וזו עילת פסלות חובה.', false, 'תשובה זו שגויה. אף שלבן המשפחה עשוי להיות עניין אישי, הפסיקה קבעה כי אין לאפשר לבעל דין ליצור עילת פסלות באמצעות פרובוקציות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לא, שכן אין לאפשר לבעל דין לקבוע מי ישפוט בעניינו באמצעות פרובוקציות, וזאת גם אם מדובר באיום על בן משפחה.', true, 'זו התשובה הנכונה. הפסיקה קובעת כי עיקרון יסוד בדיני הפסלות הוא שאין לאפשר לבעל דין לקבוע מי יפסוק בעניינו או להחליפו כאוות נפשו באמצעות פרובוקציות, ועיקרון זה חל גם כשמדובר באיומים על בן משפחה של השופט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, אך רק אם האיום הוכח מעל לכל ספק סביר.', false, 'תשובה זו שגויה. שאלת ההוכחה אינה משנה את העיקרון לפיו אין לאפשר לבעל דין ליצור עילת פסלות באופן מלאכותי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, אלא אם כן השופט עצמו מצהיר כי הוא חש חשש ממשי למשוא פנים.', false, 'תשובה זו שגויה. המבחן לפסלות הוא אובייקטיבי, ואין די בתחושתו הסובייקטיבית של השופט, במיוחד כאשר מדובר בניסיון מניפולטיבי של בעל דין.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'המבחן הוא סובייקטיבי, ודי בתחושה כנה של בעל דין כי קיים חשש למשוא פנים.', false, 'תשובה זו שגויה. הפסיקה קבעה באופן עקבי כי המבחן לפסלות שופט הוא אובייקטיבי, ואין די בתחושה סובייקטיבית של בעל דין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'המבחן הוא אובייקטיבי, ובוחן אם קיימת אפשרות ממשית למשוא פנים מנקודת מבטו של השופט הסביר, ולא של האדם הסביר או בעל הדין.', true, 'זו התשובה הנכונה. סעיף 77א(א) לחוק בתי המשפט קובע את המבחן האובייקטיבי של ''חשש ממשי למשוא פנים'', הנבחן מנקודת מבטו של השופט הסביר, ולא מנקודת מבט סובייקטיבית של בעל הדין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'המבחן הוא אובייקטיבי, אך הוא מתחשב גם בתחושות הסובייקטיביות של בעל הדין, במיוחד אם הן מבוססות על עובדות.', false, 'תשובה זו שגויה. אף שהמבחן האובייקטיבי לוקח בחשבון את כלל הנסיבות, הוא אינו מתבסס על תחושות סובייקטיביות של בעל דין, אלא על אפשרות ממשית למשוא פנים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'המבחן הוא אובייקטיבי, אך רק במקרים חריגים ניתן לפסול שופט בשל מראית פני הצדק גם ללא חשש ממשי למשוא פנים.', false, 'תשובה זו שגויה. היא מתארת את היחס בין ''חשש ממשי למשוא פנים'' ל''מראית פני הצדק'' כחריג, אך אינה מתארת את המבחן העיקרי ל''חשש ממשי למשוא פנים'' עצמו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'כן, כל היכרות קודמת עם בא כוח של צד מקימה עילת פסלות מחמת מראית פני הצדק.', false, 'תשובה זו שגויה. הפסיקה קבעה כי לא כל היכרות מקימה עילת פסלות, ונדרשת ''קרבה ממשית'' המבססת חשש ממשי למשוא פנים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לא, היכרות מקצועית או לימודית שאינה הדוקה ושחלף זמן רב מאז, אינה מקימה כשלעצמה חשש ממשי למשוא פנים.', true, 'זו התשובה הנכונה. שופטים מתמנים לרוב מקרב עורכי דין, וטבעי שתהיה להם היכרות מקצועית מוגבלת. היכרות לימודית רחוקה, שאינה הדוקה ושחלף זמן רב מאז, אינה מקימה כשלעצמה חשש ממשי למשוא פנים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'כן, אלא אם כן עורך הדין יצהיר כי אין לו כל קשר אישי עם השופט.', false, 'תשובה זו שגויה. נטל ההוכחה לקיומה של עילת פסלות מוטל על הטוען לפסלות, ואין די בהצהרה של עורך הדין כדי לשנות את המבחן האובייקטיבי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא, אך השופט חייב לגלות את ההיכרות לצדדים ולאפשר להם להגיש בקשת פסלות.', false, 'תשובה זו שגויה. אף שגילוי נאות הוא רצוי, הוא אינו הופך היכרות שאינה מקימה עילת פסלות לכזו, ואינו תנאי לפסלות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'הבקשה תידחה על הסף בשל שיהוי, שכן יש להגיש בקשת פסלות מיד עם היוודע העילה.', true, 'זו התשובה הנכונה. תקנה 173(א) לתקנות סדר הדין האזרחי (וכן סעיף 146(ג) לחוק סדר הדין הפלילי) קובעת כי יש להגיש בקשת פסלות מיד לאחר שנודעה עילת הפסלות, ואיחור בהגשה ללא הסבר מספק יוביל לדחייתה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'הבקשה תידון לגופה, שכן זכותו של בעל דין להגיש בקשת פסלות אינה מוגבלת בזמן.', false, 'תשובה זו שגויה. הגשת בקשת פסלות מוגבלת בזמן, ואיחור בהגשה עלול להוביל לדחייתה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'הבקשה תידון לגופה, אך נטל ההוכחה לקיומה של עילת הפסלות יהיה כבד יותר.', false, 'תשובה זו שגויה. אף ששיהוי יכול להשפיע על משקל הראיות, הכלל המרכזי הוא דחיית הבקשה על הסף בשל השיהוי עצמו, אם לא ניתן לו הסבר מספק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'הבקשה תידחה רק אם השיהוי גרם נזק ממשי לצד השני או למערכת המשפט.', false, 'תשובה זו שגויה. אף שנזק הוא שיקול, הכלל בדבר הגשה מיידית של בקשת פסלות הוא כלל פרוצדורלי מחייב, שאינו תלוי בהכרח בהוכחת נזק.', 4);

END $$;

-- ============================================================
-- Q26 — 2024-W-Q26 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q26';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q26 skipped: external_id % already exists', '2024-W-Q26';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q26', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'בית משפט השלום דחה בקשה לדחיית תביעה על הסף והורה על המשך בירור התביעה. הנתבע הגיש על כך ערעור. מה הדין?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 26}'::jsonb,
    'שאלה זו עוסקת במדיניות ההתערבות של ערכאת הערעור בהחלטות ביניים של הערכאה הדיונית, ובפרט בהחלטות הדוחות בקשה לסילוק על הסף. ההלכה הפסוקה קובעת כי התערבות כזו תיעשה במשורה ובמקרים חריגים בלבד, מתוך עקרון כיבוד שיקול הדעת של הערכאה הדיונית וזכות הגישה לערכאות.',
    'הלכה מושרשת היא כי ערכאת הערעור אינה נוטה להתערב בהחלטות הערכאה הדיונית המורות על המשך בירור ההליך לגופו, ובכלל זה החלטות הדוחות בקשה לסילוק על הסף. סילוק תביעה על הסף הוא סעד קיצוני, שתוצאתו מחיקה או דחייה של התביעה בטרם התבררה לגופה, ולכן שמור למקרים שבהם ברור כי גם אם יוכחו מלוא הטענות בכתב התביעה, אין כל אפשרות, ולו קלושה, כי התובע יזכה בסעד המבוקש. על כן, התערבות ערכאת הערעור בהחלטות ביניים מסוג זה תיעשה במשורה ותישמר למקרים חריגים בלבד, בהם נפלה טעות מהותית בהחלטה, או שמתעורר חשש לניהול הליך סרק הכרוך בהשקעת משאבים יוצאת דופן. רע"א 8037/23 רויטל סרן שבתאי נ'' טיולי אלון טבריה בע"מ (27.03.2024)רע"א 5464/22 דרור לדרמן נ'' עיריית קרית-גת (19.10.2022)רע"א 4635-06-25 מדינת ישראל משטרת ישראל נ'' פלונית (30.10.2025)רע"א 4512/24 מאור דהרי נ'' הטחנות הגדולות של א"י בע"מ (10.09.2024)חמי בן-נון, טל חבקין הערעור האזרחי (2012) | פרק שישי - בקשת רשות לערער',
    'לבלבל בין סילוק על הסף לבין דחיית תביעה לגופה, או לחשוב שערכאת הערעור תתערב בקלות בהחלטות ביניים, מבלי להבין את המדיניות המצמצמת של בית המשפט העליון.',
    '["סילוק על הסף", "רשות ערעור", "החלטה אחרת", "התערבות ערכאת ערעור", "טעות מהותית", "הליך סרק", "משאבים שיפוטיים", "זכות הגישה לערכאות"]'::jsonb,
    '**וריאציה 1 — מדיניות כללית:** מהי המדיניות הכללית של ערכאת הערעור לגבי החלטות הדוחות סילוק על הסף? ← אינה נוטה להתערב, שכן משמעותן היא המשך בירור ההליך לגופו (רע"א 8037/23 רויטל סרן שבתאי). **וריאציה 2 — מקרים חריגים:** באילו מקרים חריגים תתערב ערכאת הערעור? ← כאשר נפלה טעות מהותית בהחלטה, או שמתעורר חשש לניהול הליך סרק הכרוך בהשקעת משאבים יוצאת דופן (רע"א 5464/22 דרור לדרמן). **וריאציה 3 — סילוק על הסף כסעד קיצוני:** מדוע סילוק על הסף נחשב לסעד קיצוני? ← תוצאתו מחיקה או דחייה של התביעה בטרם בירורה לגופה, ולכן שמור למקרים בהם אין כל אפשרות, ולו קלושה, שהתובע יזכה (רע"א 5596/23 ספיר וברקת נדל"ן).',
    'ערעור על דחיית סילוק על הסף ← התערבות נדירה ← רק טעות מהותית / הליך סרק ← סעד קיצוני.',
    '["רע\"א 8037/23 רויטל סרן שבתאי נ'' טיולי אלון טבריה בע\"מ (27.03.2024)", "רע\"א 5464/22 דרור לדרמן נ'' עיריית קרית-גת (19.10.2022)", "רע\"א 4635-06-25 מדינת ישראל משטרת ישראל נ'' פלונית (30.10.2025)", "רע\"א 4512/24 מאור דהרי נ'' הטחנות הגדולות של א\"י בע\"מ (10.09.2024)", "חמי בן-נון, טל חבקין, הערעור האזרחי (2012), פרק שישי - בקשת רשות לערער"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט המחוזי אינו רשאי להתערב בהחלטה שכזו.', false, 'תשובה זו שגויה. בית המשפט המחוזי, כערכאת ערעור, רשאי להתערב בהחלטות ביניים, אך זאת במקרים חריגים בלבד ולא באופן גורף.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט המחוזי חייב להתערב בהחלטה שכזו.', false, 'תשובה זו שגויה. אין חובה על ערכאת הערעור להתערב בהחלטות הדוחות סילוק על הסף, אלא נהפוך הוא – המדיניות היא אי-התערבות למעט חריגים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט המחוזי יתערב במקרים חריגים כאשר נפלה טעות מהותית או שמתעורר חשש לניהול הליך סרק, הכרוך בהשקעת משאבים יוצאת דופן.', true, 'זו התשובה הנכונה. זוהי ההלכה המושרשת בפסיקת בית המשפט העליון לגבי התערבות ערכאת הערעור בהחלטות ביניים הדוחות בקשה לסילוק על הסף.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט המחוזי יתערב במקרים חריגים כאשר העניין חורג מעניינם הפרטי של הצדדים או כאשר עולה שאלה ציבורית רחבה.', false, 'תשובה זו שגויה. אלו הם קריטריונים למתן רשות ערעור ב''גלגול שלישי'' (לבית המשפט העליון), ולא למדיניות ההתערבות של ערכאת הערעור בהחלטות ביניים ב''גלגול שני''.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'סילוק על הסף מחמת היעדר עילה', 1, 'ראובן הגיש תביעה נגד שמעון בגין נזקים שנגרמו לו כתוצאה מאירוע שאין לו כל קשר לשמעון, וכתב התביעה אינו מפרט כל עילה משפטית נגד שמעון. שמעון הגיש בקשה לסילוק התביעה על הסף מחמת היעדר עילה. מהי ההחלטה הסבירה של בית המשפט?',
    'שאלה זו עוסקת באחד המקרים הקלאסיים לסילוק תביעה על הסף – היעדר עילה. היא בוחנת את הסטנדרט המחמיר הנדרש כדי להפעיל סעד קיצוני זה, המונע מבעל דין את יומו בבית המשפט, ומדגישה את הצורך בוודאות מוחלטת לגבי חוסר סיכויי התביעה.',
    'סילוק תביעה על הסף, בין אם בדרך של מחיקה ובין אם בדרך של דחייה, הוא סעד דיוני קיצוני השמור למקרים חריגים בלבד. בית המשפט יפעיל סעד זה רק כאשר שוכנע כי אין כל אפשרות, ולו קלושה, שיעלה בידי התובע לקבל את הסעד לו עתר, גם אם יוכחו מלוא הטענות שבכתב התביעה. במקרה המתואר, כאשר כתב התביעה אינו מפרט כל עילה משפטית נגד הנתבע ואין כל קשר בינו לבין הנזק הנטען, ברור כי התביעה חסרת סיכוי. במצב כזה, דחיית התביעה על הסף היא ההחלטה הנכונה, שכן המשך בירור ההליך יהווה בזבוז משאבים שיפוטיים ושל הצדדים. רע"א 5596/23 ספיר וברקת נדל"ן (הולילנד) בע"מ נ'' יאיר רחמין (07.01.2024)רע"א 6648/19 Smiths Detection LLC נ'' ווטאירפול הנדסה בע"מ (30.04.2020)ע"א 70512-09-25 מרים פורת נ'' אמיר חן (23.04.2026)שלמה יעקובוביץ סדרי הדין בבית הדין לעבודה (2024) | פרק ח פסק דין בהיעדר הגנה, מחיקה ודחייהישראל גלעד התיישנות בדין האזרחי (2022) | פרק שנים עשר היבטים דיוניים',
    'הטעות הנפוצה היא לחשוב שבית המשפט תמיד יאפשר לתובע לתקן את כתב התביעה, גם כאשר אין כל בסיס עובדתי או משפטי לתביעה נגד הנתבע הספציפי.',
    '["סילוק על הסף", "היעדר עילה", "סעד קיצוני", "זכות הגישה לערכאות", "בזבוז משאבים שיפוטיים", "מחיקה על הסף", "דחייה על הסף"]'::jsonb,
    '**וריאציה 1 — מתי סילוק על הסף?** מתי בית המשפט יסלק תביעה על הסף מחמת היעדר עילה? ← רק כאשר ברור שאין כל אפשרות, ולו קלושה, שהתובע יזכה בסעד המבוקש (רע"א 5596/23 ספיר וברקת נדל"ן). **וריאציה 2 — סעד קיצוני:** מדוע סילוק על הסף נחשב לסעד קיצוני? ← הוא מביא למחיקה או דחייה של התובענה בטרם התבררה לגופה, ופוגע בזכות הגישה לערכאות (ע"א 70512-09-25 מרים פורת). **וריאציה 3 — הבחנה בין מחיקה לדחייה:** מה ההבדל בין מחיקה לדחייה על הסף? ← דחייה מקימה מעשה בית דין וסותמת את הגולל על בירור הטענות, בעוד מחיקה בדרך כלל אינה מקימה מעשה בית דין (ע"א 70512-09-25 מרים פורת).',
    'סילוק על הסף ← סעד קיצוני ← רק כשאין סיכוי קלוש לזכייה ← היעדר עילה מוחלט ← דחייה.',
    '["רע\"א 5596/23 ספיר וברקת נדל\"ן (הולילנד) בע\"מ נ'' יאיר רחמין (07.01.2024)", "רע\"א 6648/19 Smiths Detection LLC נ'' ווטאירפול הנדסה בע\"מ (30.04.2020)", "ע\"א 70512-09-25 מרים פורת נ'' אמיר חן (23.04.2026)", "שלמה יעקובוביץ, סדרי הדין בבית הדין לעבודה (2024), פרק ח פסק דין בהיעדר הגנה, מחיקה ודחייה", "ישראל גלעד, התיישנות בדין האזרחי (2022), פרק שנים עשר היבטים דיוניים"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'סילוק על הסף כסעד קיצוני', 2, 'מהי הגישה הכללית של בתי המשפט בישראל כלפי בקשות לסילוק תביעה על הסף, ומדוע סעד זה נחשב לקיצוני?',
    'שאלה זו מתמקדת בעקרון היסוד המנחה את בתי המשפט בבואם לדון בבקשות לסילוק על הסף. היא מדגישה את האיזון העדין בין זכות הגישה לערכאות לבין הצורך בייעול המערכת השיפוטית, ומבהירה מדוע סעד זה נחשב לקיצוני ויינתן במשורה.',
    'סילוק תביעה על הסף, בין אם בדרך של מחיקה ובין אם בדרך של דחייה, הוא אמצעי דיוני קיצוני בעל השלכות מרחיקות לכת על זכויות התובע, ובראשן זכות הגישה לערכאות. בשל כך, הפסיקה קבעה כי השימוש בסעד זה ייעשה בזהירות רבה ורק במקרים חריגים בהם שוכנע בית המשפט כי אף לו יתנהלו הליכי המשפט במלואם, ובהנחה כי תוכחנה העובדות המפורטות בכתב התביעה, לא יהיה בתביעה הנדונה כדי לספק לתובע את הסעד אותו הוא מבקש. כלומר, רק כאשר ברור שאין כל אפשרות, ולו קלושה, שהתובע יצליח בתביעתו. רע"א 5596/23 ספיר וברקת נדל"ן (הולילנד) בע"מ נ'' יאיר רחמין (07.01.2024)רע"א 6648/19 Smiths Detection LLC נ'' ווטאירפול הנדסה בע"מ (30.04.2020)רע"א 6953/20 נת"ע נתיבי תחבורה עירוניים להסעת המונים בע"מ נ'' לזר - ב.י. מדידות הנדסיות בע"מ (05.01.2021)רע"א 12871-01-25 בנק דיסקונט לישראל בע"מ נ'' דוד גוזלן (30.01.2025)שלמה יעקובוביץ סדרי הדין בבית הדין לעבודה (2024) | פרק ח פסק דין בהיעדר הגנה, מחיקה ודחייה',
    'הטעות הנפוצה היא לחשוב שסילוק על הסף הוא כלי שגרתי לטיפול בתביעות חלשות, במקום להבין שהוא שמור למקרים קיצוניים בלבד, מתוך כיבוד זכות הגישה לערכאות.',
    '["סילוק על הסף", "סעד קיצוני", "זכות הגישה לערכאות", "מקרים חריגים", "אין סיכוי קלוש", "ייעול הליכים", "מחיקה ודחייה"]'::jsonb,
    '**וריאציה 1 — הגדרת סילוק על הסף:** מהו סילוק על הסף? ← אמצעי דיוני קיצוני המביא למחיקה או דחייה של תובענה בטרם התבררה לגופה (רע"א 6953/20 נת"ע). **וריאציה 2 — מתי יינתן?** באילו מקרים יינתן סעד זה? ← רק במקרים חריגים ונדירים בהם ברור שאין כל אפשרות, ולו קלושה, שהתובע יזכה בסעד המבוקש (רע"א 5596/23 ספיר וברקת נדל"ן). **וריאציה 3 — איזון שיקולים:** מהו האיזון שבית המשפט נדרש לו? ← בין זכות הגישה לערכאות לבין הצורך בייעול המערכת וחיסכון במשאבים שיפוטיים (רע"א 5337/17 כץ נ'' כץ).',
    'סילוק על הסף ← סעד קיצוני ← רק במקרים חריגים ← אין סיכוי קלוש לזכייה ← איזון זכות גישה ויעילות.',
    '["רע\"א 5596/23 ספיר וברקת נדל\"ן (הולילנד) בע\"מ נ'' יאיר רחמין (07.01.2024)", "רע\"א 6648/19 Smiths Detection LLC נ'' ווטאירפול הנדסה בע\"מ (30.04.2020)", "רע\"א 6953/20 נת\"ע נתיבי תחבורה עירוניים להסעת המונים בע\"מ נ'' לזר - ב.י. מדידות הנדסיות בע\"מ (05.01.2021)", "רע\"א 12871-01-25 בנק דיסקונט לישראל בע\"מ נ'' דוד גוזלן (30.01.2025)", "שלמה יעקובוביץ, סדרי הדין בבית הדין לעבודה (2024), פרק ח פסק דין בהיעדר הגנה, מחיקה ודחייה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'התערבות בגלגול שלישי', 3, 'בית משפט השלום דחה בקשה לסילוק על הסף. בית המשפט המחוזי דחה בקשת רשות ערעור על החלטה זו. הנתבע הגיש בקשת רשות ערעור לבית המשפט העליון (גלגול שלישי). באילו נסיבות יתערב בית המשפט העליון בהחלטה זו?',
    'שאלה זו עוסקת במדיניות המצמצמת של בית המשפט העליון במתן רשות ערעור ב''גלגול שלישי'', ובפרט על החלטות ביניים הדוחות בקשה לסילוק על הסף. היא מדגישה את הקריטריונים המחמירים להתערבות במקרים אלו, המתמקדים בשאלות עקרוניות או מניעת עיוות דין חמור, ולא בטעויות פרטניות של הערכאות הנמוכות.',
    'הלכה מושרשת היא כי ערכאת הערעור אינה נוטה להתערב בהחלטות הערכאה הדיונית המורות על המשך בירור ההליך לגופו. כלל זה חל ביתר שאת כאשר מדובר בבקשת רשות ערעור ב''גלגול שלישי'', כלומר, על החלטת בית משפט מחוזי שדחה בקשת רשות ערעור על החלטת בית משפט השלום. במקרים אלו, בית המשפט העליון יתערב רק במקרים חריגים ביותר, כאשר הקביעות בהחלטה מעוררות שאלה משפטית עקרונית החורגת מעניינם של הצדדים, או כאשר מתן רשות ערעור דרוש כדי למנוע עיוות דין. אין די בטענה לנפילת טעות מהותית בהחלטת הערכאה הדיונית, או חשש לניהול הליך סרק, כדי להצדיק התערבות ב''גלגול שלישי''. תקנה 148א לתקנות סדר הדין האזרחי, תשע"ט-2018רע"א 25857-11-25 אריק דרובוט נ'' כלל נכסי נדל"ן נשר מרכז (נ.נ.נ.מ) שותפות מוגבלת (18.03.2026)ע"א 70512-09-25 מרים פורת נ'' אמיר חן (23.04.2026)רע"א 38862-07-25 רעי משעל נ'' לונגשין קונסטרקשן גרופ קו., אל טי די (25.09.2025)',
    'הטעות הנפוצה היא ליישם את קריטריוני ההתערבות ב''גלגול שני'' (טעות מהותית או חשש להליך סרק) גם ב''גלגול שלישי'', מבלי להבין שהמבחן ב''גלגול שלישי'' מחמיר וצר יותר.',
    '["רשות ערעור", "גלגול שלישי", "החלטה אחרת", "שאלה משפטית עקרונית", "עיוות דין", "מדיניות שיפוטית", "תקנה 148א"]'::jsonb,
    '**וריאציה 1 — מתי גלגול שלישי?** מתי בית המשפט העליון ידון בבקשת רשות ערעור ב''גלגול שלישי''? ← רק במקרים חריגים ביותר, כאשר העניין חורג מעניינם הפרטי של הצדדים או כאשר מתעוררת שאלה משפטית עקרונית (תקנה 148א לתקנות סדר הדין האזרחי). **וריאציה 2 — מדיניות אי-התערבות:** מהי המדיניות הכללית ב''גלגול שלישי''? ← ערכאת הערעור תיטה שלא להתערב בהחלטות המורות על המשך בירור ההליך לגופו, ובכלל זה דחיית בקשה לסילוק על הסף (רע"א 25857-11-25 אריק דרובוט). **וריאציה 3 — מטרת ההתערבות:** מהי מטרת ההתערבות ב''גלגול שלישי''? ← למנוע נזק בלתי הפיך או ניהול הליך מיותר או שגוי, כאשר ההחלטה מעוררת שאלה עקרונית (ע"א 70512-09-25 מרים פורת).',
    'גלגול שלישי ← התערבות נדירה ← שאלה עקרונית / עיוות דין ← לא טעות פרטנית.',
    '["תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 148א", "רע\"א 25857-11-25 אריק דרובוט נ'' כלל נכסי נדל\"ן נשר מרכז (נ.נ.נ.מ) שותפות מוגבלת (18.03.2026)", "ע\"א 70512-09-25 מרים פורת נ'' אמיר חן (23.04.2026)", "רע\"א 38862-07-25 רעי משעל נ'' לונגשין קונסטרקשן גרופ קו., אל טי די (25.09.2025)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'סילוק על הסף מחמת שיהוי', 4, 'מועצה אזורית נתבעה בתביעת השבה בגין היטלי סלילה ופיתוח שנגבו ביתר. המועצה טענה לשיהוי בהגשת התביעה וביקשה לסלק אותה על הסף. מהי הגישה השיפוטית לבקשה לסילוק על הסף מחמת שיהוי במקרה זה?',
    'שאלה זו עוסקת ביישום טענת השיהוי כעילה לסילוק תביעה על הסף, ובפרט בהקשר של תביעות השבה נגד רשויות ציבוריות. היא מדגישה את הגישה הזהירה של בתי המשפט בסילוק תביעות על הסף, ואת העובדה שטענת שיהוי, אף שהיא חשובה, אינה מביאה אוטומטית לסילוק התביעה.',
    'הלכה מושרשת היא כי ההלכה הוותיקה, שיסודה בזכות הגישה לערכאות, מחייבת שימוש זהיר בכלי של סילוק תביעה על הסף. דחיית תביעה על הסף הוא סעד קיצוני, השמור למקרים בהם ברור כי גם אם יוכח מלוא הנטען בכתב התביעה, אין כל אפשרות, ולו קלושה, כי התובע יזכה לקבל את הסעד המבוקש. כך בכלל, וכך בפרט שעה שמדובר בבקשה לסילוק תביעה על הסף מחמת שיהוי. טענת שיהוי דורשת בירור עובדתי ומשפטי מעמיק, ואינה מביאה אוטומטית לסילוק התביעה על הסף, אלא במקרים חריגים ביותר. רע"א 7940-12-24 מועצה אזורית מגידו נ'' בליס דר בע"מ (13.01.2025)רע"א 6953/20 נת"ע נתיבי תחבורה עירוניים להסעת המונים בע"מ נ'' לזר - ב.י. מדידות הנדסיות בע"מ (05.01.2021)ישראל גלעד התיישנות בדין האזרחי (2022) | פרק שנים עשר היבטים דיונייםטל חבקין, יגאל נמרודי התביעה הקטנה (2017) | פרק שלישי: סדרי הדין',
    'הטעות הנפוצה היא לחשוב שטענת שיהוי, במיוחד נגד רשות ציבורית, תמיד תוביל לסילוק על הסף, מבלי להבין את הגישה הזהירה של בתי המשפט ואת הצורך בבירור עובדתי.',
    '["סילוק על הסף", "שיהוי", "זכות הגישה לערכאות", "רשויות ציבוריות", "בירור עובדתי", "סעד קיצוני", "היטלי סלילה ופיתוח"]'::jsonb,
    '**וריאציה 1 — גישה כללית לשיהוי:** מהי הגישה הכללית לסילוק על הסף מחמת שיהוי? ← שימוש זהיר בכלי זה, שכן הוא סעד קיצוני (רע"א 7940-12-24 מועצה אזורית מגידו). **וריאציה 2 — צורך בבירור עובדתי:** מתי לא יידון שיהוי כטענת סף? ← כאשר ההכרעה בטענה דורשת בירור עובדתי מעמיק (רע"א 6953/20 נת"ע). **וריאציה 3 — תביעות השבה:** האם יש גישה מיוחדת לתביעות השבה נגד רשויות? ← גם בתביעות אלו, הגישה היא זהירה, ואין סילוק אוטומטי על הסף מחמת שיהוי (רע"א 7940-12-24 מועצה אזורית מגידו).',
    'שיהוי ← סילוק על הסף בזהירות ← דורש בירור עובדתי ← לא אוטומטי.',
    '["רע\"א 7940-12-24 מועצה אזורית מגידו נ'' בליס דר בע\"מ (13.01.2025)", "רע\"א 6953/20 נת\"ע נתיבי תחבורה עירוניים להסעת המונים בע\"מ נ'' לזר - ב.י. מדידות הנדסיות בע\"מ (05.01.2021)", "ישראל גלעד, התיישנות בדין האזרחי (2022), פרק שנים עשר היבטים דיוניים", "טל חבקין, יגאל נמרודי, התביעה הקטנה (2017), פרק שלישי: סדרי הדין"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'בית המשפט ידחה את הבקשה ויורה על המשך בירור התביעה, שכן סילוק על הסף הוא סעד קיצוני.', false, 'תשובה זו שגויה. אף שסילוק על הסף הוא סעד קיצוני, במקרים בהם ברור שאין כל אפשרות, ולו קלושה, שהתובע יזכה, בית המשפט יורה על סילוק התביעה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'בית המשפט יורה על מחיקת התביעה, שכן כתב התביעה אינו מראה עילה, אך יאפשר לראובן לתקן את כתב התביעה.', false, 'תשובה זו שגויה. מחיקה על הסף ניתנת כאשר ניתן לתקן את הפגם. במקרה של היעדר עילה מוחלט וברור, ללא כל קשר לנתבע, סביר יותר שהתביעה תידחה ולא תימחק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'בית המשפט ידחה את התביעה על הסף, שכן ברור כי אין כל אפשרות, ולו קלושה, שראובן יזכה בסעד המבוקש.', true, 'זו התשובה הנכונה. סילוק תביעה על הסף מחמת היעדר עילה ייעשה רק במקרים בהם ברור כי גם אם יוכחו מלוא הטענות בכתב התביעה, אין כל אפשרות, ולו קלושה, כי התובע יזכה בסעד המבוקש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'בית המשפט יורה על העברת התביעה לבית משפט אחר, שכן מדובר בחוסר סמכות עניינית.', false, 'תשובה זו שגויה. היעדר עילה אינו חוסר סמכות עניינית. חוסר סמכות עניינית מתייחס למוסד השיפוטי המוסמך לדון בעניין, ולא למהות התביעה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'בתי המשפט נוטים להיעתר לבקשות לסילוק על הסף כדי לייעל את המערכת ולחסוך במשאבים שיפוטיים.', false, 'תשובה זו שגויה. אף שיעילות היא שיקול, היא אינה גוברת על זכות הגישה לערכאות, ובתי המשפט נוקטים בזהירות רבה בסעד זה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'סילוק על הסף הוא סעד קיצוני המונע מבעל דין את יומו בבית המשפט, ולכן יינתן רק במקרים חריגים ונדירים בהם אין כל סיכוי, ולו קלוש, שהתובע יזכה.', true, 'זו התשובה הנכונה. הפסיקה מדגישה כי סילוק על הסף הוא סעד קיצוני הפוגע בזכות הגישה לערכאות, ולכן השימוש בו ייעשה בזהירות רבה ובמקרים חריגים בלבד, כאשר ברור שאין כל סיכוי לתביעה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'סילוק על הסף הוא סעד רגיל, שנועד לסנן תביעות שאינן מבוססות דיו מבחינה עובדתית.', false, 'תשובה זו שגויה. סילוק על הסף אינו סעד רגיל, והוא אינו מיועד לבירור עובדתי מעמיק, אלא למקרים בהם חוסר הסיכוי ברור על פני הדברים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'בתי המשפט יסלקו תביעה על הסף אם הנתבע יוכיח כי התביעה הוגשה בחוסר תום לב.', false, 'תשובה זו שגויה. אף שחוסר תום לב יכול להוות שיקול, הוא אינו התנאי הבלעדי או המרכזי לסילוק על הסף, והמבחן העיקרי הוא חוסר סיכוי קלוש לתביעה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'בית המשפט העליון יתערב אם נפלה טעות מהותית בהחלטת בית משפט השלום, גם אם בית המשפט המחוזי לא התערב.', false, 'תשובה זו שגויה. ב''גלגול שלישי'', בית המשפט העליון אינו בוחן טעות מהותית של הערכאה הדיונית כשלעצמה, אלא רק אם מתקיימים קריטריונים מצומצמים למתן רשות ערעור.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בית המשפט העליון יתערב רק במקרים חריגים ביותר, כאשר העניין חורג מעניינם הפרטי של הצדדים או כאשר מתעוררת שאלה משפטית עקרונית.', true, 'זו התשובה הנכונה. ב''גלגול שלישי'', בית המשפט העליון יתערב רק במקרים המעוררים שאלה משפטית עקרונית החורגת מעניינם של הצדדים, או כאשר נדרש למנוע עיוות דין חמור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט העליון יתערב אם קיים חשש לניהול הליך סרק הכרוך בהשקעת משאבים יוצאת דופן, בדומה למבחן ב''גלגול שני''.', false, 'תשובה זו שגויה. אף שחשש להליך סרק הוא שיקול ב''גלגול שני'', ב''גלגול שלישי'' המבחן מחמיר יותר ומתמקד בשאלות עקרוניות או עיוות דין חמור.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בית המשפט העליון אינו מתערב כלל בהחלטות ביניים ב''גלגול שלישי'', שכן ההליך כבר עבר שתי ערכאות.', false, 'תשובה זו שגויה. בית המשפט העליון רשאי להתערב גם ב''גלגול שלישי'', אך זאת במקרים חריגים ונדירים ביותר, על פי קריטריונים מצומצמים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בית המשפט יסלק את התביעה על הסף, שכן שיהוי הוא טעם מובהק לדחיית תביעות, במיוחד נגד רשויות ציבוריות.', false, 'תשובה זו שגויה. אף ששיהוי הוא טענה חשובה, סילוק על הסף מחמתו ייעשה בזהירות יתרה, ואין מדובר בטעם אוטומטי לדחייה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט ידחה את הבקשה לסילוק על הסף, שכן ההלכה הוותיקה מחייבת שימוש זהיר בכלי של סילוק תביעה על הסף, ובפרט מחמת שיהוי.', true, 'זו התשובה הנכונה. הפסיקה מדגישה כי סילוק תביעה על הסף הוא סעד קיצוני, ובפרט כאשר מדובר בטענת שיהוי, יש לנקוט בזהירות יתרה ולא לדחות את התביעה על הסף אלא במקרים חריגים ביותר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בית המשפט יסלק את התביעה על הסף רק אם השיהוי גרם נזק ראייתי משמעותי למועצה האזורית.', false, 'תשובה זו שגויה. נזק ראייתי הוא שיקול, אך הוא אינו התנאי הבלעדי לסילוק על הסף מחמת שיהוי, והגישה הכללית היא זהירות רבה בסעד זה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט יורה על העברת הדיון לבית המשפט לעניינים מנהליים, שכן מדובר בתביעה נגד רשות ציבורית.', false, 'תשובה זו שגויה. השאלה עוסקת בסילוק על הסף מחמת שיהוי, ולא בסמכות עניינית. בנוסף, הלכת נוה-גד מאפשרת דיון בתביעות השבה מסוג זה גם בערכאה אזרחית.', 4);

END $$;

-- ============================================================
-- Q27 — 2024-W-Q27 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q27';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q27 skipped: external_id % already exists', '2024-W-Q27';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q27', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'באיזה מקרה מבין המקרים הבאים תתקבל טענה לפסלות חוות דעת של מומחה שמונה על ידי בית המשפט, שלגביו הוסכם כי הקביעות בחוות דעתו יחייבו את הצדדים?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 27}'::jsonb,
    'שאלה זו עוסקת באמות המידה לפסילת חוות דעת של מומחה שמונה על ידי בית המשפט, ובפרט כאשר הצדדים הסכימו כי קביעותיו יהיו מכריעות (מומחה מכריע). הפסיקה קובעת כי פסילת חוות דעת כזו היא סעד קיצוני שיינתן רק במקרים חריגים ביותר, כאשר מתעורר ''חשש ממשי למשוא פנים'' מצד המומחה, ולא די בחשש כללי או בהפרת חובת גילוי כשלעצמה.',
    'הלכה פסוקה היא כי פסילת חוות דעת של מומחה שמונה מטעם בית המשפט, ובפרט מומחה מכריע שמונה בהסכמת הצדדים, היא סעד קיצוני שיינתן רק במקרים נדירים ומטעמים מיוחדים המצדיקים זאת, למשל כאשר נפל פגם היורד לשורשו של עניין ושיש בו כדי לגרום לעיוות דין קשה. במקרה של מומחה מכריע, טענה לבטלות חוות דעתו מחמת ניגוד עניינים והפרת חובת גילוי לא תתקבל אלא במקרים שמעוררים ''חשש ממשי למשוא פנים'' מצד המומחה. הפרת חובת הגילוי כשלעצמה אינה תנאי מספיק לביטול חוות הדעת, ויש להראות קיומו של חשש ממשי למשוא פנים. זאת, בין היתר, בשל חזקת התקינות המקצועית של המומחה, שיקולי יעילות דיונית, והחשש מהתנהלות אסטרטגית של צדדים המבקשים לבטל חוות דעת בדיעבד בשל אי שביעות רצון מתוצאותיה. ע"א 2706/22 תומר בוכריס נ'' המשבב אייץ. אמ. טי. אס. בע"מ (04.07.2023)דנ"א 5535/23 המשבב אייץ. אמ. טי. אס. בע"מ נ'' תומר בוכריס (26.12.2023)רע"א 9229/23 בלה וינשטוק נ'' עשת - סורין ייזום ובניה בע"מ (12.07.2023)רע"א 8209/22 פלונית נ'' המרכז הרפואי ע"ש שיבא (07.12.2022)',
    'הטעות הנפוצה היא לחשוב שכל קשר או היכרות, או כל הפרה של חובת גילוי, מקימה עילת פסלות אוטומטית, מבלי להבין את הסטנדרט המחמיר של ''חשש ממשי למשוא פנים'' ואת חזקת התקינות המקצועית של המומחה.',
    '["מומחה מכריע", "פסילת מומחה", "חשש ממשי למשוא פנים", "ניגוד עניינים", "חובת גילוי", "חזקת תקינות מקצועית", "סעד קיצוני", "התנהלות אסטרטגית"]'::jsonb,
    '**וריאציה 1 — מומחה מכריע:** מהי אמת המידה לפסילת חוות דעת של מומחה מכריע? ← חשש ממשי למשוא פנים מצד המומחה (ע"א 2706/22 בוכריס). **וריאציה 2 — הפרת חובת גילוי:** האם הפרת חובת גילוי מספיקה לפסילה? ← לא, הפרת חובת הגילוי אינה תנאי מספיק לביטול חוות הדעת, יש להראות קיומו של חשש ממשי למשוא פנים (ע"א 2706/22 בוכריס). **וריאציה 3 — קשרים מקצועיים:** האם קשרים מקצועיים בין מומחה מכריע לגורם הקשור לצד להליך מגבשים חשש ממשי למשוא פנים? ← ככלל לא, אלא אם קיימים יחסי עבודה קבועים (ע"א 2706/22 בוכריס; רע"א 9229/23 וינשטוק).',
    'פסילת מומחה מכריע ← רק חשש ממשי למשוא פנים ← לא כל הפרת גילוי / קשר מקצועי ← חזקת תקינות.',
    '["ע\"א 2706/22 תומר בוכריס נ'' המשבב אייץ. אמ. טי. אס. בע\"מ (04.07.2023)", "דנ\"א 5535/23 המשבב אייץ. אמ. טי. אס. בע\"מ נ'' תומר בוכריס (26.12.2023)", "רע\"א 9229/23 בלה וינשטוק נ'' עשת - סורין ייזום ובניה בע\"מ (12.07.2023)", "רע\"א 53413-04-25 דרך נכסי החצב בע\"מ נ'' \"נוף הארץ\" ייזום ובנין בע\"מ (14.05.2025)", "רע\"א 7352/21 פלוני (קטין) נ'' קרנית, קרן לפיצוי נפגעי תאונות דרכים (17.11.2021)", "רע\"א 4220/22 פלוני נ'' ד\"ר יפעת וינר (28.06.2022)", "רע\"א 8209/22 פלונית נ'' המרכז הרפואי ע\"ש שיבא (07.12.2022)", "רע\"א 10895/08 גילי גולן נ'' גנאם דלאל (23.04.2009)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'במקרה שמתעורר חשש למשוא פנים.', false, 'תשובה זו שגויה. הפסיקה דורשת קיומו של ''חשש ממשי'' למשוא פנים, ולא די בחשש כללי בלבד, כדי להצדיק פסילת חוות דעת מומחה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'במקרה שמתעורר חשש ממשי למשוא פנים.', true, 'זו התשובה הנכונה. הפסיקה קובעת כי טענה לבטלות חוות דעת של מומחה מכריע מחמת ניגוד עניינים והפרת חובת גילוי, לא תתקבל אלא במקרים שמעוררים חשש ממשי למשוא פנים מצד המומחה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'הטענה תתקבל בכל מקרה בו הופרה חובת גילוי של היכרות מוקדמת עם מי מבאי כוח הצדדים.', false, 'תשובה זו שגויה. הפסיקה קבעה כי הפרת חובת הגילוי אינה תנאי מספיק לביטול חוות הדעת, ויש להראות קיומו של חשש ממשי למשוא פנים מצד המומחה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'הטענה תתקבל בכל מקרה בו יתעורר חשש של ניגוד עניינים.', false, 'תשובה זו שגויה. בדומה לתשובה א'', לא כל חשש לניגוד עניינים יצדיק פסילה, אלא רק חשש ממשי, וזאת בהתחשב בחזקת התקינות המקצועית של המומחה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'פסילת מומחה עקב חשיפה חד-צדדית לחומר', 1, 'מומחה רפואי שמונה מטעם בית המשפט גיבש את חוות דעתו לאחר שנחשף לחומר רפואי מטעם צד אחד בלבד, מבלי שניתנה לצד השני הזדמנות להציג את החומר הרלוונטי מטעמו. מה הדין לגבי חוות דעת זו?',
    'שאלה זו עוסקת בפסילת חוות דעת מומחה שמונה מטעם בית המשפט במקרה של חשיפה חד-צדדית לחומר. הפסיקה רואה בכך פגם מהותי היורד לשורש ההליך, הפוגע בזכות הטיעון ובמראית פני הצדק, ומצדיק פסילה גם אם המומחה פעל בתום לב, שכן הדבר כמוהו כמתן פסק דין בהיעדר כתב טענות של אחד הצדדים.',
    'מומחה מטעם בית המשפט משמש כזרועו הארוכה של בית המשפט, ומוטלות עליו חובות אמון ומקצועיות, ובכלל זה חובה לנהוג באובייקטיביות וללא משוא פנים. גיבוש חוות דעת על ידי מומחה בית המשפט לאחר שנחשף לחוות דעת או חומר מטעם צד אחד בלבד, כמוהו, בשינויים המתחייבים, כמתן פסק דין בהיעדר כתב טענות של מי מבעלי הדין. במקרים כאלה נפגעת זכות הטיעון של אותו צד, זכות שהיא אבן יסוד במשפט, ולפיכך, נפל פגם מהותי בחוות הדעת. פגם זה פוגע בתקינות ההליך, בזכויותיו הדיוניות של בעל הדין ובמראית העין בכל הנוגע לניטרליות המומחה, ולכן מצדיק את פסילת חוות הדעת ומינוי מומחה אחר, וזאת אף אם המומחה נהג בתום לב. רע"א 1834/18 שירותי בריאות כללית נ'' פלונית (03.05.2018)רע"א 7921/20 פלוני נ'' מרכז החינוך העצמאי לת"ת ובתי ספר (14.12.2020)רע"א 7098/10 אוהד טביבזדה נ'' שירותי בריאות כללית (31.01.2011)רע"א 8152/18 פלוני נ'' כלל חברה לביטוח בע"מ (10.02.2019)',
    'הטעות הנפוצה היא לחשוב שניתן לרפא פגם של חשיפה חד-צדדית לחומר באמצעות השלמת החומר בדיעבד, מבלי להבין את הפגיעה המהותית בזכות הטיעון ובמראית פני הצדק.',
    '["פסילת מומחה", "חשיפה חד-צדדית", "פגם היורד לשורש העניין", "עיוות דין", "זכות הטיעון", "מראית פני הצדק", "תום לב"]'::jsonb,
    '**וריאציה 1 — חשיפה חד-צדדית:** האם חשיפה של מומחה לחומר מצד אחד בלבד פוסלת את חוות דעתו? ← כן, מדובר בפגם מהותי היורד לשורש ההליך, גם אם המומחה פעל בתום לב (רע"א 1834/18 שירותי בריאות כללית). **וריאציה 2 — פגיעה בזכות הטיעון:** מדוע חשיפה חד-צדדית פוסלת? ← היא פוגעת בזכות הטיעון של הצד השני, כמוה כמתן פסק דין בהיעדר כתב טענות (רע"א 7921/20 פלוני). **וריאציה 3 — ריפוי הפגם:** האם ניתן לרפא פגם כזה? ← ככלל לא, קיים חשש שעיון מאוחר בחומר לא ירפא את הפגם המהותי, שכן המומחה כבר גיבש דעה (רע"א 8152/18 פלוני).',
    'מומחה נחשף לחומר חד-צדדי ← פגם מהותי ← פגיעה בזכות הטיעון ← פסילה, גם בתום לב.',
    '["רע\"א 1834/18 שירותי בריאות כללית נ'' פלונית (03.05.2018)", "רע\"א 7921/20 פלוני נ'' מרכז החינוך העצמאי לת\"ת ובתי ספר (14.12.2020)", "רע\"א 7098/10 אוהד טביבזדה נ'' שירותי בריאות כללית (31.01.2011)", "רע\"א 8152/18 פלוני נ'' כלל חברה לביטוח בע\"מ (10.02.2019)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'חזקת התקינות המקצועית של מומחה', 2, 'מהי ''חזקת התקינות המקצועית'' של מומחה שמונה מטעם בית המשפט, ובאילו נסיבות היא תיסתר?',
    'שאלה זו עוסקת בחזקת התקינות המקצועית של מומחה שמונה מטעם בית המשפט, שהיא אבן יסוד במעמדו של המומחה כ''זרועו הארוכה'' של בית המשפט. היא בוחנת את הסטנדרט הגבוה הנדרש כדי לסתור חזקה זו, ומדגישה כי לא די בקשרים כלליים או חששות רחוקים כדי לפסול מומחה.',
    'מומחה מטעם בית המשפט נהנה מחזקת תקינות מקצועית, לפיה הוא פועל במקצועיות ובתום לב. חזקה זו ניתנת לסתירה, אך לא בנקל. כדי לסתור אותה, יש להוכיח אינדיקציות ברורות לניגוד עניינים, או לכל הפחות זיקה מהותית על פני פרק זמן משמעותי בין המומחה לבין הצד שכנגד. לא די בקיומם של קשרים כלשהם בין המומחה לבין אחד הצדדים בתיק על מנת שהמומחה ייפסל אוטומטית. זאת, שכן במדינה קטנה כישראל, קשרים מקצועיים בין מומחים הם כמעט בלתי נמנעים. פסילת חוות דעת מומחה היא סנקציה חריפה שהשימוש בה ייעשה רק במקרים חריגים, כאשר הפגם יורד לשורשו של עניין ועלול לגרום לעיוות דין. רע"א 7352/21 פלוני (קטין) נ'' קרנית, קרן לפיצוי נפגעי תאונות דרכים (17.11.2021)רע"א 4220/22 פלוני נ'' ד"ר יפעת וינר (28.06.2022)רע"א 846/24 רובינשטיין ב.ש. סחר ונדל"ן בע"מ נ'' נציגות הבית המשותף משד'' ניצה 20 נתניה (08.04.2024)רע"א 7685/23 פלונית נ'' כלל חברה לביטוח בע"מ (20.11.2023)',
    'הטעות הנפוצה היא לחשוב שכל קשר מקצועי או היכרות בין מומחה לצדדים או לבאי כוחם, גם אם רופף או חד-פעמי, מספיק כדי לסתור את חזקת התקינות המקצועית ולפסול את המומחה.',
    '["חזקת תקינות מקצועית", "מומחה מטעם בית המשפט", "ניגוד עניינים", "זיקה מהותית", "פסילת מומחה", "אינדיקציות ברורות", "סעד קיצוני"]'::jsonb,
    '**וריאציה 1 — מהי החזקה?** מהי חזקת התקינות המקצועית של מומחה? ← הנחה שהמומחה פועל במקצועיות ובתום לב (רע"א 846/24 רובינשטיין). **וריאציה 2 — מתי תיסתר?** באילו נסיבות תיסתר החזקה? ← בהוכחת אינדיקציות ברורות לניגוד עניינים או זיקה מהותית על פני פרק זמן משמעותי (רע"א 7352/21 פלוני). **וריאציה 3 — קשרים מקצועיים:** האם קשרים מקצועיים כלשהם מספיקים לסתירת החזקה? ← לא, לא בכל מקרה שבו קיימים קשרים כלשהם בין המומחה לצדדים ייפסל המומחה אוטומטית (רע"א 7685/23 פלונית).',
    'חזקת תקינות מומחה ← פועל במקצועיות ובתום לב ← נסתרה רק באינדיקציות ברורות לניגוד עניינים / זיקה מהותית.',
    '["רע\"א 7352/21 פלוני (קטין) נ'' קרנית, קרן לפיצוי נפגעי תאונות דרכים (17.11.2021)", "רע\"א 4220/22 פלוני נ'' ד\"ר יפעת וינר (28.06.2022)", "רע\"א 846/24 רובינשטיין ב.ש. סחר ונדל\"ן בע\"מ נ'' נציגות הבית המשותף משד'' ניצה 20 נתניה (08.04.2024)", "רע\"א 7685/23 פלונית נ'' כלל חברה לביטוח בע\"מ (20.11.2023)", "רע\"א 6142/16 פלוני נ'' מרכז רפואי ע\"ש שיבא - תל השומר (28.09.2016)", "רע\"א 7590/22 הראל חברה לביטוח בע\"מ נ'' טל הל יסכה בע\"מ (09.03.2023)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'פסילת מומחה עקב חריגה מסמכות', 3, 'מומחה שמונה מטעם בית המשפט בתביעת נזיקין קבע בחוות דעתו מסקנות משפטיות לגבי שאלת האחריות, אף שמינויו הוגבל לשאלות רפואיות בלבד. מה הדין לגבי חוות דעת זו?',
    'שאלה זו עוסקת בחריגה מסמכות של מומחה שמונה מטעם בית המשפט, ובאופן שבו בית המשפט מתמודד עם פגם זה. היא מדגישה כי פסילת חוות דעת היא סעד קיצוני, וכי במקרים של חריגה מסמכות, בית המשפט יעדיף לעיתים קרובות אמצעים מתונים יותר, כגון התעלמות מהחלקים החורגים, אלא אם כן הפגם יורד לשורש העניין וגורם לעיוות דין קשה.',
    'מומחה שמונה מטעם בית המשפט משמש כזרועו הארוכה של בית המשפט, ותפקידו לסייע לבית המשפט בשאלות שבתחום מומחיותו. סמכותו של המומחה מוגבלת לשאלות מקצועיות, ואינה כוללת הכרעה בשאלות משפטיות. כאשר מומחה חורג מסמכותו וקובע קביעות משפטיות, אין הדבר מוביל בהכרח לפסילת חוות הדעת כולה. הפסיקה קובעת כי פסילת חוות דעת מומחה היא סעד קיצוני שייעשה רק במקרים נדירים, וכשמתקיימים טעמים מיוחדים המצדיקים זאת, למשל כאשר נפל פגם היורד לשורשו של עניין ושיש בו כדי לגרום עיוות דין קשה. היבט משמעותי בפסיקה זו הוא הנחת המוצא לפיה, מקום בו ניתן לרפא את הפגם באמצעים מתונים יותר יש להעדיף אפשרות זו על פני פסילת חוות הדעת כולה. במקרים של חריגה מסמכות, בית המשפט יכול להתעלם מהחלקים החורגים, או להפחית ממשקל חוות הדעת, מבלי לפסול אותה כולה. רע"א 6258/20 בנק לאומי לישראל בע"מ נ'' ששון יעקב (01.10.2020)רע"א 6585/19 נ.ש.ד.ד 2000 בע"מ נ'' הועדה המקומית לתכנון ובניה חוף הכרמל (25.11.2019)רע"א 1138/12 אי.די.איי חברה לביטוח בע"מ נ'' פלוני (09.04.2012)רע"א 53413-04-25 דרך נכסי החצב בע"מ נ'' "נוף הארץ" ייזום ובנין בע"מ (14.05.2025)',
    'הטעות הנפוצה היא לחשוב שכל חריגה מסמכות של מומחה מובילה אוטומטית לפסילת חוות דעתו במלואה, מבלי לבחון את מהות החריגה ואת האפשרות לנקוט באמצעים מתונים יותר.',
    '["חריגה מסמכות", "פסילת מומחה", "פגם היורד לשורש העניין", "עיוות דין", "סעד קיצוני", "שאלות משפטיות", "שאלות מקצועיות"]'::jsonb,
    '**וריאציה 1 — חריגה מסמכות:** האם חריגה מסמכות של מומחה מובילה לפסילה אוטומטית? ← לא בהכרח, יש לבחון אם הפגם יורד לשורש העניין וגורם לעיוות דין קשה (רע"א 6258/20 בנק לאומי). **וריאציה 2 — אמצעים מתונים:** מה יעדיף בית המשפט במקרה של חריגה מסמכות? ← להעדיף אמצעים מתונים יותר, כגון התעלמות מהחלקים החורגים, על פני פסילה מלאה (רע"א 53413-04-25 דרך נכסי החצב). **וריאציה 3 — קביעות משפטיות:** האם מומחה רשאי לקבוע קביעות משפטיות? ← לא, תפקידו של המומחה הוא לסייע בשאלות מקצועיות, לא להכריע בשאלות משפטיות (רע"א 6585/19 נ.ש.ד.ד).',
    'מומחה חרג מסמכות ← לא בהכרח פסילה מלאה ← בחינת מהות הפגם ← העדפת אמצעים מתונים.',
    '["רע\"א 6258/20 בנק לאומי לישראל בע\"מ נ'' ששון יעקב (01.10.2020)", "רע\"א 4955479 נ.ש.ד.ד 2000 בע\"מ נ'' הועדה המקומית לתכנון ובניה חוף הכרמל (25.11.2019)", "רע\"א 1138/12 אי.די.איי חברה לביטוח בע\"מ נ'' פלוני (09.04.2012)", "רע\"א 53413-04-25 דרך נכסי החצב בע\"מ נ'' \"נוף הארץ\" ייזום ובנין בע\"מ (14.05.2025)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'מינוי מומחה נוסף מול פסילת מומחה', 4, 'באיזה מקרה יעדיף בית המשפט למנות מומחה נוסף על פני פסילת חוות דעתו של המומחה המקורי שמונה מטעמו?',
    'שאלה זו עוסקת בהיררכיית הסעדים העומדים בפני בית המשפט כאשר מתגלים פגמים בחוות דעת מומחה. היא מבחינה בין הסעד הקיצוני של פסילת מומחה לבין הסעד המתון יותר של מינוי מומחה נוסף, ומדגישה את השיקולים המנחים את בית המשפט בבחירה ביניהם, תוך התחשבות ביעילות ההליך ובחשש מהתנהלות אסטרטגית של צדדים.',
    'כאשר מתגלים פגמים בחוות דעת מומחה, עומדות בפני בית המשפט מספר דרכי פעולה. פסילת חוות דעת מומחה היא סעד קיצוני ביותר, השמור למקרים חריגים בהם הפגם יורד לשורשו של עניין ועלול לגרום לעיוות דין קשה. מינוי מומחה נוסף נחשב לחלופה מתונה יותר, והפסיקה קבעה שיש להעדיף ככל האפשר מינוי של מומחה נוסף על פני פסילה של המומחה. עם זאת, גם מינוי מומחה נוסף אינו דבר של מה בכך והוא שמור למקרים חריגים בלבד, שכן הוא כרוך בעלויות לצדדים ובהתארכות וסרבול ההליכים. בית המשפט ינקוט בדרך זו רק במקרים בהם חוות הדעת הקיימת לא הביאה את הבירור הנדרש לידי מיצוי, או כאשר יש ספק בלב השופט לגבי יכולתו להכריע במחלוקת המקצועית על סמך החומר הקיים. רע"א 19060-03-25 מ. א. ע דקל בנגב בע"מ נ'' חסן מחאמיד (13.05.2025)רע"א 846/24 רובינשטיין ב.ש. סחר ונדל"ן בע"מ נ'' נציגות הבית המשותף משד'' ניצה 20 נתניה (08.04.2024)רע"א 7685/23 פלונית נ'' כלל חברה לביטוח בע"מ (20.11.2023)רע"א 19060-03-25 מ. א. ע דקל בנגב בע"מ נ'' חסן מחאמיד (13.05.2025)',
    'הטעות הנפוצה היא לחשוב שמינוי מומחה נוסף הוא סעד שגרתי לכל פגם בחוות דעת, או שפסילה היא תמיד האפשרות העדיפה, מבלי להבין את האיזון בין יעילות, עלויות וצורך בבירור האמת.',
    '["מינוי מומחה נוסף", "פסילת מומחה", "סעד קיצוני", "בירור מיצוי", "ספק בלב השופט", "עלויות והתארכות הליכים", "התנהלות אסטרטגית"]'::jsonb,
    '**וריאציה 1 — חלופות לפגם בחוות דעת:** מהן החלופות העומדות בפני בית המשפט כשמתגלה פגם בחוות דעת מומחה? ← הכרעה על בסיס החוות דעת בצירוף ראיות נוספות, מינוי מומחה נוסף, או פסילת חוות הדעת (רע"א 19060-03-25 מ. א. ע דקל). **וריאציה 2 — מתי מומחה נוסף?** מתי יעדיף בית המשפט למנות מומחה נוסף? ← כאשר חוות הדעת הקיימת לא הביאה את הבירור הנדרש לידי מיצוי, או כשיש ספק בלב השופט (רע"א 19060-03-25 מ. א. ע דקל). **וריאציה 3 — שיקולים נגד מומחה נוסף:** מהם השיקולים נגד מינוי מומחה נוסף? ← עלויות לצדדים, התארכות וסרבול ההליכים, וחשש מהתנהלות אסטרטגית של צד שאינו שבע רצון מתוכן חוות הדעת (רע"א 7685/23 פלונית).',
    'מינוי מומחה נוסף ← חלופה מתונה לפסילה ← כשאין מיצוי בירור / ספק לשופט ← שיקולי יעילות ועלות.',
    '["רע\"א 19060-03-25 מ. א. ע דקל בנגב בע\"מ נ'' חסן מחאמיד (13.05.2025)", "רע\"א 846/24 רובינשטיין ב.ש. סחר ונדל\"ן בע\"מ נ'' נציגות הבית המשותף משד'' ניצה 20 נתניה (08.04.2024)", "רע\"א 7685/23 פלונית נ'' כלל חברה לביטוח בע\"מ (20.11.2023)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'חוות הדעת תיפסל רק אם יוכח שהמומחה פעל בחוסר תום לב או שהפגם גרם לעיוות דין בפועל.', false, 'תשובה זו שגויה. חשיפה חד-צדדית לחומר מהווה פגם מהותי היורד לשורש ההליך, ועלולה להצדיק פסילה גם ללא הוכחת חוסר תום לב או עיוות דין בפועל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'חוות הדעת תיפסל, שכן מדובר בפגם מהותי היורד לשורש ההליך, הפוגע בזכות הטיעון ובמראית פני הצדק, גם אם המומחה פעל בתום לב.', true, 'זו התשובה הנכונה. הפסיקה קובעת כי חשיפה חד-צדדית לחומר מהווה פגם מהותי היורד לשורש ההליך, הפוגע בזכות הטיעון ובמראית פני הצדק, ומצדיק פסילה גם אם המומחה פעל בתום לב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'בית המשפט יורה על השלמת החומר החסר למומחה, וחוות הדעת תישאר בתוקף לאחר השלמה זו.', false, 'תשובה זו שגויה. אף שניתן לנסות לרפא פגמים, במקרה של חשיפה חד-צדדית, קיים חשש שהמומחה כבר גיבש דעה, ועיון מאוחר בחומר נוסף לא ירפא את הפגם המהותי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'חוות הדעת לא תיפסל, שכן מומחה מטעם בית המשפט נהנה מחזקת תקינות מקצועית, וניתן לסמוך עליו שידע לסנן את המידע.', false, 'תשובה זו שגויה. חזקת התקינות המקצועית אינה חלה במקרים של פגיעה מהותית בזכות הטיעון ובמראית פני הצדק כתוצאה מחשיפה חד-צדדית לחומר.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'חזקה זו משמעותה שהמומחה תמיד פועל באובייקטיביות מוחלטת, והיא אינה ניתנת לסתירה.', false, 'תשובה זו שגויה. חזקת התקינות ניתנת לסתירה, והיא אינה מבטיחה אובייקטיביות מוחלטת בכל מצב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'חזקה זו קובעת כי המומחה פועל במקצועיות ובתום לב, והיא תיסתר רק בהוכחת אינדיקציות ברורות לניגוד עניינים או זיקה מהותית על פני פרק זמן משמעותי.', true, 'זו התשובה הנכונה. הפסיקה קובעת כי מומחה מטעם בית המשפט נהנה מחזקת תקינות מקצועית, הניתנת לסתירה רק בהוכחת אינדיקציות ברורות לניגוד עניינים או זיקה מהותית על פני פרק זמן משמעותי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'חזקה זו חלה רק על מומחים שמונו בהסכמת הצדדים, ואינה חלה על מומחים שמונו ביוזמת בית המשפט.', false, 'תשובה זו שגויה. חזקת התקינות המקצועית חלה על כל מומחה שמונה מטעם בית המשפט, ללא קשר ליוזמת המינוי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'החזקה תיסתר בכל מקרה בו מתגלים קשרים כלשהם בין המומחה לבין אחד הצדדים או בא כוחו.', false, 'תשובה זו שגויה. לא כל קשר כלשהו יסתור את החזקה, אלא נדרשת זיקה מהותית או אינדיקציות ברורות לניגוד עניינים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'חוות הדעת תיפסל במלואה, שכן המומחה חרג מסמכותו באופן מהותי.', false, 'תשובה זו שגויה. לא תמיד חריגה מסמכות תוביל לפסילה מלאה. לעיתים ניתן להסתפק במחיקת החלקים החורגים או בהתעלמות מהם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בית המשפט יתעלם מהקביעות המשפטיות בחוות הדעת, אך ישאיר את יתר חלקי חוות הדעת בתוקף, אלא אם כן החריגה יורדת לשורש העניין וגורמת לעיוות דין קשה.', true, 'זו התשובה הנכונה. הפסיקה קובעת כי חריגה מסמכות המומחה אינה מובילה בהכרח לפסילה מלאה, אלא יש לבחון אם הפגם יורד לשורש העניין וגורם לעיוות דין קשה. לעיתים ניתן להסתפק בהתעלמות מהחלקים החורגים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'חוות הדעת לא תיפסל, שכן בית המשפט רשאי לסטות ממסקנות המומחה בכל מקרה.', false, 'תשובה זו שגויה. אף שבית המשפט רשאי לסטות מחוות דעת מומחה, חריגה מסמכות עלולה להוות פגם מהותי המצדיק פסילה, ולא רק סטייה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בית המשפט יורה על מינוי מומחה נוסף, שכן המומחה הראשון אינו אובייקטיבי.', false, 'תשובה זו שגויה. חריגה מסמכות אינה בהכרח מעידה על חוסר אובייקטיביות, ומינוי מומחה נוסף הוא סעד חלופי לפסילה, אך לא תמיד הפתרון המתאים לחריגה מסמכות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בית המשפט יעדיף מינוי מומחה נוסף בכל מקרה שבו מתגלה פגם כלשהו בחוות הדעת המקורית.', false, 'תשובה זו שגויה. מינוי מומחה נוסף, אף שהוא מתון יותר מפסילה, אינו סעד אוטומטי לכל פגם, אלא שמור למקרים חריגים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט יעדיף מינוי מומחה נוסף כאשר חוות הדעת הקיימת לא הביאה את הבירור הנדרש לידי מיצוי, או כאשר יש ספק בלב השופט לגבי יכולתו להכריע במחלוקת המקצועית על סמך החומר הקיים.', true, 'זו התשובה הנכונה. הפסיקה קובעת כי מינוי מומחה נוסף הוא חלופה מתונה יותר מפסילה, והוא ייעשה במקרים בהם חוות הדעת הקיימת אינה מספקת לבירור המחלוקת, או כאשר יש ספק בלב השופט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בית המשפט ימנה מומחה נוסף רק אם הצדדים מסכימים לכך, שכן מינוי מומחה נוסף כרוך בעלויות ובהתארכות ההליכים.', false, 'תשובה זו שגויה. אף ששיקולי עלות ויעילות חשובים, בית המשפט רשאי למנות מומחה נוסף גם ללא הסכמת הצדדים, אם הוא סבור שהדבר נחוץ לבירור האמת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט תמיד יעדיף פסילה של המומחה המקורי על פני מינוי מומחה נוסף, כדי למנוע סרבול והתארכות ההליכים.', false, 'תשובה זו שגויה. פסילה היא סעד קיצוני, ומינוי מומחה נוסף נחשב לחלופה מתונה יותר, המועדפת במקרים רבים על פני פסילה.', 4);

END $$;

