-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q28';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q28 skipped: external_id % already exists', '2024-W-Q28';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'jurisdiction_subject';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'jurisdiction_subject';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q28', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'חן הגישה תביעה אזרחית נגד יעקב, חברה הטוב, לפי פרק ו''1 לפקודת השותפויות, בסך 4 מיליון ש"ח בגין הפרה שהסמכות המקומית לגביה מצויה בבאר שבע. היכן תידון התביעה?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 28}'::jsonb,
    'שאלה זו עוסקת בסמכות העניינית והמקומית של המחלקה הכלכלית בבית המשפט המחוזי. היא בוחנת את הגדרת "עניין כלכלי" לפי חוק בתי המשפט, ואת הכללים הקובעים היכן יידון עניין כזה, תוך התייחסות למקרים בהם קיימת מחלקה כלכלית (תל אביב וחיפה) ולמקרים בהם היא אינה קיימת (יתר המחוזות).',
    'הסמכות העניינית לדון ב"עניין כלכלי" נתונה לבית המשפט המחוזי, כפי שקבוע בסעיף 40(6) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984. פרק ו''1 לפקודת השותפויות [נוסח חדש], תשל"ה-1975, מוגדר במפורש כ"עניין כלכלי" לפי סעיף 42ב(א)(1)(ז) לחוק בתי המשפט. המחלקות הכלכליות הוקמו בבתי המשפט המחוזיים בתל אביב ובחיפה בלבד. סעיף 42ה(א) לחוק בתי המשפט קובע כי "עניין כלכלי שבסמכות בית משפט מחוזי יידון לפני שופטי בית המשפט המחוזי שלו נתונה הסמכות המקומית לדון בו". רק אם העניין הכלכלי בסמכות בית המשפט המחוזי בתל אביב או בחיפה, הוא יידון לפני שופטי המחלקה הכלכלית באחד מבתי המשפט האמורים. במקרה הנדון, הסמכות המקומית היא בבאר שבע, שם אין מחלקה כלכלית. לכן, התביעה תידון בבית המשפט המחוזי בבאר שבע. סכום התביעה (4 מיליון ש"ח) גם הוא מעל סמכות בית משפט השלום (2.5 מיליון ש"ח), ולכן בכל מקרה הסמכות העניינית היא לבית המשפט המחוזי. סעיף 42ב(א)(1)(ז) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984סעיף 40(6) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984סעיף 42ה(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984ת"א (מחוזי ת"א) 31675-12-24 אתי יחזקאל נ'' בורסת היהלומים הישראלית בעמ (22.05.2025)יעקב שקד סדר הדין האזרחי (2026) | 2.2.8.4 המחלקה הכלכלית בבית המשפט המחוזי',
    'הטעות הנפוצה היא לבלבל בין סמכות עניינית לסמכות מקומית, ולחשוב שכל "עניין כלכלי" חייב להידון במחלקה הכלכלית בתל אביב או בחיפה, גם אם הסמכות המקומית היא במחוז אחר.',
    '["סמכות עניינית", "סמכות מקומית", "עניין כלכלי", "פקודת השותפויות", "חוק בתי המשפט", "מחלקה כלכלית", "בית המשפט המחוזי"]'::jsonb,
    '**וריאציה 1 — הגדרת עניין כלכלי:** האם תביעה לפי פרק ו''1 לפקודת השותפויות היא עניין כלכלי? ← כן, לפי סעיף 42ב(א)(1)(ז) לחוק בתי המשפט (סעיף 42ב(א)(1)(ז) לחוק בתי המשפט). **וריאציה 2 — סמכות עניינית:** היכן נדון עניין כלכלי? ← בבית המשפט המחוזי (סעיף 40(6) לחוק בתי המשפט). **וריאציה 3 — סמכות מקומית למחלקה כלכלית:** מתי עניין כלכלי נדון במחלקה הכלכלית בתל אביב/חיפה? ← רק אם הסמכות המקומית היא בתל אביב או חיפה, או במקרים ספציפיים שנקבעו בחוק. אחרת, בבית המשפט המחוזי הרגיל במחוז הסמכות המקומית (סעיף 42ה(א) לחוק בתי המשפט).',
    'תביעה לפי פרק ו''1 לפקודת השותפויות ← עניין כלכלי ← סמכות מחוזי ← מקומית באר שבע ← תידון במחוזי באר שבע.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 40(6)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 42ב(א)(1)(ז)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 42ה(א)", "ת\"א (מחוזי תל אביב-יפו) 20019-09-25 צביקי בלידן ו-33 נוספים נ'' דייברגון נדל\"ן בע\"מ (12.11.2025)", "ת\"א (מחוזי ת\"א) 31675-12-24 אתי יחזקאל נ'' בורסת היהלומים הישראלית בעמ (22.05.2025)", "יעקב שקד, סדר הדין האזרחי (2026), פרק ב סמכויות השיפוט"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בבית המשפט המחוזי בבאר שבע.', true, 'זו התשובה הנכונה. התביעה היא "עניין כלכלי" לפי סעיף 42ב(א)(1)(ז) לחוק בתי המשפט. הסמכות העניינית לדון בעניין כלכלי נתונה לבית המשפט המחוזי. מאחר שהסמכות המקומית היא בבאר שבע, ואין שם מחלקה כלכלית, התביעה תידון בבית המשפט המחוזי בבאר שבע.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בבית המשפט המחוזי בתל אביב.', false, 'תשובה זו שגויה. אף שלבית המשפט המחוזי בתל אביב יש מחלקה כלכלית, הסמכות המקומית במקרה זה היא בבאר שבע, ולכן התביעה לא תידון בתל אביב אלא אם כן קיימת הוראה ספציפית אחרת.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בבית המשפט המחוזי בתל אביב או בבאר שבע.', false, 'תשובה זו שגויה. אין בחירה בין בתי משפט מחוזיים שונים כאשר הסמכות המקומית קבועה במקום אחד. הסמכות המקומית היא בבאר שבע, ולכן רק בית המשפט המחוזי בבאר שבע מוסמך לדון בה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'במחלקה הכלכלית בבית המשפט המחוזי בתל אביב או בחיפה.', false, 'תשובה זו שגויה. המחלקות הכלכליות קיימות רק בתל אביב ובחיפה. כאשר הסמכות המקומית היא במחוז אחר (כמו באר שבע), התביעה תידון בבית המשפט המחוזי הרגיל באותו מחוז, ולא במחלקה הכלכלית בתל אביב או בחיפה, אלא אם כן מדובר בעניין כלכלי ספציפי שנקבע שידון שם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'סמכות המחלקה הכלכלית בתביעה נגזרת', 1, 'חברה הגישה תביעה נגזרת כהגדרתה בחוק החברות, בסך 3 מיליון ש"ח, כאשר הסמכות המקומית לדון בה היא בירושלים. היכן תידון התביעה?',
    'שאלה זו בוחנת את הסמכות העניינית והמקומית בתביעה נגזרת, שהיא סוג מובהק של "עניין כלכלי". היא מדגישה את הכלל לפיו עניינים כלכליים נדונים בבית המשפט המחוזי, וכי המחלקות הכלכליות בתל אביב ובחיפה אינן בעלות סמכות ייחודית גורפת על פני כל בתי המשפט המחוזיים בארץ.',
    'תביעה נגזרת כהגדרתה בחוק החברות היא "עניין כלכלי" מובהק, כפי שקבוע בסעיף 42ב(א)(2) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984. עניינים כלכליים נתונים לסמכותו העניינית של בית המשפט המחוזי, ללא קשר לשווי התביעה, שכן המחוקק ראה לסטות ממבחן הסעד ולקבוע מבחנים אחרים לסיווג סמכותן העניינית של ערכאות שיפוט בעניינים אלו. המחלקות הכלכליות הוקמו בבתי המשפט המחוזיים בתל אביב ובחיפה בלבד. סעיף 42ה(א) לחוק בתי המשפט קובע כי "עניין כלכלי שבסמכות בית משפט מחוזי יידון לפני שופטי בית המשפט המחוזי שלו נתונה הסמכות המקומית לדון בו". רק אם העניין הכלכלי בסמכות בית המשפט המחוזי בתל אביב או בחיפה, הוא יידון לפני שופטי המחלקה הכלכלית באחד מבתי המשפט האמורים. במקרה זה, הסמכות המקומית היא בירושלים, ולכן התביעה תידון בבית המשפט המחוזי בירושלים. סעיף 42ב(א)(2) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984סעיף 42ה(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984רע"א 7257/20 משה עמר נ'' שי אריאלי (07.03.2021)יעקב שקד סדר הדין האזרחי (2026) | 2.2.8.4 המחלקה הכלכלית בבית המשפט המחוזית"א (מחוזי ת"א) 31675-12-24 אתי יחזקאל נ'' בורסת היהלומים הישראלית בעמ (22.05.2025)',
    'טעות נפוצה היא לחשוב שכל "עניין כלכלי" חייב להידון במחלקה הכלכלית בתל אביב או בחיפה, מבלי להבחין בין סמכות עניינית לסמכות מקומית, ובין הכלל לחריגים.',
    '["סמכות עניינית", "סמכות מקומית", "עניין כלכלי", "תביעה נגזרת", "חוק בתי המשפט", "מחלקה כלכלית", "בית משפט מחוזי"]'::jsonb,
    '**וריאציה 1 — תביעה נגזרת:** האם תביעה נגזרת היא עניין כלכלי? ← כן, לפי סעיף 42ב(א)(2) לחוק בתי המשפט (סעיף 42ב(א)(2) לחוק בתי המשפט). **וריאציה 2 — סמכות עניינית כלכלית:** היכן נדון עניין כלכלי? ← בבית המשפט המחוזי, ללא קשר לשווי התביעה (רע"א 7257/20 עמר). **וריאציה 3 — סמכות מקומית למחלקה כלכלית:** מתי עניין כלכלי נדון במחלקה הכלכלית בתל אביב/חיפה? ← רק אם הסמכות המקומית היא בתל אביב או חיפה, או במקרים ספציפיים שנקבעו בחוק (סעיף 42ה(א) לחוק בתי המשפט).',
    'תביעה נגזרת ← עניין כלכלי ← סמכות מחוזי ← מקומית ירושלים ← תידון במחוזי ירושלים.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 42ב(א)(2)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 42ה(א)", "רע\"א 7257/20 משה עמר נ'' שי אריאלי (07.03.2021)", "יעקב שקד, סדר הדין האזרחי (2026), פרק ב סמכויות השיפוט", "ת\"א (מחוזי ת\"א) 31675-12-24 אתי יחזקאל נ'' בורסת היהלומים הישראלית בעמ (22.05.2025)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'מבחני קביעת סמכות עניינית כללית', 2, 'ראובן הגיש תביעה כספית בסך 1.5 מיליון ש"ח נגד שמעון בגין הפרת חוזה. היכן תידון התביעה?',
    'שאלה זו מתמקדת במבחן הסעד ככלי לקביעת הסמכות העניינית בתביעות אזרחיות שאינן "עניין כלכלי". היא מדגישה את חלוקת הסמכויות בין בית משפט השלום לבית המשפט המחוזי על בסיס שווי התביעה, ואת העובדה שבית המשפט המחוזי הוא בעל סמכות שיורית.',
    'ככלל, קביעת הסמכות העניינית בתחום האזרחי מוכרעת לפי מבחן הסעד, אשר לפיו יש לקבוע את זהות הערכאה המוסמכת בהתבסס על הסעדים המבוקשים בכתב התביעה. בית משפט השלום מוסמך לברר תביעה אזרחית (שאינה נוגעת למקרקעין) שסכומה או שווי נושאה אינו עולה על 2.5 מיליון ש"ח. לבית המשפט המחוזי נתונה סמכות שיורית לדון בכל עניין אזרחי שאינו נתון לסמכות בית משפט השלום. במקרה זה, מדובר בתביעה כספית בסך 1.5 מיליון ש"ח בגין הפרת חוזה, שאינה נחשבת ל"עניין כלכלי" מיוחד. לכן, בהתאם למבחן הסעד, הסמכות העניינית נתונה לבית משפט השלום. סעיף 51(א)(2) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984סעיף 40(1) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984רע"א 7257/20 משה עמר נ'' שי אריאלי (07.03.2021)יעקב שקד פינוי מקרקעין – הליכים והלכות (2024) | 13.1 סמכות עניינית – כללייששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025) | (א) ערכאות שיפוטיות ייחודיות',
    'הטעות הנפוצה היא לבלבל בין מבחן הסעד למבחן מהות הסכסוך, או לחשוב שכל תביעה בסכום גבוה יחסית (אך מתחת לתקרת המחוזי) שייכת אוטומטית לבית המשפט המחוזי.',
    '["סמכות עניינית", "מבחן הסעד", "בית משפט השלום", "בית המשפט המחוזי", "סמכות שיורית", "תביעה כספית", "הפרת חוזה"]'::jsonb,
    '**וריאציה 1 — מבחן הסעד:** מהו המבחן העיקרי לקביעת סמכות עניינית בתביעה אזרחית רגילה? ← מבחן הסעד, כלומר שווי התביעה (רע"א 7257/20 עמר). **וריאציה 2 — סמכות בית משפט השלום:** מהי סמכותו של בית משפט השלום בתביעות כספיות? ← עד 2.5 מיליון ש"ח (סעיף 51(א)(2) לחוק בתי המשפט). **וריאציה 3 — סמכות שיורית:** מהי סמכותו של בית המשפט המחוזי? ← סמכות שיורית, כל עניין אזרחי שאינו בסמכות בית משפט השלום (סעיף 40(1) לחוק בתי המשפט).',
    'סמכות עניינית ← מבחן הסעד ← עד 2.5 מיליון ש"ח שלום ← מעל מחוזי.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 40(1)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 51(א)(2)", "רע\"א 7257/20 משה עמר נ'' שי אריאלי (07.03.2021)", "יעקב שקד, פינוי מקרקעין – הליכים והלכות (2024), פרק שלושה־עשר: סמכות עניינית וסדרי דין בתביעות פינוי מקרקעין", "יששכר רוזן-צבי, הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025), פרק טו הסמכות העניינית"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'עניין כלכלי שאינו משמעותי', 3, 'חברה הגישה תביעה נגד נושא משרה בה, הכוללת עילות חוזיות ונזיקיות בסך 1 מיליון ש"ח, וכן טענה נלווית להפרת חובות לפי חוק החברות, שאינה מהווה את עיקר התביעה. הסמכות המקומית היא בחיפה. היכן תידון התביעה?',
    'שאלה זו עוסקת בחריג לכלל הסמכות העניינית של המחלקה הכלכלית, הקבוע בסעיף 42ב(א)(6) לחוק בתי המשפט. היא בוחנת מצב שבו תביעה משלבת עניין כלכלי עם עניינים אזרחיים רגילים, אך חלקו של העניין הכלכלי אינו משמעותי, ומאפשרת לבית המשפט להעביר את התביעה כולה לערכאה המוסמכת לדון בעניין האזרחי, כדי למנוע פיצול דיון.',
    'סעיף 42ב(א)(6) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "עניין אזרחי שהוא בסמכות בית משפט שלום... הכרוך בעניין כלכלי כאמור בפסקאות (1) עד (5), ובלבד שנושאם אחד או שהם נובעים מאותן נסיבות ושחלקו של העניין הכלכלי הוא משמעותי; לא היה חלקו של העניין הכלכלי משמעותי, רשאי בית המשפט להעביר גם את העניין הכלכלי לבית המשפט המוסמך לדון בעניין האזרחי כדי שידון בהם יחדיו, אם לדעתו הנזק מפיצול הדיון עולה על התועלת מקיום הדיון בפניו". במקרה זה, התביעה העיקרית היא חוזית ונזיקית בסך 1 מיליון ש"ח, הנמצאת בסמכות בית משפט השלום. טענת הפרת חובות לפי חוק החברות היא עניין כלכלי, אך נאמר כי היא אינה מהווה את עיקר התביעה, כלומר חלקו של העניין הכלכלי אינו משמעותי. לכן, בית המשפט רשאי להעביר את התביעה כולה לבית משפט השלום בחיפה, כדי למנוע פיצול דיון. סעיף 42ב(א)(6) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984ת"א (מחוזי תל אביב-יפו) 20019-09-25 צביקי בלידן ו-33 נוספים נ'' דייברגון נדל"ן בע"מ (12.11.2025)ת"א (מחוזי תל אביב-יפו) 20019-09-25 צביקי בלידן ו-33 נוספים נ'' דייברגון נדל"ן בע"מ (12.11.2025)ת"א (מחוזי ת"א) 16100-09-24 אירית גורדון נ'' שמואל אייזנברג (13.11.2024)ת"א (מחוזי ת"א) 16100-09-24 אירית גורדון נ'' שמואל אייזנברג (13.11.2024)',
    'הטעות הנפוצה היא לחשוב שכל תביעה הכוללת ולו עילה כלכלית אחת חייבת להידון במחלקה הכלכלית, מבלי לבחון את משמעותיות החלק הכלכלי בתביעה הכוללת.',
    '["עניין כלכלי שאינו משמעותי", "סעיף 42ב(א)(6) לחוק בתי המשפט", "פיצול דיון", "סמכות עניינית", "העברת תביעה", "עילות חוזיות ונזיקיות", "חוק החברות"]'::jsonb,
    '**וריאציה 1 — עניין כלכלי לא משמעותי:** מה קורה כשיש עניין כלכלי ועניין אזרחי, אך הכלכלי אינו משמעותי? ← בית המשפט רשאי להעביר את העניין הכלכלי לערכאה המוסמכת לדון בעניין האזרחי (סעיף 42ב(א)(6) לחוק בתי המשפט). **וריאציה 2 — שיקולי העברה:** מהם השיקולים להעברה במקרה כזה? ← אם הנזק מפיצול הדיון עולה על התועלת מקיום הדיון בפני המחלקה הכלכלית (סעיף 42ב(א)(6) לחוק בתי המשפט). **וריאציה 3 — מהות התביעה:** כיצד נקבעת מהות התביעה? ← לפי העילות העיקריות ולא לפי עילות נלוות, גם אם הן כלכליות (ת"א 20019-09-25 בלידן).',
    'עניין כלכלי לא משמעותי ← העברה לערכאה אזרחית רגילה ← מניעת פיצול דיון.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 42ב(א)(6)", "ת\"א (מחוזי תל אביב-יפו) 20019-09-25 צביקי בלידן ו-33 נוספים נ'' דייברגון נדל\"ן בע\"מ (12.11.2025)", "ת\"א (מחוזי ת\"א) 16100-09-24 אירית גורדון נ'' שמואל אייזנברג (13.11.2024)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'סמכות מקומית ייחודית למחלקה הכלכלית', 4, 'תביעה אזרחית לפי פרק ג'' לחוק לקידום התחרות ולצמצום הריכוזיות, בסך 5 מיליון ש"ח, הוגשה כאשר הסמכות המקומית לדון בה היא בבאר שבע. היכן תידון התביעה?',
    'שאלה זו עוסקת בחריג לכלל הסמכות המקומית בעניינים כלכליים, הקבוע בסעיף 42ה(א)(1) לחוק בתי המשפט. היא מדגישה כי ישנם סוגים מסוימים של עניינים כלכליים שנקבעו במפורש בחוק כי יידונו במחלקות הכלכליות בתל אביב או בחיפה, ללא קשר לסמכות המקומית הרגילה.',
    'סעיף 42ב(א)(1)(ו) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי עניין אזרחי לפי פרק ג'' לחוק לקידום התחרות ולצמצום הריכוזיות, התשע"ד-2013, הוא "עניין כלכלי". סעיף 42ה(א)(1) לחוק בתי המשפט קובע חריג לכלל הסמכות המקומית הרגיל, ולפיו "עניין כלכלי כאמור בסעיף 42ב(א)(1)(ו) יידון לפני שופטי המחלקה הכלכלית בבית המשפט המחוזי בתל-אביב-יפו או בבית המשפט המחוזי בחיפה, אף אם הוא בסמכות בית משפט מחוזי אחר". משמעות הדבר היא שתביעה מסוג זה, גם אם הסמכות המקומית הרגילה שלה היא בבאר שבע, תידון במחלקה הכלכלית בתל אביב או בחיפה. סעיף 42ב(א)(1)(ו) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984סעיף 42ה(א)(1) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984ת"א (מחוזי ת"א) 31675-12-24 אתי יחזקאל נ'' בורסת היהלומים הישראלית בעמ (22.05.2025)יעקב שקד סדר הדין האזרחי (2026) | 2.2.8.4 המחלקה הכלכלית בבית המשפט המחוזי',
    'הטעות הנפוצה היא ליישם את הכלל הכללי של סמכות מקומית גם על חריגים מפורשים בחוק, מבלי לשים לב להוראות ספציפיות המקנות סמכות ייחודית למחלקות הכלכליות בתל אביב ובחיפה.',
    '["סמכות מקומית ייחודית", "עניין כלכלי", "חוק לקידום התחרות", "מחלקה כלכלית", "חוק בתי המשפט", "חריגים לסמכות מקומית", "בית המשפט המחוזי"]'::jsonb,
    '**וריאציה 1 — חריג לסמכות מקומית:** האם יש עניינים כלכליים שנדונים במחלקה הכלכלית בתל אביב/חיפה ללא קשר לסמכות המקומית? ← כן, עניינים לפי סעיף 42ב(א)(1)(ו) לחוק בתי המשפט (פרק ג'' לחוק לקידום התחרות) יידונו שם אף אם הם בסמכות מחוזי אחר (סעיף 42ה(א)(1) לחוק בתי המשפט). **וריאציה 2 — מטרת החריג:** מדוע נקבע חריג כזה? ← כדי לרכז עניינים מורכבים הדורשים מומחיות מיוחדת במחלקות הכלכליות הייעודיות (ת"א 20019-09-25 בלידן). **וריאציה 3 — סמכות מקומית כללית לעניין כלכלי:** מה הכלל לסמכות מקומית בעניין כלכלי שאינו חריג? ← יידון בבית המשפט המחוזי שלו נתונה הסמכות המקומית לדון בו (סעיף 42ה(א) לחוק בתי המשפט).',
    'עניין כלכלי (חוק תחרות) ← סמכות ייחודית למחלקה הכלכלית בת"א/חיפה ← ללא קשר למקומית.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 42ב(א)(1)(ו)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 42ה(א)(1)", "ת\"א (מחוזי ת\"א) 31675-12-24 אתי יחזקאל נ'' בורסת היהלומים הישראלית בעמ (22.05.2025)", "ת\"א (מחוזי תל אביב-יפו) 20019-09-25 צביקי בלידן ו-33 נוספים נ'' דייברגון נדל\"ן בע\"מ (12.11.2025)", "יעקב שקד, סדר הדין האזרחי (2026), פרק ב סמכויות השיפוט"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'בבית המשפט המחוזי בירושלים.', true, 'זו התשובה הנכונה. תביעה נגזרת היא "עניין כלכלי" לפי סעיף 42ב(א)(2) לחוק בתי המשפט. הסמכות העניינית לדון בעניין כלכלי נתונה לבית המשפט המחוזי. מאחר שהסמכות המקומית היא בירושלים, ואין שם מחלקה כלכלית, התביעה תידון בבית המשפט המחוזי בירושלים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'במחלקה הכלכלית בבית המשפט המחוזי בתל אביב.', false, 'תשובה זו שגויה. המחלקה הכלכלית בתל אביב מוסמכת לדון בעניינים כלכליים רק אם הסמכות המקומית היא בתל אביב או חיפה, או במקרים ספציפיים שנקבעו בחוק, שאינם חלים על תביעה נגזרת רגילה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'בבית משפט השלום בירושלים.', false, 'תשובה זו שגויה. תביעה נגזרת היא "עניין כלכלי" ואינה בסמכות בית משפט השלום, ללא קשר לסכום התביעה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'בבית המשפט המחוזי בתל אביב או בחיפה.', false, 'תשובה זו שגויה. הסמכות המקומית היא בירושלים, ולכן התביעה תידון בבית המשפט המחוזי בירושלים, ולא בתל אביב או בחיפה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'בבית משפט השלום.', true, 'זו התשובה הנכונה. תביעה כספית שאינה "עניין כלכלי" נבחנת לפי מבחן הסעד. סכום של 1.5 מיליון ש"ח נמצא בסמכותו העניינית של בית משפט השלום, המוסמך לדון בתביעות עד 2.5 מיליון ש"ח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'בבית המשפט המחוזי.', false, 'תשובה זו שגויה. בית המשפט המחוזי מוסמך לדון בתביעות אזרחיות שאינן בסמכות בית משפט השלום (סמכות שיורית), או בתביעות שסכומן עולה על 2.5 מיליון ש"ח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'במחלקה הכלכלית בבית המשפט המחוזי.', false, 'תשובה זו שגויה. תביעה בגין הפרת חוזה היא עילה אזרחית "רגילה" ואינה נחשבת ל"עניין כלכלי" כהגדרתו בחוק, ולכן אינה בסמכות המחלקה הכלכלית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'בבית הדין לעבודה.', false, 'תשובה זו שגויה. בית הדין לעבודה מוסמך לדון בענייני עבודה ויחסי עובד-מעביד, ולא בתביעות כספיות כלליות בגין הפרת חוזה שאינו קשור ליחסי עבודה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'במחלקה הכלכלית בבית המשפט המחוזי בחיפה, שכן יש בה עניין כלכלי.', false, 'תשובה זו שגויה. אף שיש עניין כלכלי, אם חלקו אינו משמעותי, בית המשפט רשאי להעביר את התביעה לבית המשפט המוסמך לדון בעניין האזרחי הרגיל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בבית משפט השלום בחיפה, שכן העניין הכלכלי אינו משמעותי וסכום התביעה בסמכות השלום.', true, 'זו התשובה הנכונה. סעיף 42ב(א)(6) לחוק בתי המשפט מאפשר לבית המשפט להעביר את העניין הכלכלי לבית המשפט המוסמך לדון בעניין האזרחי (בית משפט השלום במקרה זה), אם חלקו של העניין הכלכלי אינו משמעותי והנזק מפיצול הדיון עולה על התועלת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בבית המשפט המחוזי בחיפה, שכן תביעה נגד נושא משרה היא תמיד בסמכות המחוזי.', false, 'תשובה זו שגויה. תביעה נגד נושא משרה אינה תמיד בסמכות המחוזי. אם העילות העיקריות הן חוזיות ונזיקיות בסכום הנמוך מ-2.5 מיליון ש"ח, והעניין הכלכלי אינו משמעותי, הסמכות יכולה להיות לבית משפט השלום.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בבית המשפט המחוזי בתל אביב, שכן המחלקה הכלכלית שם היא המרכזית.', false, 'תשובה זו שגויה. הסמכות המקומית היא בחיפה, ולכן אין מקום להעביר את התביעה לתל אביב.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בבית המשפט המחוזי בבאר שבע.', false, 'תשובה זו שגויה. אף שהסמכות המקומית היא בבאר שבע, תביעות לפי פרק ג'' לחוק לקידום התחרות הן חריג שנקבע במפורש שידון במחלקה הכלכלית בתל אביב או בחיפה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'במחלקה הכלכלית בבית המשפט המחוזי בתל אביב.', true, 'זו התשובה הנכונה. תביעה לפי פרק ג'' לחוק לקידום התחרות היא "עניין כלכלי" לפי סעיף 42ב(א)(1)(ו) לחוק בתי המשפט, וסעיף 42ה(א)(1) קובע כי עניינים אלו יידונו לפני שופטי המחלקה הכלכלית בתל אביב או בחיפה, אף אם הם בסמכות בית משפט מחוזי אחר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בבית משפט השלום בבאר שבע.', false, 'תשובה זו שגויה. תביעה זו היא "עניין כלכלי" וסכומה עולה על סמכות בית משפט השלום, ולכן אינה בסמכותו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בבית המשפט המחוזי בתל אביב או בחיפה, לפי בחירת התובע.', false, 'תשובה זו שגויה. אין בחירה לתובע בין תל אביב לחיפה במקרה זה, אלא אם כן הסמכות המקומית המקורית הייתה באחד מהם. סעיף 42ה(א)(1) קובע שהיא תידון באחד מהם, אך לא נותן בחירה חופשית.', 4);

END $$;

