-- Q29 — 2024-W-Q29 — chapter=civil_proc subtopic=jurisdiction_subject
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q29';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q29 skipped: external_id % already exists', '2024-W-Q29';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'jurisdiction_subject';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'jurisdiction_subject';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q29', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'יסמין מעוניינת להגיש תביעה אזרחית בשל הפרת חוק זכויות מבצעים ומשדרים, התשמ"ד-1984, כששווי נושא התביעה הוא 50,000 ש"ח. למי נתונה סמכות הדיון בתובענה?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 29}'::jsonb,
    'שאלה זו עוסקת בסמכות העניינית לדון בתביעה אזרחית בגין הפרת חוק זכויות מבצעים ומשדרים, התשמ"ד-1984, כאשר שווי נושא התביעה נמוך. היא בוחנת את הכלל המרכזי לקביעת סמכות עניינית בתביעות אזרחיות (מבחן הסעד) ואת יישומו בתחום הקניין הרוחני, תוך התייחסות להלכה הפסוקה בעניין זה.',
    'הכלל המרכזי לקביעת סמכות עניינית בתביעות אזרחיות שאינן במקרקעין הוא "מבחן הסעד", אשר לפיו יש לקבוע את זהות הערכאה המוסמכת בהתבסס על הסעדים המבוקשים בכתב התביעה. בית משפט השלום מוסמך לדון בתביעות אזרחיות שסכומן או שווי נושאן אינו עולה על 2.5 מיליון ש"ח (סעיף 51(א)(2) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984). לבית המשפט המחוזי נתונה סמכות שיורית לדון בכל עניין אזרחי שאינו בסמכות בית משפט השלום (סעיף 40(1) לחוק בתי המשפט). חוק זכויות מבצעים ומשדרים, התשמ"ד-1984, הוא אחד החוקים המנויים בסעיף 40(4) לחוק בתי המשפט כ"תביעה בענייני קניין רוחני". בעבר הייתה מחלוקת האם תביעות קניין רוחני הכוללות סעדים לא כספיים (כמו צו מניעה) נתונות אוטומטית לסמכות המחוזי. אולם, בית המשפט העליון ב`רע"א 6500/19 גבריאל נ'' אשד` הבהיר כי גם בתביעות קניין רוחני, הסמכות העניינית נקבעת על פי שווי התביעה. אם שווי התביעה (כולל הערכה של סעדים לא כספיים) נמוך מ-2.5 מיליון ש"ח, הסמכות נתונה לבית משפט השלום. במקרה הנדון, שווי נושא התביעה הוא 50,000 ש"ח, סכום הנמוך מ-2.5 מיליון ש"ח, ולכן הסמכות נתונה לבית משפט השלום. רע"א 6500/19 ד"ר שרון גבריאל נ'' ורד אשד (07.05.2020)סעיף 51(א)(2) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984סעיף 40(1) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984ת"א (שלום ראשל"צ) 55692-01-23 מיכל לבנשטיין נ'' ידיעות אחרונות בע"מ (21.04.2023)נבו - המתמחה מערכת בתי המשפט (2026) | סמכותו העניינית של בית משפט השלום',
    'הטעות הנפוצה היא להניח שכל תביעה בתחום הקניין הרוחני, ללא קשר לשוויה, נתונה אוטומטית לסמכות בית המשפט המחוזי, מבלי ליישם את מבחן הסעד כפי שהובהר בפסיקה העדכנית.',
    '["סמכות עניינית", "מבחן הסעד", "חוק זכויות מבצעים ומשדרים", "קניין רוחני", "בית משפט השלום", "בית המשפט המחוזי", "שווי נושא התביעה", "הלכת גבריאל"]'::jsonb,
    '**וריאציה 1 — סמכות בתביעת קניין רוחני כספית:** תביעה על הפרת זכויות יוצרים בסך 100,000 ש"ח. היכן תידון? ← בבית משפט השלום, לפי מבחן הסעד (רע"א 6500/19 גבריאל נ'' אשד). **וריאציה 2 — סמכות בתביעת קניין רוחני לא כספית:** תביעה על הפרת סימן מסחר הכוללת צו מניעה בלבד, וששווי נושא התביעה אינו ניתן להערכה. היכן תידון? ← בבית המשפט המחוזי, מכוח סמכותו השיורית (רע"א 6500/19 גבריאל נ'' אשד). **וריאציה 3 — סמכות בתביעת קניין רוחני משולבת:** תביעה על הפרת פטנט הכוללת סעד כספי בסך 1.5 מיליון ש"ח וצו עשה ששווי נושאו מוערך ב-500,000 ש"ח. היכן תידון? ← בבית משפט השלום, שכן סך שווי הסעדים (2 מיליון ש"ח) נמוך מ-2.5 מיליון ש"ח (רע"א 6500/19 גבריאל נ'' אשד).',
    'קניין רוחני ← סמכות עניינית לפי שווי ← עד 2.5 מיליון ש"ח שלום ← מעל 2.5 מיליון ש"ח או לא ניתן להערכה מחוזי.',
    '["סעיף 40 לחוק בתי המשפט [נוסח משולב], תשמ\"ד-1984", "סעיף 51 לחוק בתי המשפט [נוסח משולב], תשמ\"ד-1984", "רע\"א 6500/19 ד\"ר שרון גבריאל נ'' ורד אשד (07.05.2020)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לבית המשפט לתביעות קטנות.', false, 'תשובה זו שגויה. תביעות קניין רוחני, גם אם שווין נמוך, אינן נדונות בדרך כלל בבית המשפט לתביעות קטנות, המיועד לסכסוכים פשוטים ובעלי אופי שונה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לבית משפט השלום.', true, 'זו התשובה הנכונה. על פי הלכת גבריאל, הסמכות העניינית בתביעות קניין רוחני נקבעת לפי שווי התביעה, וכאשר שווי התביעה נמוך מ-2.5 מיליון ש"ח, הסמכות נתונה לבית משפט השלום.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לבית המשפט המחוזי.', false, 'תשובה זו שגויה. בית המשפט המחוזי מוסמך לדון בתביעות קניין רוחני רק אם שווי התביעה עולה על 2.5 מיליון ש"ח, או שאינו ניתן להערכה, או במקרים בהם קיימת הוראת חוק ספציפית המקנה לו סמכות ייחודית.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לבית המשפט לעניינים כלכליים.', false, 'תשובה זו שגויה. תביעות קניין רוחני אינן נחשבות ל"עניין כלכלי" כהגדרתו בחוק בתי המשפט, ולכן אינן בסמכות המחלקה הכלכלית, אלא אם כן הן כרוכות בעניין כלכלי משמעותי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'סמכות עניינית בתביעת קניין רוחני עם סעד לא כספי', 1, 'חברה הגישה תביעה בגין הפרת זכויות יוצרים, ובה היא מבקשת צו מניעה קבוע ופיצויים בסך 100,000 ש"ח. שווי צו המניעה אינו ניתן להערכה כספית מדויקת, אך ברור כי הוא אינו עולה על 2.5 מיליון ש"ח. למי נתונה סמכות הדיון בתובענה?',
    'שאלה זו בוחנת את יישום הלכת גבריאל (רע"א 6500/19) לגבי סמכות עניינית בתביעות קניין רוחני הכוללות סעד שאינו כספי. היא מדגישה כי גם במקרים אלו, אם שווי הסעד הלא-כספי ניתן להערכה (אפילו באומדן) ואינו עולה על 2.5 מיליון ש"ח, הסמכות נתונה לבית משפט השלום.',
    'על פי הלכת בית המשפט העליון ב`רע"א 6500/19 גבריאל נ'' אשד`, הסמכות העניינית לדון בתביעות בענייני קניין רוחני הכוללות סעד שאינו כספי, אינה נתונה באופן בלעדי לבית המשפט המחוזי, אלא נקבעת על פי שווי התביעה, בהתאם לכללי הסמכות העניינית החלים ביחס לתביעות אזרחיות שאינן במקרקעין. ככל ששווי התביעה (כולל הערכה של הסעד הלא-כספי) נמוך מ-2.5 מיליון ש"ח, הסמכות לדון בה נתונה לבית משפט השלום. רק כאשר שווי התביעה גבוה מ-2.5 מיליון ש"ח, או אינו ניתן להערכה כלל, הסמכות נתונה לבית המשפט המחוזי. במקרה הנדון, הסעד הכספי הוא 100,000 ש"ח, ושווי צו המניעה, אף שאינו ניתן להערכה מדויקת, ברור כי אינו עולה על 2.5 מיליון ש"ח. לפיכך, הסמכות נתונה לבית משפט השלום. רע"א 6500/19 ד"ר שרון גבריאל נ'' ורד אשד (07.05.2020)רע"א 6500/19 ד"ר שרון גבריאל נ'' ורד אשד (07.05.2020)ת"א (שלום ת"א) 36443-11-19 ROLEX SA (חברה זרה) נ'' פולו פרסום וסחר בע"מ (01.12.2019)ת"א (שלום ת"א) 51932-06-18 איתן אבניאון נ'' ידיעות אינטרנט (21.01.2019)טוני גרינמן זכויות יוצרים (2023) | 12.2.1 סמכות עניינית',
    'הטעות הנפוצה היא לחשוב שכל סעד לא כספי בתביעת קניין רוחני, ובפרט צו מניעה, מוביל אוטומטית לסמכות בית המשפט המחוזי, מבלי לבחון את שווי נושא התביעה או את יכולת הערכתו.',
    '["סמכות עניינית", "קניין רוחני", "צו מניעה", "סעד כספי", "סעד שאינו כספי", "שווי נושא התביעה", "בית משפט השלום", "בית המשפט המחוזי", "הלכת גבריאל"]'::jsonb,
    '**וריאציה 1 — סעד לא כספי ניתן להערכה:** תביעה לקניין רוחני עם צו מניעה ששוויו מוערך ב-1 מיליון ש"ח. היכן תידון? ← בבית משפט השלום, שכן השווי הכולל נמוך מ-2.5 מיליון ש"ח (רע"א 6500/19 גבריאל נ'' אשד). **וריאציה 2 — סעד לא כספי לא ניתן להערכה:** תביעה לקניין רוחני עם צו מניעה ששוויו אינו ניתן להערכה כלל. היכן תידון? ← בבית המשפט המחוזי, מכוח סמכותו השיורית (רע"א 6500/19 גבריאל נ'' אשד). **וריאציה 3 — פיצול סעדים בקניין רוחני:** האם סעיף 40(4) לחוק בתי המשפט מבטל את הלכת פיצול הסעדים בקניין רוחני? ← כן, הוא מסמיך את בית המשפט המחוזי לדון במכלול הסעדים הנתבעים, אך רק אם חלקם בסמכות המחוזי מלכתחילה (רע"א 6500/19 גבריאל נ'' אשד).',
    'קניין רוחני + סעד לא כספי ← סמכות לפי שווי נושא ← אם ניתן להערכה ועד 2.5 מיליון ש"ח שלום ← אם לא ניתן להערכה או מעל 2.5 מיליון ש"ח מחוזי.',
    '["רע\"א 6500/19 ד\"ר שרון גבריאל נ'' ורד אשד (07.05.2020)", "ת\"א (שלום ת\"א) 36443-11-19 ROLEX SA (חברה זרה) נ'' פולו פרסום וסחר בע\"מ (01.12.2019)", "ת\"א (שלום ת\"א) 51932-06-18 איתן אבניאון נ'' ידיעות אינטרנט (21.01.2019)", "טוני גרינמן, זכויות יוצרים (2023), פרק 12 הליכים וסעדים אזרחיים בגין הפרת זכות יוצרים"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'מבחן הסעד ושווי נושא התביעה', 2, 'מהו הכלל המרכזי לקביעת סמכות עניינית בתביעות אזרחיות שאינן במקרקעין, וכיצד נקבע שווי נושא התביעה בסעדים שאינם כספיים?',
    'שאלה זו מתמקדת בעקרונות היסוד של קביעת סמכות עניינית בתביעות אזרחיות, ובפרט במבחן הסעד. היא מבהירה כיצד יש לאמוד את שווי נושא התביעה כאשר מדובר בסעדים שאינם כספיים, ומדגישה את חשיבות הערך הכלכלי של האינטרסים המוגנים.',
    'הכלל המרכזי לקביעת סמכות עניינית בתביעות אזרחיות שאינן במקרקעין הוא "מבחן הסעד". מבחן זה קובע כי הסמכות נקבעת על פי הסעדים המבוקשים בכתב התביעה. שווי התביעה לצורך קביעת הסמכות העניינית נגזר משווי הסעדים הנתבעים במסגרתה. השווי של הסעדים הכספיים הוא הסכום הכספי הנתבע בתובענה. השווי של הסעדים שאינם כספיים הוא הערך הכלכלי אותו ניתן לייחס לאינטרסים עליהם מבקש התובע להגן באמצעותם. חשוב לציין כי אם ניתן להעריך את שוויו של הסעד, ולו באופן גס, בדרך של אומדן, אזי שווי הסעד ניתן להערכה כספית. רק כאשר לא ניתן להעריך, ולו באופן גס, מהו הערך הכלכלי של האינטרס עליו מבקש התובע להגן באמצעות הסעד שאינו כספי, הסמכות העניינית לדון בתביעה נתונה לבית המשפט המחוזי. רע"א 6500/19 ד"ר שרון גבריאל נ'' ורד אשד (07.05.2020)רע"א 6500/19 ד"ר שרון גבריאל נ'' ורד אשד (07.05.2020)ת"א (שלום ת"א) 5428-08-23 פרויקט אורנים בע"מ נ'' עיריית תל אביב יפו (29.02.2024)נבו - המתמחה מערכת בתי המשפט (2026) | סמכותו העניינית של בית משפט השלוםיעקב שקד סדר הדין האזרחי (2026) | 2.2.6 הכללים לבחינת הסמכות העניינית בבתי משפט השלום ובבתי המשפט המחוזיים',
    'הטעות הנפוצה היא לחשוב שכל סעד שאינו כספי אינו ניתן להערכה, ולכן אוטומטית בסמכות בית המשפט המחוזי, מבלי לנסות לאמוד את שוויו הכלכלי.',
    '["סמכות עניינית", "מבחן הסעד", "שווי נושא התביעה", "סעד כספי", "סעד שאינו כספי", "אומדן", "בית משפט השלום", "בית המשפט המחוזי"]'::jsonb,
    '**וריאציה 1 — מבחן הסעד:** מהו המבחן לקביעת סמכות עניינית בתביעות אזרחיות? ← מבחן הסעד, כלומר הסעדים המבוקשים בכתב התביעה (יעקב שקד סדר הדין האזרחי). **וריאציה 2 — שווי סעד לא כספי:** כיצד נקבע שווי סעד שאינו כספי? ← לפי הערך הכלכלי אותו ניתן לייחס לאינטרסים עליהם מבקש התובע להגן, גם על דרך של אומדן (רע"א 6500/19 גבריאל נ'' אשד). **וריאציה 3 — מתי שווי לא ניתן להערכה?** מתי שווי סעד שאינו כספי נחשב כבלתי ניתן להערכה? ← במצבים בהם לא ניתן לקבוע, אפילו על דרך של אומדן, מהו שווי נושא התביעה (רע"א 6500/19 גבריאל נ'' אשד).',
    'סמכות עניינית ← מבחן הסעד ← שווי סעד לא כספי ← הערך הכלכלי של האינטרסים המוגנים ← גם באומדן.',
    '["רע\"א 6500/19 ד\"ר שרון גבריאל נ'' ורד אשד (07.05.2020)", "ת\"א (שלום ת\"א) 5428-08-23 פרויקט אורנים בע\"מ נ'' עיריית תל אביב יפו (29.02.2024)", "נבו - המתמחה, מערכת בתי המשפט (2026), יג. סמכויות", "יעקב שקד, סדר הדין האזרחי (2026), פרק ב סמכויות השיפוט"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'סמכות ייחודית בחוקי קניין רוחני', 3, 'חברה הגישה תביעה בגין הפרת פטנט, ובה היא מבקשת צו מניעה קבוע ופיצויים בסך 100,000 ש"ח. למי נתונה סמכות הדיון בתובענה?',
    'שאלה זו בוחנת את החריג לכלל הסמכות העניינית בתביעות קניין רוחני, כאשר קיימת הוראת חוק ספציפית המקנה סמכות ייחודית לבית המשפט המחוזי. היא מדגישה את עקרון ה"דין המיוחד גובר על הדין הכללי" ומציגה דוגמאות לחוקים בהם נקבעה סמכות ייחודית כזו.',
    'הכלל הכללי לקביעת סמכות עניינית בתביעות קניין רוחני הוא מבחן הסעד, כפי שנקבע בהלכת גבריאל. אולם, קיימים חריגים לכלל זה, כאשר הוראות חוק ספציפיות בתחום הקניין הרוחני מקנות סמכות ייחודית לבית המשפט המחוזי, ללא קשר לשווי התביעה. כך למשל, סעיף 188 לחוק הפטנטים, תשכ"ז-1967, קובע שבית המשפט המוסמך לדון בתביעה בגין הפרת פטנט הוא בית המשפט המחוזי. במקרים אלו, הנורמה המיוחדת (חוק הפטנטים) גוברת על הנורמה הכללית (חוק בתי המשפט ומבחן הסעד), ולכן תביעות מעין אלו יש להגיש לבית המשפט המחוזי, וזאת מבלי להידרש כלל למבחן הסעד. רע"א 6161/20 אילה פלסט בע"מ נ'' פוטקס תבניות בע"מ (28.04.2021)רע"א 6161/20 אילה פלסט בע"מ נ'' פוטקס תבניות בע"מ (28.04.2021)סעיף 40(4) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984ת"א (שלום ת"א) 51932-06-18 איתן אבניאון נ'' ידיעות אינטרנט (21.01.2019)ת"א (שלום ת"א) 2834-05-18 גיל בסרב נ'' אריאל סמל (22.01.2019)',
    'הטעות הנפוצה היא ליישם את הכלל הכללי של מבחן הסעד גם במקרים בהם קיימת הוראת חוק ספציפית המקנה סמכות ייחודית לבית המשפט המחוזי, מבלי להבחין בין דין כללי לדין מיוחד.',
    '["סמכות עניינית", "קניין רוחני", "הפרת פטנט", "חוק הפטנטים", "דין מיוחד גובר על דין כללי", "בית המשפט המחוזי", "מבחן הסעד"]'::jsonb,
    '**וריאציה 1 — דין מיוחד גובר:** מה קורה כאשר יש סתירה בין נורמה כללית לנורמה מיוחדת? ← ידה של הנורמה המיוחדת על העליונה (רע"א 6161/20 אילה פלסט בע"מ). **וריאציה 2 — סמכות פטנטים:** למי נתונה הסמכות לדון בתביעה בגין הפרת פטנט? ← לבית המשפט המחוזי, ללא קשר לשווי התביעה, מכוח סעיף 188 לחוק הפטנטים (רע"א 6161/20 אילה פלסט בע"מ). **וריאציה 3 — הוראות מיוחדות נוספות:** אילו חוקי קניין רוחני נוספים מקנים סמכות ייחודית למחוזי? ← פקודת סימני מסחר, חוק זכות יוצרים, חוק הגנת כינויי מקור וציונים גיאוגרפיים (רע"א 6161/20 אילה פלסט בע"מ).',
    'הפרת פטנט ← סמכות ייחודית למחוזי ← דין מיוחד גובר ← ללא קשר לשווי.',
    '["רע\"א 6161/20 אילה פלסט בע\"מ נ'' פוטקס תבניות בע\"מ (28.04.2021)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 40(4)", "ת\"א (שלום ת\"א) 51932-06-18 איתן אבניאון נ'' ידיעות אינטרנט (21.01.2019)", "ת\"א (שלום ת\"א) 2834-05-18 גיל בסרב נ'' אריאל סמל (22.01.2019)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'סמכות עניינית בתביעות מקרקעין', 4, 'ראובן הגיש תביעה לאכיפת הסכם מכר מקרקעין, ששוויו 3 מיליון ש"ח. למי נתונה סמכות הדיון בתובענה?',
    'שאלה זו עוסקת בחלוקת הסמכויות הענייניות בתביעות מקרקעין, המהווה חריג למבחן הסעד הכללי. היא מדגישה את ההבחנה בין תביעות בדבר חזקה או שימוש (סמכות שלום) לבין תביעות בדבר בעלות, חכירה לדורות או תביעות אחרות הנוגעות למקרקעין (סמכות מחוזי), ללא קשר לשווי התביעה.',
    'בתביעות מקרקעין, חלוקת הסמכויות בין בתי המשפט אינה נקבעת לפי שווי הסעד, אלא לפי מהות הזכות העומדת במרכז התביעה. בית משפט השלום מוסמך לדון בתביעות בדבר חזקה או שימוש במקרקעין או בדבר חלוקתם או חלוקת השימוש בהם (סעיף 51(א)(3) לחוק בתי המשפט). לעומת זאת, בית המשפט המחוזי מוסמך לדון בתביעות בדבר בעלות במקרקעין, חכירה לדורות, או תביעות אחרות הנוגעות למקרקעין (סעיף 40(1) לחוק בתי המשפט). תביעה לאכיפת הסכם מכר מקרקעין נחשבת לתביעה בבעלות במקרקעין, שכן היא מכוונת להעברת זכויות קנייניות. לכן, הסמכות לדון בתביעה זו נתונה לבית המשפט המחוזי, ללא קשר לשווי המקרקעין או שווי הסעד. רע"א 3723/24 יאיר יעקב נ'' אהרון וכטר (20.06.2024)רע"א 8105/11 אברהים ג''ולאני נ'' אסמאעיל מוחמד סלימאן (11.12.2011)סעיף 51(א)(3) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984יעקב שקד פינוי מקרקעין – הליכים והלכות (2024) | 13.1 סמכות עניינית – כללירע"א 86226-07-25 חברת נתיבי אילון בע"מ נ'' לב המפרץ בע"מ (21.09.2025)',
    'הטעות הנפוצה היא ליישם את מבחן הסעד (שווי כספי) גם בתביעות מקרקעין, מבלי להבחין כי במקרקעין הסמכות נקבעת לפי מהות הזכות (חזקה/שימוש מול בעלות/חכירה לדורות).',
    '["סמכות עניינית", "מקרקעין", "אכיפת הסכם מכר", "בעלות במקרקעין", "חזקה ושימוש במקרקעין", "בית משפט השלום", "בית המשפט המחוזי", "מבחן מהות הזכות"]'::jsonb,
    '**וריאציה 1 — סמכות חזקה/שימוש:** למי נתונה הסמכות בתביעה לפינוי מקרקעין (חזקה/שימוש)? ← לבית משפט השלום, יהיה שווי המקרקעין אשר יהיה (סעיף 51(א)(3) לחוק בתי המשפט). **וריאציה 2 — סמכות בעלות/חכירה:** למי נתונה הסמכות בתביעה לבעלות במקרקעין? ← לבית המשפט המחוזי, ללא קשר לשווי המקרקעין (יעקב שקד פינוי מקרקעין). **וריאציה 3 — תביעה לאכיפת הסכם מכר:** האם תביעה לאכיפת הסכם מכר מקרקעין היא תביעה בבעלות? ← כן, היא נחשבת לתביעה בבעלות במקרקעין, ולכן בסמכות בית המשפט המחוזי (רע"א 8105/11 ג''ולאני נ'' סלימאן).',
    'סמכות מקרקעין ← לא לפי שווי ← חזקה/שימוש שלום ← בעלות/חכירה מחוזי.',
    '["רע\"א 3723/24 יאיר יעקב נ'' אהרון וכטר (20.06.2024)", "רע\"א 8105/11 אברהים ג''ולאני נ'' אסמאעיל מוחמד סלימאן (11.12.2011)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 51(א)(3)", "יעקב שקד, פינוי מקרקעין – הליכים והלכות (2024), פרק שלושה־עשר: סמכות עניינית וסדרי דין בתביעות פינוי מקרקעין", "רע\"א 86226-07-25 חברת נתיבי אילון בע\"מ נ'' לב המפרץ בע\"מ (21.09.2025)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לבית משפט השלום, שכן הסעד הכספי נמוך מ-2.5 מיליון ש"ח ושווי צו המניעה אינו עולה על סכום זה.', true, 'זו התשובה הנכונה. על פי הלכת גבריאל, גם כאשר נתבע סעד שאינו כספי בתביעת קניין רוחני, אם שווי נושאו ניתן להערכה (אפילו באומדן) ואינו עולה על 2.5 מיליון ש"ח, הסמכות נתונה לבית משפט השלום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לבית המשפט המחוזי, שכן תביעות קניין רוחני הכוללות צו מניעה נתונות תמיד לסמכותו.', false, 'תשובה זו שגויה. זוהי תפיסה שגויה שהייתה נהוגה בעבר, אך הלכת גבריאל הבהירה כי גם בתביעות קניין רוחני עם סעד לא כספי, הסמכות נקבעת לפי שווי התביעה, אם ניתן להעריכו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'לבית המשפט המחוזי, שכן שווי צו המניעה אינו ניתן להערכה כספית.', false, 'תשובה זו שגויה. אף ששווי צו המניעה אינו ניתן להערכה מדויקת, צוין כי הוא אינו עולה על 2.5 מיליון ש"ח, ולכן הוא אינו מוציא את התביעה מסמכות בית משפט השלום.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לבית המשפט לתביעות קטנות, שכן סכום הפיצויים נמוך.', false, 'תשובה זו שגויה. תביעות קניין רוחני, גם אם סכומן נמוך, אינן נדונות בבית המשפט לתביעות קטנות, המיועד לסכסוכים פשוטים ובעלי אופי שונה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'הכלל המרכזי הוא מבחן מהות הסכסוך, ושווי נושא התביעה בסעדים שאינם כספיים נקבע לפי שיקול דעת בית המשפט בלבד.', false, 'תשובה זו שגויה. הכלל המרכזי הוא מבחן הסעד, ולא מבחן מהות הסכסוך. שווי נושא התביעה בסעדים לא כספיים נקבע לפי הערך הכלכלי של האינטרסים המוגנים, ולא רק לפי שיקול דעת בית המשפט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'הכלל המרכזי הוא מבחן הסעד, ושווי נושא התביעה בסעדים שאינם כספיים הוא הערך הכלכלי אותו ניתן לייחס לאינטרסים עליהם מבקש התובע להגן, גם על דרך של אומדן.', true, 'זו התשובה הנכונה. מבחן הסעד הוא הכלל המרכזי, ושווי נושא התביעה בסעדים לא כספיים נקבע לפי הערך הכלכלי של האינטרסים המוגנים, הניתן להערכה גם באומדן.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'הכלל המרכזי הוא מבחן הסעד, אך שווי נושא התביעה בסעדים שאינם כספיים אינו ניתן להערכה, ולכן תמיד נתון לסמכות בית המשפט המחוזי.', false, 'תשובה זו שגויה. שווי נושא התביעה בסעדים לא כספיים ניתן להערכה במקרים רבים, גם על דרך של אומדן, ורק אם אינו ניתן להערכה כלל, הסמכות תהיה למחוזי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'הכלל המרכזי הוא מבחן העילה, ושווי נושא התביעה בסעדים שאינם כספיים נקבע לפי סכום האגרה ששולמה.', false, 'תשובה זו שגויה. הכלל המרכזי הוא מבחן הסעד, לא מבחן העילה. סכום האגרה נגזר משווי התביעה, ולא קובע אותו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'לבית משפט השלום, שכן הסעד הכספי נמוך מ-2.5 מיליון ש"ח.', false, 'תשובה זו שגויה. אף שהסעד הכספי נמוך, חוק הפטנטים קובע סמכות ייחודית לבית המשפט המחוזי, הגוברת על הכלל הכללי של מבחן הסעד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לבית המשפט המחוזי, שכן חוק הפטנטים מקנה לו סמכות ייחודית לדון בתביעות אלו, ללא קשר לשווי התביעה.', true, 'זו התשובה הנכונה. סעיף 188 לחוק הפטנטים מקנה סמכות ייחודית לבית המשפט המחוזי לדון בתביעות בגין הפרת פטנט, וזאת ללא קשר לשווי התביעה, מכוח עקרון ה"דין המיוחד גובר על הדין הכללי".', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'לבית המשפט לעניינים כלכליים, שכן מדובר בעניין מורכב הדורש מומחיות.', false, 'תשובה זו שגויה. תביעות פטנטים אינן נחשבות ל"עניין כלכלי" כהגדרתו בחוק בתי המשפט, ולכן אינן בסמכות המחלקה הכלכלית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לבית המשפט המחוזי, שכן צו מניעה תמיד בסמכותו.', false, 'תשובה זו שגויה. אף שצו מניעה יכול להביא לסמכות המחוזי אם שוויו אינו ניתן להערכה, במקרה זה הסמכות נובעת מהוראה ספציפית בחוק הפטנטים, ולא מהכלל הכללי לגבי צווי מניעה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'לבית משפט השלום, שכן הסעד הוא אכיפה ולא בעלות.', false, 'תשובה זו שגויה. תביעה לאכיפת הסכם מכר מקרקעין נחשבת לתביעה בבעלות במקרקעין, ולכן היא בסמכות בית המשפט המחוזי, ללא קשר לשווי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'לבית המשפט המחוזי, שכן תביעה לאכיפת הסכם מכר מקרקעין היא תביעה בבעלות במקרקעין, הנתונה לסמכותו.', true, 'זו התשובה הנכונה. בתביעות מקרקעין, הסמכות נקבעת לפי מהות הזכות. תביעה לאכיפת הסכם מכר מקרקעין נחשבת לתביעה בבעלות במקרקעין, שהיא בסמכות בית המשפט המחוזי, ללא קשר לשווי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'לבית משפט השלום, שכן תביעות מקרקעין תמיד בסמכותו.', false, 'תשובה זו שגויה. בית משפט השלום מוסמך לדון רק בתביעות בדבר חזקה או שימוש במקרקעין, ולא בתביעות בעלות או חכירה לדורות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'לבית המשפט המחוזי, שכן שווי התביעה עולה על 2.5 מיליון ש"ח.', false, 'תשובה זו שגויה. אף שהשווי עולה על 2.5 מיליון ש"ח, בתביעות מקרקעין הסמכות נקבעת לפי מהות הזכות ולא לפי שווי הסעד, ולכן הנימוק שגוי.', 4);

END $$;

-- ============================================================
-- Q31 — 2024-W-Q31 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q31';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q31 skipped: external_id % already exists', '2024-W-Q31';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q31', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'במעמד דיון שהוקלט, נתן בית המשפט את החלטתו בעל פה במעמד הצדדים. הפרוטוקול ובו ההחלטה הועלה לראשונה על הכתב מתוך ההקלטה 10 ימים לאחר הדיון, ההחלטה נחתמה ע"י בית המשפט 15 ימים לאחר הדיון, אך הומצאה לצדדים והייתה אפשרית לצפייה בנט המשפט 17 ימים לאחר הדיון. מתי יחל מניין הימים להגשת ערעור על ההחלטה?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 31}'::jsonb,
    'שאלה זו עוסקת בקביעת מניין הימים להגשת ערעור על החלטה שניתנה בעל פה במעמד הצדדים, כאשר הפרוטוקול הכתוב וההמצאה הפורמלית מתרחשים במועד מאוחר יותר. היא בוחנת את הוראות תקנה 179(א) לתקנות סדר הדין האזרחי, התשע"ט-2018, ואת פרשנות הפסיקה לעניין זה, המבכרת את מועד הדיון על פני מועד ההמצאה במקרים אלו.',
    'הכלל הבסיסי לקביעת מניין הימים להגשת ערעור קבוע בתקנה 179(א) לתקנות סדר הדין האזרחי, התשע"ט-2018, הקובעת כי "המועד הקובע לתחילת מניין הימים לפרק הזמן שנקבע הוא יום המצאת המסמך כמפורט בתקנות אלה; אם ניתנה החלטה במעמד בעלי הדין, יימנה המועד ממועד הדיון". כלל זה מבחין בין שני מצבים: כאשר ההחלטה ניתנה במעמד בעלי הדין (בין אם בעל פה ובין אם בכתב), מניין הימים יחל ממועד הדיון עצמו. כאשר ההחלטה ניתנה שלא במעמד בעלי הדין, מניין הימים יחל מיום המצאת המסמך כדין. במקרה הנדון, ההחלטה ניתנה בעל פה במעמד הצדדים, ולכן, על פי לשון התקנה והפסיקה, מניין הימים להגשת הערעור יחל מיום הדיון שבו ניתנה ההחלטה. העובדה שהפרוטוקול הועלה על הכתב, נחתם או הומצא במועד מאוחר יותר, אינה משנה את מועד תחילת מניין הימים במקרה זה. בית המשפט העליון הבהיר בעניין בוריסי (רע"א 7143/21) כי מניין הימים להגשת הליך ערעורי על החלטה שניתנה במעמד הצדדים במהלך דיון מוקלט, יחל ממועד מתן ההחלטה בדיון, ולא ממועד המצאת תמליל הדיון לצדדים. תקנה 179(א) לתקנות סדר הדין האזרחי, התשע"ט-2018רע"א 7143/21 אריה בוריסי נ'' יחזקאל קרטין (04.12.2022)עפ"ס (ארצי ) 22879-04-24 בית מרן נ'' אורנית לוי (07.07.2024)חמי בן-נון, טל חבקין הערעור האזרחי (2012) | פרק חמישי מועדים בערעורטל חבקין, יגאל נמרודי התביעה הקטנה (2017) | פרק שלישי: סדרי הדין',
    'הטעות הנפוצה היא לבלבל בין מועד מתן ההחלטה בעל פה במעמד הצדדים לבין מועד העלאת הפרוטוקול על הכתב או המצאתו הפורמלית, ולהתחיל את מניין הימים ממועד מאוחר יותר, בניגוד להוראות התקנות והפסיקה.',
    '["מניין ימים לערעור", "החלטה בעל פה", "מעמד הצדדים", "דיון מוקלט", "תקנות סדר הדין האזרחי", "כלל ההמצאה", "מועד הדיון"]'::jsonb,
    '**וריאציה 1 — החלטה בעל פה במעמד הצדדים:** מתי יחל מניין הימים לערעור על החלטה שניתנה בעל פה במעמד הצדדים? ← ממועד הדיון שבו ניתנה ההחלטה (תקנה 179(א) לתקנות סדר הדין האזרחי, התשע"ט-2018). **וריאציה 2 — עיכוב בפרוטוקול:** האם עיכוב בהעלאת הפרוטוקול הכתוב משנה את מניין הימים? ← לא, מניין הימים יחל ממועד מתן ההחלטה בדיון, ולא ממועד המצאת תמליל הדיון לצדדים (עפ"ס (ארצי ) 22879-04-24 בית מרן נ'' אורנית לוי). **וריאציה 3 — צורך בתמליל:** מה יעשה בעל דין הזקוק לתמליל לצורך הגשת הערעור? ← באפשרותו להגיש בקשה להארכת מועד להגשת הערעור (עפ"ס (ארצי ) 22879-04-24 בית מרן נ'' אורנית לוי).',
    'החלטה בעל פה במעמד הצדדים ← מניין ימים לערעור ממועד הדיון ← לא ממועד הפרוטוקול/המצאה.',
    '["תקנות סדר הדין האזרחי, התשע\"ט-2018, תקנה 179(א)", "רע\"א 7143/21 אריה בוריסי נ'' יחזקאל קרטין (04.12.2022)", "עפ\"ס (ארצי ) 22879-04-24 בית מרן נ'' אורנית לוי (07.07.2024)", "חמי בן-נון, טל חבקין, הערעור האזרחי (2012), פרק חמישי מועדים בערעור", "טל חבקין, יגאל נמרודי, התביעה הקטנה (2017), פרק שלישי: סדרי הדין"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מיום הדיון שנערך במעמד הצדדים, אשר במהלכו שמעו את ההחלטה.', true, 'זו התשובה הנכונה. תקנה 179(א) לתקנות סדר הדין האזרחי, התשע"ט-2018, קובעת במפורש כי אם ניתנה החלטה במעמד בעלי הדין, יימנה המועד ממועד הדיון, וזאת גם אם הפרוטוקול הכתוב או ההמצאה הפורמלית מתרחשים במועד מאוחר יותר.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מיום שהועלתה ההחלטה על הכתב.', false, 'תשובה זו שגויה. אף שהעלאת ההחלטה על הכתב היא שלב חשוב, היא אינה המועד הקובע לתחילת מניין הימים כאשר ההחלטה ניתנה בעל פה במעמד הצדדים, כפי שנקבע בתקנות ובפסיקה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מיום חתימת ההחלטה ע"י בית המשפט.', false, 'תשובה זו שגויה. חתימת ההחלטה על ידי בית המשפט אינה המועד הקובע לתחילת מניין הימים במקרה של החלטה בעל פה במעמד הצדדים, שכן הצדדים כבר שמעו את ההחלטה במועד הדיון.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'מיום המצאת ההחלטה לצדדים.', false, 'תשובה זו שגויה. כלל ההמצאה חל כאשר ההחלטה לא ניתנה במעמד בעלי הדין. במקרה זה, ההחלטה ניתנה בעל פה במעמד הצדדים, ולכן מניין הימים מתחיל ממועד הדיון עצמו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'מניין ימים לערעור: כלל הידיעה מול כלל ההמצאה', 1, 'פסק דין ניתן שלא במעמד הצדדים, אך עורך דינו של הנתבע צפה בו במערכת ''נט המשפט'' ושלח דרישת תשלום לצד שכנגד על בסיסו, בטרם הומצא לו הפסק כדין. מתי יחל מניין הימים להגשת ערעור על פסק הדין?',
    'שאלה זו בוחנת את המתח בין "כלל ההמצאה" ל"כלל הידיעה" בקביעת מניין הימים להגשת ערעור. היא מדגישה כי אף שכלל ההמצאה הוא הכלל, במקרים חריגים של ידיעה ממשית על פסק הדין בתוספת התנהגות המעידה על חוסר תום לב, ניתן להחיל את כלל הידיעה ולמנות את הימים ממועד הידיעה בפועל.',
    'הכלל הבסיסי לקביעת מניין הימים להגשת ערעור על החלטה שניתנה שלא במעמד הצדדים הוא "כלל ההמצאה", הקובע כי מניין הימים יחל מיום המצאת ההחלטה כדין (תקנה 179(א) לתקנות סדר הדין האזרחי, התשע"ט-2018, ותקנה 402 לתקנות סדר הדין האזרחי, תשמ"ד-1984). עם זאת, הפסיקה הכירה בחריג לכלל זה, המכונה "כלל הידיעה". חריג זה מבוסס על חובת תום הלב הדיונית וחל במקרים חריגים וקיצוניים שבהם הוכח כי לבעל הדין הייתה ידיעה מלאה וברורה בדבר תוכן ההחלטה לפני שהומצאה לו כדין, והוא השתהה בהגשת הערעור באופן שהתנהגותו נגועה בחוסר תום לב. "דבר מה נוסף" מעבר לידיעה גרידא, כגון פעולה על בסיס ההחלטה או יצירת מצג כלפי הצד שכנגד, יכול להצדיק את החלת כלל הידיעה. במקרה הנדון, עורך הדין לא רק ידע על פסק הדין מצפייה ב''נט המשפט'', אלא אף פעל על בסיסו כששלח דרישת תשלום. פעולה זו מהווה "דבר מה נוסף" המעיד על ידיעה ממשית ועלולה להיחשב כחוסר תום לב אם יטען לאי-המצאה. ע"א 8033/14 אהרון לוינגר נ'' הנרי זלניק (21.01.2016)רע"א 8467/06 לובנה אבו עוקסה נ'' בית הברזל טנוס בע"מ (08.07.2010)רע"א 11286/05 אריק זמיר נ'' בנק לאומי למשכנתאות בע''''מ (08.07.2007)דוד בר-אופיר הוצאה לפועל הליכים והלכות - כרך א (2025) | פרק ג'': סדרי דיןיעקב שקד סדר הדין האזרחי (2026) | פרק טו המצאות',
    'הטעות הנפוצה היא לחשוב שכל ידיעה על פסק דין, גם ללא המצאה פורמלית, מפעילה את מניין הימים, או לחלופין, שכל פגם בהמצאה מבטל לחלוטין את מניין הימים, מבלי להתחשב בחובת תום הלב הדיונית.',
    '["כלל ההמצאה", "כלל הידיעה", "תום לב דיוני", "דבר מה נוסף", "מניין ימים לערעור", "נט המשפט", "השתק"]'::jsonb,
    '**וריאציה 1 — ידיעה ופעולה:** פסק דין לא הומצא, אך עורך דין צפה בו ושלח דרישת תשלום. מתי יחל מניין הימים לערעור? ← מיום הידיעה והפעולה, בשל חוסר תום לב (ע"א 8033/14 לוינגר נ'' זלניק). **וריאציה 2 — ידיעה בלבד:** פסק דין לא הומצא, אך עורך דין ידע על קיומו. מתי יחל מניין הימים לערעור? ← רק מיום ההמצאה כדין, שכן ידיעה בלבד אינה מספיקה להפעלת כלל הידיעה (רע"א 8467/06 אבו עוקסה נ'' בית הברזל טנוס בע"מ). **וריאציה 3 — תכלית כלל הידיעה:** מהי תכליתו של כלל הידיעה? ← לאכוף את כללי סדר הדין ברוחם ועל פי תכליתם האמיתית, ולמנוע ניצול לרעה של פגמים טכניים בהמצאה (יעקב שקד סדר הדין האזרחי).',
    'כלל ההמצאה ← הכלל. כלל הידיעה ← חריג, רק בידיעה ממשית + חוסר תום לב/פעולה על בסיס ההחלטה.',
    '["תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 179(א)", "תקנות סדר הדין האזרחי, תשמ\"ד-1984, תקנה 402", "רע\"א 8467/06 לובנה אבו עוקסה נ'' בית הברזל טנוס בע\"מ (08.07.2010)", "רע\"א 11286/05 אריק זמיר נ'' בנק לאומי למשכנתאות בע\"מ (08.07.2007)", "ע\"א 8033/14 אהרון לוינגר נ'' הנרי זלניק (21.01.2016)", "חמי בן-נון, טל חבקין, הערעור האזרחי (2012), פרק חמישי מועדים בערעור", "דוד בר-אופיר, הוצאה לפועל הליכים והלכות - כרך א (2025), פרק ג'': סדרי דין", "יעקב שקד, סדר הדין האזרחי (2026), פרק טו המצאות"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'התפתחות הפסיקה ב"כלל ההמצאה" ו"כלל הידיעה"', 2, 'כיצד התפתחה הפסיקה בישראל ביחס למתח שבין "כלל ההמצאה" ל"כלל הידיעה" בקביעת מניין הימים להגשת ערעור?',
    'שאלה זו מתארת את האבולוציה הפסיקתית בישראל בנוגע לקביעת מניין הימים להגשת ערעור, תוך התמקדות במתח בין "כלל ההמצאה" הפורמלי ל"כלל הידיעה" המהותי. היא מבהירה כיצד הפסיקה ריככה את הגישה הדווקנית והכירה בחריג של "כלל הידיעה" במקרים של חוסר תום לב דיוני.',
    'בתחילה, הפסיקה דגלה בגישה דווקנית של "כלל ההמצאה", לפיה מניין הימים להגשת ערעור יחל רק ממועד ההמצאה כדין של פסק הדין או ההחלטה, גם אם בעל הדין ידע על קיומם קודם לכן (ראו: ע"א 127/60 שרונה נ'' שינברג; ע"א 244/73 פיורקו; ע"א 5120/90 כהן). עם השנים, חל ריכוך הולך וגובר בפרשנות זו. תחילה, הוכר "כלל הידיעה" כחריג במקרים של השתק, במיוחד כאשר בעל הדין לא רק ידע על פסק הדין אלא אף פעל על פיו (ראו: בש"א 1890/00 מנורה איזו אהרון נ'' אוליצקי כריה; רע"א 5007/92 לוין). בהמשך, התפתחה נטייה רחבה יותר להכיר בידיעת בעל דין כמתחילה את מרוץ הימים, במיוחד כאשר מדובר בחוסר תום לב דיוני מצד בעל הדין המערער, המנצל פגם טכני בהמצאה כדי להשיג יתרון דיוני (ראו: רע"א 1113/97 אסמעיל נ'' סלימאן; בר"ם 1299/02 תפנית אורטופדיה נ'' קופת חולים לאומית; רע"א 8467/06 אבו עוקסה נ'' בית הברזל טנוס בע"מ). "כלל ההמצאה" נותר הכלל המרכזי, ו"כלל הידיעה" הוא חריג צר המופעל במקרים חריגים וקיצוניים, המבוססים על חובת תום הלב הדיונית ועל "דבר מה נוסף" מעבר לידיעה גרידא. רע"א 11286/05 אריק זמיר נ'' בנק לאומי למשכנתאות בע''''מ (08.07.2007)רע"א 11286/05 אריק זמיר נ'' בנק לאומי למשכנתאות בע''''מ (08.07.2007)רע"א 8467/06 לובנה אבו עוקסה נ'' בית הברזל טנוס בע"מ (08.07.2010)יששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025) | פרק יד המצאותדוד בר-אופיר הוצאה לפועל הליכים והלכות - כרך א (2025) | פרק ג'': סדרי דין',
    'הטעות הנפוצה היא לחשוב שהפסיקה נטשה לחלוטין את "כלל ההמצאה" לטובת "כלל הידיעה", או לחלופין, שהיא עדיין דבקה בגישה פורמלית נוקשה, מבלי להבין את האיזון העדין שנוצר בין הכללים.',
    '["כלל ההמצאה", "כלל הידיעה", "התפתחות פסיקתית", "תום לב דיוני", "השתק", "ודאות דיונית", "ריכוך הגישה"]'::jsonb,
    '**וריאציה 1 — גישה ראשונית:** מה הייתה הגישה הראשונית למניין ימי ערעור? ← "כלל ההמצאה" הדווקני (רע"א 11286/05 זמיר נ'' בנק לאומי למשכנתאות בע"מ). **וריאציה 2 — ריכוך הגישה:** מה גרם לריכוך הגישה? ← הכרה בחובת תום הלב הדיונית ובמקרים של השתק ופעולה על בסיס הידיעה (רע"א 11286/05 זמיר נ'' בנק לאומי למשכנתאות בע"מ). **וריאציה 3 — המצב כיום:** האם "כלל הידיעה" הפך לכלל? ← לא, הוא נותר חריג צר המופעל במקרים חריגים וקיצוניים של חוסר תום לב דיוני (דוד בר-אופיר הוצאה לפועל הליכים והלכות - כרך א).',
    'פסיקה: מ"כלל ההמצאה" הדווקני ← לריכוך באמצעות "כלל הידיעה" כחריג צר המבוסס על תום לב ו"דבר מה נוסף".',
    '["רע\"א 11286/05 אריק זמיר נ'' בנק לאומי למשכנתאות בע\"מ (08.07.2007)", "רע\"א 8467/06 לובנה אבו עוקסה נ'' בית הברזל טנוס בע\"מ (08.07.2010)", "עמ\"נ (מינהליים חי'') 25858-11-18 שלמה שוקרון נ'' ועדה מקומית לתכנון ובנייה חדרה (28.05.2019)", "חמי בן-נון, טל חבקין, הערעור האזרחי (2012), פרק חמישי מועדים בערעור", "יששכר רוזן-צבי, הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025), פרק יד המצאות", "דוד בר-אופיר, הוצאה לפועל הליכים והלכות - כרך א (2025), פרק ג'': סדרי דין", "יעקב שקד, סדר הדין האזרחי (2026), פרק טו המצאות"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'חריגים סטטוטוריים למועדי ערעור', 3, 'ועדת משמעת לפי חוק המתווכים במקרקעין, תשנ"ו-1996, נתנה החלטה שלא במעמד הצדדים. מתי יחל מניין הימים להגשת ערעור על החלטה זו לבית המשפט המחוזי?',
    'שאלה זו עוסקת בחריגים לכללי מניין הימים להגשת ערעור, כאשר חוק ספציפי קובע הוראות שונות מתקנות סדר הדין האזרחי הכלליות. היא מדגישה את חשיבות הבדיקה של הוראות החיקוק הספציפיות הרלוונטיות לעניין, במיוחד כאשר מדובר בהליכים בפני גופים מעין-שיפוטיים או מקצועיים.',
    'הכלל הכללי למניין ימים להגשת ערעור בתקנות סדר הדין האזרחי, התשע"ט-2018, הוא 60 ימים מיום המצאת ההחלטה (תקנה 137(א)). אולם, כאשר קיים חיקוק ספציפי הקובע מועד אחר, הוראת החיקוק הספציפית גוברת. סעיף 14כג(א) לחוק המתווכים במקרקעין, תשנ"ו-1996, קובע במפורש כי "על החלטת ועדת המשמעת בקובלנה רשאים התובע והנקבל לערער לפני בית משפט מחוזי בתוך 45 ימים מיום מתן ההחלטה המסיימת את הדיון בקובלנה, ואם ניתנה ההחלטה שלא במעמד הצדדים - בתוך 45 ימים מיום המצאתה". במקרה הנדון, ההחלטה ניתנה שלא במעמד הצדדים, ולכן מניין הימים יחל מיום המצאת ההחלטה, והמועד הוא 45 ימים. דוגמאות נוספות לחוקים ספציפיים הקובעים מועדים שונים ניתן למצוא בחוק ההנדסאים והטכנאים המוסמכים (סעיף 34), תקנות בית הדין לעבודה (תקנה 73), תקנות חוקרים פרטיים ושירותי שמירה (תקנה 2), ועוד. סעיף 14כג(א) לחוק המתווכים במקרקעין, תשנ"ו-1996סעיף 34(א) לחוק ההנדסאים והטכנאים המוסמכים, תשע"ג-2012תקנה 73 לתקנות בית הדין לעבודה (סדרי דין), תשנ"ב-1991תקנה 2(ב) לתקנות חוקרים פרטיים ושירותי שמירה (ערעור לבית המשפט המחוזי), תשל"ב-1972תקנה 137(א) לתקנות סדר הדין האזרחי, תשע"ט-2018',
    'הטעות הנפוצה היא ליישם את הכללים הכלליים של תקנות סדר הדין האזרחי ללא בדיקה של הוראות חוק ספציפיות, אשר עשויות לקבוע מועדים או כללים שונים להגשת ערעור.',
    '["חריג סטטוטורי", "מועדי ערעור", "חוק המתווכים במקרקעין", "ועדת משמעת", "המצאה כדין", "דין ספציפי גובר", "בית המשפט המחוזי"]'::jsonb,
    '**וריאציה 1 — חוק ספציפי:** האם חוק ספציפי יכול לקבוע מועד ערעור שונה מתקנות סדר הדין האזרחי? ← כן, הוראת חוק ספציפית גוברת על הכלל הכללי (סעיף 14כג(א) לחוק המתווכים במקרקעין). **וריאציה 2 — החלטה במעמד צדדים (חוק ספציפי):** ועדת משמעת נתנה החלטה במעמד הצדדים. מתי יחל מניין הימים לערעור? ← 45 ימים מיום מתן ההחלטה (סעיף 14כג(א) לחוק המתווכים במקרקעין). **וריאציה 3 — ערעור על החלטת רשם:** מהו המועד להגשת ערעור על החלטת רשם? ← 20 ימים מיום מתן ההחלטה (תקנה 400 לתקנות סדר הדין האזרחי, תשמ"ד-1984).',
    'מועדי ערעור ← כלל: תקנות סדר הדין האזרחי. חריג: חוק ספציפי קובע מועד אחר ← יש לבדוק את החוק הספציפי.',
    '["חוק המתווכים במקרקעין, תשנ\"ו-1996, סעיף 14כג(א)", "חוק ההנדסאים והטכנאים המוסמכים, תשע\"ג-2012, סעיף 34(א)", "תקנות בית הדין לעבודה (סדרי דין), תשנ\"ב-1991, תקנה 73", "תקנות חוקרים פרטיים ושירותי שמירה (ערעור לבית המשפט המחוזי), תשל\"ב-1972, תקנה 2(ב)", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 137(א)", "תקנות סדר הדין האזרחי, תשמ\"ד-1984, תקנה 400"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'הארכת מועד להגשת ערעור', 4, 'המערער הגיש ערעור באיחור של מספר ימים. באילו תנאים יאריך בית המשפט את המועד להגשת הערעור?',
    'שאלה זו עוסקת בתנאים להארכת מועד להגשת ערעור, כאשר הערעור הוגש באיחור. היא מתמקדת בדרישת "טעמים מיוחדים שיירשמו" ובמכלול השיקולים שבית המשפט מאזן בבואו להכריע בבקשה כזו, תוך התייחסות לגישה המרוככת של הפסיקה בנושא.',
    'המועדים להגשת ערעור קבועים בחיקוק, ואיחור בהגשת ערעור עלול להביא לסילוקו על הסף. עם זאת, בית המשפט רשאי להאריך מועד להגשת ערעור "מטעמים מיוחדים שיירשמו" (תקנה 179(ד) לתקנות סדר הדין האזרחי, התשע"ט-2018, ותקנה 528 לתקנות סדר הדין האזרחי, תשמ"ד-1984). הפסיקה ריככה את הדרישה ל"טעם מיוחד" והיא בוחנת מכלול שיקולים, הכוללים את עקרון סופיות הדיון ויעילותו, התנהגותם של הצדדים ותום לבם, נסיבותיו של האיחור, מידתו והשלכתו על אינטרס ההסתמכות של הצד האחר, מהות הסוגייה וחשיבותה הציבורית, וסיכוייו של ההליך העיקרי. טעות אנוש שאינה נובעת מרשלנות, הזנחה או זלזול, עשויה להיחשב כ"טעם מיוחד". גם איחור קצר, אפילו של יום אחד, מצריך הצדקה. רע"א (מחוזי ת"א) 10561-10-19 צפניה בני נ'' עיזבון המנוח מנשה מריאמי ז"ל (11.12.2019)רע"א (מחוזי ת"א) 10561-10-19 צפניה בני נ'' עיזבון המנוח מנשה מריאמי ז"ל (11.12.2019)ע"ע (ארצי ) 39720-01-17 יוסף חניה - אבו סקיק סמיר (13.11.2017)רע"א 8467/06 לובנה אבו עוקסה נ'' בית הברזל טנוס בע"מ (08.07.2010)חמי בן-נון, טל חבקין הערעור האזרחי (2012) | פרק תשעה-עשר - הערעור בעניינים מנהליים',
    'הטעות הנפוצה היא לחשוב ש"טעמים מיוחדים" מתייחסים רק למקרים של כוח עליון או נסיבות בלתי צפויות, מבלי להבין את הגישה המרוככת של הפסיקה המאפשרת איזון בין מכלול שיקולים.',
    '["הארכת מועד", "טעמים מיוחדים", "סופיות הדיון", "זכות הגישה לערכאות", "מאזן נוחות", "תום לב", "מידתיות", "סיכויי ערעור"]'::jsonb,
    '**וריאציה 1 — דרישת טעמים מיוחדים:** האם ניתן להאריך מועד להגשת ערעור? ← כן, רק מטעמים מיוחדים שיירשמו (רע"א (מחוזי ת"א) 10561-10-19 צפניה בני). **וריאציה 2 — שיקולים לאיחור:** מהם השיקולים המרכזיים בבחינת בקשה להארכת מועד? ← סופיות הדיון, התנהגות הצדדים, מידת האיחור, סיכויי הערעור וזכות הגישה לערכאות (רע"א (מחוזי ת"א) 10561-10-19 צפניה בני). **וריאציה 3 — איחור קצר:** האם איחור של יום אחד מצריך טעם מיוחד? ← כן, גם איחור של יום אחד נחשב לאיחור המצריך הוכחת טעם מיוחד (רע"א 8467/06 אבו עוקסה נ'' בית הברזל טנוס בע"מ).',
    'הארכת מועד לערעור ← דורש "טעמים מיוחדים" ← איזון בין סופיות דיון, תום לב, מידת איחור, סיכויי ערעור וזכות גישה לערכאות.',
    '["תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 179(ד)", "תקנות סדר הדין האזרחי, תשמ\"ד-1984, תקנה 528", "רע\"א (מחוזי ת\"א) 10561-10-19 צפניה בני נ'' עיזבון המנוח מנשה מריאמי ז\"ל (11.12.2019)", "ע\"ע (ארצי ) 39720-01-17 יוסף חניה - אבו סקיק סמיר (13.11.2017)", "רע\"א 8467/06 לובנה אבו עוקסה נ'' בית הברזל טנוס בע\"מ (08.07.2010)", "חמי בן-נון, טל חבקין, הערעור האזרחי (2012), פרק תשעה-עשר - הערעור בעניינים מנהליים"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'מיום המצאת פסק הדין כדין, שכן זהו הכלל המחייב, וצפייה ב''נט המשפט'' או פעולה על בסיס הפסק אינן משנות זאת.', false, 'תשובה זו שגויה. אף שכלל ההמצאה הוא הכלל, במקרים חריגים של ידיעה ממשית ופעולה על בסיס הפסק, ניתן להחיל את כלל הידיעה, במיוחד אם ההתנהלות נגועה בחוסר תום לב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'מיום שצפה עורך הדין בפסק הדין ב''נט המשפט'' ופעל על בסיסו, שכן התנהלות זו מהווה חוסר תום לב המצדיק סטייה מכלל ההמצאה.', true, 'זו התשובה הנכונה. במקרה של ידיעה ממשית על פסק הדין, בתוספת ''דבר מה נוסף'' כמו פעולה על בסיסו, הפסיקה מכירה בחריג ''כלל הידיעה'' המבוסס על חובת תום הלב הדיונית, וקובעת כי מניין הימים יחל ממועד הידיעה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'מיום מתן פסק הדין, שכן ידיעת עורך הדין על קיומו שקולה למתן ההחלטה במעמד הצדדים.', false, 'תשובה זו שגויה. ידיעה על קיום פסק דין אינה שקולה למתן החלטה במעמד הצדדים. כלל הידיעה הוא חריג לכלל ההמצאה, ולא הופך את המקרה למצב של החלטה במעמד הצדדים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'מניין הימים לא יחל כלל, שכן פסק הדין לא הומצא כדין, ואין כלל חלופי שיכול להחליף את דרישת ההמצאה.', false, 'תשובה זו שגויה. אף שכלל ההמצאה הוא הכלל, קיימים חריגים המבוססים על ידיעה ממשית וחוסר תום לב, המאפשרים למנות את הימים גם ללא המצאה פורמלית.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'הפסיקה תמיד דגלה ב"כלל ההמצאה" באופן דווקני, ודחתה כל ניסיון להחיל את "כלל הידיעה" גם במקרים של חוסר תום לב.', false, 'תשובה זו שגויה. אף שהגישה הראשונית הייתה דווקנית, הפסיקה רוככה עם השנים והכירה בחריג של "כלל הידיעה" במקרים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'הפסיקה עברה מגישה דווקנית של "כלל ההמצאה" לגישה מרוככת יותר, המכירה ב"כלל הידיעה" כחריג המבוסס על חובת תום הלב הדיונית ועל "דבר מה נוסף" המעיד על ידיעה וניצול לרעה של פגם בהמצאה.', true, 'זו התשובה הנכונה. הפסיקה אכן התפתחה מגישה פורמלית לגישה מהותית יותר, המאזנת בין ודאות דיונית לחובת תום הלב, ומכירה ב"כלל הידיעה" כחריג צר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'הפסיקה החלה מ"כלל הידיעה" ככלל, אך עם השנים חזרה ל"כלל ההמצאה" ככלל מחייב, ללא חריגים.', false, 'תשובה זו שגויה. ההתפתחות הייתה הפוכה: מגישה דווקנית של "כלל ההמצאה" לריכוך מסוים, אך "כלל ההמצאה" נותר הכלל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'הפסיקה קבעה כי "כלל הידיעה" ו"כלל ההמצאה" הם כללים שווים במעמדם, ובית המשפט רשאי לבחור ביניהם לפי שיקול דעתו הבלעדי בכל מקרה ומקרה.', false, 'תשובה זו שגויה. "כלל ההמצאה" נותר הכלל, ו"כלל הידיעה" הוא חריג צר המופעל בתנאים ספציפיים, ולא כלל שווה במעמדו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'בתוך 45 ימים מיום מתן ההחלטה המסיימת את הדיון בקובלנה.', false, 'תשובה זו שגויה. מועד זה חל רק אם ההחלטה ניתנה במעמד הצדדים. כאשר היא ניתנה שלא במעמד הצדדים, חל מועד אחר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בתוך 45 ימים מיום המצאת ההחלטה.', true, 'זו התשובה הנכונה. סעיף 14כג(א) לחוק המתווכים במקרקעין קובע במפורש כי אם ההחלטה ניתנה שלא במעמד הצדדים, מניין הימים להגשת ערעור הוא 45 ימים מיום המצאתה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בתוך 30 ימים מיום המצאת ההחלטה, שכן זהו הכלל בתקנות סדר הדין האזרחי.', false, 'תשובה זו שגויה. אף ש-30 ימים הוא מועד נפוץ בחוקים אחרים, חוק המתווכים במקרקעין קובע מועד ספציפי של 45 ימים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בתוך 15 ימים מיום המצאת ההחלטה, שכן זהו המועד המקוצר להליכים מנהליים.', false, 'תשובה זו שגויה. אין הוראה כזו בחוק המתווכים במקרקעין, והמועד הקבוע בו הוא 45 ימים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בית המשפט יאריך את המועד רק אם האיחור נגרם עקב נסיבות חיצוניות שאינן בשליטת המערער, כגון מחלה או מוות.', false, 'תשובה זו שגויה. אף שנסיבות כאלה יכולות להוות טעם מיוחד, הפסיקה רוככה ואינה דורשת רק נסיבות חיצוניות, אלא בוחנת מכלול שיקולים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט יאריך את המועד אם מצא "טעמים מיוחדים שיירשמו", תוך איזון בין שיקולים כגון סופיות הדיון, התנהגות הצדדים, מידת האיחור, סיכויי הערעור וזכות הגישה לערכאות.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי הארכת מועד להגשת ערעור דורשת "טעמים מיוחדים שיירשמו", וכי יש לאזן מכלול שיקולים רחב, כולל אלו המפורטים בתשובה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בית המשפט יאריך את המועד אם המערער יציג סיכויי הצלחה גבוהים בערעור, ללא קשר לסיבת האיחור.', false, 'תשובה זו שגויה. סיכויי הערעור הם שיקול חשוב, אך אינם השיקול היחיד, ויש לאזן אותם עם יתר השיקולים, כולל סיבת האיחור ומידתו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט אינו רשאי להאריך מועד להגשת ערעור שנקבע בחיקוק, שכן מועדים אלו הם קוגנטיים ואינם ניתנים לשינוי.', false, 'תשובה זו שגויה. תקנות סדר הדין האזרחי (תקנה 179 לתקנות 2018, תקנה 528 לתקנות 1984) מאפשרות הארכת מועד להגשת ערעור מטעמים מיוחדים.', 4);

END $$;

