-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q32';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q32 skipped: external_id % already exists', '2024-W-Q32';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q32', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'מהו הדין לעניין הפסקת תובענה בהליך אזרחי לבקשת התובע?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 32}'::jsonb,
    'שאלה זו עוסקת בהוראות תקנה 44 לתקנות סדר הדין האזרחי, התשע"ט-2018, המסדירה את הפסקת תובענה לבקשת התובע. היא מבהירה כי הפסקת תובענה נעשית על דרך של מחיקת כתב התביעה, וכי בית המשפט רשאי להיעתר לבקשה זו, אך אינו חייב, וביכולתו להתנות את ההפסקה בתנאים.',
    'תקנה 44(א) לתקנות סדר הדין האזרחי, התשע"ט-2018, קובעת במפורש כי "בית המשפט רשאי, לבקשת תובע, להפסיק תובענה, כולה או מקצתה". תקנה 44(ב) מוסיפה כי "הפסקת תובענה תהיה על דרך של מחיקת כתב התביעה ותחול תקנה 41(ב) ו-(ג)". משמעות הדבר היא שהפסקת תובענה אינה יוצרת מעשה בית דין (תקנה 41(ב)), וכי בית המשפט רשאי להתנות את המחיקה בתנאים (תקנה 41(ג)). הפסיקה קבעה כי אף שהתובע הוא "אדון תביעתו", בית המשפט אינו חייב להיעתר לבקשה להפסקת תובענה, ובבואו להכריע בבקשה עליו לשקול שיקולים שונים, כגון השלב הדיוני של ההליך, האינטרס הציבורי במניעת השחתת משאבי שיפוט, והחשש לשימוש לרעה בהליך וקיפוח זכויות הנתבע. תקנה 44(א) לתקנות סדר הדין האזרחי, תשע"ט-2018תקנה 44(ב) לתקנות סדר הדין האזרחי, תשע"ט-2018ע"א 3018/23 פלוני נ'' אלמונית (14.11.2023)ת"א (שלום ב"ש) 29735-06-19 בטחה מושב עובדים נ'' יפת אברהם (30.05.2021)יששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025) | פרק ו סילוק כתבי טענות',
    'הטעות הנפוצה היא לחשוב שהפסקת תובענה היא זכות מוחלטת של התובע, או שהיא יוצרת מעשה בית דין, מבלי להבין את שיקול הדעת של בית המשפט ואת ההבחנה בין מחיקה לדחייה.',
    '["הפסקת תובענה", "מחיקת כתב תביעה", "מעשה בית דין", "שיקול דעת בית המשפט", "תנאים להפסקת תובענה", "תקנות סדר הדין האזרחי"]'::jsonb,
    '**וריאציה 1 — סמכות בית המשפט:** האם בית המשפט חייב להיעתר לבקשת תובע להפסקת תובענה? ← לא, בית המשפט רשאי, אך לא חייב, ויכול להתנות את ההפסקה בתנאים (תקנה 44(א) לתקנות סדר הדין האזרחי; תאד"מ (שלום ת"א) 35949-10-23 פרידה לזר). **וריאציה 2 — נפקות הפסקה:** מהי הנפקות של הפסקת תובענה? ← היא על דרך מחיקת כתב התביעה ואינה מהווה מעשה בית דין (תקנה 44(ב) לתקנות סדר הדין האזרחי). **וריאציה 3 — תנאים למחיקה:** האם בית המשפט רשאי להתנות את המחיקה בתנאים? ← כן, בית המשפט רשאי להתנות את מחיקת התביעה בתנאים, כולל קביעה שהדיון בתביעה חדשה יימשך מהשלב שבו נמחקה התביעה הנוכחית (תקנה 41(ג)(2) לתקנות סדר הדין האזרחי).',
    'הפסקת תובענה ← לבקשת תובע ← על דרך מחיקת כתב התביעה ← אינה מעשה בית דין ← בית המשפט רשאי להתנות בתנאים.',
    '["תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 41(ב)", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 41(ג)", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 44", "תאד\"מ (שלום ת\"א) 35949-10-23 פרידה לזר נ'' איי.די.איי. חברה לביטוח בע\"מ (24.12.2025)", "ע\"א 3018/23 פלוני נ'' אלמונית (14.11.2023)", "ת\"א (שלום ב\"ש) 29735-06-19 בטחה מושב עובדים נ'' יפת אברהם (30.05.2021)", "יששכר רוזן-צבי, הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025), פרק ו סילוק כתבי טענות"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט רשאי, לבקשת תובע, להפסיק תובענה, כולה או מקצתה; הפסקת תובענה תהיה על דרך של מחיקת כתב התביעה.', true, 'זו התשובה הנכונה. תקנה 44(א) ו-(ב) לתקנות סדר הדין האזרחי, התשע"ט-2018, קובעת כי בית המשפט רשאי להפסיק תובענה לבקשת תובע, והפסקתה תהיה על דרך מחיקת כתב התביעה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט רשאי, לבקשת תובע או מיוזמתו, להפסיק תובענה, כולה או מקצתה; הפסקת תובענה תהיה על דרך של מחיקת כתב התביעה.', false, 'תשובה זו שגויה. תקנה 44(א) קובעת כי הפסקת תובענה היא ''לבקשת תובע'', ולא מיוזמת בית המשפט. מחיקת תובענה יכולה להיות מיוזמת בית המשפט, אך לא הפסקתה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט רשאי, לבקשת תובע, להפסיק תובענה, כולה או מקצתה; הפסקת תובענה תהיה על דרך של דחיית כתב התביעה.', false, 'תשובה זו שגויה. הפסקת תובענה היא על דרך של מחיקת כתב התביעה, ולא דחייתו. דחייה יוצרת מעשה בית דין, בעוד מחיקה אינה יוצרת.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט רשאי, לבקשת תובע או מיוזמתו, להפסיק תובענה, כולה או מקצתה; הפסקת תובענה תהיה על דרך של דחיית כתב התביעה.', false, 'תשובה זו שגויה. הפסקת תובענה היא לבקשת תובע בלבד, ועל דרך מחיקת כתב התביעה, לא דחייתו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'הפסקת תובענה בתנאים: יתרון דיוני לנתבע', 1, 'תובע הגיש תביעה נגד נתבע. במהלך ההליך, הוגשה חוות דעת מומחה מטעם בית המשפט התומכת באופן מובהק בעמדת הנתבע. התובע, שחשש מתוצאות ההליך, ביקש להפסיק את התובענה. מהם השיקולים שבית המשפט יבחן, והאם רשאי הוא להתנות את הפסקת התובענה בתנאים?',
    'שאלה זו עוסקת בשיקול דעתו של בית המשפט בבואו לאשר בקשה להפסקת תובענה, במיוחד כאשר לנתבע נוצר יתרון דיוני משמעותי. היא מדגישה את סמכות בית המשפט להתנות את הפסקת התובענה בתנאים, שמטרתם למנוע מהתובע לנצל לרעה את ההליך ולעקוף יתרונות שרכש הנתבע.',
    'תקנה 44(א) לתקנות סדר הדין האזרחי, התשע"ט-2018, קובעת כי בית המשפט רשאי, לבקשת תובע, להפסיק תובענה. הפסקת תובענה היא על דרך של מחיקת כתב התביעה (תקנה 44(ב)), ומחיקה זו אינה מהווה מעשה בית דין (תקנה 41(ב)). עם זאת, בית המשפט רשאי להתנות את המחיקה בתנאים (תקנה 41(ג)). הפסיקה קבעה כי כאשר מונחת בפני בית המשפט בקשת תובע להפסקת תובענה, עליו לבחון אם לא יהיה בקבלת הבקשה כדי לפגוע ביתרון מהותי או דיוני ממשי שרכש הנתבע, והאם אין בבקשת התובע שימוש לרעה בהליכי משפט. במקרה של חוות דעת מומחה מטעם בית המשפט התומכת בעמדת הנתבע, מדובר ביתרון דיוני קבוע שהתובע מנסה לעקוף. לכן, בית המשפט רשאי להתנות את הפסקת התובענה בתנאים שימנעו מן התובע למנוע מן הנתבע את אותו יתרון דיוני, למשל, על ידי קביעה שחוות הדעת תחייב גם בהליך עתידי. תאד"מ (שלום ת"א) 35949-10-23 פרידה לזר נ'' איי.די.איי. חברה לביטוח בע"מ (24.12.2025)יששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025) | פרק ו סילוק כתבי טענותיששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025) | פרק ו סילוק כתבי טענותת"א (שלום ב"ש) 29735-06-19 בטחה מושב עובדים נ'' יפת אברהם (30.05.2021)',
    'הטעות הנפוצה היא לחשוב שהתובע רשאי להפסיק תובענה ללא כל מגבלה, מבלי להכיר בסמכות בית המשפט להתנות את ההפסקה בתנאים כדי למנוע פגיעה בנתבע או שימוש לרעה בהליך.',
    '["הפסקת תובענה", "מחיקת כתב תביעה", "תנאים להפסקת תובענה", "יתרון דיוני", "שימוש לרעה בהליך", "חוות דעת מומחה", "תקנות סדר הדין האזרחי"]'::jsonb,
    '**וריאציה 1 — יתרון דיוני קבוע:** תובע מבקש להפסיק תובענה לאחר שחוות דעת מומחה תמכה בנתבע. האם בית המשפט יתנה את ההפסקה? ← כן, בתנאים שימנעו מהתובע לעקוף את היתרון הדיוני הקבוע של הנתבע (יששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים). **וריאציה 2 — יתרון דיוני זמני:** האם חולשה זמנית בראיות התובע מהווה יתרון דיוני המחייב תנאים? ← לא, חולשה זמנית אינה מצדיקה התניית הפסקה בתנאים שיאסרו על התובע להביא ראיות אלו בעתיד (יששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים). **וריאציה 3 — מטרת התנאים:** מהי מטרת התנאים להפסקת תובענה? ← למנוע מהתובע לנצל לרעה את יכולתו להפסיק תובענה ולהגיש תחתיה תובענה חדשה באותה עילה, כדי למנוע מהנתבע יתרון דיוני או מהותי שרכש (יששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים).',
    'הפסקת תובענה ← בית המשפט רשאי להתנות בתנאים ← למנוע פגיעה ביתרון דיוני של הנתבע או שימוש לרעה בהליך.',
    '["תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 41(ב)", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 41(ג)", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 44(א)", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 44(ב)", "תאד\"מ (שלום ת\"א) 35949-10-23 פרידה לזר נ'' איי.די.איי. חברה לביטוח בע\"מ (24.12.2025)", "ת\"א (שלום ב\"ש) 29735-06-19 בטחה מושב עובדים נ'' יפת אברהם (30.05.2021)", "יששכר רוזן-צבי, הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025), פרק ו סילוק כתבי טענות"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'שיקולי בית המשפט בבקשה להפסקת תובענה', 2, 'מהם השיקולים המרכזיים שבית המשפט שוקל בבואו לבחון בקשה של תובע להפסקת תובענה?',
    'שאלה זו מתמקדת בשיקולים המנחים את בית המשפט בבחינת בקשה להפסקת תובענה. היא מפרטת את העקרונות המרכזיים שנקבעו בפסיקה, המאזנים בין זכות התובע להפסיק את תביעתו לבין האינטרס הציבורי במניעת השחתת משאבי שיפוט והגנה על זכויות הנתבע מפני שימוש לרעה בהליך.',
    'הלכה פסוקה היא כי כאשר מוגשת בקשה להפסקת תובענה, בית המשפט אינו פועל באופן אוטומטי, אלא מפעיל שיקול דעת. שיקולים מרכזיים שעל בית המשפט לשקול בבואו לבחון בקשה להפסקת תובענה הם השלב הדיוני שבו מצוי ההליך והאינטרס הציבורי במניעת השחתת משאבי השיפוט; והחשש לשימוש לרעה וקיפוח זכויותיו הדיוניות והמהותיות של הנתבע. ככל שההליך מצוי בשלב מתקדם יותר, כך יגדל משקלם של שיקולים אלו. שימוש לרעה יכול להתבטא בניסיון ל"מקצה שיפורים" לאחר שהתברר שהתוצאה נוטה נגד התובע, או בניסיון ל"פורום שופינג" (forum shopping) על ידי הגשת התביעה מחדש בבית משפט אחר. ע"א 3018/23 פלוני נ'' אלמונית (14.11.2023)ע"א 3975/21 מדינת ישראל - משרד הבריאות נ'' אי.סיג בע"מ (20.03.2022)ע"א 2230/21 אסף אביזוהר נ'' יואל לוליאן (30.05.2021)יששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025) | פרק ו סילוק כתבי טענות',
    'הטעות הנפוצה היא להתמקד רק בזכות התובע להפסיק את תביעתו, מבלי להבין את מכלול השיקולים המורכבים שבית המשפט מפעיל, ובמיוחד את האיזון בין זכות זו לבין זכויות הנתבע והאינטרס הציבורי.',
    '["הפסקת תובענה", "שיקול דעת בית המשפט", "שלב דיוני", "אינטרס ציבורי", "שימוש לרעה בהליך", "קיפוח זכויות הנתבע", "פורום שופינג", "מקצה שיפורים"]'::jsonb,
    '**וריאציה 1 — שיקולים מרכזיים:** מהם השיקולים המרכזיים בבקשה להפסקת תובענה? ← השלב הדיוני, אינטרס ציבורי במניעת השחתת משאבי שיפוט, וחשש לשימוש לרעה וקיפוח זכויות הנתבע (ע"א 3018/23 פלוני נ'' אלמונית). **וריאציה 2 — שלב דיוני מתקדם:** כיצד משפיע שלב דיוני מתקדם על בקשה להפסקת תובענה? ← ככל שההליך מתקדם יותר, כך תבחן הבקשה בכובד ראש רב יותר, מחשש להשחתת משאבים (ת"א (מחוזי ת"א) 24153-09-21 קליפורניה ישראל נדל"ן בע"מ נ'' חנן וקסמן). **וריאציה 3 — שימוש לרעה:** מהו שימוש לרעה בהליך בהקשר זה? ← ניסיון ל"מקצה שיפורים" או "פורום שופינג" לאחר שהתוצאה נוטה נגד התובע (ע"א 3975/21 מדינת ישראל - משרד הבריאות נ'' אי.סיג בע"מ).',
    'שיקולים להפסקת תובענה ← שלב דיוני, אינטרס ציבורי, מניעת שימוש לרעה וקיפוח זכויות הנתבע.',
    '["ע\"א 3018/23 פלוני נ'' אלמונית (14.11.2023)", "ע\"א 3975/21 מדינת ישראל - משרד הבריאות נ'' אי.סיג בע\"מ (20.03.2022)", "ע\"א 2230/21 אסף אביזוהר נ'' יואל לוליאן (30.05.2021)", "ת\"א (מחוזי ת\"א) 24153-09-21 קליפורניה ישראל נדל\"ן בע\"מ נ'' חנן וקסמן (07.02.2022)", "יששכר רוזן-צבי, הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025), פרק ו סילוק כתבי טענות"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'סירוב לבקשה להפסקת תובענה ודחייתה', 3, 'תובע הגיש בקשה להפסקת תובענה, אך בית המשפט סירב לבקשה, בין היתר משום שהבקשה הוגשה בשלב מתקדם של ההליך ונועדה ל"פורום שופינג". התובע, בתגובה, הודיע כי אינו מעוניין להמשיך בניהול התביעה. מה רשאי בית המשפט לעשות במצב זה?',
    'שאלה זו בוחנת את סמכות בית המשפט במקרה שבו תובע מבקש להפסיק תובענה, בקשתו נדחית, והוא מסרב להמשיך בניהול ההליך. היא מדגישה את סמכות בית המשפט לדחות את התובענה במצב כזה, מה שיוצר מעשה בית דין ומונע הגשת תביעה נוספת באותה עילה, במיוחד כאשר מדובר בניסיון לשימוש לרעה בהליכי משפט.',
    'תקנה 44(א) לתקנות סדר הדין האזרחי, התשע"ט-2018, קובעת כי בית המשפט רשאי, לבקשת תובע, להפסיק תובענה. עם זאת, בית המשפט אינו חייב להיעתר לבקשה, במיוחד אם הוא סבור שהבקשה מהווה שימוש לרעה בהליכי משפט, למשל, ניסיון ל"פורום שופינג" או "מקצה שיפורים" בשלב מתקדם של ההליך. אם בית המשפט סירב לבקשת התובע להפסיק את התובענה, אך התובע בחר שלא להמשיך בה, בית המשפט רשאי לדחות את התובענה. דחיית תובענה, בניגוד למחיקתה, יוצרת מעשה בית דין ומונעת הגשת תביעה נוספת בגין אותה עילה. אף שתקנות 2018 אינן כוללות הוראה מפורשת בדומה לתקנה 154(ג) לתקנות 1984, הפסיקה קבעה כי ניתן לקרוא סמכות זו לתוך תקנה 43 לתקנות החדשות, המאפשרת לבית המשפט לדחות תובענה "מכל נימוק אחר, שלפיו הוא סבור כי ראוי ונכון לדחות את התביעה". תאד"מ (שלום ת"א) 35949-10-23 פרידה לזר נ'' איי.די.איי. חברה לביטוח בע"מ (24.12.2025)יששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025) | פרק ו סילוק כתבי טענותיששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025) | פרק ו סילוק כתבי טענותת"א (שלום נצ'') 45682-12-18 פלונית נ'' מדינת ישראל - משרד הבריאות (30.03.2022)',
    'הטעות הנפוצה היא לחשוב שסירוב בית המשפט לבקשה להפסקת תובענה מחייב את התובע להמשיך בהליך, או שתוצאת הסירוב היא תמיד מחיקה ללא מעשה בית דין, מבלי להכיר בסמכות בית המשפט לדחות את התובענה במקרים אלו.',
    '["הפסקת תובענה", "סירוב לבקשה", "דחיית תובענה", "מעשה בית דין", "שימוש לרעה בהליך", "פורום שופינג", "תקנה 43 לתקסד\"א"]'::jsonb,
    '**וריאציה 1 — סירוב להפסקה:** בית המשפט סירב לבקשה להפסקת תובענה והתובע לא המשיך. מה רשאי בית המשפט לעשות? ← לדחות את התובענה, מה שיוצר מעשה בית דין (תאד"מ (שלום ת"א) 35949-10-23 פרידה לזר). **וריאציה 2 — סמכות לדחות:** מאיזו תקנה נובעת סמכות בית המשפט לדחות תובענה במצב זה? ← מתקנה 43 לתקנות החדשות, המאפשרת דחייה מ"כל נימוק אחר" (יששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים). **וריאציה 3 — מקרים פרדיגמטיים:** מתי בית המשפט יסרב לבקשה להפסקת תובענה? ← כאשר הבקשה הוגשה ל"פורום שופינג" או כדי לעקוף החלטה שלא לאפשר תיקון כתב טענות (יששכר רוזן-צבי הרפורמה בסדר הדין האזרחי: מורה נבוכים).',
    'סירוב להפסקת תובענה + אי-המשך התובענה ← בית המשפט רשאי לדחותה ← יוצר מעשה בית דין.',
    '["תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 43", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 44(א)", "תאד\"מ (שלום ת\"א) 35949-10-23 פרידה לזר נ'' איי.די.איי. חברה לביטוח בע\"מ (24.12.2025)", "ת\"א (שלום נצ'') 45682-12-18 פלונית נ'' מדינת ישראל - משרד הבריאות (30.03.2022)", "יששכר רוזן-צבי, הרפורמה בסדר הדין האזרחי: מורה נבוכים (2025), פרק ו סילוק כתבי טענות"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'הפסקת תובענה מול מחיקה מינהלית מחוסר מעש', 4, 'מהו ההבדל המהותי בין הפסקת תובענה לבקשת התובע לבין מחיקת תובענה מחוסר מעש?',
    'שאלה זו מבחינה בין שני מנגנונים לסיום הליך אזרחי: הפסקת תובענה לבקשת התובע ומחיקה מינהלית מחוסר מעש. היא מדגישה את ההבדל המהותי ביוזמה לכל אחד מההליכים, תוך ציון הנפקות הדיונית הדומה של שניהם בכך שאינם יוצרים מעשה בית דין ומאפשרים הגשת תביעה חדשה.',
    'הפסקת תובענה מעוגנת בתקנה 44 לתקנות סדר הדין האזרחי, התשע"ט-2018, ונעשית לבקשת התובע. הפסקת תובענה תהיה על דרך של מחיקת כתב התביעה (תקנה 44(ב)), ומחיקה זו אינה מהווה מעשה בית דין (תקנה 41(ב)). לעומת זאת, מחיקה מינהלית מחוסר מעש מעוגנת בתקנה 45 לתקנות החדשות (או תקנה 156 לתקנות 1984), ונעשית ביוזמת בית המשפט או המזכירות, כאשר לא נעשה כל מעש מצד בעל דין במשך תקופה מסוימת. גם מחיקה מחוסר מעש אינה מהווה מעשה בית דין. ההבדל המהותי הוא ביוזמה: הפסקת תובענה היא פעולה יזומה של התובע, בעוד מחיקה מחוסר מעש היא פעולה יזומה של המערכת עקב חוסר פעילות של התובע. תקנה 44(א) לתקנות סדר הדין האזרחי, תשע"ט-2018תקנה 44(ב) לתקנות סדר הדין האזרחי, תשע"ט-2018תקנה 41(ב) לתקנות סדר הדין האזרחי, תשע"ט-2018תקנה 45(א) לתקנות סדר הדין האזרחי, תשע"ט-2018ת"א (מחוזי חיפה) 52193-01-20 יוסף סגמן נ'' סינוגה מדיקל בע"מ (27.07.2020)',
    'הטעות הנפוצה היא לבלבל בין הפסקת תובענה למחיקה מחוסר מעש, או לחשוב שאחת מהן יוצרת מעשה בית דין בעוד השנייה לא, מבלי להבין שההבדל העיקרי הוא ביוזמה לפעולה.',
    '["הפסקת תובענה", "מחיקה מינהלית", "חוסר מעש", "יוזמת הפעולה", "מעשה בית דין", "הגשת תביעה חדשה", "תקנות סדר הדין האזרחי"]'::jsonb,
    '**וריאציה 1 — יוזמת הפעולה:** מי יוזם הפסקת תובענה ומי יוזם מחיקה מחוסר מעש? ← הפסקת תובענה: התובע. מחיקה מחוסר מעש: בית המשפט/מזכירות (תקנה 44(א) לתקנות סדר הדין האזרחי; תקנה 45(א) לתקנות סדר הדין האזרחי). **וריאציה 2 — נפקות מעשה בית דין:** האם הפסקת תובענה או מחיקה מחוסר מעש יוצרות מעשה בית דין? ← לא, שתיהן אינן יוצרות מעשה בית דין ומאפשרות הגשת תביעה חדשה (תקנה 41(ב) לתקנות סדר הדין האזרחי; ת"א (מחוזי חיפה) 52193-01-20 יוסף סגמן). **וריאציה 3 — חידוש הליך:** מהי המשמעות של "חידוש" תובענה שהופסקה? ← אין מדובר בהחייאת התביעה שהופסקה אלא בהגשת תביעה חדשה לכל דבר ועניין, שיינתן לה מספר תיק חדש (יעקב שקד סדר הדין האזרחי).',
    'הפסקת תובענה ← יוזמת תובע. מחיקה מחוסר מעש ← יוזמת בית המשפט/מזכירות. שתיהן ← מחיקה, לא מעשה בית דין.',
    '["תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 41(ב)", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 44", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 45", "תקנות סדר הדין האזרחי, תשמ\"ד-1984, תקנה 156", "ת\"א (מחוזי חיפה) 52193-01-20 יוסף סגמן נ'' סינוגה מדיקל בע\"מ (27.07.2020)", "יעקב שקד, סדר הדין האזרחי (2026), פרק ה כתבי טענות - סילוק ותיקון"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'בית המשפט יאשר את הפסקת התובענה ללא תנאים, שכן התובע הוא אדון תביעתו ורשאי להפסיקה בכל עת.', false, 'תשובה זו שגויה. אף שהתובע הוא אדון תביעתו, בית המשפט אינו חייב לאשר הפסקה ללא תנאים, במיוחד כאשר לנתבע נוצר יתרון דיוני משמעותי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'בית המשפט יבחן אם הפסקת התובענה תפגע ביתרון דיוני מהותי שרכש הנתבע, ורשאי להתנות את ההפסקה בתנאים שימנעו מהתובע לעקוף יתרון זה, כגון קביעה שחוות הדעת תחייב גם בהליך עתידי.', true, 'זו התשובה הנכונה. הפסיקה קובעת כי בית המשפט יבחן את הפגיעה בנתבע ואת החשש לשימוש לרעה בהליך, ורשאי להתנות את ההפסקה בתנאים שישמרו את היתרון הדיוני של הנתבע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'בית המשפט יסרב לבקשה להפסקת התובענה ויחייב את התובע להמשיך בניהול ההליך, שכן מדובר בניסיון לשימוש לרעה בהליכי משפט.', false, 'תשובה זו שגויה. אף שבית המשפט רשאי לסרב לבקשה, הוא אינו חייב לעשות זאת. לרוב, הוא יתנה את ההפסקה בתנאים, אלא אם כן לא ניתן להגן על הנתבע באמצעות תנאים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'בית המשפט יורה על דחיית התובענה, שכן התובע מנסה להתחמק מהכרעה שנוטה נגדו.', false, 'תשובה זו שגויה. דחיית תובענה במקרה כזה היא צעד קיצוני השמור למקרים חריגים ויוצאי דופן של שימוש לרעה חמור בהליכי משפט, ולא דרך המלך.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'השלב הדיוני שבו מצוי ההליך, האינטרס הציבורי במניעת השחתת משאבי שיפוט, והחשש לשימוש לרעה וקיפוח זכויותיו הדיוניות והמהותיות של הנתבע.', true, 'זו התשובה הנכונה. אלו הם השיקולים המרכזיים שנקבעו בפסיקת בית המשפט העליון לבחינת בקשה להפסקת תובענה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'רק סיכויי התביעה של התובע, שכן אם סיכויי התביעה נמוכים, יש לאפשר לו להפסיק את התובענה ללא תנאים.', false, 'תשובה זו שגויה. סיכויי התביעה אינם השיקול הבלעדי, ובית המשפט בוחן מכלול רחב של שיקולים, כולל זכויות הנתבע והאינטרס הציבורי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'רק הסכמת הנתבע להפסקת התובענה, שכן ללא הסכמתו, בית המשפט אינו רשאי להפסיק את התובענה.', false, 'תשובה זו שגויה. בית המשפט רשאי להפסיק תובענה גם ללא הסכמת הנתבע, תוך הפעלת שיקול דעת וקביעת תנאים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'רק גובה ההוצאות שנגרמו לנתבע עד כה, ובית המשפט יתנה את ההפסקה בתשלום הוצאות אלו בלבד.', false, 'תשובה זו שגויה. גובה ההוצאות הוא שיקול חשוב, אך אינו השיקול היחיד, ובית המשפט בוחן גם שיקולים דיוניים ומהותיים נוספים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'בית המשפט יורה על מחיקת התובענה, שכן הפסקת תובענה היא תמיד על דרך מחיקה.', false, 'תשובה זו שגויה. במקרה של סירוב לבקשת הפסקה והתובע אינו ממשיך, בית המשפט רשאי לדחות את התובענה, ולא רק למחוק אותה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בית המשפט רשאי לדחות את התובענה, באופן היוצר מעשה בית דין ומונע הגשת תביעה נוספת בגין אותה עילה.', true, 'זו התשובה הנכונה. כאשר בית המשפט מסרב לבקשה להפסקת תובענה והתובע אינו ממשיך בה, בית המשפט רשאי לדחות את התובענה, מה שיוצר מעשה בית דין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט יחייב את התובע להמשיך בניהול ההליך, שכן אין לו סמכות לדחות תובענה במצב זה.', false, 'תשובה זו שגויה. בית המשפט אינו יכול לחייב תובע להמשיך בהליך, אך יש לו סמכות לדחות את התובענה אם התובע מסרב להמשיך.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בית המשפט יורה על עיכוב ההליכים בתובענה עד שהתובע יחליט אם ברצונו להמשיך בה.', false, 'תשובה זו שגויה. עיכוב הליכים אינו הפתרון המתאים במצב שבו התובע הודיע במפורש על אי-רצונו להמשיך, ובית המשפט כבר סירב לבקשת ההפסקה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'הפסקת תובענה היא תמיד על דרך דחייה, בעוד מחיקה מחוסר מעש היא תמיד על דרך מחיקה.', false, 'תשובה זו שגויה. הפסקת תובענה היא על דרך מחיקה, לא דחייה. מחיקה מחוסר מעש היא גם מחיקה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'הפסקת תובענה נעשית לבקשת התובע, בעוד מחיקה מחוסר מעש נעשית ביוזמת בית המשפט או המזכירות, לאחר שלא נעשה מעש בהליך.', true, 'זו התשובה הנכונה. ההבדל המהותי טמון ביוזמה לפעולה: הפסקת תובענה היא יוזמת התובע, בעוד מחיקה מחוסר מעש היא יוזמה חיצונית עקב חוסר פעילות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'הפסקת תובענה יוצרת מעשה בית דין, בעוד מחיקה מחוסר מעש אינה יוצרת מעשה בית דין.', false, 'תשובה זו שגויה. הן הפסקת תובענה (על דרך מחיקה) והן מחיקה מחוסר מעש אינן יוצרות מעשה בית דין, ומאפשרות הגשת תביעה חדשה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'הפסקת תובענה מאפשרת הגשת תביעה חדשה באותה עילה, בעוד מחיקה מחוסר מעש מונעת זאת.', false, 'תשובה זו שגויה. הן הפסקת תובענה והן מחיקה מחוסר מעש מאפשרות הגשת תביעה חדשה באותה עילה, שכן שתיהן אינן יוצרות מעשה בית דין.', 4);

END $$;

-- ============================================================
-- Q34 — 2024-W-Q34 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q34';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q34 skipped: external_id % already exists', '2024-W-Q34';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q34', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'בהליך פלילי, בעלי הדין סיימו את הבאת ראיותיהם, ואולם בית המשפט ראה צורך להורות על הזמנת עד שעדותו כבר נשמעה בבית המשפט. מה הדין?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 34}'::jsonb,
    'שאלה זו עוסקת בסמכות בית המשפט בהליך פלילי להורות על הזמנת עדים או הבאת ראיות נוספות, גם לאחר שבעלי הדין סיימו את פרשת הראיות, ואף אם העד כבר העיד. היא מתבססת על סעיף 167 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, המאפשר לבית המשפט להפעיל סמכות זו הן לבקשת בעלי הדין והן מיוזמתו, אם ראה צורך בכך.',
    'סעיף 167 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע כי "סיימו בעלי הדין הבאת ראיותיהם, רשאי בית המשפט, אם ראה צורך בכך, להורות על הזמנת עד – ואפילו כבר נשמעה עדותו בפני בית המשפט – ועל הבאת ראיות אחרות, אם לבקשת בעלי דין ואם מיוזמת בית המשפט". הוראה זו מבטאת את האיזון בין עקרון סופיות הדיון וסדרי הדין לבין הצורך בגילוי האמת ומניעת עיוות דין. הפסיקה הדגישה כי הפעלת סמכות זו אינה עניין שבשגרה, וככל שההליך מתקדם יותר, כך תהא נדירה וחריגה יותר היזקקות בית המשפט לה. עם זאת, הסמכות קיימת תמיד, ובית המשפט ישקול את צורכי הנאשם מזה ואת צורכי החברה מזה, תוך העמדת השיקול של מניעת עיוות דין לנאשם בראש מעייניו. סעיף 167 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982ע"פ 8507/18 פלוני נ'' מדינת ישראל (09.09.2020)ע"פ 8507/18 פלוני נ'' מדינת ישראל (09.09.2020)פסיקה צבאית יהודה 2301/12 התביעה הצבאית נ'' פלוני קטין (01.11.2012)נבו - המתמחה סדר הדין הפלילי (2026) | פרק יב - בירור האשמה',
    'הטעות הנפוצה היא לחשוב שסמכות בית המשפט לזמן עדים או להביא ראיות נוספות מוגבלת רק לבקשת הצדדים, או שהיא אינה חלה על עדים שכבר העידו, מבלי להכיר בלשון הרחבה של סעיף 167 ובפרשנות הפסיקה.',
    '["סעיף 167 לחוק סדר הדין הפלילי", "הזמנת עד", "הבאת ראיות נוספות", "יוזמת בית המשפט", "בקשת בעלי דין", "גילוי האמת", "מניעת עיוות דין", "סופיות הדיון"]'::jsonb,
    '**וריאציה 1 — סמכות בית המשפט:** האם בית המשפט רשאי לזמן עד שכבר העיד לאחר סיום פרשת הראיות? ← כן, אם ראה צורך בכך, לבקשת בעלי דין או מיוזמתו (סעיף 167 לחוק סדר הדין הפלילי). **וריאציה 2 — תכלית הסמכות:** מהי התכלית העליונה של סמכות זו? ← מניעת עיוות דין, העלול להיגרם לנאשם או לאינטרס הציבורי (פסיקה צבאית יהודה 2301/12 התביעה הצבאית נ'' פלוני קטין (01.11.2012)). **וריאציה 3 — חריג או כלל:** האם הפעלת סמכות זו היא עניין שבשגרה? ← לא, הפעלת שיקול דעת זה אינה צריכה להיות עניין שבשגרה, והיא נדירה וחריגה יותר ככל שההליך מתקדם (ע"פ 8507/18 פלוני נ'' מדינת ישראל (09.09.2020)).',
    'סעיף 167 חסד"פ ← בית המשפט רשאי לזמן עד/ראיה נוספת (גם עד שכבר העיד) ← לבקשת צד או מיוזמתו ← לאחר סיום פרשת ראיות ← למניעת עיוות דין, אך בזהירות ובחריגות.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 167", "ע\"פ 8507/18 פלוני נ'' מדינת ישראל (09.09.2020)", "פסיקה צבאית יהודה 2301/12 התביעה הצבאית נ'' פלוני קטין (01.11.2012)", "ע\"פ 6949/07 רועי עמרם נ'' מדינת ישראל (08.07.2009)", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יב - בירור האשמה", "אמנון כרמי, בריאות ומשפט (2013), פרק ב: הרופא בבית המשפט"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט אינו רשאי לזמן את אותו העד.', false, 'תשובה זו שגויה. סעיף 167 לחוק סדר הדין הפלילי מעניק לבית המשפט סמכות מפורשת לזמן עד, גם אם עדותו כבר נשמעה, לאחר שבעלי הדין סיימו את הבאת ראיותיהם.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט אינו רשאי לזמן את אותו העד, אלא בהסכמת בעלי הדין.', false, 'תשובה זו שגויה. סעיף 167 לחוק סדר הדין הפלילי מאפשר לבית המשפט לזמן עד מיוזמתו, ללא צורך בהסכמת בעלי הדין, אם ראה צורך בכך.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט רשאי לזמן את אותו העד רק לבקשת בעלי דין ולא מיוזמת בית המשפט.', false, 'תשובה זו שגויה. סעיף 167 לחוק סדר הדין הפלילי קובע במפורש כי בית המשפט רשאי לזמן עד "אם לבקשת בעלי דין ואם מיוזמת בית המשפט".', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט רשאי לזמן את אותו העד אם לבקשת בעלי הדין ואם מיוזמת בית המשפט.', true, 'זו התשובה הנכונה. סעיף 167 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע כי לאחר שבעלי הדין סיימו את הבאת ראיותיהם, רשאי בית המשפט, אם ראה צורך בכך, להורות על הזמנת עד – ואפילו כבר נשמעה עדותו – אם לבקשת בעלי דין ואם מיוזמתו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'הגשת ראיות נוספות בשלב הערעור', 1, 'התביעה מבקשת להגיש ראיה חדשה בשלב הערעור, לאחר שכל הראיות נשמעו בערכאה הדיונית. מהם השיקולים המרכזיים שבית המשפט יבחן בבואו להכריע בבקשה זו?',
    'שאלה זו עוסקת בסמכות בית המשפט לקבל ראיות נוספות בשלב הערעור, בהתאם לסעיף 211 לחוק סדר הדין הפלילי. היא מדגישה את שלושת השיקולים המרכזיים שנקבעו בפסיקה לבחינת בקשות מסוג זה: יכולת השגת הראיה בערכאה קודמת, עקרון סופיות הדיון, וטיבן של הראיות החדשות והסיכוי שישנו את התוצאה.',
    'סעיף 211 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע כי "בית המשפט רשאי, אם היה סבור כי הדבר דרוש לעשיית צדק, לגבות ראיות או להורות לערכאה הקודמת לגבות ראיות שיורה". סמכות זו, אף שהיא רחבה, מופעלת במשורה ובזהירות רבה, שכן שלב הערעור אינו מיועד להבאת ראיות חדשות. הפסיקה קבעה שלושה שיקולים עיקריים שעל בית המשפט לבחון בבואו להכריע האם להתיר הגשת ראיות נוספות בשלב הערעור: ראשית, אם היה באפשרותו של המבקש להשיג את הראיות הנוספות במהלך הדיון בערכאה הקודמת; שנית, האינטרס בדבר השמירה על עקרון סופיות הדיון; שלישית, טיבן של הראיות הנוספות והסיכוי שהגשתן תביא לשינוי התוצאה שאליה הגיעה הערכאה הקודמת. סעיף 211 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982יניב ואקי דיני ראיות כרך א (2020) | פרק 6 - כללי קבילותיניב ואקי דיני ראיות כרך א (2020) | פרק 6 - כללי קבילות',
    'הטעות הנפוצה היא לחשוב ששלב הערעור הוא הזדמנות נוספת להבאת ראיות, מבלי להבין את אופיו החריג של הליך זה ואת השיקולים המגבילים את הפעלת הסמכות.',
    '["ראיות נוספות", "שלב הערעור", "סעיף 211 לחוק סדר הדין הפלילי", "סופיות הדיון", "גילוי האמת", "עשיית צדק", "יכולת השגה"]'::jsonb,
    '**וריאציה 1 — תנאים לקבלת ראיה בערעור:** מהם התנאים לקבלת ראיה חדשה בשלב הערעור? ← יכולת השגה בערכאה קודמת, אינטרס סופיות הדיון, וסיכוי לשינוי התוצאה (יניב ואקי דיני ראיות כרך א). **וריאציה 2 — מטרת סעיף 211:** מהי מטרת סעיף 211 לחוק סדר הדין הפלילי? ← לאפשר גביית ראיות אם הדבר דרוש לעשיית צדק (סעיף 211 לחוק סדר הדין הפלילי). **וריאציה 3 — חריג או כלל:** האם הגשת ראיות בערעור היא כלל או חריג? ← חריג, המופעל במקרים נדירים ורק כאשר הדבר דרוש לעשיית צדק (יניב ואקי דיני ראיות כרך א).',
    'הגשת ראיות בערעור ← חריג (סעיף 211 חסד"פ) ← נבחן לפי יכולת השגה, סופיות דיון וסיכוי לשינוי תוצאה.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 211", "יניב ואקי, דיני ראיות כרך א (2020), פרק 6 - כללי קבילות"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'שיקולי בית המשפט בהפעלת סמכות 167', 2, 'מהם השיקולים המרכזיים שבית המשפט שוקל בבואו להפעיל את סמכותו לפי סעיף 167 לחוק סדר הדין הפלילי, ולהתיר הבאת ראיות נוספות או זימון עד שכבר העיד?',
    'שאלה זו מתמקדת בקריטריונים ובאיזונים שבית המשפט מפעיל בבואו להשתמש בסמכותו החריגה לפי סעיף 167 לחוק סדר הדין הפלילי. היא מדגישה את המתח בין עקרונות סופיות הדיון וסדרי הדין לבין הצורך בגילוי האמת ומניעת עיוות דין, תוך שמירה על זכויות הנאשם.',
    'סעיף 167 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, מקנה לבית המשפט סמכות להורות על הזמנת עד או הבאת ראיות אחרות לאחר שבעלי הדין סיימו את הבאת ראיותיהם. הפעלת סמכות זו אינה עניין שבשגרה, והיא מבטאת איזון בין שמירה על סדרי הדין של ניהול המשפט ועקרון סופיות הדיון, לבין הצורך לאפשר גמישות דיונית שמטרתה גילוי האמת ומניעת עיוות דין. ככל שהבקשה מוגשת בשלב מתקדם יותר של ההליך, כך תהא נדירה וחריגה יותר היזקקות בית המשפט להפעלת סמכות זו. בית המשפט יעמיד בראש מעייניו את השיקול שלא ייגרם עיוות דין לנאשם, כאשר עיוות דין משמעותו פגיעה ביכולתו של הנאשם להתגונן כראוי. ע"פ 8507/18 פלוני נ'' מדינת ישראל (09.09.2020)ע"פ 8507/18 פלוני נ'' מדינת ישראל (09.09.2020)ת"פ (מחוזי תל אביב-יפו) 39345-03-20 מדינת ישראל נ'' אריה ברכה (18.12.2020)ת"פ (שלום ת"א) 60221-06-21 מדינת ישראל נ'' שאול גבע דן ריזל (01.11.2023)נבו - המתמחה סדר הדין הפלילי (2026) | פרק יב - בירור האשמה',
    'הטעות הנפוצה היא להתמקד רק באחד השיקולים (למשל, גילוי האמת או סופיות הדיון) מבלי להבין את הצורך באיזון ביניהם, ובמיוחד את הדגש על מניעת עיוות דין לנאשם.',
    '["סעיף 167 לחוק סדר הדין הפלילי", "גילוי האמת", "מניעת עיוות דין", "סופיות הדיון", "שלב דיוני", "זכויות הנאשם", "איזון שיקולים"]'::jsonb,
    '**וריאציה 1 — תכלית הסמכות:** מהי התכלית העליונה של סמכות בית המשפט לפי סעיף 167? ← גילוי האמת ומניעת עיוות דין (פסיקה צבאית יהודה 2301/12 התביעה הצבאית נ'' פלוני קטין (01.11.2012)). **וריאציה 2 — עיוות דין לנאשם:** מהו "עיוות דין" בהקשר זה? ← פגיעה ביכולתו של הנאשם להתגונן כראוי (ע"פ 8507/18 פלוני נ'' מדינת ישראל (09.09.2020)). **וריאציה 3 — שלב ההליך:** כיצד משפיע שלב ההליך על הפעלת הסמכות? ← ככל שההליך מתקדם יותר, כך תהא הפעלת הסמכות נדירה וחריגה יותר (ת"פ (מחוזי תל אביב-יפו) 39345-03-20 מדינת ישראל נ'' אריה ברכה (18.12.2020)).',
    'סעיף 167 חסד"פ ← איזון בין גילוי אמת, מניעת עיוות דין לנאשם, סופיות דיון ושלב ההליך.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 167", "ע\"פ 8507/18 פלוני נ'' מדינת ישראל (09.09.2020)", "ת\"פ (מחוזי תל אביב-יפו) 39345-03-20 מדינת ישראל נ'' אריה ברכה (18.12.2020)", "ת\"פ (שלום ת\"א) 60221-06-21 מדינת ישראל נ'' שאול גבע דן ריזל (01.11.2023)", "פסיקה צבאית יהודה 2301/12 התביעה הצבאית נ'' פלוני קטין (01.11.2012)", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יב - בירור האשמה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'הבאת ראיות הזמה מטעם התביעה', 3, 'לאחר סיום פרשת התביעה ופרשת ההגנה, התביעה מבקשת להביא ראיות הזמה. באילו תנאים רשאי בית המשפט להרשות לתובע להביא ראיות אלו?',
    'שאלה זו עוסקת בחריג ספציפי לסדר הבאת הראיות בהליך הפלילי – הבאת ראיות הזמה (ראיות לסתור) מטעם התביעה. היא מתמקדת בתנאים הקבועים בסעיף 165 לחוק סדר הדין הפלילי, המאפשרים לתביעה להגיש ראיות אלו רק במקרים של טענות בלתי צפויות מצד ההגנה או חזרה מהודיה של הנאשם.',
    'סעיף 165 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע את התנאים להבאת ראיות הזמה (ראיות לסתור) מטעם התובע: "בית המשפט רשאי להרשות לתובע להביא ראיות לסתור טענות העולות מראיות ההגנה ואשר התובע לא יכול היה לצפותן מראש, או להוכיח עובדות שהנאשם חזר בו מהודייתו בהן לאחר סיום פרשת התביעה." כלומר, קיימים שני תנאים חלופיים: האחד, שהטענות עולות מראיות ההגנה והתובע לא יכול היה לצפותן מראש; השני, שהנאשם חזר בו מהודייתו בעובדות לאחר סיום פרשת התביעה. אם התביעה יכלה לצפות את טענות ההגנה מראש, אין היא רשאית להביא ראיות הזמה. סעיף 165 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982ת"פ (שלום ת"א) 4725-04-23 מדינת ישראל נ'' יניב הראל (03.09.2025)',
    'הטעות הנפוצה היא לבלבל בין סעיף 165 (ראיות הזמה) לסעיף 167 (ראיות מטעם בית המשפט), או לחשוב שהתביעה רשאית להביא ראיות נוספות בכל עת, מבלי לעמוד בתנאים הספציפיים של סעיף 165.',
    '["ראיות הזמה", "סעיף 165 לחוק סדר הדין הפלילי", "ציפייה מראש", "חזרה מהודיה", "פרשת התביעה", "פרשת ההגנה", "סדר הבאת ראיות"]'::jsonb,
    '**וריאציה 1 — תנאי ראשון:** מתי התביעה רשאית להביא ראיות הזמה? ← לסתור טענות העולות מראיות ההגנה ואשר התובע לא יכול היה לצפותן מראש (סעיף 165 לחוק סדר הדין הפלילי). **וריאציה 2 — תנאי שני:** מהו התנאי החלופי להבאת ראיות הזמה? ← להוכיח עובדות שהנאשם חזר בו מהודייתו בהן לאחר סיום פרשת התביעה (סעיף 165 לחוק סדר הדין הפלילי). **וריאציה 3 — ציפייה מראש:** אם התביעה יכלה לצפות את טענות ההגנה, האם תורשה להביא ראיות הזמה? ← לא, היכולת לצפות מראש היא תנאי מהותי, למעט במקרה של חזרה מהודיה (ת"פ (שלום ת"א) 4725-04-23 מדינת ישראל נ'' יניב הראל).',
    'ראיות הזמה (סעיף 165 חסד"פ) ← טענות בלתי צפויות מההגנה, או חזרה מהודיה של הנאשם.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 165", "ת\"פ (שלום ת\"א) 4725-04-23 מדינת ישראל נ'' יניב הראל (03.09.2025)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'זימון עד מומחה מטעם בית המשפט', 4, 'בית המשפט מעוניין למנות מומחה מטעמו בעניין שבחשבונאות, לצורך הבהרת חומר הראיות. מהם התנאים וההליך למינוי מומחה כזה בהליך פלילי?',
    'שאלה זו עוסקת בסמכות בית המשפט למנות עד מומחה מטעמו בהליך פלילי, בהתאם לסעיף 111 לחוק סדר הדין הפלילי. היא מפרטת את התנאים למינוי (טעמים מיוחדים), את תפקיד המומחה (הבהרת חומר ראיות בעניינים טכניים), ואת זכויות הצדדים (לחקור את המומחה ולהביא ראיות לסתור).',
    'סעיף 111 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע כי "בית המשפט רשאי, מטעמים מיוחדים שיירשמו, למנות מיוזמתו מומחה בענין שבחשבונאות או בנושא אחר הדורש בדיקה טכנית או חישוב, לצורך הבהרת חומר הראיות שבפניו". המומחה יעיין בחומר הראיות שהופנה אליו ויערוך את ממצאיו על פי שאלות שהוצגו לו על ידי בית המשפט. הוא יגיש חוות דעת בכתב וייחקר עליה בבית המשפט לבקשת מי מבעלי הדין. אם הוגשה חוות דעת לפי סעיף זה, רשאים בעלי הדין להביא ראיות לסתור אותה. סמכות זו ניתנת להפעלה במהלך הדיון כולו, ולא רק בשלב הסיום של הבאת הראיות. סעיף 111(א) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982סעיף 111(ב) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982אמנון כרמי בריאות ומשפט (2013) | פרק ב: הרופא בבית המשפטאמנון כרמי בריאות ומשפט (2013) | פרק ב: הרופא בבית המשפט',
    'הטעות הנפוצה היא לחשוב שמינוי מומחה מטעם בית המשפט הוא הליך נדיר או מוגבל מאוד, או לבלבל בין סמכות זו לבין סמכות בית המשפט להזמין עדים רגילים לפי סעיף 167.',
    '["מומחה מטעם בית המשפט", "סעיף 111 לחוק סדר הדין הפלילי", "טעמים מיוחדים", "הבהרת חומר ראיות", "חקירת מומחה", "ראיות לסתור", "שיקול דעת שיפוטי"]'::jsonb,
    '**וריאציה 1 — תנאי מינוי:** מתי בית המשפט רשאי למנות מומחה מטעמו? ← מטעמים מיוחדים שיירשמו, בעניין שבחשבונאות או נושא טכני אחר, לצורך הבהרת חומר הראיות (סעיף 111(א) לחוק סדר הדין הפלילי). **וריאציה 2 — זכויות הצדדים:** מהן זכויות הצדדים ביחס למומחה שמונה? ← לבקש לחקור אותו, ולהביא ראיות לסתור את חוות דעתו (סעיף 111(ב) לחוק סדר הדין הפלילי). **וריאציה 3 — מועד המינוי:** מתי ניתן למנות מומחה מטעם בית המשפט? ← במהלך הדיון כולו, ולא רק בשלב הסיום של הבאת הראיות (אמנון כרמי בריאות ומשפט).',
    'מינוי מומחה (סעיף 111 חסד"פ) ← מטעמים מיוחדים, בעניינים טכניים, להבהרת ראיות ← הצדדים רשאים לחקור ולהביא ראיות לסתור.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 111", "אמנון כרמי, בריאות ומשפט (2013), פרק ב: הרופא בבית המשפט"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'בית המשפט יקבל את הראיה החדשה רק אם היא קריטית להוכחת אשמת הנאשם, ללא קשר ליכולת להשיגה בערכאה קודמת.', false, 'תשובה זו שגויה. אף שחשיפת האמת חשובה, בית המשפט יבחן גם את יכולת השגת הראיה בערכאה קודמת ואת עקרון סופיות הדיון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'בית המשפט יבחן אם היה באפשרות המבקש להשיג את הראיה בערכאה קודמת, את האינטרס בסופיות הדיון, ואת טיבן של הראיות החדשות והסיכוי שישנו את התוצאה.', true, 'זו התשובה הנכונה. סעיף 211 לחוק סדר הדין הפלילי מאפשר גביית ראיות בשלב הערעור, אך הפסיקה קבעה שלושה שיקולים מרכזיים לבחינת בקשה כזו, המאזנים בין גילוי האמת לסופיות הדיון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'בית המשפט יסרב לבקשה באופן גורף, שכן שלב הערעור אינו מיועד להבאת ראיות חדשות.', false, 'תשובה זו שגויה. סעיף 211 לחוק סדר הדין הפלילי מאפשר לבית המשפט לגבות ראיות בשלב הערעור, אם הדבר דרוש לעשיית צדק, אך מדובר בחריג.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'בית המשפט יקבל את הראיה החדשה רק אם היא הוגשה מיוזמתו, ולא לבקשת אחד הצדדים.', false, 'תשובה זו שגויה. סעיף 211 לחוק סדר הדין הפלילי מאפשר קבלת ראיות גם לבקשת בעל דין, אם כי מדובר בחריג.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'הצורך בגילוי האמת ומניעת עיוות דין, תוך איזון עם עקרון סופיות הדיון, השלב הדיוני של ההליך, והחשש לפגיעה ביכולת הנאשם להתגונן כראוי.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי אלו הם השיקולים המרכזיים המנחים את בית המשפט בהפעלת סמכותו לפי סעיף 167, תוך דגש על מניעת עיוות דין לנאשם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'רק הצורך בגילוי האמת, שכן זוהי התכלית העליונה של ההליך הפלילי, וכל שיקול אחר נדחה מפניו.', false, 'תשובה זו שגויה. אף שגילוי האמת הוא תכלית מרכזית, הוא מאוזן עם שיקולים נוספים, כגון סופיות הדיון והגנה על זכויות הנאשם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'רק עקרון סופיות הדיון, שכן סטייה מסדרי הדין פוגעת ביעילות המערכת המשפטית.', false, 'תשובה זו שגויה. סופיות הדיון הוא שיקול חשוב, אך אינו בלעדי, ובית המשפט רשאי לסטות ממנו במקרים של צורך בעשיית צדק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'רק אם הראיה החדשה תומכת בגרסת התביעה, שכן תפקיד בית המשפט הוא להרשיע עבריינים.', false, 'תשובה זו שגויה. תפקיד בית המשפט הוא חשיפת האמת וקביעת חפות או אשמה, תוך שמירה על זכויות הנאשם, ולא רק תמיכה בגרסת התביעה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'בית המשפט ירשה זאת רק אם הראיות נוגעות לעובדות שהנאשם חזר בו מהודייתו בהן לאחר סיום פרשת התביעה.', false, 'תשובה זו חלקית. זהו אחד התנאים, אך לא היחיד. סעיף 165 לחוק סדר הדין הפלילי מציג חלופה נוספת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בית המשפט רשאי להרשות לתובע להביא ראיות לסתור טענות העולות מראיות ההגנה ואשר התובע לא יכול היה לצפותן מראש, או להוכיח עובדות שהנאשם חזר בו מהודייתו בהן לאחר סיום פרשת התביעה.', true, 'זו התשובה הנכונה. סעיף 165 לחוק סדר הדין הפלילי מפרט את שני התנאים החלופיים להבאת ראיות הזמה מטעם התביעה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט ירשה זאת רק אם הראיות קריטיות להוכחת אשמת הנאשם, ללא קשר ליכולת התביעה לצפותן מראש.', false, 'תשובה זו שגויה. היכולת לצפות את הראיות מראש היא תנאי מהותי להבאת ראיות הזמה, למעט במקרה של חזרה מהודיה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בית המשפט ירשה זאת רק אם הראיות הוגשו מיוזמתו, ולא לבקשת התובע.', false, 'תשובה זו שגויה. סעיף 165 מתייחס לבקשת התובע, בעוד סעיף 167 מתייחס גם ליוזמת בית המשפט.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בית המשפט רשאי למנות מומחה מטעמו בכל עניין, ללא צורך בטעמים מיוחדים, והצדדים אינם רשאים להביא ראיות לסתור את חוות דעתו.', false, 'תשובה זו שגויה. מינוי מומחה דורש טעמים מיוחדים, והצדדים רשאים להביא ראיות לסתור את חוות דעתו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט רשאי, מטעמים מיוחדים שיירשמו, למנות מיוזמתו מומחה בעניין שבחשבונאות או בנושא אחר הדורש בדיקה טכנית או חישוב, והמומחה יגיש חוות דעת בכתב וייחקר עליה, ובעלי הדין רשאים להביא ראיות לסתור אותה.', true, 'זו התשובה הנכונה. סעיף 111 לחוק סדר הדין הפלילי מפרט את התנאים וההליך למינוי מומחה מטעם בית המשפט, כולל הדרישה לטעמים מיוחדים וזכות הצדדים להביא ראיות לסתור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בית המשפט רשאי למנות מומחה מטעמו רק אם הצדדים הסכימו לכך, והמומחה יחווה דעתו רק על נקודות שהיו במחלוקת בין הצדדים.', false, 'תשובה זו שגויה. בית המשפט רשאי למנות מומחה מיוזמתו, ללא הסכמת הצדדים, וחוות דעתו אינה מוגבלת רק לנקודות במחלוקת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'מינוי מומחה מטעם בית המשפט אפשרי רק בהליך אזרחי, ולא בהליך פלילי.', false, 'תשובה זו שגויה. סעיף 111 לחוק סדר הדין הפלילי קובע במפורש את סמכות בית המשפט למנות מומחה מטעמו בהליך פלילי.', 4);

END $$;

-- ============================================================
-- Q35 — 2024-W-Q35 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q35';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q35 skipped: external_id % already exists', '2024-W-Q35';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q35', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'כנגד ארז נפתחה חקירה בעבירה של סחר בבני אדם לפי סעיף 377א לחוק העונשין, התשל"ז-1977. מתוך חשש שיופעלו אמצעי לחץ על אחיו יובל, המדינה מבקשת כי בית המשפט ייגבה את עדותו של ארז לאלתר. מה הדין?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 35}'::jsonb,
    'שאלה זו עוסקת בהוראות סעיף 117 לחוק סדר הדין הפלילי [נוסח משולב], התשמ"ב-1982, המסדיר את גביית העדות המוקדמת בהליך הפלילי. היא מבהירה את התנאים והלוחות הזמנים להגשת בקשה כזו, ואת סמכות בית המשפט להורות על גביית עדות מוקדמת גם בטרם הגשת כתב אישום, אם קיים חשש סביר שהעד לא יוכל להעיד במשפט.',
    'סעיף 117(א) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע כי "הוגש כתב אישום או הוגשה בקשה למעצר או לעיכוב יציאה מן הארץ, וקיים חשש סביר שלא ניתן יהיה לגבות את עדותו של עד במשפט, רשאי בית המשפט, על פי בקשת תובע או על פי בקשת נאשם, לגבות את העדות". כלומר, ניתן לבקש גביית עדות מוקדמת גם בטרם הגשת כתב אישום, אם הוגשה בקשה למעצר או לעיכוב יציאה. סעיף 117(ב) קובע את לוחות הזמנים: "בית המשפט יחליט בבקשה לא יאוחר משבועיים מיום הגשתה, והעדות תיגבה בתוך חודשיים מיום ההחלטה, אלא אם האריך בית המשפט את התקופה מטעמים מיוחדים שיירשמו". הפסיקה מדגישה כי הפעלת סמכות זו נתונה לשיקול דעת בית המשפט, אשר יאזן בין חשיבות העדות, מידת החשש שלא ניתן יהיה לגבותה, וזכויות הנאשם, ובפרט זכותו לחקירה נגדית. סעיף 117(א) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982סעיף 117(ב) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982נבו - המתמחה סדר הדין הפלילי (2026) | פרק יב - בירור האשמה',
    'הטעות הנפוצה היא לבלבל בין לוחות הזמנים הקבועים בסעיף 117, או לחשוב שגביית עדות מוקדמת אפשרית רק לאחר הגשת כתב אישום, מבלי להכיר בחלופה של בקשת מעצר או עיכוב יציאה.',
    '["גביית עדות מוקדמת", "סעיף 117 לחוק סדר הדין הפלילי", "לוחות זמנים", "חשש שלא יוכל להעיד", "בקשת מעצר", "עיכוב יציאה", "שיקול דעת שיפוטי"]'::jsonb,
    '**וריאציה 1 — תנאי מקדמי:** מתי ניתן לבקש גביית עדות מוקדמת? ← הוגש כתב אישום, או הוגשה בקשה למעצר או לעיכוב יציאה מן הארץ (סעיף 117(א) לחוק סדר הדין הפלילי). **וריאציה 2 — לוחות זמנים:** מהם לוחות הזמנים להחלטה ולגביית העדות? ← החלטה תוך שבועיים מיום הגשת הבקשה, גביית עדות תוך חודשיים מיום ההחלטה, אלא אם הוארך מטעמים מיוחדים (סעיף 117(ב) לחוק סדר הדין הפלילי). **וריאציה 3 — יוזמת הבקשה:** מי רשאי להגיש בקשה לגביית עדות מוקדמת? ← תובע או נאשם (סעיף 117(א) לחוק סדר הדין הפלילי).',
    'גביית עדות מוקדמת (סעיף 117 חסד"פ) ← לבקשת תובע/נאשם ← לפני/אחרי כתב אישום (אם יש מעצר/עיכוב יציאה) ← החלטה תוך שבועיים, גבייה תוך חודשיים (אפשרות הארכה).',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 117", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יב - בירור האשמה"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא ניתן לבקש גביית עדות מוקדמת בטרם הגשת כתב אישום.', false, 'תשובה זו שגויה. סעיף 117(א) לחוק סדר הדין הפלילי מאפשר גביית עדות מוקדמת גם בטרם הגשת כתב אישום, אם מתקיימים התנאים לכך.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ניתן לבקש גביית עדות מוקדמת בטרם הגשת כתב אישום, ככל שכתב האישום יוגש לא יאוחר משבועיים מיום הגשת הבקשה; על בית המשפט להחליט בבקשה בתוך חודשיים מיום ההגשה, אלא אם האריך בית המשפט את התקופה מטעמים מיוחדים שיירשמו.', false, 'תשובה זו שגויה. התנאי לגבי הגשת כתב אישום תוך שבועיים אינו קיים בסעיף 117, ולוחות הזמנים להחלטה ולגביית העדות שונים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'ניתן לבקש גביית עדות מוקדמת ועל בית המשפט להחליט בבקשה לא יאוחר משבועיים מיום הגשתה; העדות תיגבה בתוך חודשיים מיום ההחלטה, אלא אם האריך בית המשפט את התקופה מטעמים מיוחדים שיירשמו.', true, 'זו התשובה הנכונה. סעיף 117(א) ו-(ב) לחוק סדר הדין הפלילי קובע כי ניתן לבקש גביית עדות מוקדמת, וכי בית המשפט יחליט בבקשה תוך שבועיים מיום הגשתה, והעדות תיגבה תוך חודשיים מיום ההחלטה, אלא אם הואריך את התקופה מטעמים מיוחדים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לא ניתן לבקש גביית עדות מוקדמת בטרם הגשת כתב אישום, אך אם בתוך שבועיים מיום הגשת הבקשה הוגש כתב האישום, על בית המשפט להחליט בבקשה בתוך חודשיים מיום ההגשה, אלא אם האריך בית המשפט את התקופה מטעמים מיוחדים שיירשמו.', false, 'תשובה זו שגויה. ניתן לבקש גביית עדות מוקדמת בטרם הגשת כתב אישום, ולוחות הזמנים להחלטה ולגביית העדות שונים מאלה המפורטים כאן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'גביית עדות מוקדמת: עד מחוץ לישראל', 1, 'עד מרכזי בתיק פלילי, אזרח זר, נמצא בחו"ל וצפוי לא לחזור לישראל עד מועד המשפט. התביעה מבקשת לגבות את עדותו מוקדם. מה הדין?',
    'שאלה זו מרחיבה את תחולת סעיף 117 לחוק סדר הדין הפלילי למקרים של עדים הנמצאים מחוץ לישראל. היא בוחנת את הפרשנות המרחיבה של הפסיקה למונח "חשש שלא יוכל להעיד במשפט", כך שיכלול גם עדים זרים או ישראלים השוהים בחו"ל, תוך שמירה על זכויות הנאשם.',
    'סעיף 117(א) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, מאפשר גביית עדות מוקדמת אם קיים "חשש סביר שלא ניתן יהיה לגבות את עדותו של עד במשפט". הפסיקה פירשה חשש זה באופן רחב, כך שיכלול גם מקרים בהם העד נמצא מחוץ לישראל וקיים חשש שלא יוכל להתייצב למשפט. במקרים אלו, בית המשפט רשאי להורות על גביית עדות מוקדמת, תוך התחשבות בזכויות הנאשם, ובפרט זכותו לחקירה נגדית. לעיתים, גביית עדות כזו תתבצע באמצעות ועידת וידאו או בדרכים אחרות המאפשרות את השתתפות הנאשם וסנגורו. בית המשפט יאזן בין חשיבות העדות לצורך גילוי האמת לבין הפגיעה בזכויות הנאשם. בש"פ 5170540/20 מדינת ישראל נ'' פלוני (27.07.2020)בש"פ 5170540/20 מדינת ישראל נ'' פלוני (27.07.2020)נבו - המתמחה סדר הדין הפלילי (2026) | פרק יב - בירור האשמה',
    'הטעות הנפוצה היא להניח שסעיף 117 מוגבל לעדים הנמצאים פיזית בישראל, מבלי להכיר בפרשנות המרחיבה של הפסיקה המאפשרת גביית עדות מוקדמת גם מעדים בחו"ל.',
    '["גביית עדות מוקדמת", "סעיף 117 לחוק סדר הדין הפלילי", "עד מחוץ לישראל", "חשש שלא יוכל להעיד", "חקירה נגדית", "איזון זכויות", "סיוע משפטי בינלאומי"]'::jsonb,
    '**וריאציה 1 — עד בחו"ל:** האם ניתן לגבות עדות מוקדמת מעד הנמצא בחו"ל? ← כן, אם קיים חשש שלא יוכל להעיד במשפט (בש"פ 5170540/20 מדינת ישראל נ'' פלוני). **וריאציה 2 — שיקולי בית המשפט:** מה יבחן בית המשפט בבקשה כזו? ← איזון בין הצורך בגביית העדות לבין זכויות הנאשם, ובפרט זכותו לחקירה נגדית (בש"פ 5170540/20 מדינת ישראל נ'' פלוני). **וריאציה 3 — אמצעי גבייה:** כיצד ניתן לגבות עדות כזו? ← באמצעות ועידת וידאו או בדרכים אחרות המאפשרות השתתפות הנאשם וסנגורו.',
    'גביית עדות מוקדמת ← גם מעד בחו"ל (סעיף 117 חסד"פ) ← אם קיים חשש שלא יוכל להעיד ← תוך איזון עם זכויות הנאשם.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 117(א)", "בש\"פ 5170540/20 מדינת ישראל נ'' פלוני (27.07.2020)", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יב - בירור האשמה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'שיקולי בית המשפט בגביית עדות מוקדמת', 2, 'מהם השיקולים המרכזיים שבית המשפט יבחן בבואו להחליט אם לאשר בקשה לגביית עדות מוקדמת לפי סעיף 117 לחוק סדר הדין הפלילי?',
    'שאלה זו מתמקדת בשיקולים המנחים את בית המשפט בבואו להפעיל את סמכותו לגביית עדות מוקדמת לפי סעיף 117 לחוק סדר הדין הפלילי. היא מדגישה את הצורך באיזון בין האינטרס הציבורי בגילוי האמת ובמניעת שיבוש הליכים לבין זכויות הנאשם להליך הוגן, ובפרט זכותו לחקירה נגדית.',
    'הפעלת סמכות בית המשפט לגביית עדות מוקדמת לפי סעיף 117 לחוק סדר הדין הפלילי אינה אוטומטית, אלא נתונה לשיקול דעת. בית המשפט יבחן מספר שיקולים מרכזיים: ראשית, חשיבות העדות לצורך גילוי האמת; שנית, מידת החשש הסביר שלא ניתן יהיה לגבות את העדות במשפט (למשל, חשש לשיבוש, היעלמות, או פגיעה בבריאות העד); שלישית, זכויות הנאשם, ובפרט זכותו לחקירה נגדית יעילה. בית המשפט יאזן בין אינטרסים אלו, וישקול חלופות אפשריות לגביית העדות המוקדמת, כגון קביעת תנאים שיבטיחו את זכויות הנאשם. המטרה היא למנוע עיוות דין, הן לתביעה והן לנאשם. בש"פ 5170540/20 מדינת ישראל נ'' פלוני (27.07.2020)בש"פ 5170540/20 מדינת ישראל נ'' פלוני (27.07.2020)נבו - המתמחה סדר הדין הפלילי (2026) | פרק יב - בירור האשמה',
    'הטעות הנפוצה היא להתמקד רק ב"חשש שלא יוכל להעיד" מבלי להבין את מכלול השיקולים, ובפרט את חשיבות האיזון עם זכויות הנאשם לחקירה נגדית.',
    '["גביית עדות מוקדמת", "סעיף 117 לחוק סדר הדין הפלילי", "שיקול דעת שיפוטי", "גילוי האמת", "הליך הוגן", "חקירה נגדית", "איזון אינטרסים"]'::jsonb,
    '**וריאציה 1 — שיקולים מרכזיים:** מהם השיקולים המרכזיים בגביית עדות מוקדמת? ← חשיבות העדות, חשש לשיבוש/היעלמות, זכויות הנאשם לחקירה נגדית, ואיזון בין גילוי אמת להליך הוגן (נבו - המתמחה סדר הדין הפלילי). **וריאציה 2 — חשש לשיבוש:** מהו סוג החשש המצדיק גביית עדות מוקדמת? ← חשש סביר שלא ניתן יהיה לגבות את העדות במשפט, לרבות חשש לשיבוש, היעלמות, או פגיעה בבריאות העד (סעיף 117(א) לחוק סדר הדין הפלילי). **וריאציה 3 — חלופות:** האם בית המשפט ישקול חלופות? ← כן, בית המשפט ישקול חלופות אפשריות לגביית העדות המוקדמת, כגון קביעת תנאים שיבטיחו את זכויות הנאשם.',
    'גביית עדות מוקדמת ← שיקולים: חשיבות העדות, חשש לאי-גבייה, זכויות הנאשם (חקירה נגדית) ← איזון בין גילוי אמת להליך הוגן.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 117", "בש\"פ 5170540/20 מדינת ישראל נ'' פלוני (27.07.2020)", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יב - בירור האשמה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'גביית עדות מוקדמת לבקשת הנאשם', 3, 'נאשם מבקש לגבות עדות מוקדמת של עד תביעה, מחשש שהעד ישכח פרטים מהותיים עד המשפט. האם סעיף 117 לחוק סדר הדין הפלילי מאפשר זאת, ומהם השיקולים שיבחן בית המשפט?',
    'שאלה זו בוחנת את תחולת סעיף 117 לחוק סדר הדין הפלילי גם על בקשות המוגשות על ידי נאשמים, ולא רק על ידי התביעה. היא מדגישה כי השיקולים המנחים את בית המשפט זהים, אך עם דגש על זכויות הנאשם להליך הוגן וליכולת להציג את הגנתו.',
    'סעיף 117(א) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע במפורש כי בקשה לגביית עדות מוקדמת יכולה להיות מוגשת "על ידי תובע או על ידי נאשם". לכן, נאשם בהחלט רשאי לבקש לגבות עדות מוקדמת של עד תביעה, אם קיים חשש סביר שלא ניתן יהיה לגבות את עדותו של העד במשפט, למשל מחשש לשיכחת פרטים מהותיים. בית המשפט יבחן את הבקשה באותם שיקולים המנחים אותו בבקשת התביעה: חשיבות העדות, מידת החשש, וזכויות הנאשם לחקירה נגדית. במקרה של בקשת נאשם, בית המשפט ייתן משקל מיוחד לזכותו להגנה יעילה וליכולת להציג את גרסתו. סעיף 117(א) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982נבו - המתמחה סדר הדין הפלילי (2026) | פרק יב - בירור האשמה',
    'הטעות הנפוצה היא לחשוב שגביית עדות מוקדמת היא כלי השמור רק לתביעה, מבלי להכיר בכך שגם הנאשם רשאי להשתמש בו להגנתו.',
    '["גביית עדות מוקדמת", "סעיף 117 לחוק סדר הדין הפלילי", "בקשת נאשם", "זכות להגנה", "חשש לשיכחת פרטים", "שיקול דעת שיפוטי", "הליך הוגן"]'::jsonb,
    '**וריאציה 1 — בקשת נאשם:** האם נאשם רשאי לבקש גביית עדות מוקדמת? ← כן, סעיף 117(א) קובע שהבקשה יכולה להיות מוגשת "על ידי תובע או על ידי נאשם" (סעיף 117(א) לחוק סדר הדין הפלילי). **וריאציה 2 — שיקולים זהים:** האם שיקולי בית המשפט שונים בבקשת נאשם? ← השיקולים זהים, אך בית המשפט ייתן משקל מיוחד לזכות הנאשם להגנה יעילה (נבו - המתמחה סדר הדין הפלילי). **וריאציה 3 — חשש לשיכחה:** האם חשש לשיכחת פרטים מצדיק גביית עדות מוקדמת? ← כן, זהו סוג של "חשש סביר שלא ניתן יהיה לגבות את עדותו של עד במשפט" (סעיף 117(א) לחוק סדר הדין הפלילי).',
    'גביית עדות מוקדמת ← גם לבקשת נאשם (סעיף 117 חסד"פ) ← שיקולים זהים, עם דגש על זכות הנאשם להגנה.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 117(א)", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יב - בירור האשמה"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'עדות מוקדמת מול עדות מחוץ לבית המשפט', 4, 'מהו ההבדל המהותי בין גביית עדות מוקדמת לפי סעיף 117 לחוק סדר הדין הפלילי לבין גביית עדות מחוץ לבית המשפט לפי סעיף 118 לאותו חוק?',
    'שאלה זו מבחינה בין שני הליכים שונים לגביית עדות בחוק סדר הדין הפלילי: גביית עדות מוקדמת (סעיף 117) וגביית עדות מחוץ לבית המשפט (סעיף 118). היא מדגישה את ההבדלים במטרות, בתנאים ובשלב הדיוני של כל אחד מההליכים.',
    'סעיף 117 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, עוסק ב"גביית עדות מוקדמת". מטרתו היא למנוע אובדן עדות חשובה כאשר קיים חשש סביר שהעד לא יוכל להעיד במשפט. הליך זה יכול להתקיים גם בטרם הגשת כתב אישום, והעדות נגבית על ידי בית המשפט. לעומת זאת, סעיף 118 לאותו חוק עוסק ב"גביית עדות מחוץ לבית המשפט". מטרתו היא לאפשר גביית עדות מאדם שאינו יכול להתייצב בבית המשפט מסיבות שונות (כגון מחלה, נכות, או שהייה בחו"ל), והוא מתקיים במהלך המשפט. בשני המקרים, העדות נגבית על ידי בית המשפט או מי מטעמו, תוך שמירה על זכויות הצדדים, ובפרט זכות הנאשם לחקירה נגדית. סעיף 117(א) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982סעיף 118(א) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982נבו - המתמחה סדר הדין הפלילי (2026) | פרק יב - בירור האשמה',
    'הטעות הנפוצה היא לבלבל בין שני הסעיפים, שכן שניהם עוסקים בגביית עדות שלא בדרך הרגילה, אך מטרותיהם והשלב הדיוני שבו הם מופעלים שונים.',
    '["גביית עדות מוקדמת", "סעיף 117 לחוק סדר הדין הפלילי", "גביית עדות מחוץ לבית המשפט", "סעיף 118 לחוק סדר הדין הפלילי", "מטרת ההליך", "שלב דיוני", "חשש לאי-גבייה"]'::jsonb,
    '**וריאציה 1 — מטרת סעיף 117:** מהי מטרת גביית עדות מוקדמת (117)? ← למנוע אובדן עדות חשובה כאשר קיים חשש סביר שהעד לא יוכל להעיד במשפט (סעיף 117(א) לחוק סדר הדין הפלילי). **וריאציה 2 — מטרת סעיף 118:** מהי מטרת גביית עדות מחוץ לבית המשפט (118)? ← לאפשר גביית עדות מאדם שאינו יכול להתייצב בבית המשפט מסיבות שונות (מחלה, חו"ל) (סעיף 118(א) לחוק סדר הדין הפלילי). **וריאציה 3 — שלב דיוני:** מתי מתרחש כל הליך? ← סעיף 117: לפני או אחרי הגשת כתב אישום, לפני המשפט. סעיף 118: במהלך המשפט (נבו - המתמחה סדר הדין הפלילי).',
    'סעיף 117 (עדות מוקדמת) ← למנוע אובדן עדות, לפני המשפט. סעיף 118 (עדות מחוץ לבית המשפט) ← לאפשר עדות מנוע, במהלך המשפט.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 117", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 118", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יב - בירור האשמה"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לא ניתן לגבות עדות מוקדמת מעד הנמצא מחוץ לישראל, שכן סעיף 117 לחוק סדר הדין הפלילי חל רק על עדים הנמצאים בישראל.', false, 'תשובה זו שגויה. הפסיקה הרחיבה את תחולת סעיף 117 גם למקרים של עדים מחוץ לישראל, אם קיים חשש שלא יוכלו להעיד במשפט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'כן, ניתן לבקש גביית עדות מוקדמת גם מעד מחוץ לישראל, ובית המשפט רשאי להורות על כך אם שוכנע כי העד לא יוכל להעיד במשפט, תוך התחשבות בזכויות הנאשם לחקירה נגדית.', true, 'זו התשובה הנכונה. סעיף 117(א) מאפשר גביית עדות מוקדמת כאשר קיים חשש שהעד לא יוכל להעיד במשפט, וחשש זה כולל גם עדים הנמצאים בחו"ל. בית המשפט יבחן את הבקשה תוך איזון בין הצורך בגביית העדות לבין זכויות הנאשם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'ניתן לגבות את העדות רק באמצעות בקשה לסיוע משפטי בינלאומי, ולא במסגרת סעיף 117 לחוק סדר הדין הפלילי.', false, 'תשובה זו שגויה. סיוע משפטי בינלאומי הוא הליך נפרד, אך סעיף 117 יכול לשמש בסיס לגביית עדות מוקדמת גם מעד בחו"ל, לעיתים בשילוב עם הליכי סיוע משפטי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'רק אם הנאשם מסכים לגביית העדות מחוץ לישראל, שכן אחרת נפגעת זכותו לחקירה נגדית.', false, 'תשובה זו שגויה. הסכמת הנאשם אינה תנאי הכרחי, אם כי בית המשפט יבחן את הפגיעה בזכותו לחקירה נגדית ויכול לקבוע תנאים לגביית העדות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'רק חשיבות העדות והחשש לשיבוש או היעלמות העד, ללא התחשבות בזכויות הנאשם.', false, 'תשובה זו שגויה. בית המשפט חייב לאזן בין הצורך בגביית העדות לבין זכויות הנאשם, ובפרט זכותו לחקירה נגדית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'חשיבות העדות, החשש לשיבוש או היעלמות העד, זכויות הנאשם לחקירה נגדית, והאיזון בין גילוי האמת להליך הוגן, תוך בחינת חלופות אפשריות.', true, 'זו התשובה הנכונה. אלו הם השיקולים המרכזיים שנקבעו בפסיקה, המבטאים את האיזון הנדרש בין האינטרסים השונים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'רק הסכמת הנאשם לגביית העדות, שכן ללא הסכמתו נפגעת זכותו להליך הוגן.', false, 'תשובה זו שגויה. הסכמת הנאשם אינה תנאי הכרחי, אם כי בית המשפט יבחן את הפגיעה בזכויותיו ויכול לקבוע תנאים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'רק השלב הדיוני של ההליך, שכן ככל שההליך מתקדם יותר, כך קשה יותר לאשר גביית עדות מוקדמת.', false, 'תשובה זו שגויה. השלב הדיוני הוא שיקול, אך אינו השיקול הבלעדי, ובית המשפט בוחן מכלול רחב של שיקולים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'לא, סעיף 117 מאפשר גביית עדות מוקדמת רק לבקשת התביעה, ולא לבקשת הנאשם.', false, 'תשובה זו שגויה. סעיף 117(א) קובע כי הבקשה יכולה להיות מוגשת "על ידי תובע או על ידי נאשם".', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'כן, סעיף 117 חל גם על בקשת נאשם, ובית המשפט יבחן את חשיבות העדות, החשש לשיבוש או היעלמות, וזכויות הנאשם לחקירה נגדית, תוך איזון עם הצורך בגילוי האמת.', true, 'זו התשובה הנכונה. סעיף 117 מאפשר הגשת בקשה גם על ידי נאשם, והשיקולים זהים לאלו של בקשת התביעה, תוך דגש על זכויות הנאשם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'כן, אך רק אם העד הוא קטין או אדם עם מוגבלות, שכן רק במקרים אלו קיים חשש לשיכחת פרטים.', false, 'תשובה זו שגויה. החשש לשיכחת פרטים אינו מוגבל לקטינים או בעלי מוגבלות, וסעיף 117 חל על כל עד שקיים חשש סביר שלא יוכל להעיד במשפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'רק אם התביעה מסכימה לבקשה, שכן אחרת הדבר עלול לפגוע באינטרס הציבורי.', false, 'תשובה זו שגויה. הסכמת התביעה אינה תנאי הכרחי, ובית המשפט יכריע בבקשה על פי שיקול דעתו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'גביית עדות מוקדמת לפי סעיף 117 מתרחשת תמיד לפני הגשת כתב אישום, בעוד גביית עדות מחוץ לבית המשפט לפי סעיף 118 מתרחשת תמיד לאחר הגשת כתב אישום.', false, 'תשובה זו שגויה. גביית עדות מוקדמת יכולה להיות גם לאחר הגשת כתב אישום, וגביית עדות מחוץ לבית המשפט מתרחשת במהלך המשפט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'גביית עדות מוקדמת לפי סעיף 117 נועדה למנוע אובדן עדות חשובה לפני המשפט, בעוד גביית עדות מחוץ לבית המשפט לפי סעיף 118 נועדה לאפשר עדות של מי שאינו יכול להתייצב בבית המשפט מסיבות שונות, והיא נגבית במהלך המשפט.', true, 'זו התשובה הנכונה. ההבדל המהותי טמון במטרת ההליך ובשלב הדיוני שבו הוא מתקיים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'גביית עדות מוקדמת לפי סעיף 117 מחייבת הסכמת נאשם, בעוד גביית עדות מחוץ לבית המשפט לפי סעיף 118 אינה מחייבת הסכמה כזו.', false, 'תשובה זו שגויה. אף אחד מהסעיפים אינו מחייב הסכמת נאשם כתנאי לגביית העדות, אם כי זכויותיו נבחנות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'גביית עדות מוקדמת לפי סעיף 117 מתבצעת תמיד על ידי שופט, בעוד גביית עדות מחוץ לבית המשפט לפי סעיף 118 יכולה להתבצע גם על ידי חוקר משטרה.', false, 'תשובה זו שגויה. שתי העדויות נגבות על ידי בית המשפט או מי מטעמו, ולא על ידי חוקר משטרה.', 4);

END $$;

-- ============================================================
-- Q36 — 2024-W-Q36 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q36';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q36 skipped: external_id % already exists', '2024-W-Q36';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q36', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'יאיר הורשע בבית משפט השלום בתל אביב בעבירת אלימות ונגזרה עליו, בין היתר, שנת מאסר על תנאי למשך שלוש שנים שלא יעבור עבירת אלימות. לאחר שנתיים, יאיר ביצע שוב עבירת אלימות והורשע בה בבית משפט השלום בראשון לציון, אך השופט לא נתן צו להפעלת המאסר על תנאי במעמד מתן גזר הדין ופרש מכס השיפוט ביום למחרת. המדינה מבקשת כי יופעל המאסר על תנאי מהרשעתו הראשונה של יאיר. מה הדין?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 36}'::jsonb,
    'השאלה עוסקת בהליך הפעלת מאסר על תנאי, שהוא כלי ענישה המאפשר לבית המשפט להטיל עונש מאסר בפועל רק אם הנאשם מבצע עבירה נוספת בתקופת התנאי. היא מתמקדת בסמכות העניינית ובדרישות הפרוצדורליות להפעלת המאסר על תנאי, כפי שנקבעו בתקנות העונשין (מאסר על תנאי), התשמ"ה-1985.',
    'מאסר על תנאי הוא עונש מאסר שאינו מבוצע בפועל, אלא אם הנאשם עובר עבירה נוספת בתקופת התנאי. סעיף 3(א) לתקנות העונשין (מאסר על תנאי), התשמ"ה-1985, קובע כי בקשה לצו להפעלת מאסר על תנאי תוגש לבית המשפט שהרשיע את הנאשם בעבירה שבגינה הופר התנאי. במקרה זה, בית משפט השלום בראשון לציון. סעיף 4(א) לתקנות מפרט את המסמכים שיש לצרף לבקשה: העתק מפסק הדין שבו הוטל המאסר על תנאי (מבית משפט השלום בתל אביב) והעתק מפסק הדין שבו הורשע הנאשם בעבירה שבגינה הופר התנאי (מבית משפט השלום בראשון לציון). העובדה שהשופט שדן בעבירה המפרה פרש מכס השיפוט אינה משנה את סמכותו של בית המשפט, והבקשה תוגש לשופט אחר באותו בית משפט, שכן הסמכות היא לבית המשפט כגוף ולא לשופט ספציפי. סעיף 3(א) לתקנות העונשין (מאסר על תנאי), התשמ"ה-1985סעיף 4(א) לתקנות העונשין (מאסר על תנאי), התשמ"ה-1985נבו - המתמחה סדר הדין הפלילי (2026) | פרק יז - עונשים',
    'טעות נפוצה היא לחשוב שהבקשה להפעלת המאסר על תנאי מוגשת לבית המשפט שהטיל את המאסר על תנאי מלכתחילה, ולא לבית המשפט שהרשיע בעבירה המפרה את התנאי. כמו כן, יש לזכור כי פרישת שופט אינה משנה את סמכותו של בית המשפט.',
    '["מאסר על תנאי", "הפעלת תנאי", "תקופת תנאי", "עבירה מפרה", "סמכות עניינית", "תקנות העונשין (מאסר על תנאי)", "פרישת שופט"]'::jsonb,
    '**וריאציה 1 — סמכות עניינית:** לאיזה בית משפט מוגשת בקשה להפעלת מאסר על תנאי? ← לבית המשפט שהרשיע בעבירה המפרה את התנאי (סעיף 3(א) לתקנות העונשין (מאסר על תנאי)). **וריאציה 2 — מסמכים נדרשים:** אילו מסמכים יש לצרף לבקשה? ← העתק מפסק הדין שהטיל את המאסר על תנאי והעתק מפסק הדין שהרשיע בעבירה המפרה (סעיף 4(א) לתקנות העונשין (מאסר על תנאי)). **וריאציה 3 — פרישת שופט:** מה קורה אם השופט שהרשיע בעבירה המפרה פרש? ← הבקשה תוגש לשופט אחר באותו בית משפט, שכן הסמכות היא לבית המשפט ולא לשופט ספציפי.',
    'הפעלת מאסר על תנאי ← בקשה לבית המשפט שהרשיע בעבירה המפרה (תקנה 3) ← לצרף פסקי דין (תקנה 4) ← פרישת שופט אינה משנה סמכות.',
    '["תקנות העונשין (מאסר על תנאי), התשמ\"ה-1985, סעיפים 3, 4", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יז - עונשים"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על המדינה להגיש בקשה לצו להפעלת מאסר על תנאי לשופט שהרשיע את יאיר בבית משפט השלום בתל אביב; עליה לצרף לבקשה העתק של פסק דינו של בית המשפט השלום בראשון לציון.', false, 'תשובה זו שגויה. סעיף 3(א) לתקנות העונשין (מאסר על תנאי) קובע כי הבקשה תוגש לבית המשפט שהרשיע בעבירה שבגינה הופר התנאי, ולא לבית המשפט שהטיל את המאסר על תנאי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על המדינה להגיש בקשה לצו להפעלת מאסר על תנאי לשופט בית המשפט המחוזי בתל אביב; עליה לצרף לבקשה העתק של פסק דינו של בית משפט השלום בתל אביב וגם העתק של פסק דינו של בית משפט השלום בראשון לציון.', false, 'תשובה זו שגויה. הסמכות היא לבית המשפט שהרשיע בעבירה השנייה (בית משפט השלום בראשון לציון), ולא לבית המשפט המחוזי, אלא אם כן הוא זה שהרשיע בעבירה השנייה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על המדינה להגיש בקשה לצו להפעלת מאסר על תנאי לשופט אחר של בית משפט השלום בראשון לציון; עליה לצרף לבקשה העתק של פסק דינו של בית משפט השלום בתל אביב וגם העתק של פסק דינו של בית משפט השלום בראשון לציון.', true, 'זו התשובה הנכונה. סעיף 3(א) לתקנות העונשין (מאסר על תנאי), התשמ"ה-1985, קובע כי בקשה לצו להפעלת מאסר על תנאי תוגש לבית המשפט שהרשיע את הנאשם בעבירה שבגינה הופר התנאי. סעיף 4(א) לתקנות קובע כי לבקשה יצורפו העתק מפסק הדין שבו הוטל המאסר על תנאי והעתק מפסק הדין שבו הורשע הנאשם בעבירה שבגינה הופר התנאי. העובדה שהשופט פרש אינה משנה את סמכותו של בית המשפט, והבקשה תוגש לשופט אחר באותו בית משפט.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על המדינה להגיש בקשה לצו להפעלת מאסר על תנאי לנשיא בית משפט השלום בראשון לציון או לסגנו; עליה לצרף לבקשה העתק של פסק דינו של בית משפט השלום בתל אביב.', false, 'תשובה זו שגויה. הבקשה אינה מוגשת לנשיא או סגנו באופן ספציפי, אלא לבית המשפט שהרשיע בעבירה השנייה, ונדרש לצרף את שני פסקי הדין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'הפעלת מאסר על תנאי בעבירה שאינה זהה', 1, 'יאיר הורשע בעבירת אלימות ונגזרה עליו שנת מאסר על תנאי למשך שלוש שנים, בתנאי שלא יעבור "עבירה מסוג פשע". לאחר שנה וחצי, יאיר הורשע בעבירת גניבה, שהיא עבירה מסוג פשע. האם ניתן להפעיל את המאסר על תנאי במקרה זה?',
    'שאלה זו בוחנת את הבנת היקף התנאי במאסר על תנאי, ומדגישה כי הפעלת המאסר תלויה בעמידה בתנאי הספציפי שנקבע בגזר הדין המקורי, ולאו דווקא בזהות מוחלטת של העבירה. היא מתייחסת לסעיף 52(א) לחוק העונשין.',
    'סעיף 52(א) לחוק העונשין, התשל"ז-1977, קובע כי בית המשפט יורה על הפעלת מאסר על תנאי אם הנאשם עבר עבירה נוספת בתקופת התנאי, והעבירה הנוספת היא מסוג העבירות שנקבעו בתנאי. במקרה זה, התנאי שהוטל על יאיר היה שלא יעבור "עבירה מסוג פשע". מכיוון שעבירת הגניבה היא עבירה מסוג פשע, התנאי הופר, ובית המשפט יורה על הפעלת המאסר על תנאי, אלא אם כן ימצא טעמים מיוחדים שלא לעשות כן. חשוב להבחין בין תנאי המגדיר סוג עבירה (כמו "פשע" או "עבירת אלימות") לבין תנאי המגדיר עבירה ספציפית. סעיף 52(א) לחוק העונשין, התשל"ז-1977נבו - המתמחה סדר הדין הפלילי (2026) | פרק יז - עונשים',
    'הטעות הנפוצה היא לחשוב שהפעלת מאסר על תנאי מחייבת זהות מוחלטת בין העבירה המקורית לעבירה המפרה, במקום לבחון את לשון התנאי הספציפי שנקבע בגזר הדין.',
    '["מאסר על תנאי", "הפעלת תנאי", "חוק העונשין", "סוג עבירה", "עבירה מפרה", "תקופת תנאי"]'::jsonb,
    '**וריאציה 1 — היקף התנאי:** האם תנאי "עבירה מסוג פשע" כולל גניבה? ← כן, אם גניבה היא פשע, התנאי הופר (סעיף 52(א) לחוק העונשין). **וריאציה 2 — זהות עבירות:** האם נדרשת זהות מוחלטת בין העבירות? ← לא, נדרשת עמידה בתנאי שנקבע, שיכול להיות רחב יותר מעבירה ספציפית (נבו - המתמחה סדר הדין הפלילי). **וריאציה 3 — שיקול דעת:** האם בית המשפט חייב להפעיל את התנאי? ← בית המשפט יורה על הפעלה, אלא אם כן ימצא טעמים מיוחדים שלא לעשות כן (סעיף 52(א) לחוק העונשין).',
    'הפעלת מאסר על תנאי ← תלויה בתנאי שנקבע (למשל, "פשע") ← לאו דווקא זהות עבירות ← סעיף 52(א) לחוק העונשין.',
    '["חוק העונשין, התשל\"ז-1977, סעיף 52(א)", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יז - עונשים"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'שיקולי בית המשפט בהפעלת מאסר על תנאי', 2, 'יאיר הורשע בעבירה מפרה של המאסר על תנאי שהוטל עליו. מהם השיקולים המרכזיים שבית המשפט יבחן בבואו להחליט אם להפעיל את המאסר על תנאי, או שמא לדחות את הפעלתו או להאריך את תקופת התנאי?',
    'שאלה זו עוסקת בשיקול הדעת הרחב הנתון לבית המשפט בבואו להחליט על הפעלת מאסר על תנאי, כפי שמעוגן בסעיף 52(א) לחוק העונשין. היא מדגישה את הצורך באיזון בין עקרון הוודאות בענישה לבין מטרות הענישה השונות, ובפרט שיקום הנאשם.',
    'סעיף 52(א) לחוק העונשין, התשל"ז-1977, קובע כי בית המשפט יורה על הפעלת מאסר על תנאי אם הנאשם עבר עבירה נוספת בתקופת התנאי, "אלא אם כן ימצא טעמים מיוחדים שלא לעשות כן". הפסיקה פירשה את המונח "טעמים מיוחדים" באופן רחב, וקבעה כי בית המשפט יבחן מכלול שיקולים, ובהם: נסיבות העבירה המפרה וחומרתה, מידת הפגיעה בערכים המוגנים, התנהגות הנאשם מאז הטלת המאסר על תנאי, וכן את מטרות הענישה, לרבות שיקום הנאשם. בית המשפט רשאי, במקום להפעיל את המאסר על תנאי, לדחות את הפעלתו או להאריך את תקופת התנאי. סעיף 52(א) לחוק העונשין, התשל"ז-1977ע"פ 4345/08 אהוד אולמרט נ'' מדינת ישראל (20.05.2008)נבו - המתמחה סדר הדין הפלילי (2026) | פרק יז - עונשים',
    'הטעות הנפוצה היא לחשוב שהפעלת מאסר על תנאי היא פעולה אוטומטית או כמעט אוטומטית, מבלי להכיר בשיקול הדעת הרחב הנתון לבית המשפט ובקיומם של "טעמים מיוחדים" המאפשרים סטייה מהפעלת התנאי.',
    '["מאסר על תנאי", "הפעלת תנאי", "טעמים מיוחדים", "שיקול דעת שיפוטי", "מטרות הענישה", "שיקום נאשם", "חוק העונשין"]'::jsonb,
    '**וריאציה 1 — טעמים מיוחדים:** מהם "טעמים מיוחדים" המצדיקים אי-הפעלה? ← נסיבות העבירה המפרה, חומרתה, התנהגות הנאשם, מטרות הענישה ושיקום (ע"פ 4345/08 אהוד אולמרט נ'' מדינת ישראל). **וריאציה 2 — חלופות להפעלה:** אילו חלופות קיימות להפעלת המאסר על תנאי? ← דחיית הפעלתו או הארכת תקופת התנאי (סעיף 52(א) לחוק העונשין). **וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל להוכיח קיומם של טעמים מיוחדים? ← על הנאשם, המבקש למנוע את הפעלת המאסר על תנאי.',
    'הפעלת מאסר על תנאי ← שיקול דעת רחב (סעיף 52(א) חוק העונשין) ← בחינת נסיבות, חומרה, התנהגות, שיקום ← אפשרות לדחייה/הארכה.',
    '["חוק העונשין, התשל\"ז-1977, סעיף 52(א)", "ע\"פ 4345/08 אהוד אולמרט נ'' מדינת ישראל (20.05.2008)", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יז - עונשים"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'דחיית הפעלת מאסר על תנאי', 3, 'יאיר הורשע בעבירה מפרה של המאסר על תנאי, אך בית המשפט סבור כי בנסיבות העניין, הפעלת המאסר על תנאי תהיה בלתי צודקת. מהן האפשרויות העומדות בפני בית המשפט במקרה זה?',
    'שאלה זו מתמקדת בחריג לכלל הפעלת מאסר על תנאי, והיא בוחנת את סמכות בית המשפט לדחות את הפעלת המאסר או להאריך את תקופת התנאי, בהתקיים "טעמים מיוחדים". היא מדגישה את האיזון בין עקרון הוודאות בענישה לבין שיקולי צדק ושיקום.',
    'סעיף 52(א) לחוק העונשין, התשל"ז-1977, קובע כי בית המשפט יורה על הפעלת מאסר על תנאי אם הנאשם עבר עבירה נוספת בתקופת התנאי, "אלא אם כן ימצא טעמים מיוחדים שלא לעשות כן". במקרה כזה, בית המשפט רשאי, במקום להפעיל את המאסר על תנאי, לדחות את הפעלתו או להאריך את תקופת התנאי. סעיף 52(ב) לחוק קובע חריג חשוב: "לא ידחה בית המשפט את הפעלת המאסר על תנאי ולא יאריך את תקופת התנאי, אם העבירה שבגללה הופר התנאי היא פשע שדינה מאסר עולם". כלומר, במקרה של פשע חמור במיוחד, אין לבית המשפט שיקול דעת לדחות או להאריך את התנאי. סעיף 52(א) לחוק העונשין, התשל"ז-1977סעיף 52(ב) לחוק העונשין, התשל"ז-1977נבו - המתמחה סדר הדין הפלילי (2026) | פרק יז - עונשים',
    'הטעות הנפוצה היא להתעלם מהחריג הקבוע בסעיף 52(ב) לחוק העונשין, המגביל את שיקול הדעת של בית המשפט במקרים של פשעים חמורים במיוחד.',
    '["מאסר על תנאי", "דחיית הפעלה", "הארכת תקופת תנאי", "טעמים מיוחדים", "פשע שדינה מאסר עולם", "חוק העונשין", "שיקול דעת שיפוטי"]'::jsonb,
    '**וריאציה 1 — סמכות לדחות:** האם בית המשפט רשאי לדחות הפעלת מאסר על תנאי? ← כן, אם מצא טעמים מיוחדים שלא לעשות כן (סעיף 52(א) לחוק העונשין). **וריאציה 2 — חריג לדחייה:** מתי בית המשפט אינו רשאי לדחות הפעלה? ← אם העבירה שבגללה הופר התנאי היא פשע שדינה מאסר עולם (סעיף 52(ב) לחוק העונשין). **וריאציה 3 — מטרת הדחייה:** מהי מטרת הסמכות לדחות או להאריך? ← לאפשר גמישות במקרים בהם הפעלה מיידית אינה צודקת או אינה משרתת את מטרות הענישה, תוך מתן הזדמנות לשיקום. ',
    'דחיית הפעלת מאסר על תנאי (סעיף 52(א) חוק העונשין) ← מטעמים מיוחדים ← חריג: לא בפשע שדינה מאסר עולם (סעיף 52(ב)).',
    '["חוק העונשין, התשל\"ז-1977, סעיף 52(א)", "חוק העונשין, התשל\"ז-1977, סעיף 52(ב)", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יז - עונשים"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'ערעור על החלטה להפעלת מאסר על תנאי', 4, 'בית המשפט השלום בראשון לציון החליט להפעיל את המאסר על תנאי של יאיר. יאיר מעוניין לערער על החלטה זו. מהו ההליך הנכון לערעור?',
    'שאלה זו עוסקת בהליך הערעור על החלטה להפעלת מאסר על תנאי, ומבהירה את הסמכות העניינית של ערכאת הערעור ואת מועדי הגשת הערעור. היא מתבססת על הוראות חוק בתי המשפט וחוק סדר הדין הפלילי.',
    'החלטה של בית משפט להפעיל מאסר על תנאי היא החלטה סופית בעניין העונש, ולכן היא ניתנת לערעור. סעיף 40(א) לחוק בתי המשפט [נוסח משולב], התשמ"ד-1984, קובע כי פסק דין של בית משפט שלום ניתן לערעור בזכות לבית המשפט המחוזי. החלטה להפעלת מאסר על תנאי נחשבת כחלק מפסק הדין לעניין העונש. סעיף 199 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע כי ערעור על פסק דין יוגש בתוך 45 ימים מיום מתן פסק הדין. לכן, יאיר רשאי לערער על החלטת בית משפט השלום בראשון לציון להפעלת המאסר על תנאי בפני בית המשפט המחוזי, וזאת בתוך 45 ימים מיום מתן ההחלטה. סעיף 40(א) לחוק בתי המשפט [נוסח משולב], התשמ"ד-1984סעיף 199 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982נבו - המתמחה סדר הדין הפלילי (2026) | פרק יז - עונשים',
    'הטעות הנפוצה היא לחשוב שהחלטה להפעלת מאסר על תנאי אינה ניתנת לערעור, או לבלבל בין הליך ערעור בזכות לבין בקשת רשות ערעור.',
    '["ערעור פלילי", "הפעלת מאסר על תנאי", "סמכות ערעור", "מועד ערעור", "חוק בתי המשפט", "חוק סדר הדין הפלילי", "פסק דין"]'::jsonb,
    '**וריאציה 1 — זכות ערעור:** האם ניתן לערער על החלטה להפעלת מאסר על תנאי? ← כן, זוהי החלטה סופית בעניין העונש וניתנת לערעור בזכות (סעיף 40(א) לחוק בתי המשפט). **וריאציה 2 — ערכאת הערעור:** לאיזו ערכאה מוגש הערעור? ← לבית המשפט המחוזי, אם ההחלטה ניתנה בבית משפט שלום (סעיף 40(א) לחוק בתי המשפט). **וריאציה 3 — מועד הגשה:** מהו מועד הגשת הערעור? ← בתוך 45 ימים מיום מתן ההחלטה (סעיף 199 לחוק סדר הדין הפלילי).',
    'ערעור על הפעלת מאסר על תנאי ← בזכות למחוזי (סעיף 40(א) חוק בתי המשפט) ← תוך 45 יום (סעיף 199 חסד"פ).',
    '["חוק בתי המשפט [נוסח משולב], התשמ\"ד-1984, סעיף 40(א)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 199", "נבו - המתמחה, סדר הדין הפלילי (2026), פרק יז - עונשים"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לא, המאסר על תנאי הוטל בגין עבירת אלימות, ולכן ניתן להפעילו רק אם יאיר יורשע בעבירת אלימות נוספת.', false, 'תשובה זו שגויה. התנאי שהוטל הוא "עבירה מסוג פשע", ולאו דווקא עבירת אלימות ספציפית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'כן, המאסר על תנאי הוטל בתנאי שלא יעבור עבירה מסוג פשע, ועבירת הגניבה היא פשע, ולכן ניתן להפעילו.', true, 'זו התשובה הנכונה. סעיף 52(א) לחוק העונשין, התשל"ז-1977, קובע כי בית המשפט יורה על הפעלת המאסר על תנאי אם הנאשם עבר עבירה נוספת בתקופת התנאי, והעבירה הנוספת היא מסוג העבירות שנקבעו בתנאי. במקרה זה, התנאי היה "עבירה מסוג פשע", ועבירת הגניבה היא פשע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'לא, עבירת הגניבה אינה עבירה זהה לעבירת האלימות, ולכן לא ניתן להפעיל את המאסר על תנאי.', false, 'תשובה זו שגויה. התנאי אינו מחייב זהות בין העבירות, אלא עמידה בתנאי שנקבע (במקרה זה, "עבירה מסוג פשע").', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'כן, אך רק אם בית המשפט ימצא טעמים מיוחדים שלא להפעיל את המאסר על תנאי, שכן עבירת הגניבה אינה עבירת אלימות.', false, 'תשובה זו שגויה. טעמים מיוחדים רלוונטיים לשקול אי-הפעלה, אך לא כתנאי להפעלה במקרה שהתנאי הופר.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'בית המשפט יפעיל את המאסר על תנאי באופן אוטומטי, אלא אם כן הנאשם יוכיח כי לא ידע על קיומו של המאסר על תנאי.', false, 'תשובה זו שגויה. הפעלת מאסר על תנאי אינה אוטומטית, וקיימים שיקולים רחבים יותר מאשר ידיעת הנאשם על התנאי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'בית המשפט יבחן את נסיבות העבירה המפרה, חומרתה, מידת הפגיעה בערכים המוגנים, התנהגות הנאשם מאז הטלת המאסר על תנאי, וכן את מטרות הענישה, תוך מתן משקל לשיקום הנאשם.', true, 'זו התשובה הנכונה. הפסיקה קבעה כי אלו הם השיקולים המרכזיים שבית המשפט יבחן בבואו להחליט על הפעלת מאסר על תנאי, תוך איזון בין מטרות הענישה השונות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'בית המשפט יפעיל את המאסר על תנאי רק אם התביעה תבקש זאת במפורש, ואין לו סמכות לדחות את הפעלתו מיוזמתו.', false, 'תשובה זו שגויה. לבית המשפט סמכות לדחות או להאריך את תקופת התנאי גם מיוזמתו, אם מצא טעמים מיוחדים לכך.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'בית המשפט יפעיל את המאסר על תנאי רק אם העבירה המפרה היא זהה לחלוטין לעבירה המקורית שבגינה הוטל המאסר על תנאי.', false, 'תשובה זו שגויה. כפי שצוין בשאלה הקודמת, נדרשת עמידה בתנאי שנקבע, ולאו דווקא זהות מוחלטת של העבירות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'בית המשפט חייב להפעיל את המאסר על תנאי, שכן התנאי הופר, ואין לו סמכות לדחות את הפעלתו.', false, 'תשובה זו שגויה. סעיף 52(א) לחוק העונשין מעניק לבית המשפט סמכות לדחות את הפעלת המאסר על תנאי או להאריך את תקופת התנאי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בית המשפט רשאי לדחות את הפעלת המאסר על תנאי, או להאריך את תקופת התנאי, אם מצא טעמים מיוחדים שלא להפעילו, ובלבד שהעבירה המפרה אינה פשע שדינה מאסר עולם.', true, 'זו התשובה הנכונה. סעיף 52(א) לחוק העונשין מאפשר דחייה או הארכה של תקופת התנאי מטעמים מיוחדים, וסעיף 52(ב) קובע חריג לעבירות פשע שדינן מאסר עולם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט רשאי לדחות את הפעלת המאסר על תנאי, אך רק אם התביעה מסכימה לכך.', false, 'תשובה זו שגויה. הסכמת התביעה אינה תנאי לדחייה או הארכה, אם כי היא יכולה להשפיע על שיקול דעת בית המשפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בית המשפט רשאי להמיר את המאסר על תנאי בעונש קל יותר, כגון קנס או שירות לתועלת הציבור.', false, 'תשובה זו שגויה. החוק אינו מאפשר המרה של מאסר על תנאי בעונש קל יותר במקרה של הפרת תנאי, אלא רק הפעלה, דחייה או הארכה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'יאיר רשאי לערער על החלטת ההפעלה בפני בית המשפט המחוזי, וזאת בתוך 45 ימים מיום מתן ההחלטה.', true, 'זו התשובה הנכונה. סעיף 40(א) לחוק בתי המשפט [נוסח משולב], התשמ"ד-1984, קובע כי פסק דין של בית משפט שלום ניתן לערעור בזכות לבית המשפט המחוזי, וסעיף 199 לחוק סדר הדין הפלילי קובע את מועד הערעור.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'יאיר אינו רשאי לערער על החלטה להפעלת מאסר על תנאי, שכן זוהי החלטה דיונית ולא פסק דין.', false, 'תשובה זו שגויה. החלטה להפעלת מאסר על תנאי היא החלטה סופית בעניין העונש, וניתן לערער עליה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'יאיר רשאי להגיש בקשת רשות ערעור לבית המשפט העליון, שכן מדובר בעניין עקרוני.', false, 'תשובה זו שגויה. ערעור על החלטת בית משפט שלום הוא בזכות לבית המשפט המחוזי, ולא בקשת רשות ערעור לעליון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'יאיר רשאי לערער על החלטת ההפעלה בפני בית המשפט שהטיל את המאסר על תנאי מלכתחילה.', false, 'תשובה זו שגויה. הערעור מוגש לערכאת הערעור הרלוונטית (המחוזי), ולא לערכאה שהטילה את העונש המקורי.', 4);

END $$;

-- ============================================================
-- Q38 — 2024-W-Q38 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q38';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q38 skipped: external_id % already exists', '2024-W-Q38';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q38', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'מתי יושעה מכהונתו חבר כנסת שהורשע בביצוע עבירה פלילית?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 38}'::jsonb,
    'השאלה עוסקת בהוראות סעיף 42ב לחוק-יסוד: הכנסת, המסדיר את השעייתו של חבר כנסת מכהונתו בעקבות הרשעה בעבירה פלילית. היא מבהירה את התנאים להשעיה (קביעת קלון על ידי בית המשפט) ואת משך ההשעיה (מיום הקביעה ועד שפסק הדין נעשה סופי).',
    'סעיף 42ב(א) לחוק-יסוד: הכנסת קובע כי "חבר הכנסת שהורשע בעבירה פלילית וקבע בית המשפט, ביוזמתו או לבקשת היועץ המשפטי לממשלה, שיש עם העבירה קלון, יושעה מכהונתו בכנסת מיום קביעת בית המשפט ועד למועד שבו פסק הדין נעשה סופי". הוראה זו מבחינה בין השעיה לבין הפסקת חברות. השעיה היא צעד זמני, המתרחש כאשר בית המשפט קובע קלון, אך פסק הדין טרם הפך לסופי. מטרת ההשעיה היא למנוע מחבר כנסת שהורשע בעבירה חמורה להמשיך לכהן בתפקידו עד למיצוי ההליכים המשפטיים. אם פסק הדין הופך סופי ונקבע קלון, חברותו בכנסת נפסקת באופן קבוע מכוח סעיף 42א לחוק-יסוד: הכנסת. סעיף 42ב(א) לחוק-יסוד: הכנסתבג"ץ 306/81 שמואל פלאטו שרון נ'' ועדת הכנסת (30.07.1981)נבו - המתמחה חוקי יסוד (2026) | השעיה של חבר כנסת (סעיף 42ב לחו"י הכנסת)בג"ץ 2592/20 התנועה למען איכות השלטון בישראל נ'' היועץ המשפטי לממשלה (27.05.2020)',
    'הטעות הנפוצה היא לבלבל בין השעיה (סעיף 42ב) לבין הפסקת חברות (סעיף 42א), או לחשוב שההשעיה מתחילה מיום ההרשעה ללא קביעת קלון.',
    '["השעיה", "חבר כנסת", "קלון", "פסק דין סופי", "חוק-יסוד: הכנסת", "עבירה פלילית", "יועץ משפטי לממשלה"]'::jsonb,
    '**וריאציה 1 — תנאי ההשעיה:** מהו התנאי להשעיית חבר כנסת? ← הרשעה בעבירה פלילית וקביעת בית המשפט שיש עם העבירה קלון (סעיף 42ב(א) לחוק-יסוד: הכנסת). **וריאציה 2 — משך ההשעיה:** מתי מתחילה ומסתיימת ההשעיה? ← מיום קביעת בית המשפט ועד למועד שבו פסק הדין נעשה סופי (סעיף 42ב(א) לחוק-יסוד: הכנסת). **וריאציה 3 — השעיה לעומת הפסקת חברות:** מה ההבדל בין השעיה להפסקת חברות? ← השעיה היא זמנית עד לפסק דין סופי, הפסקת חברות היא קבועה ביום שפסק הדין נעשה סופי ונקבע קלון (סעיף 42א(א) לחוק-יסוד: הכנסת).',
    'ח"כ שהורשע + קלון ← יושעה מיום קביעת ביהמ"ש עד פסק דין סופי (42ב(א) חוק-יסוד: הכנסת).',
    '["חוק-יסוד: הכנסת, סעיף 42א(א)", "חוק-יסוד: הכנסת, סעיף 42ב(א)", "בג\"ץ 306/81 שמואל פלאטו שרון נ'' ועדת הכנסת (30.07.1981)", "בג\"ץ 2592/20 התנועה למען איכות השלטון בישראל נ'' היועץ המשפטי לממשלה (27.05.2020)", "נבו - המתמחה, חוקי יסוד (2026), השעיה של חבר כנסת (סעיף 42ב לחו\"י הכנסת)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'אם קבע בית המשפט שיש עם העבירה קלון, וזאת מיום קביעת בית המשפט ועד למועד שבו פסק הדין נעשה סופי.', true, 'זו התשובה הנכונה. סעיף 42ב(א) לחוק-יסוד: הכנסת קובע כי חבר כנסת יושעה מכהונתו מיום קביעת בית המשפט שיש עם העבירה קלון ועד למועד שבו פסק הדין נעשה סופי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מיום הרשעתו בבית המשפט ועד למועד שבו פסק הדין נעשה סופי.', false, 'תשובה זו שגויה. ההשעיה אינה אוטומטית מיום ההרשעה, אלא מותנית בקביעת בית המשפט כי יש עם העבירה קלון.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אם קבע בית המשפט שיש עם העבירה קלון, וזאת ביום שפסק הדין נעשה סופי.', false, 'תשובה זו שגויה. ביום שפסק הדין נעשה סופי, אם נקבע קלון, חברותו של חבר הכנסת נפסקת, ולא רק מושעית. ההשעיה היא לתקופה שעד לפסק הדין הסופי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ביום שפסק הדין נעשה סופי.', false, 'תשובה זו שגויה. ביום שפסק הדין נעשה סופי, אם נקבע קלון, חברותו של חבר הכנסת נפסקת, ולא רק מושעית. בנוסף, ההשעיה מותנית בקביעת קלון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'הפסקת חברות בכנסת לעומת השעיה', 1, 'חבר כנסת הורשע בפסק דין סופי בעבירה פלילית ובית המשפט קבע שיש עם העבירה קלון. מהי ההשלכה המיידית על חברותו בכנסת?',
    'שאלה זו מבחינה בין השעיה לבין הפסקת חברות של חבר כנסת שהורשע בעבירה פלילית שיש עמה קלון. היא מתמקדת בסעיף 42א לחוק-יסוד: הכנסת, הקובע את התנאים להפסקת חברות, ומדגישה את השינויים ההיסטוריים בחקיקה בנושא.',
    'סעיף 42א(א) לחוק-יסוד: הכנסת קובע כי "חבר הכנסת שהורשע בפסק דין סופי בעבירה פלילית, וקבע בית המשפט, ביוזמתו או לבקשת היועץ המשפטי לממשלה, שיש עם העבירה קלון, תיפסק חברותו בכנסת ביום שפסק הדין נעשה סופי". חשוב להבחין בין השעיה (סעיף 42ב) לבין הפסקת חברות (סעיף 42א). השעיה היא צעד זמני החל מיום קביעת בית המשפט ועד שפסק הדין נעשה סופי. הפסקת חברות היא צעד קבוע המתרחש ביום שפסק הדין נעשה סופי. בעבר, נדרש גם עונש מאסר בפועל של שנה או יותר, והחלטת הכנסת ברוב מיוחד, אך דרישות אלו בוטלו בתיקונים לחוק היסוד בשנים 1995 ו-2001. סעיף 42א(א) לחוק-יסוד: הכנסתת"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח"כ צחי הנגבי (09.11.2010)ת"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח"כ צחי הנגבי (09.11.2010)ת"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח"כ צחי הנגבי (09.11.2010)נבו - המתמחה חוקי יסוד (2026) | הפסקת כהונה של חבר כנסת שהורשע (סעיף 42א לחו"י הכנסת)',
    'הטעות הנפוצה היא לבלבל בין השעיה (צעד זמני) לבין הפסקת חברות (צעד קבוע), או להתבסס על נוסחי חוק ישנים שדרשו מאסר בפועל או החלטת כנסת להפסקת חברות.',
    '["הפסקת חברות", "השעיה", "חבר כנסת", "קלון", "פסק דין סופי", "חוק-יסוד: הכנסת", "היסטוריה חקיקתית"]'::jsonb,
    '**וריאציה 1 — פסק דין סופי:** מה קורה לחבר כנסת שהורשע בפסק דין סופי ונקבע קלון? ← חברותו בכנסת תיפסק ביום שפסק הדין נעשה סופי (סעיף 42א(א) לחוק-יסוד: הכנסת). **וריאציה 2 — לפני פסק דין סופי:** מה קורה לחבר כנסת שהורשע ונקבע קלון, אך פסק הדין אינו סופי? ← הוא יושעה מכהונתו עד למועד שבו פסק הדין נעשה סופי (סעיף 42ב(א) לחוק-יסוד: הכנסת). **וריאציה 3 — דרישת מאסר בפועל:** האם נדרש מאסר בפועל להפסקת חברות? ← לא, דרישה זו בוטלה בתיקון משנת 2001 (ת"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח"כ צחי הנגבי).',
    'ח"כ הורשע + קלון ← פסק דין סופי: הפסקת חברות (42א) ← לפני פסק דין סופי: השעיה (42ב) ← לא נדרש מאסר בפועל.',
    '["חוק-יסוד: הכנסת, סעיף 42א(א)", "חוק-יסוד: הכנסת, סעיף 42ב(א)", "ת\"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח\"כ צחי הנגבי (09.11.2010)", "נבו - המתמחה, חוקי יסוד (2026), הפסקת כהונה של חבר כנסת שהורשע (סעיף 42א לחו\"י הכנסת)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'הגדרת קלון והשפעתו על כשירות ציבורית', 2, 'מהו המבחן לקביעת "קלון" בעבירה פלילית, וכיצד הוא משפיע על כשירותו של אדם לכהן בתפקיד ציבורי?',
    'שאלה זו עוסקת במושג "קלון" במשפט הישראלי, בהגדרתו, במבחנים לקביעתו ובהשלכותיו על כשירות לכהונה ציבורית. היא מתבססת על הפסיקה והספרות המשפטית המדגישות את אופיו הערכי-מוסרי של הקלון ואת תפקידו כמנגנון סינון לשמירה על טוהר המידות בשירות הציבורי.',
    'המושג "קלון" הוא מושג עמום הנושא מטען מוסרי-ערכי שלילי, בבחינת דופי מוסרי. קביעתו אינה עניין ערטילאי אלא תלויה בהקשר ובנסיבות. המבחן לקביעת קלון אינו טמון רק בסיווג הפורמלי של העבירה בקודקס הפלילי, אלא במהותה ובנסיבות ביצועה, ובמידה שבה היא מבטאת פגם מוסרי. קלון אינו רכיב ענישתי, אלא מנגנון סינון שנועד לשמור על היגיינה ציבורית וטוהר מידות של משרתי ציבור ונבחריו. קיומו של קלון מגביל או שולל את ההכשר למלא תפקידים ציבוריים שונים או לשמש בעיסוק הדורש מידה מיוחדת של יושרה וניקיון כפיים. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | 1. הגדרת הביטוי "עבירה שיש עמה קלון"ת"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח"כ צחי הנגבי (09.11.2010)ת"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח"כ צחי הנגבי (09.11.2010)יונה דה-לוי דיני הנוטריון ותולדותיהם (2016) | מהו קלון?יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | 2. הנפקות לקיומו של קלון בעבירה',
    'הטעות הנפוצה היא להתייחס לקלון כאל עונש נוסף או כאל קביעה אוטומטית על בסיס סיווג העבירה, במקום להבין את אופיו המוסרי-ערכי ואת תפקידו כמנגנון סינון.',
    '["קלון", "פגם מוסרי", "כשירות ציבורית", "נסיבות העבירה", "תכלית החקיקה", "מנגנון סינון", "טוהר מידות"]'::jsonb,
    '**וריאציה 1 — מהות הקלון:** מהו קלון? ← מושג עמום המבטא פגם מוסרי-ערכי שלילי, דופי מוסרי (יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית). **וריאציה 2 — מבחן הקלון:** כיצד נקבע קלון? ← לא לפי סיווג פורמלי, אלא לפי מהות העבירה ונסיבותיה, והאם היא מבטאת פגם מוסרי (יונה דה-לוי דיני הנוטריון ותולדותיהם). **וריאציה 3 — תכלית הקלון:** מהי תכלית קביעת קלון? ← מנגנון סינון לשמירה על היגיינה ציבורית וטוהר מידות של נבחרי ציבור, ולא עונש נוסף (ת"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח"כ צחי הנגבי).',
    'קלון ← פגם מוסרי-ערכי ← נקבע לפי נסיבות ותכלית ← מנגנון סינון לכשירות ציבורית.',
    '["יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022), 1. הגדרת הביטוי \"עבירה שיש עמה קלון\"", "ת\"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח\"כ צחי הנגבי (09.11.2010)", "יונה דה-לוי, דיני הנוטריון ותולדותיהם (2016), מהו קלון?"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'השעיה של חבר כנסת שנידון למאסר', 3, 'חבר כנסת הורשע בעבירה פלילית ונידון למאסר בפועל, אך בית המשפט לא קבע שיש עם העבירה קלון. מה הדין לעניין השעייתו מכהונתו בכנסת?',
    'שאלה זו בוחנת את ההוראה הספציפית בסעיף 42ב(ב) לחוק-יסוד: הכנסת, העוסקת בהשעיית חבר כנסת שנידון למאסר בפועל. היא מדגישה כי במקרה זה, ההשעיה מתרחשת למשך תקופת המאסר, ואינה מותנית בקביעת קלון על ידי בית המשפט, בניגוד למצב של השעיה לפי סעיף 42ב(א).',
    'סעיף 42ב לחוק-יסוד: הכנסת קובע שני מצבים שונים להשעיית חבר כנסת. סעיף 42ב(א) עוסק בהשעיה כאשר בית המשפט קובע שיש עם העבירה קלון, וההשעיה נמשכת מיום הקביעה ועד שפסק הדין נעשה סופי. לעומת זאת, סעיף 42ב(ב) קובע כי "חבר הכנסת שהורשע בעבירה פלילית ונידון למאסר יושעה מכהונתו בכנסת למשך הזמן שהוא נושא את עונש המאסר". במקרה זה, ההשעיה אינה מותנית בקביעת קלון, אלא בעצם הטלת עונש מאסר בפועל. ההשעיה חלה למשך תקופת ריצוי המאסר. סעיף 42ב(ב) לחוק-יסוד: הכנסתנבו - המתמחה חוקי יסוד (2026) | השעיה של חבר כנסת (סעיף 42ב לחו"י הכנסת)בג"ץ 306/81 שמואל פלאטו שרון נ'' ועדת הכנסת (30.07.1981)',
    'הטעות הנפוצה היא להניח שכל השעיה של חבר כנסת מותנית בקביעת קלון, מבלי להבחין בין המקרים השונים המפורטים בסעיף 42ב לחוק-יסוד: הכנסת.',
    '["השעיה", "חבר כנסת", "מאסר בפועל", "קלון", "חוק-יסוד: הכנסת", "עונש מאסר"]'::jsonb,
    '**וריאציה 1 — השעיה עקב מאסר:** מתי חבר כנסת מושעה אם נידון למאסר? ← למשך הזמן שהוא נושא את עונש המאסר (סעיף 42ב(ב) לחוק-יסוד: הכנסת). **וריאציה 2 — דרישת קלון:** האם נדרש קלון להשעיה עקב מאסר? ← לא, השעיה זו אינה מותנית בקביעת קלון (סעיף 42ב(ב) לחוק-יסוד: הכנסת). **וריאציה 3 — השעיה לפני כהונה:** האם הוראות השעיה חלות גם על מי שהורשע לפני שהיה חבר כנסת? ← כן, הוראות סעיף 42ב חלות גם על חבר כנסת שהורשע בעבירה כאמור לפני היותו חבר כנסת (סעיף 42ב(ב1) לחוק-יסוד: הכנסת).',
    'ח"כ נידון למאסר ← מושעה למשך המאסר (42ב(ב)) ← ללא קשר לקלון ← חל גם על הרשעה לפני כהונה.',
    '["חוק-יסוד: הכנסת, סעיף 42ב(ב)", "חוק-יסוד: הכנסת, סעיף 42ב(ב1)", "נבו - המתמחה, חוקי יסוד (2026), השעיה של חבר כנסת (סעיף 42ב לחו\"י הכנסת)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'השפעת התפטרות חבר כנסת על קביעת קלון', 4, 'חבר כנסת שהוגש נגדו כתב אישום בעבירות מס, התפטר מכהונתו בכנסת לפני מתן גזר הדין. היועץ המשפטי לממשלה הודיע כי לא יטען לעניין קלון בפני הערכאה הדיונית, נוכח ההתפטרות. האם התפטרות זו מונעת מבית המשפט לקבוע קלון?',
    'שאלה זו עוסקת בהשפעת התפטרותו של חבר כנסת מכהונתו על סמכות בית המשפט לקבוע קלון בעבירה שביצע, בהקשר של סעיף 42א לחוק-יסוד: הכנסת. היא מתייחסת לפסיקת בג"ץ בעניין דרעי, אשר דנה בתרחיש "הדלת המסתובבת" ובפרשנות המונח "חבר כנסת שהורשע".',
    'סעיף 42א(א) לחוק-יסוד: הכנסת קובע כי "חבר הכנסת שהורשע בפסק דין סופי בעבירה פלילית, וקבע בית המשפט... שיש עם העבירה קלון, תיפסק חברותו בכנסת...". הפסיקה, ובפרט בג"ץ 8954/21 בעניין דרעי, קבעה כי ככל שחבר הכנסת מתפטר מכהונתו לפני מתן גזר הדין, הוא אינו נחשב עוד "חבר כנסת" לעניין סעיף זה. כתוצאה מכך, נשללת מבית המשפט הסמכות לקבוע אם יש בעבירות שביצע קלון לצורך הפסקת חברות בכנסת. התפטרות זו מונעת את תחולת הסנקציה של הפסקת חברות, ומוציאה את הדיון בשאלת הקלון מתחום סמכותו של בית המשפט בהקשר זה. בג"ץ 8954/21 התנועה למען איכות השלטון בישראל נ'' היועץ המשפטי לממשלה (17.01.2022)בג"ץ 8954/21 התנועה למען איכות השלטון בישראל נ'' היועץ המשפטי לממשלה (17.01.2022)בג"ץ 8948/22 אילן שיינפלד נ'' הכנסת (18.01.2023)בג"ץ 8948/22 אילן שיינפלד נ'' הכנסת (18.01.2023)נבו - המתמחה חוקי יסוד (2026) | סיום כהונה של נושאי משרה עקב התפטרות והרשעה - טבלת השוואה',
    'הטעות הנפוצה היא לחשוב שקביעת קלון היא סמכות כללית של בית המשפט שאינה תלויה בסטטוס הנאשם כחבר כנסת בעת מתן גזר הדין, מבלי להכיר בפרשנות המצמצמת של סעיף 42א(א) לחוק-יסוד: הכנסת.',
    '["קלון", "חבר כנסת", "התפטרות", "סמכות בית משפט", "חוק-יסוד: הכנסת", "פסק דין סופי", "הסדר טיעון", "תרחיש הדלת המסתובבת"]'::jsonb,
    '**וריאציה 1 — התפטרות לפני גזר דין:** האם התפטרות חבר כנסת לפני גזר דין מונעת קביעת קלון? ← כן, שכן סעיף 42א(א) חל רק על "חבר כנסת שהורשע" (בג"ץ 8948/22 אילן שיינפלד נ'' הכנסת). **וריאציה 2 — תרחיש הדלת המסתובבת:** מהו "תרחיש הדלת המסתובבת"? ← חשש שחבר כנסת יתפטר כדי למנוע קביעת קלון, ואז ישוב וייבחר לכנסת מבלי ששאלת הקלון נדונה (בג"ץ 8948/22 אילן שיינפלד נ'' הכנסת). **וריאציה 3 — השלכות על כשירות לשר:** האם התפטרות מונעת קביעת קלון לעניין כשירות לכהן כשר? ← לא, לעניין כשירות לכהן כשר, קביעת קלון יכולה להיעשות גם על ידי יו"ר ועדת הבחירות המרכזית, ואינה תלויה בסטטוס חבר הכנסת בעת ההרשעה (בג"ץ 8948/22 אילן שיינפלד נ'' הכנסת).',
    'התפטרות ח"כ לפני גזר דין ← מונעת קביעת קלון לפי 42א(א) חוק-יסוד: הכנסת ← לא מונעת קביעת קלון לעניין כשירות לשר.',
    '["חוק-יסוד: הכנסת, סעיף 42א(א)", "בג\"ץ 8954/21 התנועה למען איכות השלטון בישראל נ'' היועץ המשפטי לממשלה (17.01.2022)", "בג\"ץ 8948/22 אילן שיינפלד נ'' הכנסת (18.01.2023)", "נבו - המתמחה, חוקי יסוד (2026), סיום כהונה של נושאי משרה עקב התפטרות והרשעה - טבלת השוואה"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'חברותו בכנסת תיפסק ביום שפסק הדין נעשה סופי.', true, 'זו התשובה הנכונה. סעיף 42א(א) לחוק-יסוד: הכנסת קובע כי חברותו של חבר כנסת שהורשע בפסק דין סופי בעבירה שיש עמה קלון, תיפסק ביום שפסק הדין נעשה סופי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'חברותו בכנסת תושעה מיום קביעת בית המשפט ועד למועד שבו פסק הדין נעשה סופי.', false, 'תשובה זו מתארת את מצב ההשעיה, החל לפני שפסק הדין נעשה סופי, ולא את ההשלכה המיידית של פסק דין סופי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'חברותו בכנסת תיפסק רק אם הוטל עליו עונש מאסר בפועל של שנה אחת או יותר.', false, 'תשובה זו שגויה. דרישת המאסר בפועל בוטלה בתיקון משנת 2001 לסעיף 42א לחוק-יסוד: הכנסת, וכיום די בקביעת קלון בפסק דין סופי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'הכנסת רשאית, ברוב של שני שלישים מחבריה, להחליט על הפסקת חברותו.', false, 'תשובה זו שגויה. הצורך בהחלטת הכנסת ברוב מיוחד בוטל בתיקון משנת 1995 לסעיף 42א לחוק-יסוד: הכנסת.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'קלון הוא מושג עמום המבטא פגם מוסרי-ערכי שלילי, וקביעתו תלויה בנסיבות ביצוע העבירה ובתכלית החקיקה. קיומו של קלון מגביל או שולל את ההכשר למלא תפקידים ציבוריים הדורשים יושרה.', true, 'זו התשובה הנכונה. הפסיקה והספרות המשפטית מדגישות את אופיו הערכי-מוסרי של הקלון, את תלותו בנסיבות העבירה ובתכלית החקיקה, ואת השלכותיו על כשירות לתפקידים ציבוריים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'קלון נקבע באופן אובייקטיבי על פי סיווג העבירה בקודקס הפלילי, ואינו מושפע מנסיבות ביצועה או מתכלית החקיקה.', false, 'תשובה זו שגויה. הפסיקה קבעה כי דירוג העבירה בקודקס הפלילי אינו חזות הכל, ויש להתייחס למהות העבירה ונסיבותיה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'קביעת קלון נועדה להעניש את העבריין על העבירה שביצע, ואינה קשורה לתנאי התאמה וכשירות לתפקיד ציבורי.', false, 'תשובה זו שגויה. קביעת קלון אינה רכיב ענישתי, אלא מנגנון סינון שנועד לשמור על היגיינה ציבורית וטוהר מידות של נבחרי ציבור.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'קלון נקבע רק בעבירות חמורות במיוחד שדינן מאסר בפועל, ואינו חל על עבירות קלות יותר.', false, 'תשובה זו שגויה. קלון יכול לדבוק גם בעבירות שאינן מהחמורות ביותר, ואינו תלוי בהכרח בעונש מאסר בפועל.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'חברותו בכנסת תושעה למשך הזמן שהוא נושא את עונש המאסר, גם ללא קביעת קלון.', true, 'זו התשובה הנכונה. סעיף 42ב(ב) לחוק-יסוד: הכנסת קובע כי חבר כנסת שנידון למאסר יושעה מכהונתו למשך תקופת המאסר, ללא תלות בקביעת קלון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'חברותו בכנסת לא תושעה, שכן השעיה מותנית תמיד בקביעת קלון על ידי בית המשפט.', false, 'תשובה זו שגויה. סעיף 42ב לחוק-יסוד: הכנסת מבחין בין השעיה עקב קלון (סעיף קטן א'') לבין השעיה עקב מאסר (סעיף קטן ב'').', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'חברותו בכנסת תושעה רק אם עונש המאסר הוא שנה אחת או יותר.', false, 'תשובה זו שגויה. סעיף 42ב(ב) אינו קובע דרישה לתקופת מאסר מינימלית לצורך השעיה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'הכנסת רשאית, ברוב של שני שלישים מחבריה, להחליט על השעייתו.', false, 'תשובה זו שגויה. השעיה עקב מאסר היא אוטומטית מכוח החוק, ואינה דורשת החלטת כנסת ברוב מיוחד.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'כן, התפטרות חבר הכנסת לפני מתן גזר הדין שוללת מבית המשפט את הסמכות לקבוע קלון, שכן סעיף 42א(א) לחוק-יסוד: הכנסת חל רק על "חבר כנסת שהורשע".', true, 'זו התשובה הנכונה. הפסיקה קבעה כי התפטרות חבר כנסת לפני מתן גזר הדין מונעת את תחולת סעיף 42א(א) לחוק-יסוד: הכנסת, ובכך שוללת מבית המשפט את הסמכות לקבוע קלון לעניין הפסקת חברות בכנסת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'לא, בית המשפט רשאי לקבוע קלון גם אם חבר הכנסת התפטר, שכן הקלון דבק בעבירה עצמה ולא בסטטוס של חבר הכנסת.', false, 'תשובה זו שגויה. אף שהקלון דבק בעבירה, סמכות בית המשפט לקבוע קלון לעניין סעיף 42א(א) מותנית בכך שהנאשם הוא "חבר כנסת שהורשע".', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'כן, אך רק אם היועץ המשפטי לממשלה הסכים במפורש שלא לטעון לקלון במסגרת הסדר טיעון.', false, 'תשובה זו שגויה. הסכמת היועץ המשפטי לממשלה היא תוצאה של ההתפטרות, ולא התנאי לשלילת הסמכות מבית המשפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'לא, בית המשפט חייב לקבוע קלון אם העבירה היא מסוג העבירות שיש עמן קלון, ללא קשר להתפטרות.', false, 'תשובה זו שגויה. קביעת קלון אינה אוטומטית, ובמקרה זה, התפטרות חבר הכנסת שוללת את הסמכות הספציפית של בית המשפט לקבוע קלון לעניין סעיף 42א(א).', 4);

END $$;

-- ============================================================
-- Q39 — 2024-W-Q39 — chapter=civil_proc subtopic=class_actions
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q39';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q39 skipped: external_id % already exists', '2024-W-Q39';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'class_actions';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'class_actions';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q39', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'כנגד עיריית רעננה הוגשה ביום 1.6.2023 בקשה לאישור תובענה ייצוגית להשבת סכומים שגבתה שלא כדין בגין ארנונה. הבקשה הומצאה לעירייה באותו היום. עיריית רעננה, שהבינה שאכן הגבייה אינה כדין, לא רוצה שבית המשפט יאשר את התובענה הייצוגית. מה באפשרות העירייה לעשות?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 39}'::jsonb,
    'שאלה זו עוסקת במנגנון "הודעת חדילה" הקבוע בסעיף 9 לחוק תובענות ייצוגיות, תשס"ו-2006, המעניק לרשויות ציבוריות הגנה מיוחדת מפני תביעות השבה ייצוגיות. היא בוחנת את התנאים להפעלת מנגנון זה, ובפרט את לוחות הזמנים להגשת הודעת החדילה ואת אופן חישובם, תוך התייחסות להלכה הפסוקה ולתקנות סדר הדין האזרחי.',
    'סעיף 9(ב) לחוק תובענות ייצוגיות קובע כי בית המשפט לא יאשר תובענה ייצוגית בתביעת השבה נגד רשות, אם הרשות הודיעה כי תחדל מהגבייה שבשלה הוגשה הבקשה לאישור והוכח לבית המשפט כי היא חדלה מהגבייה כאמור לכל המאוחר במועד הקובע. סעיף 9(א) מגדיר את "המועד הקובע" כ-90 ימים ממועד הגשת הבקשה לאישור. עם זאת, הפסיקה, ובפרט בר"מ 7689/13 מינהל מקרקעי ישראל נ'' דהאן, קבעה כי אם בקשת האישור הומצאה לרשות לאחר המועד בו הוגשה לבית המשפט, יהווה הדבר טעם המצדיק את הארכת התקופה של 90 הימים, כך שהיא תימנה ממועד ההמצאה. בנוסף, תקנה 179(ב) לתקנות סדר הדין האזרחי, תשע"ט-2018, קובעת כי תקופת פגרה של בית המשפט לא תובא במניין הימים שנקבעו בתקנות אלה או שנקבעו בידי בית המשפט, זולת אם בית המשפט הורה אחרת. הלכת דהאן אישרה כי ימי פגרה אינם נמנים במניין 90 הימים לעניין המועד האחרון בו רשאית הרשות להודיע לבית המשפט על החדילה. סעיף 9(א) לחוק תובענות ייצוגיות, תשס"ו-2006סעיף 9(ב) לחוק תובענות ייצוגיות, תשס"ו-2006תקנה 179(ב) לתקנות סדר הדין האזרחי, תשע"ט-2018ת"צ (מינהליים מרכז) 15807-07-16 אייל צדיק נ'' מדינת ישראל-רשות האכיפה והגביה (02.12.2016)ת"צ (מינהליים מרכז) 63172-06-16 גיורא שגב נ'' מדינת ישראל - הנהלת בתי המשפט (02.12.2016)בר"מ 7689/13 מינהל מקרקעי ישראל נ'' דהאן (29.06.2014)',
    'הטעות הנפוצה היא לבלבל בין מועד הגשת הבקשה למועד המצאתה, או לחשוב שימי פגרה נמנים במניין 90 הימים להודעת החדילה, מבלי להכיר בפרשנות הפסיקה ובתקנות סדר הדין האזרחי.',
    '["הודעת חדילה", "חוק תובענות ייצוגיות", "רשות ציבורית", "מועד קובע", "מניין ימים", "פגרת בית המשפט", "המצאה"]'::jsonb,
    '**וריאציה 1 — מועד החדילה:** מתי יש להגיש הודעת חדילה? ← בתוך 90 ימים מיום הגשת הבקשה לאישור, או מיום המצאתה לרשות אם יש פער (סעיף 9(א) לחוק תובענות ייצוגיות, בר"מ 7689/13 מינהל מקרקעי ישראל נ'' דהאן). **וריאציה 2 — מניין ימי פגרה:** האם ימי פגרה נמנים במניין 90 הימים? ← לא, ימי פגרה אינם נמנים במניין הימים לתקופות שנקבעו בחוק או על ידי בית המשפט, אלא אם נקבע אחרת (תקנה 179(ב) לתקנות סדר הדין האזרחי, ת"צ (מינהליים מרכז) 15807-07-16 אייל צדיק נ'' מדינת ישראל-רשות האכיפה והגביה). **וריאציה 3 — תכלית החדילה:** מהי תכלית מנגנון החדילה? ← לאפשר לרשות לבחון את חוקיות הגבייה ולחדול ממנה, תוך איזון בין אכיפת הדין לשמירה על הקופה הציבורית (ת"צ (מינהליים ת"א) 387-04-23 נתאי חיים סקוברוניק נ'' מדינת ישראל - משרד התחבורה).',
    'הודעת חדילה (סעיף 9 חוק תובענות ייצוגיות) ← תוך 90 ימים מיום המצאת הבקשה (דהאן) ← ימי פגרה לא נמנים (תקנה 179(ב) תקסד"א).',
    '["חוק תובענות ייצוגיות, תשס\"ו-2006, סעיף 9", "תקנות סדר הדין האזרחי, תשע\"ט-2018, תקנה 179", "בר\"מ 7689/13 מינהל מקרקעי ישראל נ'' דהאן (29.6.2014)", "ת\"צ (מינהליים מרכז) 15807-07-16 אייל צדיק נ'' מדינת ישראל-רשות האכיפה והגביה (02.12.2016)", "ת\"צ (מינהליים מרכז) 63172-06-16 גיורא שגב נ'' מדינת ישראל - הנהלת בתי המשפט (02.12.2016)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'להחזיר לתובע הייצוגי את הסכום שניגבה ממנו שלא כדין קודם הדיון בבקשה לאישור התובענה הייצוגית, מה שיגרום למחיקת הבקשה.', false, 'תשובה זו שגויה. החזר כספים לתובע הייצוגי בלבד אינו מנגנון החדילה הקבוע בחוק, ואינו מוביל למחיקת הבקשה לאישור תובענה ייצוגית באופן אוטומטי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'להחזיר לתובע הייצוגי את הסכום שניגבה ממנו שלא כדין קודם הדיון בבקשה לאישור התובענה הייצוגית, מה שיגרום לדחיית הבקשה.', false, 'תשובה זו שגויה. החזר כספים לתובע הייצוגי בלבד אינו המנגנון הקבוע בסעיף 9 לחוק תובענות ייצוגיות לדחיית הבקשה לאישור תובענה ייצוגית נגד רשות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'להודיע לבית המשפט כי העירייה תחדל מהגבייה הלא חוקית. ההודעה חייבת להימסר בתוך 90 ימים מיום המצאת הבקשה כאשר ימי הפגרה (קיץ וסוכות) יבואו במניין הימים.', false, 'תשובה זו שגויה. אף שהודעת החדילה צריכה להימסר תוך 90 ימים מיום המצאת הבקשה (כפי שפורש בפסיקה), ימי פגרה אינם נמנים במניין הימים לתקופות שנקבעו בחוק או על ידי בית המשפט, אלא אם נקבע אחרת.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'להודיע לבית המשפט כי העירייה תחדל מהגבייה הלא חוקית. ההודעה חייבת להימסר בתוך 90 ימים מיום המצאת הבקשה כאשר ימי הפגרה (קיץ וסוכות) לא יבואו במניין הימים.', true, 'זו התשובה הנכונה. סעיף 9(ב) לחוק תובענות ייצוגיות מאפשר לרשות להודיע על חדילה מגבייה שלא כדין. המועד הקובע הוא 90 ימים ממועד הגשת הבקשה, אך הפסיקה (בר"מ 7689/13 דהאן) קבעה כי אם יש פער בין מועד ההגשה למועד ההמצאה, יש למנות את 90 הימים ממועד ההמצאה. תקנה 179(ב) לתקנות סדר הדין האזרחי, תשע"ט-2018, קובעת כי תקופת פגרה לא תובא במניין הימים שנקבעו בחוק, אלא אם בית המשפט הורה אחרת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'הודעת חדילה: חדילה סטטוטורית', 1, 'כנגד רשות מקומית הוגשה בקשה לאישור תובענה ייצוגית בטענה לגביית היטל פיתוח שלא כדין. לאחר הגשת הבקשה, אך בטרם חלפו 90 ימים, נכנס לתוקפו חוק חדש המכשיר את גביית היטל הפיתוח. הרשות הודיעה לבית המשפט כי היא חדלה מהגבייה מכוח החוק החדש. האם הודעה זו תיחשב כהודעת חדילה תקפה?',
    'שאלה זו בוחנת את ההבנה של המושג "חדילה סטטוטורית" בהקשר של הודעת חדילה בתובענות ייצוגיות נגד רשות. היא מדגישה כי הפסיקה הכירה בכך שגם חדילה הנובעת משינוי חקיקתי, המכשיר או מבהיר את חוקיות הגבייה, תיחשב כחדילה תקפה לצורך סעיף 9 לחוק תובענות ייצוגיות.',
    'סעיף 9(ב) לחוק תובענות ייצוגיות קובע כי בית המשפט לא יאשר תובענה ייצוגית נגד רשות אם הרשות הודיעה כי תחדל מהגבייה והוכח שחדלה. הפסיקה, ובפרט רע"א 6340/07 עיריית תל אביב נ'' טיומקין, קבעה כי חדילה יכולה להיות גם "חדילה סטטוטורית". כלומר, מצב שבו הרשות חדלה מהגבייה הנטענת שלא כדין, משום שהוראת חוק חדשה הכשירה אותה או הבהירה מפורשות את דבר חוקיותה. במצב כזה, גם אם הגבייה הייתה שלא כדין קודם לכן, הודעת החדילה תיחשב תקפה, ובית המשפט לא יאשר את התובענה הייצוגית. זאת, מתוך תכלית מנגנון החדילה לאזן בין האינטרס הציבורי בשמירה על הקופה הציבורית לבין אכיפת הדין. ת"צ (מינהליים ת"א) 387-04-23 נתאי חיים סקוברוניק נ'' מדינת ישראל - משרד התחבורה (02.07.2025)ת"צ (מינהליים ת"א) 45470-03-23 גלית סקוברוניק נ'' מדינת ישראל משרד התחבורה (09.09.2024)ת"צ (מינהליים ת"א) 48218-02-18 שחר ארביב נ'' עיריית הרצליה (24.09.2018)ת"צ (מינהליים חי'') 33113-12-17 טמר אבו אלפול נ'' עירית שפרעם (30.07.2018)',
    'הטעות הנפוצה היא לחשוב שחדילה חייבת להיות פעולה יזומה של הרשות, ולא להכיר בכך שגם שינוי חקיקתי יכול להוות בסיס לחדילה תקפה, המכונה "חדילה סטטוטורית".',
    '["הודעת חדילה", "חדילה סטטוטורית", "חוק תובענות ייצוגיות", "רשות ציבורית", "גבייה שלא כדין", "שינוי חקיקה"]'::jsonb,
    '**וריאציה 1 — הגדרת חדילה סטטוטורית:** מהי חדילה סטטוטורית? ← חדילה מגבייה עקב הוראת חוק חדשה המכשירה או מבהירה את חוקיות הגבייה (ת"צ (מינהליים ת"א) 387-04-23 נתאי חיים סקוברוניק נ'' מדינת ישראל - משרד התחבורה). **וריאציה 2 — תוקף חדילה סטטוטורית:** האם חדילה סטטוטורית תקפה לצורך סעיף 9? ← כן, היא נחשבת לחדילה צליחה ומובילה לדחיית בקשת האישור (ת"צ (מינהליים ת"א) 45470-03-23 גלית סקוברוניק נ'' מדינת ישראל משרד התחבורה). **וריאציה 3 — קשר סיבתי:** האם נדרש קשר סיבתי בין הגשת הבקשה לחדילה סטטוטורית? ← לא, הפסיקה קבעה כי לא נדרש קשר סיבתי בין הגשת בקשת האישור לחדילה (ת"צ (מינהליים ת"א) 387-04-23 נתאי חיים סקוברוניק נ'' מדינת ישראל - משרד התחבורה).',
    'חדילה סטטוטורית ← מכוח חוק חדש המכשיר גבייה ← נחשבת חדילה תקפה (סעיף 9 חוק תובענות ייצוגיות) ← לא נדרש קשר סיבתי.',
    '["חוק תובענות ייצוגיות, תשס\"ו-2006, סעיף 9", "רע\"א 6340/07 עיריית תל אביב נ'' טיומקין (13.2.2011)", "ת\"צ (מינהליים ת\"א) 387-04-23 נתאי חיים סקוברוניק נ'' מדינת ישראל - משרד התחבורה (02.07.2025)", "ת\"צ (מינהליים ת\"א) 45470-03-23 גלית סקוברוניק נ'' מדינת ישראל משרד התחבורה (09.09.2024)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'שיקולי בית המשפט בהארכת מועד לחדילה', 2, 'עיריית רעננה הגישה הודעת חדילה 120 ימים לאחר המצאת הבקשה לאישור תובענה ייצוגית, וביקשה מבית המשפט להאריך את המועד להגשתה. מהם השיקולים המרכזיים שינחו את בית המשפט בהחלטתו האם לאשר את הארכת המועד?',
    'שאלה זו מתמקדת בשיקול הדעת של בית המשפט בהארכת המועד להגשת הודעת חדילה לפי סעיף 9(א) לחוק תובענות ייצוגיות. היא מדגישה את ההבחנה בין "טעמים שיירשמו" ל"טעמים מיוחדים שיירשמו", ואת הצורך בפרשנות דווקנית של זכות היתר הניתנת לרשות, תוך איזון עם זכויות חברי הקבוצה.',
    'סעיף 9(א) לחוק תובענות ייצוגיות קובע כי בית המשפט רשאי להאריך את תקופת 90 הימים להגשת הודעת חדילה "מטעמים שיירשמו". הפסיקה הבהירה כי דרישה זו פחות מחמירה מדרישה ל"טעמים מיוחדים שיירשמו" (בר"מ 7689/13 מינהל מקרקעי ישראל נ'' דהאן). עם זאת, מאחר שמנגנון החדילה מעניק לרשות זכות יתר משמעותית, המאפשרת לה להימנע מהשבת כספים שנגבו שלא כדין במסגרת תובענה ייצוגית, יש לפרש את הוראות הסעיף בדקדקנות ובדווקנות. בתי המשפט נוטים לאשר הארכות מועד מטעמים טכניים (כגון פער בין מועד הגשת הבקשה למועד המצאתה לרשות), אך נזהרים ממתן ארכות מטעמים מהותיים, שכן הדבר עלול לפגוע באופן משמעותי בחברי הקבוצה. סעיף 9(א) לחוק תובענות ייצוגיות, תשס"ו-2006ת"צ (מינהליים י-ם) 42430-09-14 ישראל בן עזרא נ'' הועדה המקומית לתכנון ובניה ירושלים (13.04.2016)ת"צ (מינהליים י-ם) 27840-01-14 דניאל עברי נ'' מי שמש בע"מ (13.08.2015)ת"צ (מינהליים ת"א) 25301-08-18 מועצה מקומית כפר שמריהו נ'' שחר ארביב (30.12.2018)ת"צ (מינהליים ב"ש) 31879-04-18 שלום יצחק מזרחי נ'' עיריית אשקלון (19.07.2020)',
    'הטעות הנפוצה היא לחשוב ש"טעמים שיירשמו" מאפשרים הארכה כמעט אוטומטית, מבלי להבין את הפרשנות המצמצמת של הפסיקה ואת האיזון הנדרש מול הפגיעה בחברי הקבוצה.',
    '["הודעת חדילה", "הארכת מועד", "טעמים שיירשמו", "זכות יתר לרשות", "פרשנות דווקנית", "איזון אינטרסים", "חוק תובענות ייצוגיות"]'::jsonb,
    '**וריאציה 1 — רף ההנמקה:** מהו רף ההנמקה הנדרש להארכת מועד לחדילה? ← "טעמים שיירשמו", רף פחות מחמיר מ"טעמים מיוחדים שיירשמו" (סעיף 9(א) לחוק תובענות ייצוגיות). **וריאציה 2 — שיקולים לאישור:** אילו שיקולים ינחו את בית המשפט? ← יישום דווקני של סעיף 9 בשל היותו זכות יתר לרשות, ומניעת פגיעה בחברי הקבוצה (ת"צ (מינהליים י-ם) 42430-09-14 ישראל בן עזרא נ'' הועדה המקומית לתכנון ובניה ירושלים). **וריאציה 3 — טעמים טכניים מול מהותיים:** האם רק טעמים טכניים מצדיקים הארכה? ← הפסיקה חלוקה, אך יש נטייה לאשר מטעמים טכניים (כמו פער בין הגשה להמצאה) ולהיזהר מטעמים מהותיים (ת"צ (מינהליים י-ם) 27840-01-14 דניאל עברי נ'' מי שמש בע"מ).',
    'הארכת מועד לחדילה ← "טעמים שיירשמו" (סעיף 9(א) חוק תובענות ייצוגיות) ← פרשנות דווקנית ← איזון מול פגיעה בקבוצה.',
    '["חוק תובענות ייצוגיות, תשס\"ו-2006, סעיף 9(א)", "בר\"מ 7689/13 מינהל מקרקעי ישראל נ'' דהאן (29.6.2014)", "ת\"צ (מינהליים י-ם) 42430-09-14 ישראל בן עזרא נ'' הועדה המקומית לתכנון ובניה ירושלים (13.04.2016)", "ת\"צ (מינהליים י-ם) 27840-01-14 דניאל עברי נ'' מי שמש בע\"מ (13.08.2015)", "ת\"צ (מינהליים ב\"ש) 31879-04-18 שלום יצחק מזרחי נ'' עיריית אשקלון (19.07.2020)", "ת\"צ (מינהליים ת\"א) 25301-08-18 מועצה מקומית כפר שמריהו נ'' שחר ארביב (30.12.2018)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'השבת כספים לאחר הודעת חדילה', 3, 'עיריית רעננה הגישה הודעת חדילה תקפה, ובית המשפט קיבל אותה ודחה את הבקשה לאישור תובענה ייצוגית. האם חברי הקבוצה זכאים להשבת הסכומים שנגבו מהם שלא כדין על ידי העירייה במסגרת הליך זה?',
    'שאלה זו עוסקת בהשלכות המהותיות של קבלת הודעת חדילה על זכות ההשבה של חברי הקבוצה. היא מדגישה את האיזון העדין שערך המחוקק בסעיף 9 לחוק תובענות ייצוגיות, המעניק לרשות "פתח מילוט" מהשבה במסגרת ההליך הייצוגי, אך שומר על זכות התביעה האישית של כל אחד מחברי הקבוצה.',
    'סעיף 9(ב) לחוק תובענות ייצוגיות קובע כי אם הרשות הודיעה כי תחדל מהגבייה והוכח שחדלה, בית המשפט לא יאשר את התובענה הייצוגית. משמעותה המעשית של הוראה זו היא כי רשות שחדלה מגבייה פטורה מלהשיב את הסכומים שנטען כי נגבו על ידה שלא כדין, למי שלא הגיש נגדה תביעת השבה אישית. מנגנון זה מאפשר לרשות לשמור בקופתה את פירות הגבייה הבלתי חוקית שביצעה בעבר. עם זאת, המחוקק לא שלל בהסדרים המיוחדים שנקבעו בחוק תובענות ייצוגיות את זכותו של כל אחד מחברי הקבוצה לתבוע את מלוא הנזק האישי שנגרם לו בתביעה אישית נגד הרשות. ת"צ (מינהליים ת"א) 387-04-23 נתאי חיים סקוברוניק נ'' מדינת ישראל - משרד התחבורה (02.07.2025)ת"צ (מינהליים ת"א) 45470-03-23 גלית סקוברוניק נ'' מדינת ישראל משרד התחבורה (09.09.2024)ע"א 665/23 מדינת ישראל- רשות המיסים נ'' עודד כהנא (23.04.2026)ת"צ (מינהליים י-ם) 42430-09-14 ישראל בן עזרא נ'' הועדה המקומית לתכנון ובניה ירושלים (13.04.2016)',
    'הטעות הנפוצה היא לחשוב שקבלת הודעת חדילה מחייבת את הרשות להשיב את הכספים שנגבו שלא כדין, או לחלופין, שהיא שוללת לחלוטין את זכות ההשבה, מבלי להבחין בין תביעה ייצוגית לתביעה אישית.',
    '["הודעת חדילה", "השבת כספים", "תובענה ייצוגית", "תביעה אישית", "רשות ציבורית", "גבייה שלא כדין", "איזון אינטרסים"]'::jsonb,
    '**וריאציה 1 — השבה בתובענה ייצוגית:** האם הרשות חייבת להשיב כספים במסגרת התובענה הייצוגית לאחר חדילה? ← לא, סעיף 9(ב) פוטר את הרשות מהשבה במסגרת ההליך הייצוגי (ת"צ (מינהליים ת"א) 387-04-23 נתאי חיים סקוברוניק נ'' מדינת ישראל - משרד התחבורה). **וריאציה 2 — תביעה אישית:** האם חברי הקבוצה יכולים לתבוע השבה בתביעה אישית? ← כן, המחוקק לא שלל את זכות התביעה האישית (ת"צ (מינהליים ת"א) 387-04-23 נתאי חיים סקוברוניק נ'' מדינת ישראל - משרד התחבורה). **וריאציה 3 — תכלית החדילה:** מהי תכלית מנגנון החדילה בהקשר זה? ← לאזן בין עניינם של חברי הקבוצה והאינטרס הציבורי שבאכיפת הדין, לבין החשש מפגיעה בקופה הציבורית (ת"צ (מינהליים ת"א) 387-04-23 נתאי חיים סקוברוניק נ'' מדינת ישראל - משרד התחבורה).',
    'קבלת הודעת חדילה ← פוטרת הרשות מהשבה בתובענה ייצוגית (סעיף 9(ב) חוק תובענות ייצוגיות) ← לא שוללת תביעה אישית.',
    '["חוק תובענות ייצוגיות, תשס\"ו-2006, סעיף 9(ב)", "ת\"צ (מינהליים ת\"א) 387-04-23 נתאי חיים סקוברוניק נ'' מדינת ישראל - משרד התחבורה (02.07.2025)", "ת\"צ (מינהליים ת\"א) 45470-03-23 גלית סקוברוניק נ'' מדינת ישראל משרד התחבורה (09.09.2024)", "ע\"א 665/23 מדינת ישראל- רשות המיסים נ'' עודד כהנא (23.04.2026)", "ת\"צ (מינהליים י-ם) 42430-09-14 ישראל בן עזרא נ'' הועדה המקומית לתכנון ובניה ירושלים (13.04.2016)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'גמול ושכר טרחה לאחר הודעת חדילה', 4, 'עיריית רעננה הגישה הודעת חדילה תקפה, ובית המשפט קיבל אותה ודחה את הבקשה לאישור תובענה ייצוגית. האם התובע הייצוגי ובא כוחו זכאים לגמול ושכר טרחה במקרה זה?',
    'שאלה זו עוסקת בסוגיית פסיקת גמול ושכר טרחה לתובע הייצוגי ולבא כוחו במקרה של קבלת הודעת חדילה. היא מתייחסת לסעיף 9(ג) לחוק תובענות ייצוגיות, המעניק לבית המשפט סמכות לפסוק תשלומים אלו, על אף דחיית הבקשה לאישור התובענה הייצוגית, וזאת בהתחשב בתרומת ההליך לאכיפת הדין.',
    'סעיף 9(ג) לחוק תובענות ייצוגיות קובע במפורש כי אם בית המשפט החליט לקבל הודעת חדילה ולדחות את התובענה הייצוגית, הוא רשאי, על אף הוראות סעיף 22, לפסוק גמול למבקש בהתחשב בשיקולים כאמור בסעיף 22(ב), ולקבוע שכר טרחה לבא כוח המייצג בהתאם להוראות סעיף 23. הוראה זו נועדה לתמרץ תובעים ייצוגיים להגיש תובענות מוצדקות גם נגד רשויות, שכן גם אם הרשות תבחר ב"פתח המילוט" של החדילה, התובע ובא כוחו יזכו לתגמול על תרומתם לאכיפת הדין ולמניעת גבייה בלתי חוקית בעתיד. בית המשפט יבחן את מכלול נסיבות העניין, לרבות היקף הגבייה הבלתי חוקית, התועלת שצמחה לחברי הקבוצה, והשקעת התובע ובא כוחו. סעיף 9(ג) לחוק תובענות ייצוגיות, תשס"ו-2006ת"צ (מנהלי נצרת) 67166-04-25 איסר חוארי נ'' עיריית נצרת (26.01.2026)ת"צ (מינהליים חי'') 54805-04-23 אייל אמרגי נ'' עיריית חריש (22.02.2025)ת"צ (מינהליים ת"א) 45470-03-23 גלית סקוברוניק נ'' מדינת ישראל משרד התחבורה (09.09.2024)',
    'הטעות הנפוצה היא לחשוב שדחיית בקשת האישור שוללת אוטומטית את הזכות לגמול ושכר טרחה, מבלי להכיר בהוראה הספציפית בסעיף 9(ג) המאפשרת זאת.',
    '["גמול לתובע ייצוגי", "שכר טרחה", "הודעת חדילה", "חוק תובענות ייצוגיות", "שיקול דעת שיפוטי", "תמריץ להגשת תובענות"]'::jsonb,
    '**וריאציה 1 — סמכות בית המשפט:** האם בית המשפט רשאי לפסוק גמול ושכר טרחה לאחר קבלת חדילה? ← כן, סעיף 9(ג) לחוק תובענות ייצוגיות מקנה לו סמכות זו (סעיף 9(ג) לחוק תובענות ייצוגיות). **וריאציה 2 — שיקולים לפסיקה:** מהם השיקולים לפסיקת גמול ושכר טרחה במקרה כזה? ← מכלול נסיבות העניין, היקף הגבייה הבלתי חוקית, התועלת שצמחה לחברי הקבוצה, והשקעת התובע ובא כוחו (ת"צ (מנהלי נצרת) 67166-04-25 איסר חוארי נ'' עיריית נצרת). **וריאציה 3 — תכלית ההוראה:** מהי תכלית סעיף 9(ג)? ← לעודד תובעים ייצוגיים להעמיד לביקורת שיפוטית כשלים בהתנהלות הרשויות, גם אם ההליך מסתיים בחדילה (ת"צ (מנהלי נצרת) 67166-04-25 איסר חוארי נ'' עיריית נצרת).',
    'קבלת הודעת חדילה ← בית המשפט רשאי לפסוק גמול ושכר טרחה (סעיף 9(ג) חוק תובענות ייצוגיות) ← בהתחשב בשיקולים מסעיפים 22(ב) ו-23.',
    '["חוק תובענות ייצוגיות, תשס\"ו-2006, סעיף 9(ג)", "חוק תובענות ייצוגיות, תשס\"ו-2006, סעיף 22(ב)", "חוק תובענות ייצוגיות, תשס\"ו-2006, סעיף 23", "ת\"צ (מנהלי נצרת) 67166-04-25 איסר חוארי נ'' עיריית נצרת (26.01.2026)", "ת\"צ (מינהליים חי'') 54805-04-23 אייל אמרגי נ'' עיריית חריש (22.02.2025)", "ת\"צ (מינהליים ת\"א) 45470-03-23 גלית סקוברוניק נ'' מדינת ישראל משרד התחבורה (09.09.2024)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לא, חדילה סטטוטורית אינה נחשבת לחדילה לצורך סעיף 9 לחוק תובענות ייצוגיות, שכן הרשות לא חדלה מיוזמתה.', false, 'תשובה זו שגויה. הפסיקה הכירה במפורש ב"חדילה סטטוטורית" כסוג של חדילה תקפה לצורך סעיף 9 לחוק תובענות ייצוגיות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'כן, חדילה מכוח הוראת חוק חדשה, המכשירה או מבהירה את הגבייה, נכללת בגדרי חדילה צליחה לפי סעיף 9 לחוק תובענות ייצוגיות, גם אם הגבייה הייתה שלא כדין קודם לכן.', true, 'זו התשובה הנכונה. הפסיקה (רע"א 6340/07 עיריית תל אביב נ'' טיומקין) קבעה כי חדילה סטטוטורית, כלומר חדילה מכוח הוראת חוק חדשה המכשירה את הגבייה, נחשבת לחדילה תקפה לצורך סעיף 9 לחוק תובענות ייצוגיות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, אך רק אם הרשות תוכיח כי לא היה לה כל קשר סיבתי להליך החקיקה החדש.', false, 'תשובה זו שגויה. הפסיקה קבעה כי לא נדרש קשר סיבתי בין הגשת בקשת האישור לחדילה, ודרישה לקשר סיבתי להליך חקיקה אינה קיימת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, רק חדילה בפועל של הרשות מיוזמתה, ולא מכוח חוק, תיחשב כחדילה תקפה.', false, 'תשובה זו שגויה. הפסיקה מבחינה בין חדילה בפועל (פעולה יזומה של הרשות) לבין חדילה סטטוטורית (מכוח חוק), ושניהם נחשבים לחדילה תקפה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'בית המשפט יאריך את המועד רק אם מדובר בטעמים טכניים במהותם, כגון פער בין מועד הגשת הבקשה למועד המצאתה לרשות, ולא מטעמים מהותיים.', false, 'תשובה זו שגויה. אף שטעמים טכניים יכולים להצדיק הארכה, הפסיקה אינה מגבילה את הארכת המועד לטעמים טכניים בלבד, וניתן להאריך גם מטעמים מהותיים, אם כי בזהירות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'בית המשפט יבחן אם מתקיימים "טעמים שיירשמו", שהיא דרישה פחות מחמירה מ"טעמים מיוחדים שיירשמו", תוך הקפדה על יישום דווקני של סעיף 9 בשל היותו זכות יתר לרשות, ועל מנת למנוע פגיעה בחברי הקבוצה.', true, 'זו התשובה הנכונה. סעיף 9(א) דורש "טעמים שיירשמו", רף נמוך יותר מ"טעמים מיוחדים". עם זאת, הפסיקה מדגישה כי מדובר בזכות יתר לרשות, ולכן יש לפרש את הסעיף בצמצום ולהאריך את המועד רק במקרים ראויים, תוך איזון עם הפגיעה בחברי הקבוצה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'בית המשפט יאריך את המועד באופן אוטומטי, שכן מטרת החדילה היא לעודד את הרשות לחדול מגבייה בלתי חוקית.', false, 'תשובה זו שגויה. הארכת המועד אינה אוטומטית, ובית המשפט מפעיל שיקול דעת תוך בחינת הטעמים שהוצגו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'בית המשפט יאריך את המועד רק אם הרשות תוכיח כי האיחור נבע מכוח עליון או מנסיבות בלתי צפויות שלא הייתה לה שליטה עליהן.', false, 'תשובה זו שגויה. דרישה זו מחמירה מדי ואינה עולה בקנה אחד עם רף ה"טעמים שיירשמו" הקבוע בחוק.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'כן, הרשות חייבת להשיב את כל הסכומים שנגבו שלא כדין, שכן מטרת החוק היא להרתיע מפני גבייה בלתי חוקית.', false, 'תשובה זו שגויה. מנגנון החדילה פוטר את הרשות מהשבת הכספים במסגרת התובענה הייצוגית, אם כי חברי הקבוצה יכולים לתבוע באופן אישי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לא, קבלת הודעת חדילה פוטרת את הרשות מהשבת הסכומים שנגבו שלא כדין במסגרת התובענה הייצוגית, אך אינה שוללת את זכותם של חברי הקבוצה לתבוע השבה בתביעה אישית.', true, 'זו התשובה הנכונה. סעיף 9(ב) לחוק תובענות ייצוגיות קובע כי הרשות פטורה מהשבה במסגרת התובענה הייצוגית, אך הפסיקה הבהירה כי זכות התביעה האישית נשמרת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'כן, אך רק אם הרשות התחייבה להשיב את הכספים במסגרת הודעת החדילה.', false, 'תשובה זו שגויה. הודעת חדילה אינה מתנה את דחיית בקשת האישור בהתחייבות להשיב, אם כי הרשות יכולה לבחור לעשות זאת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא, קבלת הודעת חדילה שוללת לחלוטין כל אפשרות להשבת כספים, בין בתובענה ייצוגית ובין בתביעה אישית.', false, 'תשובה זו שגויה. זכות התביעה האישית נשמרת, והמחוקק לא שלל אותה בהסדרים המיוחדים שנקבעו בחוק תובענות ייצוגיות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'לא, דחיית הבקשה לאישור תובענה ייצוגית שוללת כל זכות לגמול ושכר טרחה.', false, 'תשובה זו שגויה. סעיף 9(ג) לחוק תובענות ייצוגיות מאפשר לבית המשפט לפסוק גמול ושכר טרחה גם במקרה של קבלת הודעת חדילה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'כן, בית המשפט רשאי לפסוק גמול למבקש ושכר טרחה לבא כוחו, בהתחשב בשיקולים הקבועים בסעיפים 22(ב) ו-23 לחוק תובענות ייצוגיות.', true, 'זו התשובה הנכונה. סעיף 9(ג) לחוק תובענות ייצוגיות מקנה לבית המשפט סמכות לפסוק גמול ושכר טרחה במקרה של קבלת הודעת חדילה, תוך התחשבות בשיקולים הרלוונטיים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'כן, אך רק אם הרשות הסכימה מראש לתשלום גמול ושכר טרחה במסגרת הודעת החדילה.', false, 'תשובה זו שגויה. הסכמת הרשות אינה תנאי הכרחי, שכן לבית המשפט נתון שיקול דעת לפסוק גמול ושכר טרחה מכוח החוק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'לא, אלא אם כן התובע הייצוגי הוכיח כי הודעת החדילה הוגשה בחוסר תום לב מצד הרשות.', false, 'תשובה זו שגויה. חוסר תום לב של הרשות יכול להשפיע על קבלת הודעת החדילה עצמה, אך אינו תנאי לפסיקת גמול ושכר טרחה לאחר קבלתה.', 4);

END $$;

-- ============================================================
-- Q40 — 2024-W-Q40 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2024-W-Q40';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q40 skipped: external_id % already exists', '2024-W-Q40';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2024-W-Q40', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'לאחר ביטול טיסתם לפריז, יעקב ורחל תבעו בתביעה קטנה את חברת הטיסות בתביעה על סך 7,000 ש"ח על רקע ביטול הטיסה בסמוך. הרשמת הבכירה בבית משפט השלום בירושלים קיבלה את התביעה בחלקה, ופסקה לזכותם 3,000 ש"ח בלבד. יעקב ורחל אינם מרוצים מהתוצאה. מה הדין?',
    '{"exam_year": 2024, "exam_season": "winter", "exam_part": 2, "exam_question_number": 40}'::jsonb,
    'השאלה עוסקת בהליכי ערעור על פסקי דין של בית המשפט לתביעות קטנות, תוך התמקדות בסמכות העניינית ובמספר השופטים הדנים בבקשת רשות הערעור בבית המשפט המחוזי ובהמשך בבית המשפט העליון. היא מתבססת על סעיפים 26 ו-64 לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, ועל פרשנותם בפסיקת בית המשפט העליון.',
    'סעיף 64 לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי פסק דין של בית משפט לתביעות קטנות ניתן לערעור לפני בית משפט מחוזי אם ניתנה רשות לכך מאת שופט של בית המשפט המחוזי, ובית המשפט המחוזי ידון בערעור בשופט אחד (דן יחיד). כלומר, אין זכות ערעור אוטומטית על פסקי דין של תביעות קטנות. באשר ל"גלגול שלישי" (בקשת רשות ערעור לבית המשפט העליון), הפסיקה, ובפרט רע"א 8190/14 אייל רוזנברג נ'' בזק בינלאומי בע"מ, מבהירה כי הסדר ספציפי זה, החל על תביעות קטנות, אינו נופל לגדר החריג הקבוע בסעיף 26(4) לחוק בתי המשפט, הקובע כי בית המשפט העליון ידון בשלושה רק בערעורים על פסק דין של בית המשפט המחוזי שניתן בדן יחיד בערעור לפי סעיף 37(ב)(9) (תביעה אזרחית שסכומה אינו עולה על 300,000 ש"ח). לכן, גם בקשת רשות ערעור לבית המשפט העליון על פסק דין שראשיתו בתביעות קטנות, תידון בדן יחיד. סעיף 64 לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984רע"א 8190/14 אייל רוזנברג נ'' בזק בינלאומי בע"מ (24.06.2015)רע"א 8190/14 אייל רוזנברג נ'' בזק בינלאומי בע"מ (24.06.2015)',
    'הטעות הנפוצה היא לבלבל בין כללי הערעור הרגילים (ערעור בזכות על פסק דין שלום, ערעור ברשות על פסק דין מחוזי) לבין הכללים המיוחדים החלים על פסקי דין של בית משפט לתביעות קטנות, ובפרט לגבי הרכב השופטים בערכאות הערעור.',
    '["בית משפט לתביעות קטנות", "רשות ערעור", "גלגול שלישי", "דן יחיד", "מותב תלתא", "חוק בתי המשפט", "סמכות עניינית"]'::jsonb,
    '**וריאציה 1 — ערעור ראשון:** לאן מוגשת בקשת רשות ערעור על פסק דין של תביעות קטנות? ← לבית המשפט המחוזי, ונדון בדן יחיד (סעיף 64 לחוק בתי המשפט). **וריאציה 2 — ערעור שני (גלגול שלישי):** לאן מוגשת בקשת רשות ערעור על החלטת המחוזי? ← לבית המשפט העליון, ונדון בדן יחיד (רע"א 8190/14 אייל רוזנברג נ'' בזק בינלאומי בע"מ). **וריאציה 3 — תכלית ההסדר:** מדוע ההסדר שונה בתביעות קטנות? ← כדי לשמור על אופיו של בית המשפט לתביעות קטנות כהליך מהיר, פשוט וזול, וכדי למנוע הארכת התדיינות וייקור ההליך (רת"ק (מחוזי י-ם) 62412-02-22 יוסף עזאזמה נ'' עאיד חמדאן).',
    'ערעור על תביעות קטנות ← בקשת רשות ערעור למחוזי (דן יחיד) ← בקשת רשות ערעור לעליון (דן יחיד) ← סעיפים 26, 64 לחוק בתי המשפט.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 26", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 64", "רע\"א 8190/14 אייל רוזנברג נ'' בזק בינלאומי בע\"מ (24.06.2015)", "רת\"ק (מחוזי י-ם) 62412-02-22 יוסף עזאזמה נ'' עאיד חמדאן (20.03.2022)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'יעקב ורחל רשאים להגיש ערעור בזכות לבית משפט השלום, ועל החלטתו להגיש בקשת רשות ערעור לבית המשפט המחוזי שתידון במותב של שלושה שופטים.', false, 'תשובה זו שגויה. על פסק דין של בית משפט לתביעות קטנות אין זכות ערעור, אלא יש להגיש בקשת רשות ערעור לבית המשפט המחוזי, והיא תידון בדן יחיד.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'יעקב ורחל רשאים להגיש בקשת רשות ערעור לבית המשפט המחוזי שתידון בדן יחיד, ועל החלטתו ניתן להגיש לבית המשפט העליון בקשת רשות ערעור שניתן לדון בה לגופה בדן יחיד.', true, 'זו התשובה הנכונה. סעיף 64 לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי פסק דין של בית משפט לתביעות קטנות ניתן לערעור לפני בית משפט מחוזי אם ניתנה רשות לכך מאת שופט של בית המשפט המחוזי, ובית המשפט המחוזי ידון בערעור בשופט אחד. בנוסף, הפסיקה קבעה כי גם ערעור ב"גלגול שלישי" (בקשת רשות ערעור לבית המשפט העליון) על פסק דין שראשיתו בתביעות קטנות, יידון בדן יחיד, ולא במותב תלתא, שכן סעיף 26(4) לחוק בתי המשפט אינו חל במקרה זה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'יעקב ורחל רשאים להגיש בקשת רשות ערעור לבית המשפט המחוזי שתידון בדן יחיד, ועל החלטתו ניתן להגיש בקשת רשות ערעור לבית המשפט העליון שניתן לדון בה לגופה בהרכב של שלושה שופטים.', false, 'תשובה זו שגויה. אף שרשות הערעור לבית המשפט המחוזי תידון בדן יחיד, בקשת רשות ערעור לבית המשפט העליון על פסק דין שראשיתו בתביעות קטנות תידון אף היא בדן יחיד, ולא בהרכב של שלושה שופטים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'יעקב ורחל רשאים להגיש ערעור בזכות לבית משפט השלום, ועל החלטתו להגיש בקשת רשות ערעור לבית המשפט המחוזי שתידון בדן יחיד.', false, 'תשובה זו שגויה. אין ערעור בזכות על פסק דין של בית משפט לתביעות קטנות, וערכאת הערעור הראשונה היא בית המשפט המחוזי, לא בית משפט השלום.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'תנאים למתן רשות ערעור על תביעות קטנות', 1, 'מהם המקרים החריגים בהם תינתן רשות ערעור על פסק דין של בית משפט לתביעות קטנות?',
    'שאלה זו עוסקת באמות המידה המחמירות למתן רשות ערעור על פסקי דין של בית משפט לתביעות קטנות. היא מדגישה את תכלית הקמתו של בית המשפט לתביעות קטנות כהליך מהיר, פשוט וזול, ואת הצורך לשמור על תכלית זו באמצעות ריסון בהתערבות ערכאת הערעור.',
    'המחוקק לא העניק זכות ערעור על פסקי דין של בית המשפט לתביעות קטנות, אלא התנה זאת בקבלת רשות מבית המשפט המחוזי (סעיף 64 לחוק בתי המשפט). הפסיקה קבעה כי אמת המידה למתן רשות ערעור על פסקי דין אלו היא מחמירה במיוחד. רשות זו תינתן רק במקרים חריגים ביותר, כגון כאשר נפל פגם מהותי הדורש את התערבותה של ערכאת הערעור, או כאשר נעשה לאחד הצדדים עוול קשה, או כאשר הבקשה מעוררת שאלה משפטית בדרגת חשיבות גבוהה ביותר. גישה מצמצמת זו נועדה לשמור על אופיו המיוחד של המוסד, להבטיח את סופיות הדיון ולמנוע הפיכת הליך שאמור להיות פשוט למורכב וממושך. רת"ק (מחוזי י-ם) 62412-02-22 יוסף עזאזמה נ'' עאיד חמדאן (20.03.2022)רת"ק (מחוזי ת"א) 32348-05-21 שי רחימי נ'' עידן גורן (15.07.2021)רת"ק (מחוזי ת"א) 61577-12-25 איליה מרשק נ'' אלון בן דוד (09.02.2026)רע"א 7535/16 אבירם דהרי נ'' דרור לדרמן (26.12.2016)רע"א 6480/13 אליה דיאס נ'' חברת בזק לתקשורת בע''''מ (01.12.2013)',
    'הטעות הנפוצה היא לחשוב שניתן לערער על פסק דין של בית משפט לתביעות קטנות באותה קלות כמו על פסק דין של בית משפט שלום, מבלי להכיר באמות המידה המחמירות שנקבעו בפסיקה.',
    '["רשות ערעור", "בית משפט לתביעות קטנות", "פגם מהותי", "עוול קשה", "שאלה משפטית עקרונית", "סופיות הדיון", "חוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — תכלית ההליך:** מהי תכלית בית המשפט לתביעות קטנות? ← הליך פשוט, מהיר וזול (רת"ק (מחוזי י-ם) 62412-02-22 יוסף עזאזמה נ'' עאיד חמדאן). **וריאציה 2 — אמות מידה למתן רשות:** באילו מקרים תינתן רשות ערעור? ← פגם מהותי, עוול קשה, שאלה משפטית בדרגת חשיבות גבוהה ביותר (רת"ק (מחוזי ת"א) 61577-12-25 איליה מרשק נ'' אלון בן דוד). **וריאציה 3 — חשיבות ציבורית:** האם שאלה משפטית בעלת חשיבות ציבורית תמיד תצדיק רשות ערעור? ← לא בהכרח, גם אם מתעוררת שאלה משפטית בעלת חשיבות החורגת מעניינם הישיר של הצדדים (רע"א 7535/16 אבירם דהרי נ'' דרור לדרמן).',
    'רשות ערעור על תביעות קטנות (סעיף 64 לחוק בתי המשפט) ← אמות מידה מחמירות ← פגם מהותי / עוול קשה / שאלה משפטית חשובה ביותר.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 64", "רת\"ק (מחוזי י-ם) 62412-02-22 יוסף עזאזמה נ'' עאיד חמדאן (20.03.2022)", "רת\"ק (מחוזי ת\"א) 32348-05-21 שי רחימי נ'' עידן גורן (15.07.2021)", "רת\"ק (מחוזי ת\"א) 61577-12-25 איליה מרשק נ'' אלון בן דוד (09.02.2026)", "רע\"א 7535/16 אבירם דהרי נ'' דרור לדרמן (26.12.2016)", "רע\"א 6480/13 אליה דיאס נ'' חברת בזק לתקשורת בע''''מ (01.12.2013)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'התערבות ערכאת ערעור בממצאי עובדה ומהימנות', 2, 'יעקב ורחל טוענים בבקשת רשות הערעור כי בית המשפט לתביעות קטנות שגה בקביעותיו העובדתיות ובממצאי המהימנות שלו. האם ערכאת הערעור תתערב בטענות אלו?',
    'שאלה זו בוחנת את היקף התערבותה של ערכאת הערעור בממצאי עובדה ומהימנות שנקבעו על ידי בית המשפט לתביעות קטנות. היא מדגישה את הכלל לפיו ערכאת הערעור ממעטת להתערב בקביעות אלו, ואת הרציונל העומד מאחורי כלל זה, הנובע מאופיו המיוחד של הליך התביעות הקטנות.',
    'הלכה פסוקה היא כי ערכאת הערעור לא תתערב בממצאי עובדה ומהימנות שנקבעו על ידי הערכאה הדיונית, אלא במקרים חריגים ביותר. כלל זה חל ביתר שאת כאשר מדובר בפסק דין של בית משפט לתביעות קטנות, שכן הליך זה נועד להיות מהיר ופשוט, והשופט בערכאה הדיונית הוא זה שהתרשם באופן בלתי אמצעי מהעדים והראיות. התערבות תתאפשר רק כאשר מדובר בטעות עובדתית גלויה וברורה על פניו של פסק הדין, או כאשר נגרם עוול קשה. טענות המופנות כנגד קביעות עובדתיות וממצאי מהימנות, המצויים בליבת שיקול דעתו של בית המשפט לתביעות קטנות, לא יצדיקו ככלל מתן רשות ערעור. רת"ק (מחוזי ב"ש) 57991-06-21 אבישי חי נתיב נ'' מישל בניסטי (08.08.2021)רת"ק (מחוזי ת"א) 1199-12-24 אליהו לאב נ'' דוד עזרא (17.03.2025)רת"ק (מחוזי מרכז) 30961-08-25 רינה אלון סינגר נ'' אביב גולן זאנגי (15.02.2026)רת"ק (מחוזי ת"א) 22555-08-20 יעקב גבאי נ'' כלל חברה לביטוח בע"מ (19.08.2020)רת"ק (מחוזי תל אביב-יפו) 8016-01-26 אוריאל רז המאושר נ'' זוהר מימיס (08.01.2026)',
    'הטעות הנפוצה היא לחשוב שערכאת הערעור תשמש כערכאה דיונית נוספת ותבחן מחדש את כל העובדות, מבלי להבין את הריסון השיפוטי בהתערבות בממצאי עובדה ומהימנות, במיוחד בתביעות קטנות.',
    '["ממצאי עובדה", "ממצאי מהימנות", "התערבות ערכאת ערעור", "בית משפט לתביעות קטנות", "טעות גלויה וברורה", "עוול קשה", "שיקול דעת שיפוטי"]'::jsonb,
    '**וריאציה 1 — כלל אי-ההתערבות:** האם ערכאת הערעור מתערבת בממצאי עובדה? ← ככלל לא, במיוחד בתביעות קטנות, שכן הערכאה הדיונית התרשמה ישירות (רת"ק (מחוזי ב"ש) 57991-06-21 אבישי חי נתיב נ'' מישל בניסטי). **וריאציה 2 — חריגים להתערבות:** מתי כן תתערב? ← במקרים חריגים ביותר של טעות גלויה וברורה, או עוול קשה (רת"ק (מחוזי ת"א) 22555-08-20 יעקב גבאי נ'' כלל חברה לביטוח בע"מ). **וריאציה 3 — תכלית הריסון:** מדוע ערכאת הערעור ממעטת להתערב? ← כדי לשמור על אופיו המיוחד של הליך התביעות הקטנות כהליך מהיר, פשוט וזול, וכדי לכבד את התרשמות הערכאה הדיונית מהעדים (רת"ק (מחוזי ב"ש) 46485-09-11 רויטל מגידש נ'' משה בן חיון).',
    'התערבות בממצאי עובדה ומהימנות בתביעות קטנות ← רק במקרים חריגים ביותר ← טעות גלויה / עוול קשה.',
    '["רת\"ק (מחוזי ב\"ש) 57991-06-21 אבישי חי נתיב נ'' מישל בניסטי (08.08.2021)", "רת\"ק (מחוזי ת\"א) 1199-12-24 אליהו לאב נ'' דוד עזרא (17.03.2025)", "רת\"ק (מחוזי מרכז) 30961-08-25 רינה אלון סינגר נ'' אביב גולן זאנגי (15.02.2026)", "רת\"ק (מחוזי ת\"א) 22555-08-20 יעקב גבאי נ'' כלל חברה לביטוח בע\"מ (19.08.2020)", "רת\"ק (מחוזי תל אביב-יפו) 8016-01-26 אוריאל רז המאושר נ'' זוהר מימיס (08.01.2026)", "רת\"ק (מחוזי ב\"ש) 46485-09-11 רויטל מגידש נ'' משה בן חיון (10.11.2011)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'ערעור על פסק דין שניתן בפשרה בתביעות קטנות', 3, 'נניח שיעקב ורחל הסכימו שפסק הדין בבית המשפט לתביעות קטנות יינתן על דרך הפשרה לפי סעיף 79א לחוק בתי המשפט. מהם התנאים להתערבות ערכאת הערעור בפסק דין כזה?',
    'שאלה זו בוחנת את אמות המידה להתערבות ערכאת הערעור בפסק דין של בית משפט לתביעות קטנות שניתן על דרך הפשרה לפי סעיף 79א לחוק בתי המשפט. היא מדגישה את הריסון השיפוטי המוגבר במקרים אלו, הנובע מהסכמת הצדדים לוויתור על זכות הערעור הרגילה.',
    'פסק דין שניתן על דרך הפשרה לפי סעיף 79א לחוק בתי המשפט, ובפרט בבית משפט לתביעות קטנות, נהנה מחסינות מוגברת מפני התערבות ערכאת הערעור. הצדדים, בהסכמתם לפשרה, מוותרים למעשה על זכות הערעור הרגילה, ולרוב גם על הנמקה מפורטת. לכן, התערבות ערכאת הערעור בפסק דין כזה תהיה במקרים חריגים ביותר בלבד, כגון כאשר בית המשפט חרג מסמכותו, סטה באופן קיצוני מגבולות הסבירות או חרג בקביעת הסכומים שנפסקו, או מקום שבו מוכח כי נפלה טעות היורדת לשורש ההסכמות שאליהן הגיעו הצדדים. רת"ק (מחוזי חי'') 28741-06-25 שושנה אברבנל נ'' בלה עדני (06.07.2025)רת"ק (מחוזי חי'') 2143-09-14 בועז בוהארון נ'' מעבדת אלקטרוניקה-יצחק (01.10.2014)רת"ק (מחוזי ב"ש) 4155-02-25 צוריאל חזי נ'' צבי מימון (02.04.2025)רת"ק (מחוזי ת"א) 30541-07-20 מיקי שחם נ'' עו"ד רויטל מגל (15.07.2020)',
    'הטעות הנפוצה היא להתייחס לפסק דין פשרה כאל פסק דין רגיל הניתן לערעור, מבלי להבין את המשמעות של הסכמת הצדדים לוותר על זכות הערעור ואת הרף הגבוה הנדרש להתערבות במקרים אלו.',
    '["פסק דין פשרה", "סעיף 79א לחוק בתי המשפט", "בית משפט לתביעות קטנות", "התערבות ערכאת ערעור", "חריגה מסמכות", "סטייה קיצונית מסבירות", "טעות יורדת לשורש ההסכמות"]'::jsonb,
    '**וריאציה 1 — רף ההתערבות:** מהו רף ההתערבות בפסק דין פשרה בתביעות קטנות? ← חריג ביותר, כגון חריגה מסמכות או סטייה קיצונית מסבירות (רת"ק (מחוזי חי'') 2143-09-14 בועז בוהארון נ'' מעבדת אלקטרוניקה-יצחק). **וריאציה 2 — משמעות ההסכמה:** מהי משמעות הסכמת הצדדים לפסק דין פשרה? ← ויתור על זכות הערעור הרגילה, והסכמה לתוצאה שאינה בהכרח מנומקת (רת"ק (מחוזי חי'') 28741-06-25 שושנה אברבנל נ'' בלה עדני). **וריאציה 3 — טעות היורדת לשורש ההסכמות:** האם טעות היורדת לשורש ההסכמות תצדיק התערבות? ← כן, זהו אחד המקרים החריגים המצדיקים התערבות בפסק דין פשרה (רת"ק (מחוזי חי'') 2143-09-14 בועז בוהארון נ'' מעבדת אלקטרוניקה-יצחק).',
    'ערעור על פסק דין פשרה (סעיף 79א) בתביעות קטנות ← התערבות רק במקרים חריגים ביותר ← חריגה מסמכות / סטייה קיצונית מסבירות / טעות יורדת לשורש ההסכמות.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 79א", "רת\"ק (מחוזי חי'') 28741-06-25 שושנה אברבנל נ'' בלה עדני (06.07.2025)", "רת\"ק (מחוזי חי'') 2143-09-14 בועז בוהארון נ'' מעבדת אלקטרוניקה-יצחק (01.10.2014)", "רת\"ק (מחוזי ב\"ש) 4155-02-25 צוריאל חזי נ'' צבי מימון (02.04.2025)", "רת\"ק (מחוזי ת\"א) 30541-07-20 מיקי שחם נ'' עו\"ד רויטל מגל (15.07.2020)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'ערעור על החלטה אחרת בתביעות קטנות', 4, 'במהלך הדיון בתביעה הקטנה, בית המשפט לתביעות קטנות דחה בקשה של יעקב ורחל לצרף ראיה חדשה. יעקב ורחל מעוניינים לערער על החלטה זו באופן מיידי. האם ניתן להגיש בקשת רשות ערעור על "החלטה אחרת" כזו של בית המשפט לתביעות קטנות?',
    'שאלה זו עוסקת בהבחנה בין ערעור על פסק דין לבין ערעור על "החלטה אחרת" בהליכי תביעות קטנות. היא מדגישה את הכלל לפיו אין אפשרות לערער על החלטות ביניים של בית המשפט לתביעות קטנות, למעט חריג ספציפי הקבוע בתקנות.',
    'סעיף 64 לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, ותקנה 16(א) לתקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, מתייחסים לאפשרות להשיג על פסק דין של בית משפט לתביעות קטנות, ולא על "החלטה אחרת". הפסיקה קבעה כי ככלל, אין אפשרות לערער (לא ברשות ולא בזכות) על "החלטה אחרת" של בית משפט לתביעות קטנות, למעט החלטה שניתנה בבקשה לביטול פסק דין בהתאם לתקנה 12 לתקנות השיפוט. המשמעות היא שעל החלטות ביניים שונות, כמו דחיית בקשה לצרף ראיה, לא ניתן לערער באופן מיידי, אלא ניתן יהיה להעלות טענות נגד החלטות אלו במסגרת ערעור על פסק הדין הסופי, אם תינתן רשות לכך. סעיף 64 לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984רת"ק (מחוזי מרכז) 41258-04-17 אפרת זליקוביץ נ'' מדינת ישראל- משטרת ישראל (11.06.2017)',
    'הטעות הנפוצה היא להקיש מכללי הערעור על "החלטה אחרת" בבתי משפט רגילים (שלום/מחוזי) לכללי הערעור בתביעות קטנות, מבלי להכיר בהסדר המיוחד והמצומצם החל על תביעות קטנות.',
    '["החלטה אחרת", "בית משפט לתביעות קטנות", "רשות ערעור", "פסק דין סופי", "תקנה 12 לתקנות שיפוט בתביעות קטנות", "חוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — סמכות ערעור על החלטה אחרת:** האם ניתן לערער על "החלטה אחרת" בתביעות קטנות? ← ככלל לא, למעט החלטה בבקשה לביטול פסק דין (רת"ק (מחוזי מרכז) 41258-04-17 אפרת זליקוביץ נ'' מדינת ישראל- משטרת ישראל). **וריאציה 2 — מועד העלאת הטענות:** מתי ניתן להעלות טענות נגד החלטה אחרת? ← במסגרת ערעור על פסק הדין הסופי, אם תינתן רשות לכך (רת"ק (מחוזי מרכז) 41258-04-17 אפרת זליקוביץ נ'' מדינת ישראל- משטרת ישראל). **וריאציה 3 — חריג לכלל:** מהו החריג היחיד המאפשר ערעור על החלטה אחרת? ← החלטה שניתנה בבקשה לביטול פסק דין בהתאם לתקנה 12 לתקנות שיפוט בתביעות קטנות (רת"ק (מחוזי מרכז) 41258-04-17 אפרת זליקוביץ נ'' מדינת ישראל- משטרת ישראל).',
    'ערעור על "החלטה אחרת" בתביעות קטנות ← ככלל לא ניתן ← חריג: החלטה בבקשה לביטול פסק דין (תקנה 12).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 64", "תקנות שיפוט בתביעות קטנות (סדרי דין), תשל\"ז-1976, תקנה 12", "תקנות שיפוט בתביעות קטנות (סדרי דין), תשל\"ז-1976, תקנה 16(א)", "רת\"ק (מחוזי מרכז) 41258-04-17 אפרת זליקוביץ נ'' מדינת ישראל- משטרת ישראל (11.06.2017)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'רשות ערעור תינתן כאשר נפל פגם מהותי הדורש את התערבותה של ערכאת הערעור, או כאשר נעשה לאחד הצדדים עוול קשה, או כאשר הבקשה מעוררת שאלה משפטית בדרגת חשיבות גבוהה ביותר.', true, 'זו התשובה הנכונה. הפסיקה קבעה אמות מידה מחמירות למתן רשות ערעור על פסקי דין של בית משפט לתביעות קטנות, והיא תינתן רק במקרים חריגים אלו, כדי לשמור על תכלית ההליך המהיר והפשוט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'רשות ערעור תינתן בכל מקרה שבו אחד הצדדים אינו מרוצה מתוצאת פסק הדין, שכן זכות הערעור היא זכות יסוד חוקתית.', false, 'תשובה זו שגויה. על פסק דין של בית משפט לתביעות קטנות אין זכות ערעור, אלא ערעור ברשות, ואמות המידה למתן רשות מחמירות במיוחד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'רשות ערעור תינתן רק אם נפלה טעות משפטית גלויה בפסק הדין, ואין חשיבות לשאלות עובדתיות או לעוול שנגרם.', false, 'תשובה זו שגויה. גם טעות עובדתית גלויה וברורה, או עוול קשה, יכולים להצדיק מתן רשות ערעור, ולא רק טעות משפטית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'רשות ערעור תינתן אם סכום התביעה המקורי עולה על 10,000 ש"ח, ללא קשר למהות הטענות.', false, 'תשובה זו שגויה. סכום התביעה אינו מהווה קריטריון למתן רשות ערעור, אלא מהות הפגם או השאלה המשפטית.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'כן, ערכאת הערעור תבחן מחדש את כל הראיות והעדויות ותקבע ממצאי עובדה ומהימנות משלה.', false, 'תשובה זו שגויה. אין זו דרכה של ערכאת הערעור לבחון מחדש את כל הראיות והעדויות, אלא להתערב רק במקרים חריגים ביותר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'לא, ככלל, ערכאת הערעור לא תתערב בממצאי עובדה ומהימנות שנקבעו על ידי הערכאה הדיונית, ובפרט כך בתביעות קטנות, אלא במקרים חריגים ביותר של טעות גלויה וברורה.', true, 'זו התשובה הנכונה. הפסיקה קובעת כי ערכאת הערעור ממעטת להתערב בממצאי עובדה ומהימנות, במיוחד בתביעות קטנות, שכן הערכאה הדיונית היא זו שהתרשמה באופן בלתי אמצעי מהעדים והראיות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'כן, אם הטענות העובדתיות נוגעות לסכום הפיצוי שנפסק, שכן זהו עניין מהותי.', false, 'תשובה זו שגויה. גם טענות הנוגעות לגובה הפיצוי, אם הן מבוססות על ממצאי עובדה ומהימנות, לא יצדיקו התערבות אלא במקרים חריגים ביותר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'לא, אלא אם כן בית המשפט לתביעות קטנות לא נימק כלל את קביעותיו העובדתיות.', false, 'תשובה זו שגויה. גם אם פסק הדין מנומק, ערכאת הערעור לא תתערב בממצאי עובדה ומהימנות אלא במקרים חריגים ביותר.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'ערכאת הערעור תתערב רק במקרים חריגים ביותר, כגון כאשר בית המשפט חרג מסמכותו, סטה באופן קיצוני מגבולות הסבירות, או כאשר נפלה טעות היורדת לשורש ההסכמות שאליהן הגיעו הצדדים.', true, 'זו התשובה הנכונה. הפסיקה קבעה רף התערבות מחמיר במיוחד בפסקי דין שניתנו על דרך הפשרה, במיוחד בתביעות קטנות, שכן הצדדים הסכימו מראש לוותר על זכות הערעור הרגילה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'ערכאת הערעור תתערב בכל מקרה שבו פסק הדין אינו מנומק, שכן חוסר הנמקה מהווה פגם מהותי.', false, 'תשובה זו שגויה. פסק דין שניתן על דרך הפשרה לפי סעיף 79א אינו חייב להיות מנומק, והצדדים מודעים לכך מראש, ולכן חוסר הנמקה אינו עילה להתערבות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'ערכאת הערעור תתערב אם סכום הפיצוי שנפסק אינו תואם את הצעת המחיר שהוצגה על ידי אחד הצדדים.', false, 'תשובה זו שגויה. סטייה מהצעת מחיר אינה עילה להתערבות בפסק דין פשרה, אלא אם היא חורגת באופן קיצוני מגבולות הסבירות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'ערכאת הערעור תתערב אם הצדדים לא היו מיוצגים על ידי עורך דין, שכן הדבר פוגע ביכולתם להבין את משמעות הפשרה.', false, 'תשובה זו שגויה. אי-ייצוג על ידי עורך דין הוא מאפיין מובנה של הליך התביעות הקטנות, ואינו עילה להתערבות בפסק דין פשרה, במיוחד אם הוסברה לצדדים משמעות הסעיף.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'כן, ניתן להגיש בקשת רשות ערעור על כל החלטה של בית המשפט לתביעות קטנות, בדומה לבית משפט שלום.', false, 'תשובה זו שגויה. הכללים לגבי ערעור על החלטות אחרות בתביעות קטנות שונים מאשר בבית משפט שלום, והם מצומצמים יותר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'לא, ככלל, לא ניתן לערער (לא ברשות ולא בזכות) על "החלטה אחרת" של בית משפט לתביעות קטנות, למעט החלטה שניתנה בבקשה לביטול פסק דין.', true, 'זו התשובה הנכונה. סעיף 64 לחוק בתי המשפט ותקנה 16(א) לתקנות שיפוט בתביעות קטנות מתייחסים לערעור על פסק דין, ולא על "החלטה אחרת", למעט חריג מפורש לגבי ביטול פסק דין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'כן, אך רק אם ההחלטה גורמת לעיוות דין בלתי הפיך.', false, 'תשובה זו שגויה. אף שעיוות דין הוא שיקול חשוב, הוא אינו מקנה זכות ערעור על "החלטה אחרת" בתביעות קטנות, למעט החריג המפורש בחוק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'לא, אלא אם כן בית המשפט לתביעות קטנות אישר במפורש הגשת בקשת רשות ערעור על ההחלטה.', false, 'תשובה זו שגויה. אין הוראה בחוק המאפשרת לבית המשפט לתביעות קטנות לאשר ערעור על החלטה אחרת.', 4);

END $$;
